INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (1,N'01',N'01',N'화는 우리를 어떻게 변화시키나요?',NULL,N'생각을 못하게 만들어서 동물처럼 행동하게 되어요.',N'환한 웃음을 주기도 하고,  눈물을 흘리게 만들어요.',N'힘이 샘솟고 뭐든지 할 수 있다는 생각을 갖게 해요. ',N'마음이 차분해지고 주변이 잘 보여요.',N'1',N'01',N'',N'S'),
	 (1,N'01',N'02',N'뉘우침은 우리에게 어떤 사실을 알려 주나요?',NULL,N'잘못의 원인은 나 스스로에게 없다는 사실',N'기대가 한순간에 무너질 수 있다는 사실',N'우리가 한 행동에 대해서는 스스로 책임져야 한다는 사실',N'다른 사람의 잘못만 먼저 보게 된다는 사실',N'3',N'01',N'',N'S'),
	 (1,N'01',N'03',N'긴장된 마음이 안심이 되는 과정을 순서대로 나열한 것을 찾으세요.',N'(1) 한참동안 길을 헤매다가 겨우 집으로 가는 길을 찾았어요. 
(2) 집으로 돌아와 엄마를 만나니 마음이 편안해졌어요. 
(3) 낯선 동네에서 길을 잃어 마음이 조마조마했어요.',N'(1)-(3)-(2)',N'(3)-(1)-(2)',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (1,N'01',N'04',N'다음 중 속상한 마음이 생긴 이유로 알맞은 것은 무엇인가요?',NULL,N'친구와 재미있게 놀았기 때문에',N'갑자기 비가 와서 소풍이 취소되었기 때문에',N'숙제를 모두 끝냈기 때문에',N'칭찬을 많이 들었기 때문에',N'2',N'03',N'',N'S'),
	 (1,N'01',N'05',N'이 책을 읽고 느낀 점을 잘못 말한 것을 찾으세요.',NULL,N'내가 느낀 감정을 솔직하게 표현하도록 노력할거야.',N'언제나 내 감정이 우선시 되어야 한다는 것을 알았어.',N'문제가 생겼을 때, 대화를 통해 감정을 조절할거야.',N'다른 사람의 마음도 함께 생각해야겠어.',N'2',N'04',N'',N'S'),
	 (1,N'01',N'06',N'이 책을 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'감정은 숨기지 않고 마음대로 행동해도 된다.',N'내 마음만 중요하니 다른 사람은 신경 쓰지 않아도 된다.',N'감정을 알고 조절하면 더 잘 지낼 수 있다.',N'화가 나면 바로 소리를 질러야 한다.',N'3',N'04',N'',N'S'),
	 (1,N'01',N'07',N'다음은 어떤 마음이 드는 상황인가요?',N'배를 타고 가는 중 집채만 한 파도가 덮쳐 오고 있었어요. 
