INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (8,N'01',N'14',N'다음 예시의 "엄숙, 정연, 결론" 각각의 뜻과 알맞게 짝지어진 것은 무엇인가요?',N'(ㄱ)엄숙(嚴肅)하고 (ㄴ)정연(井沿)하게 (ㄷ)결론(結論)을 내렸다.',N'ㄱ-엄하게 다스리다',N'ㄴ-질서가 있다',N'ㄷ-결과가 좋지 않다',N'ㄷ-상벌을 주다',N'2',N'03',N'Y',N'S'),
	 (8,N'01',N'15',N'"이름이나 책 제목 같은 것을 순서대로 적은 것"을 뜻하는 단어는 무엇인가요?',N'',N'목석(木石)',N'목록(目錄)',N'녹록(碌碌)',N'석차(席次)',N'2',N'06',N'N',N'S'),
	 (9,N'01',N'01',N'눈이 내린 어느날, 엄마가 사주신 것은 무엇인가요?',N'',N'따뜻한 옷',N'따뜻한 장갑',N'따뜻한 목도리',N'따뜻한 양말',N'1',N'01',N'',N'S'),
	 (9,N'01',N'02',N'거울을 보던 아이는 무엇이 삐져나온 걸 발견했나요?',N'',N'실밥 하나',N'안감 하나',N'깃털 하나',N'단추 하나',N'3',N'03',N'',N'S'),
	 (9,N'01',N'03',N'학교 가는 길에 바람이 불자 일어난 이상한 일은 무엇인가요?',NULL,N'오리에게 줬는데도 깃털이 또 빠짐',N'깃털이 하늘을 날아다님',N'아이의 몸이 떠오름',N'옷이 찢어짐',N'1',N'01',NULL,N'S'),
	 (9,N'01',N'04',N'재채기한 아이에게 엄마는 왜 감기에 걸렸다고 했나요?',NULL,N'마스크를 안 써서',N'찬 음식을 먹어서',N'이불을 잘 덮고 자지 않아서',N'오리와 놀아서',N'3',N'04',NULL,N'S'),
	 (9,N'01',N'05',N' 아이를 칭찬해줄 말로 알맞은 것은?',NULL,N'정직한 아이야',N'건강을 잘 지키는구나',N'오리 마음을 헤아리는 사랑스런 아이야',N'겁이 많은 아이야',N'3',N'04',NULL,N'S'),
	 (9,N'01',N'06',N'다음 문장의 ‘깜박’과 바꿔 쓸 수 있는 말은?',N'깃털이 왜 삐져나왔을까 생각하다가 ''깜빡'' 잠이 들었다',N'스르르',N'화들짝',N'곰곰이',N'벌컥',N'1',N'02',N'Y',N'S'),
	 (9,N'01',N'07',N'오리들에게 깃털을 심어 주는 장면에서 아이의 마음을 잘 표현한 말은?',N'',N'살짝',N'재빨리',N'정성껏',N'무심코',N'3',N'02',N'N',N'S'),
	 (9,N'01',N'08',N'빈칸에 알맞은 이어주는 말을 찾아보세요. ',N'나는 오리들과 언덕에서 썰매를 탔다.
(       ) 숨바꼭질도 했다.',N'그런데',N'그리고',N'그래서',N'그러나',N'2',N'06',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (9,N'01',N'09',N'‘삐져나왔다’는 말을 바꾸어 쓸 수 있는 말은?',NULL,N'밀려났다',N'들어갔다',N'숨어있었다',N'튀어나왔다',N'4',N'06',NULL,N'S'),
	 (9,N'01',N'10',N'깃털을 받은 오리들이 느꼈을 감정으로 알맞은 것은?',NULL,N'부끄러움',N'외로움',N'감사함',N'억울함',N'3',N'07',NULL,N'S'),
	 (9,N'01',N'11',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 오리들과 멀리 있는 언덕으로 달려갔다.
(2) 눈을 떠보니 오리 여러 마리가 모여 있었다.
(3) 깃털이 왜 삐져 나왔을까 생각하다가 잠이 들었다.',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (9,N'01',N'12',N'오리는 어떤 마음으로 깃털을 달라고 부탁했나요?',NULL,N'실망한 마음',N'간절한 마음',N'놀라고 화난 마음',N'무서운 마음',N'2',N'07',NULL,N'S'),
	 (10,N'01',N'01',N'누나는 생일 선물로 무엇을 받았나요?',NULL,N'토끼',N'고양이',N'강아지',N'새',N'3',N'01',N'',N'S'),
	 (10,N'01',N'02',N'화가 난 동생은 누나에게 무엇을 빌려주지 않았나요?',NULL,N'크레파스',N'색연필',N'사인펜',N'공책',N'1',N'01',N'',N'S'),
	 (10,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 동생은 복실이와 함께 놀기 위해 누나에게 크레파스를 빌려주기로 했어요.
(2) 누나는 복실이가 자신의 강아지라고 함께 노는 것을 금지 시켰어요.
(3) 동생은 생일 때 받고 싶은 동물들을 상상하며 잠시 즐거웠어요.',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'(1)-(2)-(3)',N'2',N'03',N'Y',N'S'),
	 (10,N'01',N'04',N'동생이 크레파스를 빌려주기로 한 이유로 알맞은 것은 무엇인가요?',NULL,N'그림을 그리고 싶어서',N'누나와 싸우기 싫어서',N'혼자 놀고 싶어서',N'복실이와 함께 놀고 싶어서',N'4',N'03',N'',N'S'),
	 (10,N'01',N'05',N'이 책을 읽고 느낀 점을 잘못 말한 것을 찾아보세요.',NULL,N'"마지막 장면에서 누나와 동생이 서로 양보할 때 다정해 보여서 기분이 좋았어."',N'"동생이 생일 선물을 많이 받은 걸 보니 정말 욕심이 많은 것 같아. "',N'"동생이 생일 선물로 복실이를 받고 싶은 이유는 함께 놀 때 행복했기 때문일 거야."',N'"가족끼리 함께 나누고 배려하는 것이 중요하다는  사실을 알게 되었어."',N'2',N'04',N'',N'S'),
	 (10,N'01',N'06',N'이 이야기를 통해 우리가 배울 점으로 알맞은 것은 무엇인가요?',NULL,N'내 물건은 절대 나누지 말아야 해요.',N'화가 나면 말하지 않는 게 좋아요.',N'혼자 노는 게 제일 재미있어요.',N'서로 양보하면 사이가 좋아져요.',N'4',N'04',N'',N'S');
