	 (10,N'01',N'07',N'누나는 어떤 목소리로 말했을까요?',N'"너 이제부터 복실이랑 놀지 마"
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (11,N'01',N'05',N'강아지 똥에게 어떤 말을 해줄 수 있을까요?',NULL,N'“꽃이 필수 있게 거름이 되어준 너는 정말 소중해”',N'“냄새나고 쓸모없지만 용기를 가져.”',N'“친구들을 놀리지 말고 친하게 지내.”',N'"다음에는 숨지 말아."',N'1',N'04',N'',N'S'),
	 (11,N'01',N'06',N'이 이야기를 통해 알 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'보기 싫은 것은 모두 버려야 해요.',N'동물은 사람보다 중요해요.',N'꽃은 빗물만 있으면 피어요.',N'작고 하찮아 보여도 소중할 수 있어요.',N'4',N'04',N'',N'S'),
	 (11,N'01',N'07',N'강아지 똥은 어떤 마음이었을까요?',N'“똥! 똥! 에그, 더러워…….”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (12,N'01',N'03',N'이야기의 순서가 바르게 나열된 것을 찾으세요.',N'(1) 방아가 벼 한 말을 다 찧었어요. 
(2) 개구리와 친구들은 모두 둘러 앉아 한솥밥을 먹었어요. 
(3) 개구리는 소시랑 게의 다친 발을 고쳐 주었어요.  ',N'(1)-(2)-(3)',N'(3)-(1)-(2)',N'(2)-(3)-(1)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (12,N'01',N'04',N'개구리가 형 집에 늦게 도착하게 된 까닭으로 알맞은 것은 무엇인가요?',NULL,N'길이 너무 멀어서',N'비가 많이 내려서',N'만난 친구들을 도와주느라',N'길을 잃어버렸기 때문에',N'3',N'03',N'',N'S'),
	 (12,N'01',N'05',N'개구리와 동물 친구들에게 어떤 말을 해줄 수 있을까요?',NULL,N'“친구끼리는 약속을 지키는 모습이 멋져 보였어.”',N'“친구끼리 서로 돕는 모습을 본받아야겠어.”',N'“친구끼리 서로 양보를 하는 것이 중요하다고 생각해.”',N'"혼자서도 다 할 수 있어야 해."',N'2',N'04',N'',N'S'),
	 (12,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'바쁠 때는 친구를 도와주지 않아도 된다.',N'어려운 친구를 보면 지나쳐도 된다.',N'먼저 부탁한 사람이 항상 옳다.',N'서로 도우면 모두가 기뻐질 수 있다.',N'4',N'04',N'',N'S'),
	 (12,N'01',N'07',N'개똥벌레는 어떤 목소리로 말했을까요?',N'개똥벌레가 울다가 대답했어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (13,N'01',N'01',N'개구리는 어떤 방법으로 겨울잠을 자는 두꺼비를 깨웠나요?',NULL,N'두꺼비에게 찬물을 부었어요.',N'찬바람이 들어오게 했어요.',N'달력을 뜯어 5월로 바꿔놓았어요.',N'소리를 크게 질렀어요.',N'3',N'01',N'',N'S'),
	 (13,N'01',N'02',N'결국 단추는 어디에서 발견 되었나요?',NULL,N'바위 아래',N'마루 위',N'나무 뒤',N'풀숲 안',N'2',N'01',N'',N'S'),
	 (13,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요 ',N'(1) 개구리는 달팽이에게 편지를 전해 달라고 부탁했어요. 
(2) 두꺼비는 개구리의 편지를 받고 무척이나 기뻤어요. 
(3) 급히 집으로 온 개구리는 두꺼비에게 편지를 썼어요.',N'(3)-(2)-(1)',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (13,N'01',N'04',N'두꺼비가 편지를 받고 기뻐한 이유는 무엇인가요?',NULL,N'편지를 많이 받아서',N'글씨가 예뻐서',N'달팽이가 빨리 와서',N'처음으로 친구에게 편지를 받아서',N'4',N'03',N'',N'S'),
	 (13,N'01',N'05',N'이 책의 큰 주제는 무엇인가요?',NULL,N'남녀 사이의 사랑',N'형제 사이의 우애',N'친구 사이의 우정',N'가족 간의 사랑',N'3',N'04',N'',N'S'),
	 (13,N'01',N'06',N'개구리는 어떤 성격인가요?',N'개구리가 말했어요. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (13,N'01',N'11',N'밑줄 친 윗도리의 뜻으로 알맞은 것을 찾으세요.',N'두꺼비의 <u>윗도리</u> 단추 하나가 없어졌어요.',N'아래 입는 옷',N'위에 입는 옷',N'안에 입는 옷',N'잘 때 입는 옷',N'2',N'06',N'Y',N'S'),
	 (13,N'01',N'12',N'‘우정’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'형제 사이의 마음',N'가족을 사랑하는 마음',N'친구 사이의 깊은 마음',N'혼자 있는 것이 좋은 마음',N'3',N'06',N'',N'S'),
	 (14,N'01',N'01',N'소나무 잎은 어떤 모양인가요?',N'',N'바늘과 같이 날카롭고 좁다.',N'둥글고 넓다.',N'울퉁불퉁하다.',N'납작하고 부드럽다.',N'1',N'01',N'',N'S'),
	 (14,N'01',N'02',N'곰에 대한 설명으로 알맞지 않은 것은 무엇인가요?',N'',N'반달가슴곰은 도토리, 머루, 다래, 산딸기 같은 열매를 먹는다.',N'불곰은 식물의 뿌리나 열매, 곤충이나 물고기를 먹는다.',N'먹다 남은 고기는 그냥 버린다.',N'곰은 열매도 먹는다',N'3',N'01',N'',N'S'),
	 (14,N'01',N'03',N'흰색 털 토끼의 대부분이 빨간 눈을 가진 이유는 무엇일까요?',N'',N'눈에도 색소가 없는 흰색 토끼는 눈 안쪽에 있는 빨간색 피가 그대로 보여서',N'눈에서 피가 나서',N'흰색 토끼는 눈의 색깔을 마음대로 바꿀 수 있어서',N'눈이 햇빛에 약해서',N'1',N'04',N'',N'S'),
	 (14,N'01',N'04',N'다람쥐가 쉬지 않고 딱딱한 걸 갉아 대는 이유는 무엇인가요?',N'',N'딱딱한 걸 갉아 내는 것이 재미있기 때문에',N'계속 자라는 이빨을 닳게 하기 위해서',N'이빨을 날카롭게 만들면 다른 동물과 싸울 때 유리하기 때문에',N'소리를 내려고',N'2',N'04',N'',N'S'),
	 (14,N'01',N'05',N'빈칸에 들어갈 알맞은 단어는 무엇일까요?',N'도롱뇽 알은 투명하고 젤리처럼 (           )하기 때문에 바위나 나뭇가지 등에 잘 붙어요.',N'씩씩',N'뾰족뾰족',N'두리번두리번',N'말랑말랑',N'4',N'02',N'Y',N'S'),
	 (14,N'01',N'06',N'다음 중 여우가 사냥개를 따돌리는 방법이 아닌 것은 무엇일까요?',N'',N'갑자기 옆으로 2~3미터씩 비껴 뛰기도 한다.',N'호랑이 울음소리를 흉내 낸다.',N'더러운 거름통에 발을 담가 냄새를 감춰 버린다.',N'나무 위로 도망가기',N'2',N'02',N'',N'S'),
	 (14,N'01',N'07',N'표고버섯은 어떤 나무를 좋아하나요?',N'',N'소나무',N'밤나무',N'사과나무',N'감나무',N'2',N'07',N'',N'S'),
	 (14,N'01',N'08',N'빈칸에 들어갈 알맞은 단어는 무엇일까요?',N'무덤을 단단히 다지기 위해 뿌리는 ‘(     )가루’는 할미꽃을 더 잘 자라게 해 준대요.',N'잿',N'유화',N'모래',N'석회',N'4',N'06',N'Y',N'S');
