INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (16,N'01',N'05',N'비둘기와 개미에게 어떤 말을 해 줄 수 있을까요?',NULL,N'“도움을 받고 은혜를 갚는 모습이 정말      감동적이야.”',N'"부지런한 자세를 배워야겠어.”',N'“항상 노력하는 모습이 정말 훌륭해.”',N'"혼자서도 잘 지내는 게 중요해."',N'1',N'04',N'',N'S'),
	 (16,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점은 무엇인가요?',NULL,N'힘이 센 동물이 가장 중요해요.',N'어려울 때는 모른 척해야 해요.',N'도움을 받으면 다시 도와줄 수 있어요.',N'위험한 일에는 가까이 가지 말아야 해요.',N'3',N'04',N'',N'S'),
	 (16,N'01',N'07',N'농부는 어떤 마음이었을까요?',N'농부는 모자를 물고 온 독수리에게 인사를 했어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (17,N'01',N'03',N'거미가 사람들에게 도움이 되는 까닭은 무엇인가요?',NULL,N'8개의 다리로 곳곳을 깨끗하게 닦아 주기 때문에',N'파리, 모기처럼 해로운 벌레를 없애 주기 때문에 ',N'거미줄로 실을 만들어 옷을 입을 수 있게 해주기 때문에',N'사람을 물지 않기 때문에',N'2',N'03',N'',N'S'),
	 (17,N'01',N'04',N'거미가 거미줄을 이용해 먹이를 잡을 수 있는 이유는 무엇인가요?',NULL,N'거미줄이 끈적거려서',N'거미줄이 눈에 잘 보여서',N'거미줄이 아주 무거워서',N'거미줄이 소리가 나서',N'1',N'03',N'',N'S'),
	 (17,N'01',N'05',N'이 책을 읽고 느낀 점을 올바르게 말한 것을 찾으세요.',NULL,N'거미도 소중한 생명이니 함부로 해치지 않아야겠어.',N'거미는 사람에게 도움이 되지 않는 쓸모없는 존재야.',N'알을 등에 업고 다니는 거미는 정말 욕심꾸러기 같아.',N'거미는 모두 무서운 동물인 것 같아.',N'1',N'04',N'',N'S'),
	 (17,N'01',N'06',N'이 책을 통해 우리가 가져야 할 마음가짐으로 알맞은 것은 무엇인가요?',NULL,N'보기 싫은 동물은 없애도 된다는 마음',N'무서운 동물은 피하기만 하면 된다는 마음',N'곤충은 모두 해롭다는 생각',N'작은 생명도 소중히 여기는 마음',N'4',N'04',N'',N'S'),
	 (17,N'01',N'07',N'알을 등에 업고 새끼를 보살피는 거미의 마음은 어떨까요?',NULL,N'새끼가 귀찮고 싫은 마음',N'새끼가 무섭고 도망치고 싶은 마음',N'새끼를 걱정하고 소중히 여기는 마음',N'새끼 때문에 속상하고 슬픈 마음',N'3',N'05',N'',N'S'),
	 (17,N'01',N'08',N'사람들이 거미가 벌레를 잡아 준다는 사실을 알게 되었을 때 어떤 마음이 들까요?',NULL,N'화가 나고 짜증 나는 마음',N'고맙고 안심되는 마음',N'부끄럽고 숨고 싶은 마음',N'심심하고 따분한 마음',N'2',N'05',N'',N'S'),
	 (17,N'01',N'09',N'다음 문장에 어울리는 꾸며주는 말을 찾아 보세요.',N'거미는 물고기를 잡는 (         ) 거미줄을 사용해서 먹이를 잡아요. ',N'그물만큼',N'그물보다',N'그물처럼',N'그물 아래',N'3',N'02',N'Y',N'S'),
	 (17,N'01',N'10',N'다음 중 거미가 조심스레 움직이는 모습을 잘 나타낸 말은 무엇인가요?',NULL,N'살금살금',N'쿵쾅쿵쾅',N'반짝반짝',N'데굴데굴',N'1',N'02',N'',N'S'),
	 (17,N'01',N'11',N'유쾌하고 활발하다''는 뜻의 어휘는 무엇인가요?',NULL,N'조용하다',N'우울하다   ',N'명랑하다',N'침착하다',N'3',N'06',N'',N'S'),
