	 (19,N'01',N'07',N'부벨라가 날아가는 열기구를 잡았을 때 알맞은 아이들의 마음을 찾아보세요.',N'',N'아쉬움',N'섭섭함',N'의아함',N'고마움',N'4',N'04',N'',N'S'),
	 (19,N'01',N'08',N'착륙할 때 부벨라가 잃어버린 것은 무엇인가요?',N'',N'다이아몬드 목걸이',N'호박 목걸이',N'나무 목걸이',N'돌 목걸이',N'2',N'03',N'',N'S'),
