INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (20,N'01',N'04',N'거인의 정원에 다시 봄이 찾아온 이유는 무엇인가요?',NULL,N'북풍과 서리와 우박이 지쳐서 사라졌기 때문에',N'거인이 봄을 간절히 기다렸기 때문에',N'아이들이 다시 정원에 돌아왔기 때문에',N'거인이 꽃을 심었기 때문에',N'3',N'03',N'',N'S'),
	 (20,N'01',N'05',N'거인은 자신의 정원을 내주면서 아이들을 통해 무엇을 깨달았을까요?',NULL,N'자신이 가진 것을 나눌 때 더 큰 행복이 찾아온다는 사실 ',N'정원의 꽃보다 아이들이  더 맑고 순수하다는 사실 ',N'정원은 봄보다 겨울이 훨씬 더 아름답다는 사실',N'정원은 혼자 써야 한다는 사실',N'1',N'04',N'',N'S'),
	 (20,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'좋은 것은 혼자만 가져야 한다.',N'나눔은 손해가 된다.',N'아이들은 항상 시끄럽다.',N'함께 나누면 모두가 행복해질 수 있다.',N'4',N'04',N'',N'S'),
	 (20,N'01',N'07',N'거인은 어떤 마음이었을까요?',N'"그동안 내가 나밖에 몰랐구나. 왜 정원에 봄이 오지 않았는지 이제 알았어."',N'봄이 온 걸 안타까워하는 마음',N'자신의 행동을 뉘우치는 마음',N'정원이 마음에 들어 기쁜 마음',N'아이들이 싫어진 마음',N'2',N'05',N'Y',N'S'),
	 (20,N'01',N'08',N'거인이 아이들과 함께 정원에서 놀 때 어떤 마음이 들었을까요?',NULL,N'화가 나고 짜증 나는 마음',N'외롭고 쓸쓸한 마음',N'따뜻하고 기쁜 마음',N'무섭고 걱정되는 마음',N'3',N'05',N'',N'S'),
	 (20,N'01',N'09',N'문장에 어울리는 흉내 내는 말을 찾아보세요.',N'"거기서 뭣들 하는 거야?"
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (21,N'01',N'02',N'헤어진 견우와 직녀가 일 년에 단 한 번 만날 수 있는 날은 언제인가요?',NULL,N'8월 15일',N'7월 7일 ',N'1월 1일 ',N'12월 31일',N'2',N'01',N'',N'S'),
	 (21,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 견우와 직녀는 다리를 건너서 다시 만나게 되어 눈물을 흘렸어요.
(2) 화가 난 하늘나라 임금은 견우와 직녀에게 벌을 내렸어요.
(3) 견우와 직녀가 일을 하지 않아 하늘나라 사람들이 많은 불편을 겪었어요.',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(1)-(3)-(2)',N'1',N'03',N'Y',N'S'),
	 (21,N'01',N'04',N'견우와 직녀가 서로 만날 수 없었던 이유는 무엇인가요?',NULL,N'은하수가 가로막고 있었기 때문에 ',N'견우가 소를 몰다가 늦었기 때문에',N'직녀가 베를 짜다가 손을 다쳤기 때문에',N'하늘나라 사람들이 말렸기 때문에',N'1',N'03',N'',N'S'),
	 (21,N'01',N'05',N'견우와 직녀는 벌을 받으며 어떤 점을 반성하고 있을까요?',NULL,N'서로에게 약속을 지키지 않은 점',N'자신이 할 일을 제대로 하지 않은 점',N'동물의 생명을 함부로 대한 점',N'거짓말을 한 점',N'2',N'04',N'',N'S'),
	 (21,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'하고 싶은 일만 해도 괜찮아요.',N'벌을 받지 않게 숨겨야 해요.',N'슬플 때는 아무것도 하지 않아도 돼요.',N'자기 할 일은 책임지고 해야 해요.',N'4',N'04',N'',N'S'),
	 (21,N'01',N'07',N'다리를 본 견우와 직녀는 어떤 마음이었을까요?',NULL,N'슬프고 외로움',N'놀랍고 실망함  ',N'반갑고 고마움',N'화나고 속상함',N'3',N'05',N'',N'S'),
	 (21,N'01',N'08',N'임금님은 어떤 목소리로 말했을까요?',N'“너희 둘을 함께 지내도록 놔둘 수가 없구나.
