	 (22,N'01',N'11',N'다음 중 반대되는 의미의 단어로 짝지어진 것 중 올바르지 않은 것은 무엇인가요?',N'',N'후하다-박하다',N'풍년-흉년',N'존경심-동경심',N'많다-적다',N'3',N'06',N'',N'S'),
	 (22,N'01',N'12',N'‘마음이 어질고 자애롭다’를 무엇이라고 하나요?',N'',N'동정하다',N'인자하다',N'엄격하다',N'공손하다',N'2',N'06',N'',N'S'),
	 (23,N'01',N'01',N'혁이가 불편한 곳은 어디인가요?',N'',N'다리',N'팔',N'허리',N'어깨',N'1',N'01',N'',N'S'),
