	 (33,N'01',N'03',N'구운몽을 읽고 추측한 것 중 틀린 것은 무엇인가요?',N'',N'지윤: 아마 작가는 인생의 덧없음을 말하려고 했던 것 같아.',N'재민: 환생은 불교의 윤회사상을 담은 것 아닐까.',N'신준: 성진과 팔선녀에게 처벌을 내린 염라대왕의 처사는 너무했어.',N'지훈: 꿈에서 깨어난 양소유는 수양을 게을리 하지 않았을 거야.',N'3',N'04',N'',N'S'),
	 (33,N'01',N'04',N'양소유가 감옥에 갇히게 된 이유는 무엇인가요?',N'',N'황제의 토벌 명령을 어겨서',N'황제의 혼사 명령을 거절해서',N'정사를 게을리해서',N'스승의 예언을 어겨서',N'2',N'01',N'',N'S'),
	 (33,N'01',N'05',N' 다음 예시를 읽고 대화한 것 중 잘못된 것은 무엇인가요?',N'액자식 구성 : 외부 이야기에 내부 이야기를 결합한 구성 방식. ',N'정희: 아하! 구운몽의 내부 이야기는 성진이 환생하는 부분이겠구나!',N'지민: 그러면 외부 이야기는 현실 세계일거야.',N'호찬: 외부이야기를 A, 내부이야기를 B라 하면 소설의 구성은 B-A-B이구나.',N'성주: 꿈을 통해 내부 이야기를 이끌어가고 있어.',N'3',N'07',N'Y',N'S'),
	 (33,N'01',N'06',N'다음 빈칸에 어울리는 단어는 무엇인가요?',N'황태후: 자네를 부마로 (  ) 하시네.',N'채택하려',N'선정하려',N'간택하려',N'선택하려',N'3',N'02',N'Y',N'S'),
	 (33,N'01',N'07',N'다음 예시의 사건을 시간 순서대로 나열한 것은 무엇인가요?',N'A: 성진이 양소유로 환생함. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (33,N'01',N'12',N'다음 예시에 어울리는 사자성어를 무엇인가요?',N'성진: 부귀영화도 다 덧없고 부질없구나!',N'등화가친(燈火可親)',N'일장춘몽(一場春夢)',N'경국지색(傾國之色)',N'사고무친(四顧無親)',N'2',N'06',N'Y',N'S'),
	 (33,N'01',N'13',N'혼인하기에 알맞은 나이''를 뜻하는 단어는 무엇인가요?',N'',N'혼사(婚事)',N'혼절(昏絶)',N'혼기(婚期)',N'혼몽(昏懜)',N'3',N'07',N'N',N'S'),
	 (33,N'01',N'14',N'단어의 뜻이 올바른 것은 무엇인가요?',N'',N'도리: 윗사람이 아랫사람에게 시킨 일',N'기상: 타고난 기개나 마음씨',N'혼담: 혼인식을 가리키는 말',N'가상: 지나간 일이나 때',N'2',N'06',N'',N'S'),
	 (33,N'01',N'15',N'은혜와 뜻이 다른 것은 무엇인가요?',N'',N'자비(慈悲)',N'긍휼(矜恤)',N'관용(寬容)',N'혜택(惠澤)',N'3',N'06',N'',N'S'),
	 (34,N'01',N'01',N'쌍둥이 몰루와 차가이는 몇 살인가요?',N'',N'10살',N'8살',N'13살',N'9살',N'1',N'01',N'',N'S'),
	 (34,N'01',N'02',N'아빠가 말씀하신 말의 뜻은 무엇인가요?',N' "눈물은 사람을 약하게 만든단다. 우는 사람은 자기 목숨조차 구할 수 없단다."',N'"너희들의 눈물은 소중하단다."',N'"힘들어도 울지말고 어려움을 해결하자."',N'"우는 사람은 누구나 빨리 죽는단다."',N'"약한 사람은 오래 못 산단다."',N'2',N'04',N'Y',N'S'),
	 (34,N'01',N'03',N'쌍둥이와 헤어지기 전, 엄마가 용기의 물약을 마신 까닭은 무엇인가요?',N'',N'용기의 물약이 몸에 좋아서',N'용기의 물약은 쉽게 구할 수 없는 귀한 약이기 때문에',N'사랑하는 아이들과 쉽게 작별하기가 어려워서',N'병이 있어서',N'3',N'04',N'',N'S'),
	 (34,N'01',N'04',N'적군을 피해 왔던 할아버지집도 안전하지 않자, 엄마는 쌍둥이에게 어디에 가야한다고 했나요? ',N'',N'국경을 넘어 다른 나라에 살고 있는 마르와리 삼촌집',N'원래 살았던 마을과 집',N'이웃마을 외할머니 집',N'피난소',N'1',N'01',N'',N'S'),
	 (34,N'01',N'05',N'삼촌 집에 가기전에 쌍둥이가 가야하는 곳은 어디인가요?',N'"(     )에 가면 너희처럼 목숨을 건지기 위해 자기가 살고 있던 마을과 도시에서 도망나온 사람들이 많을거야."',N'빈민촌',N'부촌',N'병원',N'난민촌',N'4',N'07',N'Y',N'S'),
	 (34,N'01',N'06',N'국경을 넘는 쌍둥이에게 주술사 할머니가 준 것이 아닌 것은 무엇인가요?',N'',N'작은 뼈',N'작은 돌',N'작은 벌레',N'작은 나뭇가',N'3',N'07',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (34,N'01',N'07',N'난민촌을 찾아가던 쌍둥이가 했던 행동이 바르게 짝지어진 것은 무엇인가요?',N'',N'사자를 만났을 때 - 손을 잡고 사자들 사이로 지나갔다.',N'군인을 만났을 때 -  돌을 던진 뒤 바위 사이에 숨었다.',N'하이에나를 만났을 때 - 크게 소리를 지르며 뛰어갔다.',N'하이에나를 만났을 때 - 나뭇가지를 던졌다.',N'1',N'03',N'',N'S'),
	 (34,N'01',N'08',N'차가이가 불안하거나 걱정될 때마다 했던 습관은 무엇인가요?',N'',N'손톱 물어뜯기',N'코 후비기',N'입술 물어뜯기',N'어깨를 움츠림',N'1',N'02',N'',N'S'),
	 (34,N'01',N'09',N'난민촌에서 몇달간 생활했던 쌍둥이에 대한 사실을 잘못 말한 것은 누구인가요?',N'',N'예진: 물루는 난민촌에 처음왔을 때 거기서 살고싶지 않다고 했어.',N'소희: 쌍둥이는 난민촌 학교에서 농사하는 법을 배웠어.',N'현수:  난민촌에 온지 몇달 뒤 쌍둥이는 삼촌을 만날 수 있었어.',N'소희: 쌍둥이는 엄마 아빠를 만나지 못했어.',N'2',N'03',N'',N'S'),
	 (34,N'01',N'10',N'''이를 딱딱 맞부딪히다''의 사용이 어색한 문장은 무엇인가요?',N'',N'그들은 두려움에 이를 딱딱 맞부딪혔다.',N'자기전에 편안해서 이를 딱딱 맞부딪혔다.',N'너무 추워서 이가 딱딱 맞부딪혔다.',N'무서워서 이를 맞부딪혔다.',N'2',N'02',N'',N'S'),
	 (34,N'01',N'11',N'‘전쟁이나 가난으로 어려움을 겪는 사람’을 뜻하는 단어는 무엇인가요?',N'',N'시민',N'평민',N'난민',N'유랑자',N'3',N'06',N'',N'S'),
	 (34,N'01',N'12',N'물루와 차가이는 몇날 며칠을 걸어서 국경을 넘어요. 국경(國境)의 뜻은 무엇인가요? ',N'',N'나라의 경사스럽고 축하할 일',N'한 나라를 구성하는 사람',N'나라와 나라를 구분하는 경계',N'나라를 사랑하는 마음',N'3',N'06',N'',N'S'),
	 (35,N'01',N'01',N'가족들이 모여서 누구의 집을 만들고 있나요?',N'',N'병만이',N'만만이',N'동만이',N'아빠',N'2',N'01',N'',N'S'),
	 (35,N'01',N'02',N'만만이 집에 들어온 동만이가 베고 누운 것은 무엇인가요?',N'',N'병만이 배',N'만만이 배',N'베개',N'책',N'1',N'01',N'',N'S'),
	 (35,N'01',N'03',N'우리나라 천연기념물이자 귀신을 쫓는 개로 알려진 용감하고 영리한 개는 무엇인가요?',N'',N'시츄',N'삽살개',N'도베르만',N'진돗개',N'2',N'07',N'',N'S'),
	 (35,N'01',N'04',N'내가 침대에서 일어난 까닭은 무엇인가요?',N'',N'만만이를 집에 넣어 주고 오려고',N'화장실에 가고 싶어서',N'배가 고팠기 때문에',N'무서워서',N'1',N'04',N'',N'S');
