	 (35,N'01',N'05',N'빈칸에 어울리는 말을 찾아보세요.',N'걸을 때도 (            ) 살금살금.',N'코끼리처럼',N'뱀처럼',N'고양이처럼',N'토끼처럼',N'3',N'02',N'Y',N'S'),
	 (35,N'01',N'06',N'일이 일어난 순서대로 나열해보세요.',N'(1) 병만이와 동만이가 만만이 집으로 들어갔다.
(2) 병만이와 동만이가 만만이를 보러 마당으로 나갔다.
(3) 마당에서 만만이와 마주쳤다.',N'(1)-(2)-(3)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(3)-(1)-(2)',N'3',N'03',N'Y',N'S'),
	 (35,N'01',N'07',N'만만이가 꼬리를 흔들고, 주둥이로 손등을 핥은 까닭은 무엇인가요?',N'',N'너무 추워서',N'귀신을 보았기 때문에',N'병만이와 동만이가 나오니까 좋아서',N'무서워서',N'3',N'03',N'',N'S'),
	 (35,N'01',N'08',N'물건이나 자리가 보드랍고 따뜻하다는 뜻은 무엇인가요?',N'',N'근사하다',N'포근하다',N'날카롭다',N'따갑다',N'2',N'06',N'',N'S'),
	 (35,N'01',N'09',N'처음에는 무섭게 느껴졌던 감나무 잎소리가 나중에는 어떤 소리처럼 들렸나요?',N'',N'휘파람 소리',N'고기 굽는 소리',N'파도 소리',N'바람 소리',N'3',N'02',N'',N'S'),
	 (35,N'01',N'10',N'마지막에 병만이에게 든 생각은 무엇인가요?',N'',N'그래도 귀신은 무섭다.',N'감나무 집으로 이사오길 정말 잘했다.',N'만만이를 산책시켜 줘야겠다.',N'만만이는 겁쟁이야.',N'2',N'04',N'',N'S'),
	 (35,N'01',N'11',N'농가의 창고나 헛간 등지에 설치하는 말과 소를 기르는 장소는 어디인가요?',N'',N'헛간',N'대장간',N'푸줏간',N'외양간',N'4',N'07',N'N',N'S'),
	 (35,N'01',N'12',N'병만이와 동만이가 만만이 보고 귀신보고 놀라는 장면은 어떤 속담과 비슷한가요?',N'',N'같은 값이면 다홍치마',N'황소 뒷걸음치다 쥐 잡는다.',N'자라보고 놀란 가슴 솥뚜껑보고 놀란다.',N'콩 심은 데 콩 나고 팥 심은 데 팥 난다',N'3',N'06',N'',N'S'),
	 (36,N'01',N'01',N'민구네 집엔 동네에 하나뿐인 무엇이 있었나요?',NULL,N'전축',N'텔레비전',N'전화기',N'라디오',N'2',N'01',N'',N'S'),
	 (36,N'01',N'02',N'민구가 자신의 집에 오지 말라고 했을 때, 창수는 어떻게 행동했나요?',NULL,N'민구에게 딴 구슬을 몽땅 내밀었어요.',N'화를 내며 민구에게 따졌어요.',N'동생을 데리고 레슬링을 보러갔어요.',N'집에 그냥 돌아갔어요.',N'1',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (36,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 민구는 심술이 나서 창수에게 집에 오지 말라고 얘기했어요.
(2) 창수는 민구네 집에 가서 텔레비전 소리를 들었어요.
(3) 김일 선수가 상대 선수를 쓰러뜨리자 사람들의 환호성이 터져 나왔어요. ',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(2)-(1)-(3)',N'1',N'03',N'Y',N'S'),
	 (36,N'01',N'04',N'민구와 창수가 다시 웃을 수 있었던 이유는 무엇인가요?',NULL,N'창수가 먼저 사과했기 때문에',N'민구 아버지가 혼냈기 때문에',N'텔레비전이 고장 나지 않았기 때문에',N'레슬링 시합에서 우리나라 선수가 이겼기 때문에',N'4',N'03',N'',N'S'),
	 (36,N'01',N'05',N'옛날 사람들이 텔레비전을 보는 풍경과 오늘날 사람들이 텔레비전을 보는 풍경은 어떻게 다른 것 같나요?',NULL,N'옛날에는 화면이 작은 텔레비전을 봤고 요즘에는 무조건 대형 화면으로 텔레비전을 봐요.',N'요즘은 거실에 앉아 가족끼리 텔레비전을 보지만 옛날에는 마을 사람들이 한데 모여 텔레비전을 봤어요.',N'요즘은 자신이 보고 싶을 때 텔레비전을 보지만 옛날에는 강제로 텔레비전을 봐야 했어요.',N'옛날에는 텔레비전이 흔해서 집집마다 있었고, 요즘에는 마을 사람들이 한데 모여서 봐요.',N'2',N'04',N'',N'S'),
	 (36,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'좋은 것은 혼자만 가져야 한다.',N'친구와 다툰 뒤에는 더 크게 싸워야 한다.',N'함께 즐거움을 나누면 더 기쁘다.',N'남의 물건은 몰래 사용해도 된다.',N'3',N'04',N'',N'S'),
	 (36,N'01',N'07',N'창수의 마음은 어땠을까요?',N'사람들이 지지직대는 화면을 안타깝게 바라봤어. 창수는 뜨끔해서 엄마 옆에 바짝 붙어 앉았지.',N'후련하고 기쁜 마음',N'불안하고 조마조마한 마음',N'걱정스럽고 슬픈 마음',N'신나고 즐거운 마음',N'2',N'05',N'Y',N'S'),
	 (36,N'01',N'08',N'민구와 다시 함께 웃게 되었을 때, 창수의 마음은 어땠을까요?',NULL,N'겁이 나고 무서운 마음',N'서운하고 속상한 마음',N'화가 난 마음',N'기쁘고 후련한 마음',N'4',N'05',N'',N'S'),
	 (36,N'01',N'09',N'다음 빈칸에 들어갈 알맞은 표현을 찾으세요.',N'아이들이 마당 위에서 (      ) 뛰어 다녔어.',N'펄럭펄럭',N'팔랑팔랑',N'팔딱팔딱',N'팔락팔락',N'3',N'02',N'Y',N'S'),
