INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (43,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 형과 아우는 금덩이를 버리고 예전처럼 사이좋게 지냈어요. 
(2) 아우가 돌부리에 걸려서 넘어지고 말았어요.
(3) 잔칫집에 가는 길에 아우가 수풀 속에서 무언가를 발견했어요. ',N'(3)-(2)-(1)',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'1',N'03',N'Y',N'S'),
	 (43,N'01',N'04',N'배에 오른 형이 금덩이를 강물에 던진 이유는 무엇인가요?',NULL,N'실수로 손에서 놓쳤기 때문에',N'아우가 금을 먼저 발견했기 때문에',N'금이 형제 사이를 갈라놓는다고 생각했기 때문에',N'강물이 깊어서 숨기려고 했기 때문에',N'3',N'03',N'',N'S'),
	 (43,N'01',N'05',N'형과 아우가 계속 서로의 금덩이를 탐냈다면 결국 어떻게 되었을까요?',NULL,N'더 많은 금덩이를 찾기 위해 힘을 합쳐 움직였을 거예요. ',N'부자가 되어 예전처럼 사이좋게 지낼 수 있을 거예요.',N'서로를 믿지 못하고 우애가 깨졌을 거예요.',N'더 커다란 금을 얻을 수 있었을 거예요.',N'3',N'04',N'',N'S'),
	 (43,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'돈이 있으면 무엇이든 해결된다.',N'욕심은 사이좋은 마음을 망칠 수 있다.',N'형제는 항상 경쟁해야 한다.',N'중요한 것은 많이 가지는 것이다.',N'2',N'04',N'',N'S'),
	 (43,N'01',N'07',N'형과 아우는 어떤 마음이었을까요?',N'형과 아우는 서로 딴마음을 먹고 흘금흘금 곁눈질을 했어요. 눈치를 살피느라 앞서거니 뒤서거니 했지요.',N'억울하고 슬퍼요.',N'화가 나고 마음이 어수선해요.',N'미안하고 부끄러워요.',N'기쁘고 설레요.',N'2',N'05',N'Y',N'S'),
	 (43,N'01',N'08',N'형이 금덩이를 강물에 던진 뒤 형과 아우의 마음은 어땠을까요?',NULL,N'속이 후련하고 편안한 마음',N'여전히 화가 난 마음',N'겁이 나고 두려운 마음',N'부자가 되고 싶은 마음',N'1',N'05',N'',N'S'),
	 (43,N'01',N'09',N'빈칸에 들어갈 흉내내는 말을 찾아보세요.',N'갑작스런 소식에 사람들의 마음이 (      ) 했어요.',N'출렁출렁',N'일렁일렁',N'술렁술렁',N'반짝반짝',N'3',N'02',N'Y',N'S'),
	 (43,N'01',N'10',N'다음 상황에 가장 어울리는 말은 무엇인가요?',N'형과 아우는 가진 것이 많지 않았지만, 누구보다 서로를 아끼고 생각했어요.',N'눈이 휘둥그레질 만큼',N'발이 닳도록',N'입이 딱 벌어질 만큼',N'콩 한쪽도 나누어 먹을 만큼',N'4',N'02',N'Y',N'S'),
	 (43,N'01',N'11',N'나무들이 무성하게 우거져 있는 것''을 가리키는 낱말을 찾아보세요.',NULL,N'잡초',N'수풀',N'나뭇잎',N'꽃다발',N'2',N'06',N'',N'S'),
	 (43,N'01',N'12',N'‘우애’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'서로 미워하는 마음',N'형제나 가족 사이의 정다운 마음',N'많은 재산을 갖고 싶은 마음',N'혼자만 잘되려는 마음',N'2',N'06',N'',N'S');
