	 (51,N'01',N'05',N'고기잡이''에서 화자의 고향을 유추할 수 있는 것은 무엇인가요?',N'',N'바다',N'산',N'강',N'도시',N'1',N'01',N'N',N'S'),
	 (51,N'01',N'06',N'김득신이 ''대장간''을 김홍도의 ''대장간'' 그림과 다르게 그린 이유는 무엇인가요?',N'',N'차별화를 두기 위해서',N'초라하고 힘 없는 모습의 그림이 싫어서',N'자신의 것으로 만들려고',N'주목을 받기 위해서',N'2',N'04',N'N',N'S'),
	 (51,N'01',N'07',N'다음 중 사군자가 아닌 것은 무엇인가요?',N'',N'매화',N'대나무',N'소나무',N'국화',N'3',N'07',N'N',N'S'),
	 (51,N'01',N'08',N'활쏘기''에서 김홍도는 왼발과 오른발을 바꾸어 그린 이유는 무엇인가요?',N'',N'왼손잡이라서',N'다른 그림처럼 실수해서',N'서툰 활솜씨를 강조하려고',N'왼발이 앞서는 것은 죄로 처벌받기 때문에',N'3',N'03',N'N',N'S'),
	 (51,N'01',N'09',N'이 책을 잘 이해한 학생은 누구인가요?',N'도영: 김홍도의 그림은 쉽고 재밌어. 특히 사실적이라 기억에 잘 남아.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (51,N'01',N'15',N'숭유억불(崇儒抑佛)''의 뜻은 무엇인가요?',N'',N'불교를 높이고 유교를 억누르다.',N'유교를 높이고 불교를 억누르다.',N'유교만큼 불교도 숭배하자.',N'유교는 숭고하고 불교는 억울하다.',N'2',N'06',N'N',N'S'),
	 (52,N'01',N'01',N'할아버지는 양털에서 뽑은 털실로 무엇을 만들었나요?',NULL,N'양들이 덮고 자는  이불을 만들었어요. ',N'뜨개질을 해서 양말과 목도리, 모자 등을 만들었어요. ',N'양치기 개 폴로에게 신발을 만들어 주었어요 ',N'양 우리를 멋지게 꾸몄어요.',N'2',N'01',N'',N'S'),
	 (52,N'01',N'02',N'폴로가 까만 아기 양을 못마땅하게 생각한 까닭은 무엇인가요?',NULL,N'까만 아기 양이 움직이지 않고 먹는 것만 좋아해서',N'다른 양들과 달리 까만 아기 양이 자신의 말을 듣지 않아서',N'할아버지가 자신보다 까만 아기 양만 좋아해서',N'까만 아기 양이 병이 들어서',N'2',N'01',N'',N'S'),
	 (52,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 얼마 후, 할아버지는 색이 모두 다른 특별한 양떼를 갖게 되었어요. 
(2) 다음날 아침, 밤새 내리던 눈이 그쳤어요.
(3) 알프스 산의 변덕꾸러기 날씨가 심술을 부렸어요.',N'(2)-(1)-(3)',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (52,N'01',N'04',N'눈보라가 거세게 몰아치자 할아버지와 폴로는 어떻게 했나요?',NULL,N'오두막으로 들어가 눈보라를 피했어요. ',N'눈보라를 맞으며 양들을 지켰어요.',N'양들에게 가만히 있으라고 소리쳤어요.',N'동굴로 숨어들었어요.',N'1',N'03',N'',N'S'),
	 (52,N'01',N'05',N'하얀 털을 가지고 싶어하던 까만 아기 양은 할아버지의 칭찬을 통해 무엇을 깨달았을까요?',N'"오 기특하구나, 네가 아니었으면 양들을 찾지 못했을 거야. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (52,N'01',N'10',N'다음 문장에 어울리는 표현을 찾아보세요.',N'눈보라 속에서도 양들은 서로 꼭 붙어 있었어요.',N'옹기종기',N'듬성듬성',N'띄엄띄엄',N'데굴데굴',N'1',N'02',N'Y',N'S'),
	 (52,N'01',N'11',N'밑줄 친 말과 비슷한 뜻을 가진 어휘를 찾아보세요.',N'"내가 할 일이지, 네가 <u>참견</u>할 일이 아니야!"',N'방관',N'간섭',N'참고',N'양보',N'2',N'06',N'Y',N'S'),
	 (52,N'01',N'12',N'뉘우치다''의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'잘한 일을 자랑하다',N'기분이 좋아 웃다',N'잘못한 일을 돌아보며 미안해하다',N'무서워서 숨다',N'3',N'06',N'',N'S'),
	 (53,N'01',N'01',N'아프리카의 수많은 사람들이 굶어 죽거나 병에 걸려 죽어갔던 이유는 무엇인가요?',NULL,N'흉년으로 인해 먹을 것이 없었기 때문이에요.',N'오랫동안 전쟁을 치렀기 때문이에요.',N'대규모 지진이 일어났기 때문이에요.',N'병원이 없었기 때문이에요.',N'2',N'01',N'',N'S'),
	 (53,N'01',N'02',N'한상기 박사님이 카사바 뿌리를 연구했던 이유는 무엇이었나요?',NULL,N'아프리카 사람들이 카사바를 배불리 먹게 하기 위해서예요.',N'한국에서 카사바 재배에 성공하기 위해서예요.',N'카사바 뿌리로 약재를 만들기 위해서예요.',N'카사바를 팔아서 돈을 벌기 위해서예요.',N'1',N'01',N'',N'S'),
	 (53,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 성스러운 추장 왕이 박사님의 머리에 이코코 나뭇가지를 꽂아 주었어요.
(2) 콩고의 카사바 밭을 쑥밭으로 만든 벌레의 정체를 알아냈어요.
(3) 한상기 박사님은 밭에 나가 카사바 뿌리를 연구했어요.',N'(2)-(3)-(1)',N'(3)-(1)-(2)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'3',N'03',N'Y',N'S'),
	 (53,N'01',N'04',N'카사바 밭을 쑥밭으로 바꾼 면충을 없앨 수 있었던 이유는 무엇인가요?',NULL,N'카사바 재배를 포기했기 때문이에요.',N'농약을 많이 뿌렸기 때문이에요.',N'날씨가 좋아졌기 때문이에요.',N'면충의 천적인 기생충을 이용했기 때문이에요.',N'4',N'03',N'',N'S'),
	 (53,N'01',N'05',N'한상기 박사님의 어떤 점이 가장 대단하다고 느껴지나요?',NULL,N'머나먼 아프리카에 가서도 대한민국을 위해 애쓴 점이 대단해요.',N'연구를 열심히 해서 아프리카의 의학 발전에 도움을 준 점이 대단해요.',N'아프리카 사람들과 함께 어울려 가족처럼 지낸 모습이 멋졌어요.',N'유명해지려고 혼자서만 연구한 점이 대단해요.',N'2',N'04',N'',N'S'),
	 (53,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'어려운 곳에서는 아무것도 할 수 없다.',N'다른 사람을 돕는 일은 큰 용기가 필요하다.',N'공부는 자기만을 위해 해야 한다.',N'외국 사람은 믿을 수 없다.',N'2',N'04',N'',N'S'),
	 (53,N'01',N'07',N'늙은 농부는 어떤 마음이었을까요?',N'"고맙습니다, 박사님! 그 소식을 전하러 이 먼 길을 오시다니요......"
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (53,N'01',N'08',N'아프리카 사람들이 박사님을 추장으로 모시며 어떤 마음이었을까요?',NULL,N'억지로 따르는 마음',N'고맙고 믿음이 가는 마음',N'무섭고 두려운 마음',N'아무 관심 없는 마음',N'2',N'05',N'',N'S'),
	 (53,N'01',N'09',N'다음 문장에 어울리는 표현을 찾아보세요.',N'서로 눈치만 살피던 사람들이 앞으로 나섰습니다. ',N'쭈뼛쭈뼛',N'올망졸망',N'졸래졸래',N'소곤소곤',N'1',N'02',N'Y',N'S'),
	 (53,N'01',N'10',N'빈칸에 어울리는 흉내 내는 말을 찾아보세요.',N'어느덧 붉은 해가 (       ) 지고 있었습니다.',N'덜컹덜컹',N'옹기종기',N'졸래졸래',N'뉘엿뉘엿',N'4',N'02',N'Y',N'S'),
	 (53,N'01',N'11',N'식물에서 나온 씨 또는 씨앗을 가리키는 낱말을 찾아보세요.',NULL,N'수확',N'종자',N'개량',N'비료',N'2',N'06',N'',N'S'),
	 (53,N'01',N'12',N'다음 중 ‘추장’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'마을에서 가장 힘이 센 사람',N'전쟁에서 싸우는 군인',N'한 부족이나 마을을 이끄는 어른',N'나라에서 가장 키가 큰 사람',N'3',N'06',N'',N'S'),
	 (54,N'01',N'01',N'초등학교에 들어간 찬호가 가장 기뻤던 사실은 무엇인가요?',NULL,N'샛별초등학교 이름이 마음에 든 것',N'아파트 친구들과 같은 반이 된 것 ',N'좋아하는 고은이랑 같은 반이 된 것 ',N'새 가방을 받은 것',N'3',N'01',N'',N'S'),
	 (54,N'01',N'02',N'며칠 뒤 억수가 학교에 지각한 이유는 무엇인가요?',NULL,N'꽃밭에 난 풀을 뽑고 오느라고',N'흙탕물에 젖은 옷을 갈아입고 오느라고',N'땅콩 장사 할머니의 땅콩을 주워드린다고',N'길을 잃어 다시 찾느라고',N'3',N'01',N'',N'S'),
	 (54,N'01',N'03',N'억수가 지각했는데도 선생님께 혼나지 않은 까닭은 무엇인가요?',NULL,N'일부러 늦게 왔기 때문에',N'억수가 착한 일을 하고 왔기 때문에',N'공부를 잘했기 때문에',N'친구들이 대신 변명해 줬기 때문에',N'2',N'03',N'',N'S'),
	 (54,N'01',N'04',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 선생님은 작고 예쁜 별을 억수에게 달아 주었어요.
(2) 할머니는 교실로 찾아와 억수에게 땅콩 한 봉지를 주고 가셨어요.
(3) 찬호는 고은이에게 생일 초대장을 받아 기뻤어요.',N'(1)-(3)-(2) ',N'(2)-(1)-(3)',N'(3)-(2)-(1)  ',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (54,N'01',N'05',N'찬호의 잘못은 무엇인가요?',N'억수는 옷도 싸구려만 입는 데다 자주 빨지도 않는 것 같았어요.
