	 (55,N'01',N'04',N'빈칸에 들어갈 수 없는 말은 무엇인가요?',N'아빠는 무슨 대단한 일이나 한 사람처럼 (            )하게 말했습니다. ',N'의기양양',N'위풍당당',N'의기소침',N'당당',N'3',N'02',N'Y',N'S'),
	 (55,N'01',N'05',N'’아나바다 운동‘의 뜻으로 알맞은 것은 무엇인가요?',N'',N'아껴 쓰고, 나눠 쓰고, 바꿔 쓰고, 다시 쓰자.',N'아껴 쓰고, 나만 쓰고, 바꿔 쓰고, 다시 쓰자.',N'아껴 쓰고, 나눠 쓰고, 바꿔 쓰고, 다시는 쓰지 말자.',N'아끼지 말고, 나만 쓰고, 바꾸지 말자',N'1',N'07',N'',N'S'),
	 (55,N'01',N'06',N'벼룩시장에 대한 설명으로 알맞지 않은 것은 무엇인가요?',N'',N'자기가 쓰지 않는 물건을 필요한 사람에게 싸게 판다.',N'다른 사람의 물건과 바꾼다.',N'자신이 샀던 가격보다 더 높게 판다.',N'필요한 물건을 저렴하게 살 수 있다.',N'3',N'07',N'',N'S'),
	 (55,N'01',N'07',N'억수가 비 오는 날 지렁이를 화단으로 옮긴 이유는 무엇인가요?',N'',N'지렁이가 보기 흉해서',N'사람들이 다니는 길은 위험하기 때문에',N'장난치려고',N'지렁이를 키우려고',N'2',N'01',N'',N'S'),
	 (55,N'01',N'08',N'아이들이 우르르 억수의 곁으로 모여든 이유는 무엇인가요?',N'',N'억수가 새 운동화를 사서',N'억수가 지렁이를 교실에 가져와서',N'억수가 접으면 로켓 모양이 되는 필통을 가지고 있어서',N'억수가 간식을 나눠줘서',N'3',N'04',N'',N'S'),
	 (55,N'01',N'09',N'찬호가 벼룩시장을 싫어하는 이유는 무엇인가요?',N'',N'벼룩시장에서 고장 난 물건을 사서',N'가격이 바싸다고 생각해서',N'엄마가 벼룩시장에 가지 말라고 해서',N'남이 쓰던 헌 물건은 더럽다고 생각해서',N'4',N'04',N'N',N'S'),
	 (55,N'01',N'10',N'다음이 설명하는 단어는 무엇인가요?',N'“억수? 아, 그 착하고 (      )한 애!” 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (56,N'01',N'02',N'한국말 노래를 듣고 궁금해 하는 노에미에게 진주는 어떻게 해 주었나요?',NULL,N'노랫말 뜻을 설명해 주었어요.',N'한국말을 모른다고 핀잔을 주었어요.',N'이제 인형을 가지고 놀자고 했어요.',N'노래를 그만 부르자고 했어요.',N'1',N'01',N'',N'S'),
	 (56,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 저녁이 되자, 밥을 먹기위해 모두 모였어요..
(2) 노에미가 진주네 집에 놀러 왔어요.
(3) 노에미는 포크를 사용해 저녁밥을 배불리 먹었어요.',N'(3)-(1)-(2)',N'(2)-(1)-(3)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'2',N'03',N'Y',N'S'),
	 (56,N'01',N'04',N'노에미가 김치를 먹고 물을 찾게 된 이유는 무엇인가요?',NULL,N'배가 너무 고팠기 때문에',N'김치가 맵다는 것을 몰랐기 때문에',N'젓가락질이 어려웠기 때문에',N'음식이 차가웠기 때문에',N'2',N'03',N'',N'S'),
	 (56,N'01',N'05',N'한국에서 온 진주와 프랑스 소녀 노에미를 칭찬하는 말로 가장 올바른 것을 찾으세요.',NULL,N'“동물을 사랑하는 마음을 본받아야겠어.”',N'“힘든 일이 있어도 끈기 있게 이겨내는      모습이 정말 대단해!”',N'“서로 다른 점을 이해하고 친구가 된 점이 정말 감동이야!”',N'"새로운 것을 거절하고 익숙한 것을 지키려는 모습이 멋져!"',N'3',N'04',N'',N'S'),
	 (56,N'01',N'06',N'진주가 노에미에게 한국 문화를 알려 준 이유로 알맞은 것은 무엇인가요?',NULL,N'자랑하고 싶어서',N'노에미를 시험해 보고 싶어서',N'혼자만 알고 싶어서',N'친구에게 친절하게 대해 주고 싶어서',N'4',N'04',N'',N'S'),
	 (56,N'01',N'07',N'노에미는 어떤 마음이었을까요?',N'"호호, 매워요! 물 좀 주세요!"
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
