	 (60,N'01',N'08',N'예시를 읽고 기찬이가 들었던 감정을 찾아보세요.',N'기찬이는 어리둥절 했어요. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (61,N'01',N'02',N'꼬마 아가씨는 소년에게 준 것은 무엇인가요?',N'',N'꽃신',N'댕기',N'장갑',N'비단 옷',N'1',N'01',N'',N'S'),
	 (61,N'01',N'03',N'다음에 들어갈 수 있는 말은 무엇일까요?',N'꼬마 아가씨는 가마에서 내렸어. (           ) 아가씨는 오른쪽 다리를 절며 거지 소년에게 걸어가',N'쌩쌩',N'으쓱으쓱',N'절뚝절뚝',N'살금살금',N'3',N'02',N'Y',N'S'),
	 (61,N'01',N'04',N'거지 소년이 신발 만드는 법을 배우고 싶은 이유는 무엇인가요?',N'',N'어른들이 권유했기 때문에',N'신발을 만들어 팔면 돈을 많이 벌 수 있어서',N'예쁜 신발을 만들어 신고 싶어서',N'편안한 신발을 만들어 주고 싶은 사람이 있어서',N'4',N'03',N'',N'S'),
	 (61,N'01',N'05',N'당초무늬는 어떤 무늬를 의미할까요?',N'',N'꽃무늬',N'덩굴무늬',N'구름무늬',N'물결무늬',N'2',N'07',N'',N'S'),
	 (61,N'01',N'06',N'노인들이 신기에 편한 신은 무엇일까요?',N'',N'태사혜',N'징신',N'발막신',N'운혜',N'3',N'07',N'',N'S'),
	 (61,N'01',N'07',N'정성을 다해 신발을 만들던 주인공은 사람들의 무엇을 사랑하게 되었나요?',N'',N'발',N'손',N'다리',N'무릎',N'1',N'02',N'',N'S'),
	 (61,N'01',N'08',N'주인공이 아가씨의 걸음을 보기와 같이 생각한 까닭은 무엇인가요?',N'사랑하는 사람을 생각하면 가벼워졌다가 자신을 생각하면 다시 무거워지는 걸음이다.',N'꼿꼿하게 바른 자세로 걸어서',N'한쪽 다리를 절며 걸어서',N'근심걱정이 많은 얼굴이라서',N'걸음걸이가 너무 빨라서',N'2',N'04',N'Y',N'S'),
	 (61,N'01',N'09',N'아가씨는 어떤 바람을 가지고 있나요?',N'',N'한 달 뒤의 혼례식 때만이라도 다리를 절뚝거리지 않고 똑바로 걸을 수 있으면 좋겠다.',N'다리가 하루아침에 깨끗이 다 나으면 좋겠다.',N'누가 항상 자신을 업고 다녀 줬으면 좋겠다.',N'아픈 다리가 더 이상 다른 사람 눈에 띄지 않기를 바랐다.',N'1',N'04',N'',N'S'),
	 (61,N'01',N'10',N'주인공은 앞으로 어떤 신을 만들겠다고 다짐했나요?',N'',N'사람들의 마음을 헤아릴 수 있는 신',N'비싸게 팔 수 있는 신',N'좋은 재료를 사용하는 신',N'유행에 맞는 신',N'1',N'03',N'',N'S'),
	 (61,N'01',N'11',N'다음이 설명하는 단어는 무엇일까요?',N'예전에, 가죽신을 만드는 일을 직업으로 하던 사람.',N'사또',N'갖바치',N'보부상',N'역관',N'2',N'06',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (61,N'01',N'12',N'다음의 상황에서 사용된 ‘울타리’는 어떤 의미일까요?',N'가죽위에 비단을 붙이고 울타리를 한 땀 한 땀 정성스레 꿰맸어.',N'신발의 가장자리 둘레',N'풀이나 나무 따위를 얽거나 엮어서 담 대신에 경계를 지어 막는 물건',N'적이 들어오거나 범인이 도망가는 것을 막기 위하여 설정한 지대',N'땅속을 깊게 판 다음 은엄폐해서 보이지 않게 만든 덫',N'1',N'06',N'Y',N'S'),
	 (62,N'01',N'01',N'너구리가 슬퍼하며 울었던 까닭은 무엇인가요?',NULL,N'원숭이에게 바나나를 빼앗겨서',N'여우에게 집을 빼앗겨서',N'토끼에게 꿀독을 빼앗겨서',N'사자에게 혼나서',N'2',N'01',N'',N'S'),
	 (62,N'01',N'02',N'달리기에서 1등을 한 여우가 상품으로 받은 것은 무엇인가요?',NULL,N'꿀 독',N'바나나',N'대포',N'메달',N'1',N'01',N'',N'S'),
	 (62,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 여우는 1등을 했지만 결국 꿀독에 빠지고 말았어요.
(2) 숲속 나라 달리기 대회가 시작 되었어요.
(3) 여우는 다른 친구들에게 부탁해 방해작전을 펼쳤어요.',N'(2)-(1)-(3)',N'(3)-(1)-(2)',N'(2)-(3)-(1)',N'(1)-(3)-(2)',N'3',N'03',N'Y',N'S'),
	 (62,N'01',N'04',N'사자 대왕이 체육대회를 연 까닭은 무엇인가요?',NULL,N'누가 빠른지 알아보기 위해',N'서로 친해지기 위해',N'누가 힘이 센지 겨루기 위해',N'상품을 나누어 주기 위해',N'2',N'03',N'',N'S'),
	 (62,N'01',N'05',N'등장인물의 성격을 <u>잘못</u> 이야기한 것을 찾아보세요.',NULL,N'너구리-본인의 잘못을 인정하고 고치려 한 점은 정말 용기있어.',N'곰- 슬퍼하는 친구를  위로해준 걸 보니 마음이 따뜻해.',N' 여우-친구를 속이고 괴롭히다니 자기밖에 모르는 것 같아. ',N'사자-모두가 사이좋게 지내길 바라는 왕이야.',N'1',N'04',N'',N'S'),
	 (62,N'01',N'06',N'이 책을 읽고 알게 된 교훈을 올바르게 말한 것을 찾아보세요.',NULL,N'서로 배려하고 이해하는 마음이 있어야 좋은 친구가 될 수 있다.',N'어려운 이웃을 도와 함께 행복하게 살아야 한다.',N'규칙을 잘 지켜야 질서있는 사회를 만들 수 있다.',N'힘이 세고 빠르면 무엇이든 이길 수 있다.',N'1',N'04',N'',N'S'),
	 (62,N'01',N'07',N'여우는 어떤 마음이었을까요?',N'"아이고, 따가워 여우 살려!"
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (62,N'01',N'10',N' 빈칸에 어울리는 표현을 찾아보세요.',N'곰이 묻자 너구리는 아니라며 (       ).',N'머리를 설레설레 흔들었어요.',N'발을 쿵쿵 굴렀어요.',N'손을 번쩍 들었어요.',N'크게 소리쳤어요.',N'1',N'02',N'Y',N'S'),
	 (62,N'01',N'11',N'자기가 하고도 하지 않은 체하다''라는 뜻이 완성되도록 빈칸에 들어갈 알맞은 어휘를 찾아 보세요.',N'(        )를 떼다.',N'멍청이',N'시치미',N'동치미',N'시금치',N'2',N'06',N'Y',N'S'),
	 (62,N'01',N'12',N'꾀가 많다''는 말의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'힘이 아주 세다.',N'달리기를 아주 잘한다.',N'친구를 잘 도와준다.',N'생각을 많이 하여 좋은 계획을 세운다.',N'4',N'06',N'',N'S'),
	 (63,N'01',N'01',N'25살의 나이차이를 극복하고 워런 버핏과 진정한 우정을 나눈 친구는 누구인가요?',N'',N'앙리 뒤낭',N'알프레드 노벨',N'빌 게이츠',N'앤드류 카네기',N'3',N'01',N'',N'S'),
	 (63,N'01',N'02',N'노벨의 어린 시절 꿈은 무엇인가요?',N'',N'노동자들을 위한 노동법을 개정하는 것',N'안전한 폭약을 만드는 것',N'전 세계의 주인이 되는 것',N'위대한 발명품으로 부자가 되는 것',N'2',N'01',N'',N'S'),
	 (63,N'01',N'03',N'노벨이 다이너마이트를 발명하고 후회했던 이유는 무엇인가요?',N'',N'노벨의 화약이 전쟁의 무기로 사용되었기 때문에',N'아무도 자신의 발명을 알아주지 않아서',N'다이너마이트를 발명하다가 자신의 건강이 악화되었기 때문에',N'노벨이 다이너마이트를 만들었을때는 이미 전쟁이 끝났기 때문에',N'1',N'04',N'',N'S'),
	 (63,N'01',N'04',N'카네기의 홈스테드 사건을 설명한 것으로 옳지 않은 것은 무엇인가요?',N'',N'카네기의 비도덕적인 행위에 불만을 가진 노동자들은 파업을 벌였고, 그런 노동자들을 강제로 해산시키는 과정에서 노동자가 죽는 일이 벌어지기도 했어.',N'카네기는 생산비를 줄이기 위해 노동자들에게 형편없는 임금을 지급하면서 노동자 문제가 커지기 시작했어.',N'개별 임금의 인상보다는 공익을 위한 기부 행위가 더 바람직하다고 주장한 카네기의 의견에 동의한 시민들이 카네기 동상을 세웠어.',N'“부자는 사회에 환원해야 한다”고 말했지만 자신 회사의 노동자에게는 가혹한 환경을 제공했던 모순을 보여준다.',N'3',N'03',N'',N'S'),
	 (63,N'01',N'05',N'백성 천 백여 명을 구제한 김만덕에게 임금이 소원을 들어준다고 하자 김만덕의 대답으로 옳은 것은 무엇인가요?',N'',N'딱 한가지 소원이 있습니다. 저희 마을 사람들 모두가 서울로 올라와 호의호식하며 살 수 있게 도와주는 것이 소원입니다.',N'다른 소원은 없습니다. 오로지 서울에 올라가 임금이 계시는 궁궐을 우러러 뵙고, 금강산 일만 이천봉을 둘러보는 것이 소원입니다.',N'소원은 없습니다. 이대로 충분히 행복합니다.',N'제가 제주도를 떠나 서울에서 살아갈 수 있도록 땅과 집을 마련해 주십시오.',N'2',N'01',N'',N'S'),
	 (63,N'01',N'06',N'다음 괄호 안에 들어갈 표현으로 적절한 것은 무엇인가요?',N'주변 사람들의 걱정은 (  )이 아니었지요.',N'이만저만',N'도란도란',N'둥실둥실',N'주렁주렁 ',N'1',N'02',N'Y',N'S'),
	 (63,N'01',N'07',N'자유법조단에 대한 설명으로 옳은 것은 무엇인가요?',N'',N'자유법조단은 일본의 제국주의적인 역사관을 바꾸기 보다는 받아들이는 입장이야',N'자유법조단은 일본 정부의 역사 왜곡을 비판하지 않고 연구하는 사람들이야',N'자유법조단은 일제 강점기에 후세 다츠지가 만든 변호사들의 모임이야',N'자유법조단은 일제 강점기 동안 부당하게 적용되던 법과 제도를 바르게 고치기 위해 만들어진 모임이야',N'3',N'04',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (63,N'01',N'08',N'윈턴에 대한 설명으로 옳지 않은 것은 무엇인가요?',N'',N'윈턴은 아이들을 살린 일을 스스로 자랑스럽게 여기며 자신이 한 일을 온 세상에 알리려고 노력했어',N'윈턴은 미처 구하지 못한 250명의 생명을 안타까워하며 자신이 한 일은 ''자랑할 것이 없는 일''이라고 말했어',N'윈턴 덕분에 살아남은 669명의 아이들은 호호백발의 노인이 되어서도 여전히 자신들을 ''윈턴의 아이들''이라고 부르고 있어',N'윈턴은 50년 동안 자신의 선행을 숨긴 ‘보이지 않는 진짜 영웅’이라고 할 수 있어',N'1',N'03',N'',N'S'),
	 (63,N'01',N'09',N'노블레스 오블리주에 대한 설명으로 옳은 것은 무엇인가요?',N'',N'노블레스 오블리주는 저소득층을 위한 노동 환경 개선책 중 하나예요',N'노블레스 오블리주는 사회 고위층에 요구되는 높은 도덕적 의무를 말해요',N'노블레스 오블리주는 시민들에게 주어지는 세금 혜택이에요',N'노블레스 오블리주는 권력을 가진 사람들이 특권을 더 많이 누려야 한다는 뜻이에요',N'2',N'01',N'',N'S'),
	 (63,N'01',N'10',N'어떤 행동이나 이론 따위에서 일관되게 지켜야 하는 기본적인 규칙이나 법칙을 뜻하는 단어는 무엇인가요?',N'',N'원칙 (原則)',N'견책 (譴責)',N'묘책 (妙策)',N'변칙 (變則)',N'1',N'06',N'',N'S'),
	 (63,N'01',N'11',N'다음 괄호 안에 들어갈 표현으로 적절한 것은 무엇인가요?',N'은근히 속이 (   )끓었지만, 기분 상한 티를 내고 싶지 않았다.',N'간질간질',N'부글부글',N'찰싹찰싹',N'몽글몽글 ',N'2',N'02',N'Y',N'S'),
	 (63,N'01',N'12',N'열 가운데 여덟이나 아홉 정도로 거의 대부분이거나 거의 틀림없음을 뜻하는 말로 적절한 것은 무엇인가요?',N'',N'인간대사(人間大事)',N'혼전신성(昏定晨省)',N'십중팔구 (十中八九)',N'학수고대(鶴首苦待)',N'3',N'07',N'',N'S'),
	 (63,N'01',N'13',N'어떤 견해나 의견에 같은 생각을 가지는 것을 의미하는 단어는 무엇인가요?',N'',N'정감 (精鑑)',N'동감 (同感)',N'교감 (交感)',N'동질 (同質)',N'2',N'07',N'',N'S'),
	 (63,N'01',N'14',N'마음이나 상황 따위를 뒤흔들어서 어지럽고 혼란하게 하는 것을 무엇이라고 하나요?',N'',N'무리(無理)',N'교배(交配)',N'교란(攪亂)',N'위증(僞證)',N'3',N'06',N'',N'S'),
	 (63,N'01',N'15',N'다음 괄호 속에 들어갈 말로 적절한 것은 무엇인가요?',N'나는 글 쓰는 거 딱 (  )이다. 몹시 싫어하거나 꺼리다.',N'질색(窒塞)',N'질척',N'사색(思索)',N'절교(絶交)',N'1',N'06',N'Y',N'S'),
	 (64,N'01',N'01',N'7번 애벌레의 별명은 무엇인가요?',NULL,N'무당 벌레',N'무늬 애벌레',N'나비 애벌레',N'점박이 애벌레',N'2',N'01',NULL,N'S'),
	 (64,N'01',N'02',N'형님 애벌레들이 7번 애벌레에게 인간을 조심하라고 한 이유는 무엇인가요?',NULL,N'인간들은 작은 생명에게 관심이 없다고 생각해서',N'인간에게 잡아먹힌 애벌레를 봐서',N'인간들이 항상 사랑해줘서',N'인간은 곤충을 관찰해서',N'1',N'03',NULL,N'S');
