INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (65,N'01',N'01',N'다음은 나를 위한 어떤 행동에 대한 설명인가요?',N'(1) 손톱이 자라면 깎아줘요.
(2) 헝클어진 머리를 빗으로 빗어요.
(3) 상처가 나면 약을 발라요.',N'내 마음이 하는 말 듣는 일 ',N'내 몸을 돌보아 주는 일 ',N'내가 잘하는 것 아는 일',N'친구를 도와주는 일',N'2',N'01',N'Y',N'S'),
	 (65,N'01',N'02',N'위험한 곳에서 내 몸을 지키는 방법이 <u>아닌</u> 것은 무엇인가요?',NULL,N'내리막길에서 뛰어 다녀요.',N'건널목에서 차 조심을 해요.    ',N'높은 데는 함부로 올라가지 않아요.',N'보호자의 말을 잘 들어요.',N'1',N'01',N'',N'S'),
	 (65,N'01',N'03',N'일이 일어난 차례대로 나열한 것을 고르세요.',N'(1) 나는 내가 어떤 사람이 되고 싶은지 생각해요.
(2) 나는 내가 무엇을 잘 하는지 알아요. 
(3) 나는 내 몸을 잘 돌보아 주어요.',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(1)-(2)-(3)',N'(3)-(1)-(2)',N'1',N'03',N'Y',N'S'),
	 (65,N'01',N'04',N'나는 마음의 주인이기 때문에 화가 날 때 어떻게 해야 하나요?',NULL,N'엄마에게 소리치며 화풀이해요.',N'화난 기분이 나아지도록 노력해요.',N'물건을 던져 망가뜨려요.',N'친구에게 화를 내요.',N'2',N'03',N'',N'S'),
	 (65,N'01',N'05',N'사람들이 내 몸과 마음을 다치게 할 때 가장 바른 행동은 무엇인가요?',NULL,N'나도 똑같이 그 사람을 함부로 대해요.',N'겁이 나서 아무 말도 못하고 울어요.',N'“싫어요, 하지마세요”라고 용기 있게 말해요.',N'혼자 참고 아무에게도 말하지 않아요.',N'3',N'04',N'',N'S'),
	 (65,N'01',N'06',N'스스로가 자기 자신의 주인이 되려면 어떤 마음을 가져야 할까요?',NULL,N'다른 사람과 비교하며 속상해해요.',N'자신을 사랑하고 존중하는 마음을 가져요.',N'다른 사람 입장보다 항상 ''나 자신이 먼저’라는 생각을 가져요. ',N'혼자서만 잘하려는 마음을 가져요.',N'2',N'04',N'',N'S'),
	 (65,N'01',N'07',N'나’는 어떤 마음일까요?',N'나는 아빠랑 자전거 타는 것을 좋아합니다.
