	 (72,N'01',N'05',N'숲을 지킬 수 있는 방법을 올바르게 말한 것을 찾으세요.',NULL,N'골프장을 많이 지어 푸른 잔디밭을 만들어요.',N'그린벨트 지역을 풀어서 주택을 많이 지어요.  ',N'산불로 소중한 자연 자원을 잃어 버리지 않도록 불조심을 해요. ',N'숲에 쓰레기를 많이 버려요.',N'3',N'04',N'',N'S'),
	 (72,N'01',N'06',N'이 책을 읽고 우리가 가져야 할 태도로 알맞은 것은 무엇인가요?',NULL,N'숲은 필요할 때마다 없애도 된다.',N'나무보다 건물이 더 중요하다.',N'숲은 동물만을 위한 곳이다.',N'숲을 소중히 여기고 지켜야 한다.',N'4',N'04',N'',N'S'),
	 (72,N'01',N'07',N'아마존에 살고 있는 동물들은 어떤 마음일까요?',N'"숲이 점점 사라져서 산소가 부족해.  
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (73,N'01',N'02',N'‘나’가 학교에 가는 것이 걱정되었던 이유는 무엇인가요?',N'',N'선생님이 나만 미워하는 것 같아서',N'준비물을 살 돈을 다 써버려서',N'왕따를 당해서',N'친구가 놀릴까 봐',N'1',N'03',N'',N'S'),
	 (73,N'01',N'03',N'''나''가 과학 경진 대회에 나가려는 이유로 옳지 않은 것은 무엇인가요?',NULL,N'꿈이 과학자라서',N'칠판에 이름이 적히고 반 대표가 될 수 있어서',N'선생님에게 뭘 잘 하는지 보여 줄 수 있는 기회라서',N'착한 어린이표를 받고 싶어서',N'3',N'04',NULL,N'S'),
	 (73,N'01',N'04',N'자그마한 것들이 한곳에 많이 붙어 있는 모양으로, 다음 빈칸에 들어갈 알맞은 말은 무엇인가요?',N'노란색 스티커를 머리에 (           ) 붙여 주고 싶었지요.',N'알뜰살뜰',N'우물쭈물',N'살금살금',N'다닥다닥',N'4',N'02',N'Y',N'S'),
	 (73,N'01',N'05',N'‘나’가 수첩에 나쁜 선생님 표를 쓴 이유로 올바르지 않은 것은 무엇인가요?',N'',N'싸움은 지연이가 먼저 시작했어요!',N'고자질한 애한테는 착한 어린이 표를 줘야죠!',N'저도 발표 좀 시켜 주세요.',N'규칙을 마구 바꾸면 안 돼요.',N'2',N'07',N'',N'S'),
	 (73,N'01',N'06',N'폐품은 버리는 물건입니다. 폐품을 활용할 수 없는 상황은 무엇인가요?',N'',N'다 마신 우유팩에 흙을 넣어 식물을 기른다.',N'여기저기 흩어진 비누 조각을 녹여 하나의 비누로 만든다.',N'병원에서 앞의 환자가 썼던 바늘을 활용한다.',N'헌 옷을 모아 가방을 만든다.',N'3',N'07',N'',N'S'),
	 (73,N'01',N'07',N'비가 오는데 우산을 씌워준 사람은 누구인가요?',N'',N'지연이',N'민철이',N'은지',N'선생님',N'3',N'01',N'',N'S'),
	 (73,N'01',N'08',N'조금 느릿느릿 힘없는 걸음으로 걸어가는 모양을 무엇이라고 하나요?',N'',N'쿵쾅쿵쾅',N'살금살금',N'타박타박',N'꾸물꾸물',N'3',N'02',N'',N'S'),
	 (73,N'01',N'09',N'‘나’는 왜 스티커를 찢어 변기에 넣고 버렸나요?',N'',N'더 이상 나쁜 어린이표를 받기 싫어서',N'스티커의 색깔이 맘에 들지 않아서',N'선생님을 골탕 먹이려고',N'화가 나서',N'1',N'04',N'',N'S'),
	 (73,N'01',N'10',N'이 책을 잘 이해한 학생은 누구인가요?',N'',N'가영: 나쁜 어린이표는 착한 아이만 받는 거래.',N'민수: 착한 어린이는 나쁜 어린이표를 받지 않아.',N'수현: 선생님 기준만으로 아이를 판단하면 안 돼.',N'도윤: 책 내용은 그냥 장난으로 쓴 이야기야.',N'3',N'03',N'N',N'S'),
	 (73,N'01',N'11',N'건드리지 아니하여 조금도 축이 나거나 변하지 아니하고 그대로 온전한 상태를 무엇이라고 하나요?',N'',N'온종일',N'제대로',N'고스란히',N'깔끔히',N'3',N'06',N'',N'S');
