	 (74,N'01',N'10',N'사물을 분별하고 판단하여 아는 것을 무엇이라고 하나요?',N'',N'인식(認識)',N'신뢰(信賴)',N'맹세(盟誓)',N'지식(知識)',N'1',N'02',N'N',N'S'),
	 (74,N'01',N'11',N'허물이나 결함을 나무라거나 핀잔하는 것을 무엇이라고 하나요?',N'',N'야박하다',N'타박하다',N'혼쭐내다',N'거절하다',N'2',N'07',N'N',N'S'),
	 (74,N'01',N'12',N'코로 맡을 수 있는 나쁘지 않거나 향기로운 기운을 뜻하는 단어는 무엇인가요?',N'',N'향음',N'하음',N'내음',N'시음',N'3',N'07',N'N',N'S'),
	 (74,N'01',N'13',N'잘못되거나 부족하여 완전하지 못한 점을 무엇이라고 하나요?',N'',N'강점(强點)',N'결점(缺點)',N'손실(損失)',N'충족(充足)',N'2',N'06',N'N',N'S'),
	 (74,N'01',N'14',N'도망쳐 봐야 크게 벗어날 수 없다는 뜻을 가진 속담은 무엇인가요?',N'',N'우물 안 개구리',N'누워서 떡 먹기',N'뛰어 봤자 벼룩',N'티끌 모아 태산',N'3',N'02',N'N',N'S'),
	 (74,N'01',N'15',N'친절한 마음씨. 또는 좋게 생각하여 주는 마음을 무엇이라고 하나요?',N'',N'의리(義理)',N'불의(不義)',N'호의(好意)',N'숙명(宿命)',N'3',N'06',N'N',N'S'),
	 (75,N'01',N'01',N'마르카와 나의 다른 점은 무엇이었나요?',NULL,N'마르카는 교회에 다니고 나는 휴대교 회당에 다녔어요.',N'마르카는 키가 크고 나는 키가 작았어요.',N'마르카는 읽기를 잘하고 나는 달리기가 빨랐어요.',N'마르카는 노래를 잘하고 나는 그림을 잘 그렸어요.',N'1',N'01',N'',N'S'),
	 (75,N'01',N'02',N'벤치에 붙은 금속 표지판에는 무슨 내용이 적혀 있었나요?',NULL,N'어린아이는 앉을 수 없다고 적혀 있었어요.',N'기독교인은 앉을 수 없다고 적혀 있었어요.',N'유대인은 앉을 수 없다고 적혀 있었어요.',N'군인만 앉을 수 있다고 적혀 있었어요.',N'3',N'01',N'',N'S'),
	 (75,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 동생과 나는 추위와 공포에 떨었어요.
(2) 나는 보드리에게 전쟁이 끝났다고 말했어요.
(3) 군인들이 유대인들을 끌어내 한곳에 모아놨어요.',N'(3)-(1)-(2)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'1',N'03',N'Y',N'S'),
	 (75,N'01',N'04',N'보드리가 가족을 따라오자 군인들은 왜 발길질해 쫓아버렸을까요?',NULL,N'보드리가 시끄럽게 울어서',N'유대인과 함께하는 것을 허락하지 않았기 때문에',N'개를 무서워했기 때문에',N'기차에 탈 자리가 없어서',N'2',N'03',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (75,N'01',N'05',N'리비아와 ‘나’가 겪은 일을 계속 이야기하는 이유는 무엇인가요?',NULL,N'살아남은 것이 자랑스러워서',N'잘못 없는 사람이 다시는 죽임을 당하지 않기를 바라서',N'독일 사람들이 더 미워서',N'자신을 불쌍하게 보이게 하려고',N'2',N'04',N'',N'S'),
	 (75,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'힘이 있으면 다른 사람을 괴롭혀도 된다.',N'전쟁은 나라를 강하게 만든다.',N'약한 사람은 보호받지 못한다.',N'사람은 종교나 민족으로 차별 받아서는 안 된다.',N'4',N'04',N'',N'S'),
	 (75,N'01',N'07',N'나는 어떤 마음이었을까요?',N'나의 보드리가 안보일 때까지 나는 손을 흔들고 또 흔들었어요...... 나는 보드리가 나 없이 어떻게 지낼까 밤낮으로 생각했어요.',N'걱정스럽고 슬픈 마음',N'기대되고 설레는 마음',N'후련하고 시원섭섭한 마음',N'화가 나고 분한 마음',N'1',N'05',N'Y',N'S'),
	 (75,N'01',N'08',N'가족과 떨어져 수용소에 모여 있을 때 동생과 ‘나’의 마음은 어땠을까요?',NULL,N'즐겁고 신난 마음',N'무섭고 불안한 마음',N'자랑스럽고 뿌듯한 마음',N'아무 느낌 없는 마음',N'2',N'05',N'',N'S'),
	 (75,N'01',N'09',N'다음 문장에 어울리는 표현을 찾아보세요.',N'보드리는 너무 기뻐 온몸으로 울부짖었어요. 잠시 후 진정하고 자리에 앉더니, 눈물을 글썽이며 나를 한참 바라보았어요.',N'술렁술렁',N'일렁일렁',N'그렁그렁',N'번쩍번쩍',N'3',N'02',N'Y',N'S'),
	 (75,N'01',N'10',N'다음 문장에 어울리는 표현을 찾아보세요.',N'어느 날, 라디오에서 어떤 남자가 외치는 소리를 들었어요.',N'쩌렁쩌렁',N'반짝반짝',N'그렁그렁',N'살금살금',N'1',N'02',N'Y',N'S'),
	 (75,N'01',N'11',N'많은 사람들을 한곳에 가두어 모아두는 곳''을 가리키는 낱말을 찾아보세요.',NULL,N'보건소',N'수용소',N'목공소',N'공작소',N'2',N'06',N'',N'S'),
	 (75,N'01',N'12',N'다음 중 ‘차별’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'사람을 모두 똑같이 대하는 것',N'이유 없이 사람을 다르게 대하는 것',N'서로 도와주는 것',N'사이좋게 지내는 것',N'2',N'06',N'',N'S'),
	 (76,N'01',N'01',N'제제가 처음 라임오렌지나무를 만났을 때 어떤 심정이었나요?',N'',N'자신의 나무가 제일 특별하다고 생각했다.',N'자신이 세상에서 가장 재수없는 아이라고 생각했다.',N'자신과 나무가 꼭 닮았다고 생각했다.',N'자신이 부족한 것이 없는 가장 행복한 아이라고 생각했다.',N'2',N'01',N'N',N'S'),
	 (76,N'01',N'02',N'제제가 구두닦이로 번 돈으로 아버지를 위해 산 선물은 무엇인가요?',N'',N'담배',N'구두',N'모자',N'음식',N'1',N'01',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (76,N'01',N'03',N'또또가 형이 크리스마스 때 빵을 먹지 못한 이유는 무엇인가요?',N'',N'가족들 몰래 음식을 너무 많이 먹었기 때문에',N'배가 아픈 것을 제제에게 숨기려고',N'가난 때문에 힘들어하는 아버지가 마음에 걸려서',N'예전에 빵을 먹고 체한 기억이 있기 때문에',N'3',N'04',N'N',N'S'),
	 (76,N'01',N'04',N'제제가 구멍 난 검정 스타킹을 주운 이유는 무엇인가요?',N'',N'뱀의 모양과 닮아 장난 칠 수 있겠다는 생각이 들었기 때문에',N'밍기뉴의 나뭇가지에 묶어주려고',N'조금만 수선하면 쓸만 할 것 같아 누나에게 선물하려고',N'버려진 스타킹은 쓸모 없다고 생각했기 때문에',N'1',N'04',N'N',N'S'),
	 (76,N'01',N'05',N'제제는 자신의 마음 속에 무엇이 살고 있다고 믿고 있나요?',N'',N'작은 나무',N'작은 왕자',N'작은 새',N'작은 곤충',N'3',N'02',N'N',N'S'),
	 (76,N'01',N'06',N'쎄실리아 빠임 선생님이 착한 일을 한 제제에게 했던 말은 무엇인가요?',N'',N'황금 같은 마음씨를 가진 아이',N'별빛 같은 마음씨를 가진 아이',N'달빛 같은 마음씨를 가진 아이',N'햇볕같은 마음씨를 가진 아이',N'1',N'02',N'N',N'S'),
	 (76,N'01',N'07',N'브라질의 크리스마스가 여름인 이유는 무엇인가요?',N'',N'우리나라와 크리스마스 날짜가 다르기 때문에',N'브라질은 남반구에 있어 우리나라와 계절이 반대이기 때문에',N'브라질은 겨울이 없기 때문에',N'크리스마스를 더 즐겁게 즐기기 위해서',N'2',N'07',N'N',N'S'),
	 (76,N'01',N'08',N'뽀르뚜가의 뜻은 무엇인가요? ',N'',N'브라질 사람과 포르투갈 사람 사이에서 태어난 아이를 가리키는 말',N'포르투갈 사람을 낮춰 부르는 말',N'포르투갈의 영어 발음',N'브라질에서 쓰는 나무의 이름',N'2',N'07',N'N',N'S'),
	 (76,N'01',N'09',N'제제가 뽀르뚜가 아저씨에게 자신을 아들로 데려가 달라고 한 이유는 무엇인가요?',N'',N' 뽀르뚜가 아저씨가 자신의 아버지보다 더 똑똑해서',N'뽀르뚜가 아저씨의 차가 마음에 들어서',N'뽀르뚜가 아저씨는 자신의 심정을 누구보다 잘 이해해주고 공감해줘서',N'뽀르두가 아저씨가 아니면 더이상 살아갈 이유가 없다고 생각해서',N'3',N'03',N'N',N'S'),
	 (76,N'01',N'10',N'라임오렌지나무가 꽃을 피웠다는 것이 의미하는 것은 무엇인가요?',N'',N'제제가 더 이상 아프지 않을 것이란 것.',N'제제가 더 이상 밍기뉴를 반기지 않는다는 것',N'제제가 뽀르뚜가 아저씨를 완전히 잊었다는 것',N'제제가 한층 더 성숙해졌다는 것.',N'4',N'03',N'N',N'S'),
	 (76,N'01',N'11',N'백 번 쏘아 백 번 맞힌다는 뜻으로, 총이나 활 따위를 쏠 때마다 겨눈 곳에 다 맞음을 이르는 말은 무엇인가요?',N'',N'백발백중(百發百中)',N'백전노장(百戰老將)',N'백전백승(百戰百勝)',N'승승장구(乘勝長驅)',N'1',N'06',N'N',N'S'),
	 (76,N'01',N'12',N'가족들이 제제를 두고 한 말로,  ''도저히 돕거나 구하여 주는 것이 불가능한 사람. 또는 그런 상태''를 뜻하는 말은 무엇인가요?',N'',N'구사일생(九死一生)',N'구제불능(救濟不能)',N'전전긍긍(戰戰兢兢)',N'오리무중(五里霧中)',N'2',N'02',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (76,N'01',N'13',N' ''값은 나중에 치르기로 하고 물건을 사거나 파는 일''을 뜻하는 단어는 무엇인가요?',N'',N'외박(外泊)',N'외면(外面)',N'외상(外上)',N'외출(外出)',N'3',N'06',N'N',N'S'),
	 (76,N'01',N'14',N'아리오발두가 제제에게 했던 말로, 두 사람이 같이 노래를 부르는 것을 뜻하는 단어는 무엇인가요?',N'',N'솔로',N'듀오',N'트리오',N'합주',N'2',N'06',N'N',N'S'),
	 (76,N'01',N'15',N'말을 빨리 달리게 하기 위해 발로 차는 행위에서 유래된 것으로, 일이 빨리 진행되도록 힘을 더한다는 뜻을 나타내는 말은 무엇인가요?',N'',N'박차를 가하다',N'안간힘을 쓰다',N'박진감 넘치다',N'긴장감이 넘치다',N'1',N'06',N'N',N'S'),
	 (77,N'01',N'01',N'날라의 무사 귀환을 축하하는 자리에서 보언씨가 전한 소식은 무엇인가요?',N'',N'납치범이 도망갔다는 소식을 전했다.',N'납치범의 건강이 악화되었다는 소식을 전했다.',N'케냐 국민들이 반란을 일으켰다는 소식을 들었다.',N'케냐 국민들을 위한 재단을 설립했다는 소식을 전했다.',N'4',N'04',N'N',N'S'),
	 (77,N'01',N'02',N'날라의 엄마와 아빠가 만난 곳인 ''플라잉 닥터'' 단체가 하는 일이 아닌 것은 무엇인가요?',N'',N'비행기로 마을을 찾아 다니며 사람들에게 건강 검진과 백신을 투여하는 일을 해.',N'아픈 사람들을 도시로 이송하는 일을 해.',N'건물이 무너진 곳을 찾아 다니며 다시 건물을 세우는 일을 해.',N'죽어가는 사람들을 살리는 인도적 구호활동을 해',N'3',N'07',N'N',N'S'),
	 (77,N'01',N'03',N'날라가 얼리사의 데이터 조작을 의심한 것에 대해 대니얼이 해준 조언으로 옳지 않은 것은 무엇인가요?',N'',N'망설이지 말고 가서 이게 지금 뭐하는 짓이냐고 화내면서 혼쭐을 내야 해.',N'일단 그 사람에게 아주 정중한 태도로 이 실험 결과가 진짜인지 확신하지 못하겠다고 말해야 해.',N'우리가 잘못된 결과를 보고하지 않으려면 이 실험을 잠시 중단해야 한다고 말해야 해.',N'의심하기 보다는 증거를 확인하는 것을 우선으로 해야해',N'1',N'03',N'N',N'S'),
	 (77,N'01',N'04',N'학교 도서관에서 누군가 컴퓨터에 적어놓은 글귀가 큰 사건이 되었는데, 이 글귀는 무엇인가요?',N'',N'날라는 거짓말쟁이',N'흑인들이 죽든 말든 상관없음',N'백인들이 죽든 말든 상관없음',N'흑인이고 백인이고 죽든 말든 상관 없음',N'2',N'01',N'N',N'S'),
	 (77,N'01',N'05',N'날라가 도서관에서 일어난 사건을 그냥 넘어가려 하자 졸린이 화를 낸 이유는 무엇인가요?',N'',N'백인편을 드는 것 같아 화가 나서',N'선생님한테 이 사건을 비밀로 하는 것이 싫어서',N'날라가 이 사건의 범인이 사실 자신이라고 거짓말하며 넘어가려 해서',N'모든 사람들이 알고있는 사실을 자신에게만 숨긴다고 생각해서',N'1',N'03',N'N',N'S'),
	 (77,N'01',N'06',N'날라가 도서관 사건을 학교에 말하지 않고 자신만 알고 있으려고 한 이유는 무엇인가요?',N'',N'자신이 그 글귀를 적었기 때문에',N'백인편이 되고 싶어서',N'괜히 선생님께 이간질하는 것 같아서',N'흑인 편이 되고 싶어서',N'3',N'04',N'N',N'S'),
	 (77,N'01',N'07',N'잭슨은 날라가 드로실라 회장의 딸이 아님을 알고도 풀어주지 않은 이유는 무엇인가요?',N'',N'드로실라 회장과 날라가 엄청 친한 사이라고 생각해서',N'날라가 연구를 위해 필요할 것이기 때문에 자신의 요구를 들어줄 것이라 생각해서',N'날라와 함께 있다 보니 정이 들어서',N'회장의 딸은 아니지만 다른 쓸모가 있다고 생각했기 때문에',N'2',N'04',N'N',N'S');
