INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (84,N'01',N'08',N'방울토마토에 열매가 열린 것을 보았을 때 아영이의 마음은 어땠을까요?',NULL,N'화가 난 마음',N'지루한 마음',N'걱정되는 마음',N'기쁘고 뿌듯한 마음',N'4',N'05',N'',N'S'),
	 (84,N'01',N'09',N'빈칸에 어울리는 알맞은 흉내 내는 말을 찾아 보세요.',N'“봄바람이 (        ) 불어오니 방울토마토가 (        ) 고개를 움직여요.”',N'살랑살랑 - 흔들흔들',N'재잘재잘 - 엉금엉금 ',N'폴짝폴짝 - 소곤소곤',N'주룩주룩 - 끄덕끄덕',N'1',N'02',N'Y',N'S'),
	 (84,N'01',N'10',N'빈칸에 어울리는 알맞은 흉내 내는 말을 찾아 보세요.',N'얼른 말하고 싶어서 입이 (       ) 해요.',N'흔들흔들',N'꾸벅꾸벅',N'근질근질',N'그렁그렁',N'3',N'02',N'Y',N'S'),
	 (84,N'01',N'11',N'어떤 일을 성의 없이 대충 겉으로만 함''을 무엇이라고 하나요? ',NULL,N'경건',N'집중  ',N'건성',N'정성',N'3',N'06',N'',N'S'),
	 (84,N'01',N'12',N'‘정성’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'귀찮아하며 하는 마음',N'대충 넘기는 태도',N'다른 사람에게 맡기는 것',N'마음을 다해 애쓰는 것',N'4',N'06',N'',N'S'),
	 (85,N'01',N'01',N'활달하지만 수줍음을 많이 타는 아이는 무슨 동물과 비슷하나요?',NULL,N'고양이',N'강아지',N'병아리',N'원숭이',N'1',N'01',N'',N'S'),
	 (85,N'01',N'02',N'거북이 아이를 행복하게 하는 방법에는 무엇이 있을까요?',NULL,N'자유로운 환경을 만들어줘요.',N'서두르지 않아요.',N'빨리 하라고 다그쳐요.',N'계속 재촉해요.',N'2',N'01',N'',N'S'),
	 (85,N'01',N'03',N'일이 일어난 차례대로 순서대로 나열한 것을 찾으세요.',N'(1) 선생님은 학생들이 어떤 아이인지 궁금하다고 하셨어요.
(2) 세상에는 많은 아이들이 있고, 저마다 특성이 있어요.
(3) 아이들마다 행복하게 만드는 방법이 달라요.',N'(2)-(1)-(3)',N'(1)-(2)-(3)',N'(2)-(3)-(1)',N'(3)-(1)-(2)',N'3',N'03',N'Y',N'S'),
	 (85,N'01',N'04',N'이야기의 흐름으로 보아, 마지막에 전하려는 생각으로 알맞은 것은 무엇인가요?',NULL,N'아이들은 모두 똑같아야 해요.',N'아이들마다 성격이 다를 수 있어요.',N'아이들은 항상 활발해야 해요.',N'조용한 아이는 문제가 있어요.',N'2',N'03',N'',N'S'),
	 (85,N'01',N'05',N'저마다 다른 특성을 가진 아이들을 같은 방식으로 대한다면 어떤 일이 일어날까요?',NULL,N'아이들이 불행해질 거예요.',N'아이들이 행복해질 거예요.',N'아이들이 어른들을 존경하게 돼요.',N'아이들이 경쟁을 더 잘할 거예요.',N'1',N'04',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (85,N'01',N'06',N'이 책을 통해 우리가 배울 수 있는 가장 중요한 점은 무엇인가요?',NULL,N'친구를 모두 똑같이 대해야 해요.',N'아이마다 필요한 배려가 달라요.',N'조용한 아이는 바뀌어야 해요.',N'활발한 아이만 칭찬해야 해요.',N'2',N'04',N'',N'S'),
	 (85,N'01',N'07',N'나비 같은 아이를 함부로 대한다면 그 아이의 마음은 어떨까요?',NULL,N'두렵고 속상해요.',N'어색하고 설레요.',N'기쁘고 행복해요.',N'신나고 즐거워요.',N'1',N'05',N'',N'S'),
	 (85,N'01',N'08',N'자신의 성격을 이해 받았을 때 아이의 마음은 어떨까요?',NULL,N'불안해요.',N'화가 나요.',N'부끄러워요.',N'편안하고 기뻐요.',N'4',N'05',N'',N'S'),
	 (85,N'01',N'09',N'다음 문장에 어울리는 표현을 찾아보세요.',N'원숭이 아이는 언제나 엄마 옆에 붙어 있답니다.',N'찰싹',N'척척',N'줄줄',N'질질',N'1',N'02',N'Y',N'S'),
	 (85,N'01',N'10',N'빈칸에 어울리는 표현을 찾아보세요.',N'모기 같은 아이는 주변을 (      ) 돌아요.',N'뱅뱅',N'짝짝',N'슥슥',N'콕콕',N'1',N'02',N'Y',N'S'),
	 (85,N'01',N'11',N'어려움을 참고 견디는 마음''을 뜻하는 낱말을 찾아보세요.',NULL,N'경쟁심',N'조바심',N'인내심',N'질투심',N'3',N'06',N'',N'S'),
	 (85,N'01',N'12',N'서두르지 않다''와 가장 가까운 뜻을 가진 말은 무엇인가요?',NULL,N'재촉하다',N'다그치다',N'몰아붙이다',N'기다리다',N'4',N'06',N'',N'S'),
	 (86,N'01',N'01',N'사람들이 대도시로 몰려드는 이유는 무엇인가요?',NULL,N'공기 좋은 곳에서 살기 위해서예요.',N'일자리를 찾고 더 나은 교육을 받기 위해서예요.',N'자연과 더불어 살기 위해서예요.',N'농사를 짓기 위해서예요.',N'2',N'01',N'',N'S'),
	 (86,N'01',N'02',N'대도시의 인구수는 어떻게 변화하고 있나요?',NULL,N'인구수의 변화가 없어요.',N'갈수록 줄어들고 있어요.',N'갈수록 늘어나고 있어요.',N'갑자기 없어지고 있어요.',N'3',N'01',N'',N'S'),
	 (86,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 윤이는 아빠랑 상우네로 놀러갔어요.
(2) 윤이랑 형아는 대도시 탐험에 나섰어요.
(3) 윤이는 아름이와 고모를 따라 마을로 갔어요.',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(1)-(3)-(2)',N'3',N'03',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (86,N'01',N'04',N'아름이가 멀리 있는 학교를 다니게 된 이유는 무엇인가요?',NULL,N'아이들의 숫자가 줄어들어서 학교가 문을 닫았기 때문이에요.',N'공부를 더 열심히 하고 싶어서예요.',N'친구들이 모두 그 학교에 다녀서예요.',N'학교가 새로 생겼기 때문이에요.',N'1',N'03',N'',N'S'),
	 (86,N'01',N'05',N'상우와 아름이의 생활을 보고 알 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'모두 같은 곳에서 살아야 해요.',N'편리함만 있으면 충분해요.',N'자연만 있으면 불편해도 괜찮아요.',N'사람과 자연이 어울리는 삶이 중요해요.',N'4',N'04',N'',N'S'),
	 (86,N'01',N'06',N'이 책을 읽고 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'도시가 더 크면 무조건 좋은 곳이라는 것',N'사람 사는 곳마다 장단점이 있다는 것',N'마을보다는 도시가 더 재미있다는 것',N'친구는 가까이 살아야만 만날 수 있다는 것',N'2',N'04',N'',N'S'),
	 (86,N'01',N'07',N'윤이 아빠의 마음은 어땠을까요?',N'깜깜한 밤이 되어서야 윤이 아빠가 돌아왔어. 거리를 메운 자동차가 매연을 뿜어대서 공기가 좋지 않아.',N'자동차가 많아져서 옛날보다 훨씬 편리해졌어요.',N'도시생활이 편리하지만 힘들기도 해요.',N'바쁜 도시생활을 하고 있지만 쾌적한 환경이라 기분이 좋아요.',N'마을로 돌아가고 싶은 즐거운 마음이에요.',N'2',N'05',N'Y',N'S'),
	 (86,N'01',N'08',N'멀리 있는 학교를 다니는 아름이의 마음은 어떠했을까요?',NULL,N'친구를 만나서 항상 신나는 마음',N'학교에 가기 싫어 화가 난 마음',N'힘들지만 참고 견디는 마음',N'아무 감정도 없는 마음',N'3',N'05',N'',N'S'),
	 (86,N'01',N'09',N'빈칸에 들어갈 알맞은 표현을 찾아보세요.',N'아무리 생각해도 알 수 없는 (       )한 얘기를 들었다.',N'일렁일렁',N'들쭉날쭉',N'알쏭달쏭',N'알록달록',N'3',N'02',N'Y',N'S'),
	 (86,N'01',N'10',N'빈칸에 들어갈 알맞은 표현을 찾아보세요.',N'저 멀리로는 (        ) 흐르는 강이랑 다리가 보여.',N'굽이굽이',N'들썩들썩',N'부들부들',N'데굴데굴',N'1',N'02',N'Y',N'S'),
	 (86,N'01',N'11',N'생물이 살아가는 모양이나 상태''를 가리키는 낱말을 찾아보세요.',NULL,N'자연',N'생태',N'생활',N'환경',N'2',N'06',N'',N'S'),
	 (86,N'01',N'12',N'다음 중 ‘대도시’의 뜻으로 가장 알맞은 것은 무엇인가요?',NULL,N'사람이 거의 살지 않는 조용한 곳',N'논과 밭이 넓게 펼쳐진 곳',N'산과 숲이 많아 자연이 잘 보존된 곳',N'사람이 많이 모여 살고 일자리와 시설이 많은 곳',N'4',N'06',N'',N'S'),
	 (87,N'01',N'01',N'남자는 겉으로 봤을 때, 자신에게 천재적인 재능이 있다고 말하는 이유는 무엇인가요?',N'',N'친구들에게 언제나 실력을 인정받기 때문에',N'작품들이 값비싸게 팔리기 때문에',N'부모님이 항상 작품을 보며 칭찬해주시기때문에',N'감정평가사의 "천재같다"는 평가 때문에',N'2',N'04',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (87,N'01',N'02',N'미술선생님이 아버지가 자신의 친구인지 알아볼 수 있었던 이유는 무엇인가요?',N'',N'아버지 작품 전시회를 보고',N'읍내에서 팔리고 있는 아버지의 작품을 보고',N'염소를 판 아버지가 화방에 들어가는 모습을 보고',N'아버지가 그린 염소 그림을 보고',N'3',N'04',N'N',N'S'),
	 (87,N'01',N'03',N'여자가 남자의 작품을 보며 비유한 것이 아닌 것은 무엇인가요?',N'',N'비싼 물감으로 그린 그림은 역시 다른 것일까',N'구미호가 그에게 검정 물감을 가져다 주는 것일까',N'도깨비가 가져다준 물감을 쓰는 것일까',N'내가 그린 걸까, 누군가 대신 그려 준 걸까',N'1',N'01',N'N',N'S'),
	 (87,N'01',N'04',N'우리나라의 행정구역 단위가 큰 것부터 순서대로 나열된 보기를 찾으세요.',N'',N'시군구동읍면',N'군시읍구면동',N'시군구읍면동',N'읍면동시군구',N'3',N'07',N'N',N'S'),
	 (87,N'01',N'05',N'남자가 난생처음 장원을 했을 때 아버지의 반응으로 알맞은 것은 무엇인가요?',N'',N'박수치며 아들을 안아주셨다.',N'쑥스럽게 웃는 듯 했다.',N'기뻐서 소리를 지르셨다.',N'수줍게 웃으며 눈을 맞추었다.',N'2',N'04',N'N',N'S'),
	 (87,N'01',N'06',N'여자 아버지의 성격으로 알맞은 것은 무엇인가요?',N'',N'딸이 원하는 대로 다 해주는 아버지',N'언제나 엄격한 아버지',N'딸에게 자신의 생각을 강요하는 아버지',N'딸에게 무관심한 아버지',N'1',N'01',N'N',N'S'),
	 (87,N'01',N'07',N'남자가 미술반에서 그림을 많이 그리지 않은 이유로 어색한 것은 무엇인가요?',N'',N'아버지의 재능을 물려받아 자신은 이미 천재라고 생각해서',N'미술이 별것 아니라 생각해서',N'그림 그리는 것이 귀찮고 따분해서',N'재능을 드러내기 위해 많이 그릴 필요를 느끼지 않았기 때문에',N'3',N'04',N'N',N'S'),
	 (87,N'01',N'08',N'다음 괄호 안에 들어갈 표현으로 적절한 것은 무엇인가요?',N'그림을 보자 다리가 (   ) 떨려 주저앉아 버렸다.',N'후루룩 후루룩',N'후들후들',N'말랑말랑',N'바스락바스락',N'2',N'02',N'Y',N'S'),
	 (87,N'01',N'09',N'사생대회에서 일어난 사건으로 남자가 느낀 것이 아닌 것은 무엇인가요?',N'',N'끊임없이 자신의 재능을 의심했다.',N'누군가가 나보다 더 뛰어난 그림을 그릴 수 있다고 생각하게 되었다.',N'자신은 여전히 아버지의 재능을 물려받은 천재라고 생각했다.',N'사람들의 반응과 평가에 마음이 아팠다.',N'3',N'01',N'N',N'S'),
	 (87,N'01',N'10',N'올바른 순서대로 나열된 것은 무엇인가요?',N'(1) 사생 대회 이틀 후 전교생이 보는 앞에서 장원상을 받았다.
