	 (96,N'01',N'02',N'가끔 열이 나고 아플 때면 어떻게 해주는 게 좋을까요?',NULL,N'혼자서 꾹 참아요.',N'미지근한 물에 목욕을 해요.',N'몸을 따뜻하게 해줘요.',N'아무것도 하지 않아요.',N'3',N'01',N'',N'S'),
	 (96,N'01',N'03',N'다음 지문을 읽고, 마음 상태가 어떻게 변하는지 찾아보세요.',N'하루 종일, 네 마음의 소리에만 귀를 기울이는 거야. 아무것도 하지 않아도 괜찮아. ',N'모든 것으로부터 자유로워져요.',N'다른 사람의 말은 무조건 무시해요.',N'무조건 내가 옳다고 생각해요. ',N'아무 생각도 하지 않게 돼요.',N'1',N'03',N'Y',N'S'),
	 (96,N'01',N'04',N'괜찮아''라는 말을 계속 들으면 어떤 변화가 생길까요?',NULL,N'더 긴장하게 돼요.',N'마음이 편안해져요.',N'화가 더 나요.',N'눈치를 더 보게 돼요.',N'2',N'03',N'',N'S'),
	 (96,N'01',N'05',N'모두가 똑바로 갈 때, 왼쪽이나 오른쪽으로 가도 되는 이유는 무엇인가요?',NULL,N'모두와 다른 행동을 하면 혼나기 때문이에요.',N'길을 잘못 가면 돌아와야 하기 때문이에요.',N'혼자 가야 멋져 보이기 때문이에요.',N'나만의 길을 선택하는 것도 소중하기 때문이에요.',N'4',N'04',N'',N'S'),
	 (96,N'01',N'06',N'이 책을 읽고 우리가 가져야 할 생각으로 가장 알맞은 것은 무엇인가요?',NULL,N'다른 사람의 시선에 맞춰 살아야 해요.',N'항상 남보다 더 잘해야 해요.',N'내 마음의 소리를 믿어도 괜찮아요.',N'실수는 하면 안 돼요.',N'3',N'04',N'',N'S'),
	 (96,N'01',N'07',N'''너''는 어떤 표정을 하고 있었을까요?',N'너는 춤을 추고 공연을 할 수도 있고 머리끝부터 발끝까지 땀에 젖을 수도 있어. 셔츠와 스카프를 벗어던지고 고개를 젖힌 채 행복을 느껴보는 거야.',N'지치고 우울한 표정',N'서운하고 아쉬운 표정',N'기쁘고 행복한 표정',N'겁먹고 불안한 표정',N'3',N'05',N'Y',N'S'),
	 (96,N'01',N'08',N'내 마음을 있는 그대로 표현했을 때, 나는 어떤 마음이 들까요?',NULL,N'창피하고 숨고 싶은 마음',N'후련하고 가벼운 마음',N'화가 나고 답답한 마음',N'무섭고 긴장된 마음',N'2',N'05',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (96,N'01',N'09',N'다음 문장에 어울리는 표현을 찾으세요. ',N'전쟁 놀이를 할 때면 땅바닥을 뒹굴 수도 있고, 옷이 더러워질 수도 있어.',N'우락부락',N'데굴데굴',N'빙글빙글',N'살금살금',N'2',N'02',N'Y',N'S'),
	 (96,N'01',N'10',N'빈칸에 어울리는 표현을 찾아보세요.',N'넓은 동그라미, 찌그러진 동그라미, 긴 동그라미를 (         ) 그리고 있어요.',N'마음대로',N'정성껏 ',N'똑같이',N'가지런히',N'1',N'02',N'Y',N'S'),
	 (96,N'01',N'11',N'같은 목적을 두고 이기려고 서로 겨루는 것'' 을 가리키는 낱말을 찾으세요.',NULL,N'선행',N'경쟁',N'협동',N'양보',N'2',N'06',N'',N'S'),
	 (96,N'01',N'12',N'‘눈치를 보다’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'다른 사람의 마음이나 반응을 살피며 행동하는 것',N'앞만 보고 빠르게 행동하는 것',N'내 마음대로 말하고 행동하는 것',N'실수를 하지 않으려고 가만히 있는 것',N'1',N'06',N'',N'S'),
	 (97,N'01',N'01',N'‘아기 돼지 삼 형제’의 진짜 이야기를 아무도 모르는 이유는 무엇인가요?',N'',N'늑대 입장에서 하는 이야기는 아무도 들은 적이 없기 때문에',N'작가가 진짜 이야기를 숨겼기 때문에',N'돼지 입장에서 하는 이야기는 아무도 들은 적이 없기 때문에',N'늑대가 말을 하지 못해서',N'1',N'01',N'',N'S'),
	 (97,N'01',N'02',N'다음 중 ‘명예’의 뜻으로 알맞은 것은 무엇인가요?',N'',N'자신이나 자신과 관련 있는 것을 스스로 자랑하며 뽐냄',N'도와주거나 보살펴 주려고 마음을 씀',N'세상에서 훌륭하다고 인정되는 이름이나 자랑',N'말이나 행동을 예의 바르게 하는 것',N'3',N'06',N'',N'S'),
	 (97,N'01',N'03',N'다음이 설명하고 있는 말은 무엇인가요? ',N'커다랗고 고약한 늑대 이야기는 (    ) 거짓말이라는 거야. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (97,N'01',N'07',N'지푸라기 더미 한복판의 아기 돼지를 보고 늑대가 한 생각으로 옳은 것은 무엇인가요?',N'',N'달콤한 초콜릿',N'달콤한 설탕',N'맛있는 케이크',N'먹음직스러운 햄',N'4',N'07',N'',N'S'),
	 (97,N'01',N'08',N'늑대가 재채기를 하자 나뭇가지로 만든 아기 돼지의 집은 어떻게 되었나요?',N'',N'크게 흔들렸다.',N'완전히 무너졌다.',N'아무런 변화가 없었다.',N'하늘로 날아갔다.',N'2',N'02',N'',N'S'),
	 (97,N'01',N'09',N'늑대는 마지막 아기 돼지가 가장 머리가 좋다고 생각한 이유는 무엇인가요?',N'',N'설탕을 미리 밖에 내놓아서',N'미리 이사를 가서',N'먼저 달아나서',N'벽돌로 집을 지어서',N'4',N'03',N'',N'S'),
	 (97,N'01',N'10',N'평소에는 꽤 침착한 늑대가 미친 이유는 무엇인가요?',N'',N'배가 너무 불러서',N'마지막 아기 돼지가 늑대의 할머니 다리가 부러지라고 해서',N'아기 돼지의 집을 부수고 후회가 되어서',N'늑대가 감기에 걸려서',N'2',N'03',N'',N'S'),
	 (97,N'01',N'11',N'다음이 설명하는 단어는 무엇인가요?',N'사실이 아닌 일로 이름을 더럽히는 억울한 평판.',N'누명',N'사고',N'명성',N'자존심',N'1',N'07',N'Y',N'S'),
	 (97,N'01',N'12',N'다음에 들어갈 수 있는 단어는 무엇인가요?',N'나는 코를 벌름거리고 술을 들이마시고 재채기를 하면서 (           )을 떨고 있었지. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (98,N'01',N'05',N'<늑대와 일곱 마리 아기염소> 이야기를 읽고 느낀 점을 올바르게 이야기 한 것을 찾아보세요.',NULL,N' 엄마 염소가 지혜롭게 늑대를 혼내주고 아기 염소들과 다시 만나게 되어 다행이야. ',N'집에 혼자 있을 때 모르는 사람이 찾아오면 반갑게 문을 열어 줘야 해.',N'늑대가 엄마 흉내를 낸 걸 보면 아기 염소를 사랑하는 마음이 큰 것 같아.',N'늑대는 항상 불쌍한 존재이기 때문에 가엾게 여겨야 해.',N'1',N'04',N'',N'S'),
	 (98,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'모르는 사람이 와도 친절해야 해요.',N'혼자 있을 때는 밖으로 나가 놀아도 돼요.',N'늑대는 무조건 믿어도 돼요.',N'어른의 말씀을 잘 들어야 해요.',N'4',N'04',N'',N'S'),
	 (98,N'01',N'07',N'집으로 돌아온 엄마는 어떤 마음이었을까요?',N'엄마 염소가 돌아왔을 때 집이 엉망진창이었어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (99,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) ''상''이 기침을 하자 세 아이가 한꺼번에 줄을 놓았어요.
(2) ''상''은 털이 덥수룩한 늑대 얼굴을 보았어요.
(3) 어머니는 세 딸을  집에 남겨 두고 할머니 집에 가게 되었어요.',N'(3)-(2)-(1)',N'(3)-(1)-(2)',N'(2)-(3)-(1)',N'(1)-(3)-(2)',N'1',N'03',N'Y',N'S'),
	 (99,N'01',N'04',N'아이들이 은행을 먹으려는 늑대를 속인 이유는 무엇인가요?',NULL,N'늑대를 도와주기 위해서예요.',N'늑대에게 은행을 주기 위해서예요.',N'늑대를 위험한 상황에서 벗어나게 하기 위해서예요.',N'늑대에게 잡아먹히지 않기 위해서예요.',N'4',N'03',N'',N'S'),
	 (99,N'01',N'05',N'늑대 할머니'' 이야기에서 얻을 수 있는 교훈은 무엇일까요?',NULL,N'착한 아이가 되기 위해 부지런히 노력해야 해요.',N'어려운 상황에서도 현명하게 행동하면 위기를 이겨낼 수 있어요.',N'아이들은 엄마와  떨어져서는 안돼요.',N'모르는 사람의 말은 모두 믿어야 해요.',N'2',N'04',N'',N'S'),
	 (99,N'01',N'06',N'아이들의 행동을 보고 가장 알맞게 말한 것은 무엇인가요?',NULL,N'"힘이 센 늑대를 힘으로 이길 수 있어서 대단해!"',N'"늑대를 속인 것이 정말 나쁘다고 생각해!"',N'"위험한 상황에서도 지혜롭게 행동했구나!"',N'"늑대를 벌주기 위해 일부러 다치게 했구나!"',N'3',N'04',N'',N'S'),
	 (99,N'01',N'07',N'상''의 얼굴 표정은 어땠을까요?',N'상이 일어나 촛불을 켜자 늑대가 훅 불어서 꺼버렸어요. 불이 꺼지기 전에 상은 털이 덥수룩한 늑대 얼굴을 보았습니다.',N'슬픔이 가득한 표정',N'호기심이 가득한 표정',N'두려움이 가득한 표정',N'기쁨이 가득한 표정',N'3',N'05',N'Y',N'S'),
	 (99,N'01',N'08',N'늑대의 정체를 알아챘을 때 아이들의 마음은 어땠을까요?',NULL,N'즐겁고 신나는 마음',N'무섭고 긴장되는 마음',N'뿌듯하고 자랑스러운 마음',N'서운하고 속상한 마음',N'2',N'05',N'',N'S'),
	 (99,N'01',N'09',N'다음 빈칸에 들어갈 알맞은 표현을 찾아보세요.',N'귀여운 고슴도치의 가시는 (     ) 하고 날카로워요.',N'얼룩덜룩',N'뾰족뾰족',N'울퉁불퉁',N'말랑말랑',N'2',N'02',N'Y',N'S'),
	 (99,N'01',N'10',N'다음 빈칸에 들어갈 알맞은 표현을 찾아보세요.',N'할머니의 발은 이상하게 (      ) 했어요.',N'북실북실',N'살랑살랑',N'소곤소곤',N'데굴데굴',N'1',N'02',N'Y',N'S'),
	 (99,N'01',N'11',N'문을 닫고 잠그는 막대기를 가리키는 말을 찾아보세요.',NULL,N'빗장',N'열쇠',N'송곳',N'고리',N'1',N'06',N'',N'S'),
	 (99,N'01',N'12',N'이야기에서 말하는 ‘꼭대기’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'가장 아래쪽',N'가운데 부분',N'옆으로 튀어나온 곳',N'맨 위에 있는 곳',N'4',N'06',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (100,N'01',N'01',N'늘보씨가 챙긴 준비물이 아닌 것은 무엇인가요?',NULL,N'도시락',N'구급약',N'주스',N'물',N'3',N'01',N'',N'S'),
	 (100,N'01',N'02',N'바퀴가 구르지 않도록 조심해서 타야 하는 곳을 찾아보세요.',NULL,N'지하철 리프트',N'횡단보도',N'공원의 다리',N'집 앞 마당',N'1',N'01',N'',N'S'),
	 (100,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열된 것을 찾으세요.',N'(1) 힘껏 바퀴를 밀어서 목적지에 도착했어요.
(2) 비가 내려서 계속 가야할지 망설였어요.
(3) 아침 일찍 휠체어를 타고 출발했어요.',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(1)-(2)-(3)',N'1',N'03',N'Y',N'S'),
	 (100,N'01',N'04',N'비가 내렸는데도 늘보씨가 계속 이동한 뒤에 일어난 일로 알맞은 것은 무엇인가요?',NULL,N'길에서 사람들과 다투었어요.',N'바퀴를 힘껏 밀어 목적지에 도착했어요.',N'비가 그치기를 기다렸어요.',N'계속 가기를 멈추고 포기했어요.',N'2',N'03',N'',N'S'),
	 (100,N'01',N'05',N'늘보씨에게 어떤 얘기를 해줄 수 있을까요?',NULL,N'비가 올 때는 무조건 집으로 돌아가야 해요.',N'힘든 상황에도 불구하고 노력하는 모습이 감동적이에요.',N'다른 사람의 도움을 받지 않는 것이 최고예요.',N'위험한 일은 아예 하지 말아야 해요.',N'2',N'04',N'',N'S'),
	 (100,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 적절하지 <u>않은</u> 것은 무엇인가요?',NULL,N'넘어질 까봐 걱정되면 밖에 나가지 않는 것이 좋아요.',N'다른 사람의 도움이 필요할 때는 고맙게 받아들이면 돼요.',N'어려움이 있어도 스스로 선택한 길을 끝까지 가려는 마음이 중요해요.',N'가끔 넘어질 수 있어도 부끄러워하지 않아도 돼요.',N'1',N'04',N'',N'S'),
	 (100,N'01',N'07',N'비가 와서 휠체어에서 넘어졌을때 늘보씨의 마음은 어땠을까요?',NULL,N'힘들고 슬퍼요.',N'괴롭고 걱정돼요.',N'부끄럽고 화가 나요.',N'신나고 즐거워요.',N'1',N'05',N'',N'S'),
	 (100,N'01',N'08',N'누군가 휠체어를 잡아주며 도와주었을 때 늘보씨의 마음은 어땠을까요?',NULL,N'재미있고 웃음이 났어요.',N'화가 나고 불쾌했어요.',N'창피해서 숨고 싶었어요.',N'고맙고 안심이 되었어요.',N'4',N'05',N'',N'S'),
	 (100,N'01',N'09',N'문장의 빈칸에 어울리는 흉내내는 말을 찾으세요.',N'도로에 차들이 너무 많아서 (   ) 기침이 났어요.',N'으슬으슬',N'그렁그렁',N'쿨럭쿨럭',N'반짝반짝',N'3',N'02',N'Y',N'S'),
