	 (123,N'01',N'11',N'로빈 후드는 어떻게 메리언과 결혼했을까요?',N'',N'어머니의 권유로',N'리틀 존을 따라',N'결혼하라는 왕명을 내려서',N'메리언과 서로 사랑해서',N'3',N'03',N'N',N'S'),
	 (123,N'01',N'12',N'의기(義氣)가 드높아 매우 자랑스럽게 행동(行動)하는 모양을 말하며 괄호 안에 들어갈 표현은 무엇일까요?',N'승권이는 자기편인 형이 오자 (      )하게 말했다.',N'비실비실',N'의기양양',N'또렷또렷',N'허심탄회',N'2',N'02',N'Y',N'S'),
	 (123,N'01',N'13',N'로빈 후드가 도운 기사 리처드는 어떤 어려움을 겪고 있었나요?',N'',N'아들이 자꾸 용돈달라고 했다.',N'아들의 실수로 빚이 많다.',N'아들이 집에 들어오지 않았다.',N'아들의 실수로 다리를 다쳤다.',N'2',N'04',N'N',N'S'),
	 (123,N'01',N'14',N'로빈 후드가 잠들어 있는 땜장이의 가방에서 꺼낸 것은 무엇일까요?',N'',N'지갑',N'체포 영장',N'활과 화살',N'음식',N'2',N'04',N'N',N'S'),
	 (123,N'01',N'15',N'멀리 돌지 않고 가깝게 질러 통하는 길을 뜻하는 단어는 무엇일까요?',N'',N'지름길',N'올레길',N'둘레길',N'오솔길',N'1',N'06',N'N',N'S'),
	 (124,N'01',N'01',N'할아버지와 할머니는 어디에서 일하던 얘기를 로자에게 들려주었나요?',NULL,N'학교',N'공장',N'농장',N'가게',N'3',N'01',N'',N'S'),
	 (124,N'01',N'02',N'버스 기사가 백인에게 자리를 내주라고 말하자 로자는 어떻게 행동했나요?',NULL,N'얼른 자리를 양보해 주었어요.',N'"싫어요."라고 대답했어요.',N'다른 흑인에게 도움을 요청했어요.',N'버스에서 내렸어요.',N'2',N'01',N'',N'S'),
	 (124,N'01',N'03',N'다음 중 일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 대법원은 버스에서 흑인과 백인을 분리시키는 것은 잘못된 일이라고 판결했어요. 
(2) 흑인들은 비가 오든 눈이 오든 걸어서 다녔어요. 
(3) 로자는 백인에게 자리를 양보하지 않았다는 이유로 경찰서에 끌려갔어요.',N'(1)-(3)-(2)',N'(3)-(2)-(1)',N'(3)-(1)-(2)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (124,N'01',N'04',N'로자의 삶에서 본받을 점은 무엇일까요?',NULL,N'옳지 않은 일에 맞서 싸워요. ',N'어려운 사람들을 도와줘요.',N'백인들을 위해 봉사해요.',N'버스를 타고 다녀요.',N'1',N'03',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (124,N'01',N'05',N'로자의 행동을 보고 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'힘이 센 사람이 이겨요.',N'옳지 않은 일에는 용기를 내야 해요.',N'다수의 말은 항상 옳아요.',N'조용히 따르는 게 좋아요.',N'2',N'04',N'',N'S'),
	 (124,N'01',N'06',N'만약 로자가 자리를 양보했다면 어떤 일이 일어났을까요?',NULL,N'흑인과 백인의 차별 문제가 알려지지 않았을 거예요.',N'로자가 더 유명해졌을 거예요.',N'버스 기사가 사과했을 거예요.',N'시민들이 더 화가 났을 거예요.',N'1',N'04',N'',N'S'),
	 (124,N'01',N'07',N'버스 좌석 흑백 분리제도가 폐지되었을 때, 로자의 마음은 어땠을까요?',NULL,N'기쁘고 감격스러워요.',N'안타깝고 슬퍼요.',N'부끄럽고 후회돼요.',N'무섭고 불안해요.',N'1',N'05',N'',N'S'),
	 (124,N'01',N'08',N'비가 오는데도 걸어서 다니던 흑인들의 마음으로 가장 알맞은 것은 무엇인가요?',NULL,N'즐겁고 신나는 마음',N'포기하고 싶은 마음',N'힘들지만 참고 견디는 마음',N'두렵고 긴장되는 마음',N'3',N'05',N'',N'S'),
	 (124,N'01',N'09',N'다음 빈칸에 들어갈 알맞은 표현을 찾아보세요.',N'비가 (    ) 내리는 날에도 다같이 걸어다녔어요.',N'덜컹덜컹',N'부슬부슬',N'치렁치렁',N'쿵쾅쿵쾅',N'2',N'02',N'Y',N'S'),
	 (124,N'01',N'10',N'다음 중 문장에 어울리지 <u>않는</u> 표현을 찾아보세요.',N'비가 오는 날에도 사람들은 걸어서 길을 나섰어요.',N'비가 부슬부슬 내렸어요.',N'사람들은 묵묵히 걸어갔어요.',N'길이 미끄러워 조심조심 걸었어요.',N'사람들이 덜컹덜컹 걸어갔어요.',N'4',N'02',N'Y',N'S'),
	 (124,N'01',N'11',N'보통 사람이 하기 어려운 일을 해내는 사람'' 을 가리켜 무엇이라고 부르나요?',NULL,N'박사',N'영웅',N'천재',N'의사',N'2',N'06',N'',N'S'),
	 (124,N'01',N'12',N'차별 없이 똑같이 대함''을 뜻하는 말로 알맞은 것은 무엇인가요?',NULL,N'명령',N'규칙',N'복종',N'평등',N'4',N'06',N'',N'S'),
	 (125,N'01',N'01',N'리디아는 가정 형편이 나아질 때까지 누구의 집에서 지내게 되었나요?',NULL,N'외삼촌 집',N'이모 집',N'고모 집',N'할머니 집',N'1',N'01',N'',N'S'),
	 (125,N'01',N'02',N'비밀장소인 옥상정원에 도착한 외삼촌은 리디아에게 무엇을 선물했나요?',NULL,N'꽃다발 ',N'꽃 케이크   ',N'꽃 화분',N'꽃병',N'2',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (125,N'01',N'03',N'리디아가 외삼촌이 시를 좋아한다고 생각한 까닭은 무엇인가요?',NULL,N'시를 읽고 크게 웃으셨기 때문에',N'시를 크게 읽고 주머니에 넣어 톡톡 두드리셨기 때문에',N'리디아를 위한 시를 지어주셨기 때문에',N'시를 매일 외우셨기 때문에',N'2',N'03',N'',N'S'),
	 (125,N'01',N'04',N'리디아가 겪은 일을 순서대로 나열한 것을 찾아보세요.',N'(1) 아빠가 취직을 하셨다는 소식을 듣고 다시 집으로 돌아가게 되었어요.
(2) 비밀 장소를 발견하고 꽃씨를 심느라 많이 바빴어요.
(3) 외삼촌 집에 가기 전 기차역에서 외삼촌에게 편지를 썼어요.',N'(2)-(3)-(1) ',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (125,N'01',N'05',N'리디아를 칭찬하는 말로 가장 올바른 것을 찾으세요.',NULL,N'“밝고 긍정적인 성격을 본받고 싶어.” ',N'“어려운 친구를 돕는 마음이 예뻐.”',N'“나라를 사랑하는 마음이 정말 멋져.”',N'"규칙을 잘 지키는 아이야."',N'1',N'04',N'',N'S'),
	 (125,N'01',N'06',N'리디아가 꽃을 가꾸며 사람들을 기쁘게 한 이유로 알맞은 것은 무엇인가요?',NULL,N'꽃을 팔아 돈을 벌기 위해서예요.',N'외삼촌의 시를 따라 하고 싶어서예요.',N'심심해서 시간을 보내려고 했어요.',N'자신의 마음을 꽃으로 전하고 싶었기 때문이에요.',N'4',N'04',N'',N'S'),
	 (125,N'01',N'07',N'리디아는 어떤 마음이었을까요?',N'지금 저는 가슴이 터질 것 같아요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (126,N'01',N'01',N'복숭아 나무의 꽃잎이 지고 나면 어떤 일이 일어날까요?',NULL,N'달콤한 복숭아가 주렁주렁 열려요.',N'복숭아 나무가 앙상해져요.',N'복숭아 나무에 새 꽃이 피어나요.',N'복숭아 나무가 말라 버려요.',N'1',N'01',N'',N'S'),
	 (126,N'01',N'02',N'린 할머니네 복숭아 나무에 복숭아가 딱 한 개 남았을때 누가 도착했나요?',NULL,N'다람쥐',N'호랑이',N'거북이',N'달팽이',N'3',N'01',N'',N'S'),
	 (126,N'01',N'03',N'일이 일어난 차례대로 바르게 나열한 것을 찾으세요.',N'(1) 린 할머니네 집 앞 복숭아 나무에 꽃이 피었어요. 
(2) 할머니는 마지막 남은 복숭아로 파이를 만들었어요.
(3) 할머니는 아기 다람쥐, 염소, 호랑이에게 복숭아를 나눠 주었어요.',N'(1)-(2)-(3)',N'(1)-(3)-(2)',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (126,N'01',N'04',N'복숭아 씨가 다시 나무로 자랄 수 있었던 까닭은 무엇인가요?',NULL,N'씨앗을 버리지 않고 땅에 남겨 두었기 때문이에요.',N'씨앗을 동물들이 밟았기 때문이에요.',N'비가 오지 않았기 때문이에요.',N'할머니가 씨앗을 숨겼기 때문이에요.',N'1',N'03',N'',N'S'),
	 (126,N'01',N'05',N'또다시 린 할머니네 집 앞 복숭아 나무에 꽃이 피고 열매가 열리면 어떤 일이 일어날까요?',NULL,N'린 할머니 혼자서 복숭아를 다 먹어 버렸을 거예요.',N'복숭아를 더 많이 먹으려고 다투었을 거예요.',N'모두 웃으며 사이좋게 복숭아를 나눠 먹을 거예요.',N'아무도 복숭아를 먹지 못했을 거예요.',N'3',N'04',N'',N'S'),
	 (126,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'맛있는 것은 혼자 먹어야 해요.',N'먼저 차지하는 사람이 이겨요.',N'늦게 온 사람은 기다리면 안 돼요.',N'함께 나누면 기쁨이 커져요.',N'4',N'04',N'',N'S'),
	 (126,N'01',N'07',N'달콤한 복숭아 파이와 꽃잎 차를 맛본 거북이들의 마음은 어땠을까요?',NULL,N'행복하고 기뻐요.',N'실망스럽고 안타까워요.',N'서운하고 슬퍼요.',N'무섭고 놀랐어요.',N'1',N'05',N'',N'S'),
	 (126,N'01',N'08',N'동물들이 함께 웃으며 복숭아 파이를 먹는 모습을 본 린 할머니의 마음으로 알맞은 것은 무엇인가요?',NULL,N'외롭고 쓸쓸했어요.',N'뿌듯하고 따뜻했어요.',N'부끄럽고 창피했어요.',N'무섭고 긴장됐어요.',N'2',N'05',N'',N'S'),
	 (126,N'01',N'09',N'다음 문장에 알맞은 표현을 찾아보세요.',N'늦가을이 되자 알록달록한 나뭇잎들이 바람에 떨어져요.',N'우수수',N'우루루',N'스르르',N'와르르',N'1',N'02',N'Y',N'S'),
	 (126,N'01',N'10',N'다음 중 복숭아가 많이 열린 모습을 떠올리게 하는 표현은 무엇인가요?',NULL,N'깡총깡총',N'또각또각',N'주렁주렁',N'빙글빙글',N'3',N'02',N'',N'S');
