	 (129,N'01',N'08',N'가장 가난한 사람들을 보며 테레사 수녀의 마음은 어떠했을까요?',N'',N'마음이 무거웠을 것이다',N'신이 났을 것이다',N'자랑스러웠을 것이다',N'장난치고 싶었을 것이다',N'1',N'05',N'N',NULL),
	 (129,N'01',N'09',N'테레사 수녀가 받은 상을 찾으세요.',N'',N'노벨 문학상',N'노벨 평화상',N'노벨 화학상',N'노벨 경제학상',N'2',N'01',N'N',NULL),
	 (129,N'01',N'10',N'테레사 수녀에게 어떤 말을 해줄 수 있을까요?',N'',N'가난한 사람을 위해 봉사한 점이 대단해요.',N'먼 곳으로 여행을 떠난 삶이 멋져요.',N'끊임없이 도전하는 모습을 배우고 싶어요.',N'힘든 일을 만나도 포기하지 않은 모습이 기억에 남아요.',N'1',N'04',N'N',NULL),
	 (129,N'01',N'11',N'‘봉사’와 비슷한 뜻을 가진 낱말은 무엇인가요?',N'',N'도움',N'경쟁',N'싸움',N'놀이',N'1',N'06',N'N',NULL),
	 (129,N'01',N'12',N'알맞은 문장부호를 고르세요.',N'“이 사람을 꼭 도와야 해( )”',N'.',N'?',N'!',N',',N'3',N'02',N'Y',NULL),
	 (130,N'01',N'01',N'마리가 집을 떠나 프랑스 파리에 가려고 한 이유를 찾으세요.',NULL,N'프랑스 여행을 하고 싶어서',N'폴란드의 대학들은 여자를 받아주지 않아서',N'폴란드에서 공부하기 싫어서 ',N'프랑스 친구를 만나기 위해서',N'2',N'01',N'',N'S');
