INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (131,N'01',N'10',N'다음 중 책을 올바르게 이해하지 못한 사람은 누구인가요?',N'',N'현주: 부모와 아이가 서로 이해하는 것이 중요하네.',N'민수: 요정이 렝켄에게 너무 큰 시련을 줬다고 느꼈어.',N'재우: 나중에 렝켄이 요정에게 설탕을 또 달라고 할 것 같아.',N'진우: 렝켄은 부모를 더 잘 이해하게 되었어.',N'3',N'03',N'N',N'S'),
	 (131,N'01',N'11',N'다음의 ’반박‘이 나타내는 뜻으로 알맞은 것은 무엇인가요?',N'엄마와 아빠는 반박하지 않고 가만히 있었습니다.',N'여러 빛깔이 뒤섞여 아롱진 모양',N'어떤 의견, 주장, 논설 따위에 반대하여 말함 ',N'한 박자의 반',N'다양한 생각이 모인 의견',N'2',N'06',N'Y',N'S'),
	 (131,N'01',N'12',N'다음이 설명하는 단어는 무엇인가요?',N'방법이 있을 거요. 우리가 처해 있는 상황을 한번 잘 생각해 봅시다. 그러면 뭔가 (      )이 떠오를 거요.
