	 (132,N'01',N'08',N'세종이 장영실의 재주를 알아보고 벼슬을 내렸을 때, 장영실의 마음은 어땠을까요?',NULL,N'무섭고 떨리는 마음',N'억울하고 화난 마음',N'기쁘고 뿌듯한 마음',N'지루하고 심심한 마음',N'3',N'05',N'',N'S'),
	 (132,N'01',N'09',N'다음 문장에 어울리는 표현을 찾으세요.',N'뻘건 태양만 (       )거렸습니다.',N'이글이글',N'서글서글',N'수군수군',N'끈적끈적',N'1',N'02',N'Y',N'S'),
	 (132,N'01',N'10',N'다음 문장에 어울리는 표현을 찾으세요.',N'고장 난 물건이 눈에 띄면 (       ) 고쳐 놓곤 했어요.',N'힐끔',N'또각',N'뚝딱',N'사뿐',N'3',N'02',N'Y',N'S'),
	 (132,N'01',N'11',N'다음 빈칸에 들어갈 알맞은 말을 찾아보세요.',N'임금께서 재주가 뛰어난 인재를 (      )하라고 하셨다.',N'의심',N'추천',N'실천',N'반대',N'2',N'06',N'Y',N'S'),
	 (132,N'01',N'12',N'‘발명’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'이미 있는 것을 따라 만드는 것',N'새롭고 유용한 것을 처음으로 만들어 내는 것',N'물건을 사고파는 것',N'오래된 것을 고치는 것',N'2',N'06',N'',N'S'),
	 (133,N'01',N'01',N'일제강점기 당시 우리 민족이 겪었던 일들로 알맞지 않은 것은?',N'',N'창씨개명을 강요당해 이름을 일본식으로 바꾸어야 했다.',N'젊은이들이 징병 대상자가 되어 전쟁터에 끌려가기도 했다.',N'국민학교를 소학교로 이름을 바꿔버렸다.',N'토지조사사업으로 자신의 땅을 빼앗겼다.',N'3',N'01',N'N',N'S'),
	 (133,N'01',N'02',N'<남작의 아들>에서 가즈오의 아버지가 남작이 될 수 있었던 이유는 무엇인가요?',N'',N'일본에게 충성을 바치고 조선과 일본이 하나가 되는데 앞장섰기 때문에',N'조상이 일본사람이었기 때문에',N'조선 독립을 위해 만세 운동을 계획했기 때문에',N'조선 사람들을 위해 몰래 독립운동자금을 모았기 때문에',N'1',N'01',N'N',N'S'),
	 (133,N'01',N'03',N'<방구 아저씨>에서 방구 아저씨가 죽고도 꽃상여를 타지 못한 이유는 무엇인가요?',N'',N'돈이 없었기 때문에',N'일본 순사들의 눈치가 보여서',N'시신을 수습하지 못해서',N'마을 사람들이 싫어해서',N'2',N'04',N'N',N'S'),
	 (133,N'01',N'04',N'<흙으로 빚은 고향>에서 사치코가 할머니에게 ''봄 이야기''를 불러드린 의미는 무엇인가요? ',N'',N'중창 대회에 나가지 못한 것을 못내 아쉬워하고 있다.',N'더 이상 조선인이라는 사실을 부끄러워 하지 않게 되었다는 것을 보여준다.',N'할머니와 함께 일본으로 가고 싶어하는 마음을 보여준다.',N'할머니가 가장 좋아하셨던 계절이 봄이기 때문에',N'2',N'04',N'N',N'S'),
	 (133,N'01',N'05',N'괄호 안의 단어가 상징하는 것들이 잘못 연결된 것은 무엇인가요?',N'(나무)는 아무리 (모진 겨울)일지라도 (뿌리)만 얼어 죽지 않으면 반드시 잎이 돋고 (꽃)을 피운다.',N'나무 - 조국',N'모진 겨울 - 남북 분단의 현실',N'꽃 - 독립',N'뿌리 - 민족 정신',N'2',N'02',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (133,N'01',N'06',N'<잠들어라 새야>에서 제목이 의미하는 것은 무엇인가요?',N'',N'자신을 괴롭혔던 일본인들이 모두 죽길 바라는 마음',N'자신을 기다리다 돌아가신 어머니를 그리워하는 마음',N'아픈 기억은 잊어버리고 새롭게 태어나길 바라는 마음',N'일제의 속박에서 벗어나 새처럼 자유로운 삶을 살아가기 위해서',N'3',N'02',N'N',N'S'),
	 (133,N'01',N'07',N'소설 <잎새에 이는 바람>은 실존했던 누구의 이야기를 각색한 것일까요?',N'',N'윤동주',N'이육사',N'김소월',N'서정주',N'1',N'07',N'N',N'S'),
	 (133,N'01',N'08',N'<꾳을 먹는 아이들>의 배경이 되는 역사적 사건은 무엇인가요?',N'',N'1919년 3.1 독립만세운동',N'1923년 관동 대지진',N'1945년 8.15 해방',N'1911년 1월 1일 105인 사건',N'2',N'07',N'N',N'S'),
	 (133,N'01',N'09',N'<남작의 아들>에서 보듯, 당시 만세꾼이 있었던 까닭은 무엇인가요?',N'',N'조선 사람들이 만세를 부르도록 부추기고 힘을 내게 하려고',N'일본의 업적을 칭송하고 홍보하기 위해서',N'일본 순사들이 변장하여 조선인들을 감시하기 위해서',N'조선왕조의 무궁한 발전을 기리기 위해서',N'1',N'03',N'N',N'S'),
	 (133,N'01',N'10',N'<마사코의 질문>에서 마사코의 질문에 할머니가 제대로 답변을 하지 못한 이유는 무엇인가요?',N'',N'마사코가 할머니도 겪어보지 않았던 걸 물어봤기 때문에 ',N'마사코가 진실을 알게되면 조선을 싫어할까봐',N'할머니도 일본의 잘못이 있다는 걸 알고 있기 때문에',N'할머니는 일본이 전혀 잘못하지 않았다고 생각했기 때문에',N'3',N'03',N'N',N'S'),
	 (133,N'01',N'11',N'국민이 수요에 따라 농업 생산물이나 기물 따위를 의무적으로 정부에 내어놓는 것'' 뜻하는 단어는 무엇인가요?',N'',N'공출(供出)',N'수출(輸出)',N'차출(差出)',N'입찰(入札)',N'1',N'06',N'N',N'S'),
	 (133,N'01',N'12',N'국가권력으로 국민을 일정한 업무에 강제적으로 종사시키는 일''을 뜻하는 단어는 무엇인가요?',N'',N'노동(勞動)',N'징용(徵用)',N'용병(傭兵)',N'공출(供出)',N'2',N'06',N'N',N'S'),
	 (133,N'01',N'13',N' ''법률, 명령, 약속 따위를 지키지 않고 어김''을 뜻하는 단어는 무엇인가요?',N'',N'반칙(反則)',N'벌칙(罰則)',N'위반(違反)',N'준수(遵守)',N'3',N'06',N'N',N'S'),
	 (133,N'01',N'14',N'한국을 대표하는 민요의 이름은 무엇인가요?',N'',N'애국가(愛國歌)',N'아리랑',N'시조(時調)',N'군밤타령',N'2',N'06',N'N',N'S'),
	 (133,N'01',N'15',N'일본과 조선은 한 몸이라는 뜻으로, 일제 강점기 때 일본이 조선인의 정신을 말살하고 조선을 착취하기 위하여 만들어 낸 구호는 무엇인가요?',N'',N'국권피탈(國權被奪)',N'내선일체(內鮮一體)',N'황국신민(皇國臣民)',N'신사참배(神社參拜)',N'2',N'06',N'N',N'S');
