	 (134,N'01',N'01',N'송이는 맨날 같이 노는 준이가 없어서 마음이 어떻다고 했나요?',NULL,N'마음이 텅텅 빈 상자같아요.',N'마음이 텅텅 빈 그릇 같아요.',N'마음이 텅텅 빈 놀이터 같아요. ',N'마음이 텅텅 빈 가방 같아요.',N'1',N'01',N'',N'S'),
	 (134,N'01',N'02',N'동생이랑 공놀이를 할 때 준이가 지나가자, 송이는 어떻게 행동했나요?',NULL,N'준이에게 인사를 했어요.',N'준이를 모른척 했어요.',N'마음속으로 생각만 했어요.',N'준이에게 달려갔어요.',N'3',N'01',N'',N'S'),
	 (134,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열된 것을 찾으세요.',N'(1) 송이와 준이는 내리막길을 힘차게 달렸어요.
(2) 송이는 준이와 싸우고 화가 나서 소리를 질렀어요.
(3) 교실에서 준이가 송이를 힐끗 보더니 인사를 하지 않았어요.',N'(2)-(1)-(3)',N'(1)-(2)-(3)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (134,N'01',N'04',N'송이의 마음이 점점 콩알처럼 작아진 까닭은 무엇인가요?',NULL,N'준이가 계속 같이 놀자고 해서',N'준이에게 다가가고 싶었지만 용기가 나지 않아서',N'동생이 자꾸 놀자고 졸라서',N'학교에 가기 싫어서',N'2',N'03',N'',N'S'),
	 (134,N'01',N'05',N'만약에 송이가 먼저 준이에게 사과했다면 어땠을까요?',NULL,N'준이가 사과를 받아 주지 않고  짜증을 냈을 거예요.',N'준이가 기뻐하며 같이 놀자고 했을 거예요.',N'송이는 자존심이 상해서 준이랑 사이 좋게 지내지 못했을 거예요.',N'선생님께 혼이 났을 거예요.',N'2',N'04',N'',N'S'),
	 (134,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'친구와 싸우면 먼저 다가가지 말아야 해요.',N'마음이 상하면 혼자서 참아야 해요.',N'친구보다 자존심이 더 중요해요.',N'마음을 솔직하게 전하는 것이 중요해요.',N'4',N'04',N'',N'S'),
	 (134,N'01',N'07',N'송이의 마음은 어땠을까요?',N'마음이 간질간질, 자꾸 웃음이 나와.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (134,N'01',N'11',N'문장에서 밑줄 친 부분을 대신 할 수 있는 낱말을 찾아보세요.',N'마음이 또 <u>심통</u>을 부려.',N'감정',N'심정',N'심술',N'감사',N'3',N'06',N'Y',N'S'),
	 (134,N'01',N'12',N'‘허전하다’의 뜻으로 알맞은 것을 찾아보세요.',NULL,N'배가 불러서 더 이상 먹고 싶지 않은 상태',N'마음이 비어 있는 것처럼 쓸쓸하고 아쉬운 상태',N'몸이 아프고 힘이 없는 상태',N'화가 나서 짜증이 나는 상태',N'2',N'06',N'',N'S'),
	 (135,N'01',N'01',N'친구 엄마는 마틴을 어떻게 대했나요?',NULL,N'돌아가라고 했어요. ',N'친절하게 대해주었어요.',N'다음에 오라고 했어요.',N'간식을 주었어요.',N'1',N'01',N'',N'S'),
	 (135,N'01',N'02',N'흑인 분류법은 무슨 법인가요?',NULL,N'흑인과 백인이 같이 학교에 다닐 수 있어요.',N'공공장소에서 흑인은 백인과 함께 있을 수 없어요.',N'흑인과 백인은 항상 사이좋게 지내요.',N'흑인만 학교에 다닐 수 있어요.',N'2',N'01',N'',N'S'),
	 (135,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열된 것을 찾으세요.',N'(1) 워싱턴의 군중 앞에서 연설을 해요
(2) 버스 안타기 운동을 벌였어요.
(3) 어른이 되면 불의에 맞서기로 다짐해요.',N'(2)-(3)-(1)',N'(1)-(3)-(2)',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'3',N'03',N'Y',N'S'),
	 (135,N'01',N'04',N'버스 안 타기 운동 다음에 일어난 일로 알맞은 것은 무엇인가요?',NULL,N'사람들이 더 많이 싸웠어요.',N'모두 버스를 타지 않았어요.',N'운동이 금방 끝났어요.',N'흑인 분리법이 없어졌어요.',N'4',N'03',N'',N'S'),
	 (135,N'01',N'05',N'마틴 루터킹에게 본받을 점은 무엇인가요?',NULL,N'가장 어린 나이에 노벨상을 받았어요.',N'평화적인 방식으로 차별을 이겨냈어요.',N'흑인들이 버스를 이용하지 못하도록 했어요.',N'혼자만 잘되려고 했어요.',N'2',N'04',N'',N'S'),
	 (135,N'01',N'06',N'이 책을 읽고 우리가 할 수 있는 행동으로 알맞은 것은 무엇인가요?',NULL,N'친구를 차별해도 괜찮아요.',N'불공평한 일에 관심을 가져요.',N'싸우는 것이 가장 빨라요.',N'모르는 척 지나쳐요.',N'2',N'04',N'',N'S'),
	 (135,N'01',N'07',N'스물아홉번이나 체포되었을 때 마틴의 마음은 어땠을까요?',NULL,N'감옥에 가는 일이 시시해요.',N'힘들지만 흑인의 권리를 위해 싸울 거예요.',N'이제 그만 쉬고 싶어요.',N'화가 나서 포기하고 싶어요.',N'2',N'05',N'',N'S'),
	 (135,N'01',N'08',N'워싱턴에서 많은 사람들 앞에 섰을 때 마틴의 마음으로 알맞은 것은 무엇인가요?',NULL,N'두렵고 도망치고 싶었어요.',N'화가 나서 소리쳤어요.',N'뿌듯하고 간절했어요.',N'지루하고 재미없었어요.',N'3',N'05',N'',N'S');
