	 (154,N'01',N'03',N'미세먼지와 초미세먼지의 지름이 알맞게 짝지어진 것을 찾아보세요.',N'',N'미세먼지: 10μm 초미세먼지: 5μm',N'미세먼지: 20μm 초미세먼지: 2μm',N'미세먼지: 10μm 초미세먼지: 2.5μm',N'미세먼지: 20μm 초미세먼지: 5μm',N'3',N'07',N'N',N'S'),
	 (154,N'01',N'04',N'다음 예시를 읽고 올바른 추측을 하는 사람은 누구인가요?',N'우리나라처럼 사계절이 뚜렷한 나라에서는 계절에 따라 미세먼지 농도가 달라지는 것을 체감할 수 있다. 미세먼지가 가장 극심한 계절은 겨울철과 봄철이다. 반대로 여름철과 가을철은 미세먼지가 옅다.',N'채영: 봄은 건조하기 때문에 먼지가 많이 생기나봐.',N'민현: 여름에 미세먼지 농도가 옅은 것은 역전층 현상이 겨울보다 더 잘 나타나기 때문이야.',N'지훈: 가을철에 미세먼지가 적다니 신기해. 기압이 느리게 흘러서 대기의 순환이 잘 되나봐.',N'수진: 미세먼지는 계절과 무관하게 항상 많이 볼 수 있어',N'1',N'03',N'Y',N'S'),
	 (154,N'01',N'05',N'환경에 악영향을 끼치는 원인으로 옳지 않은 것은 무엇인가요?',N'',N'값싼 석탄을 과도하게 사용한다.',N'생활수준이 올라가면서 대중교통을 많이 이용한다.',N'무분별한 벌목으로 나무를 없앤다.',N'석유제품을 무분별하게 생산, 소비 한다.',N'2',N'01',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (154,N'01',N'06',N'깨끗한 공기를 찾아 떠나는 사람들을 지칭하는 말은 무엇인가요?',N'',N'에어 파인더',N'에어 콜렉터',N'에어 노마드',N'에어 익스트렉터',N'3',N'07',N'N',N'S'),
	 (154,N'01',N'07',N'다음 예시를 읽고 추측할 수 있는 것은 무엇인가요?',N'선생님: 중국에는 미세먼지를 유발하는 것들이 매우 많아요. 그리고 중국에서 한국으로 편서풍이 많이 붑니다.',N'태민: 미세먼지를 줄이기 위해 대중교통을 이용해야지.',N'지윤: 미세먼지가 편서풍을 타고 우리나라에 오겠구나.',N'정현: 편서풍이면 우리나라에서 중국으로 바람이 부는거겠지.',N'수진: 중국과 한국은 다른 나라이기 때문에 미세먼지가 영향을 주고받지 못해',N'2',N'03',N'Y',N'S'),
	 (154,N'01',N'08',N'다음 예시의 빈칸에 어울리는 말은 무엇인가요?',N'당황해서 우물쭈물 거리다 말을 (    ).',N'당당하게 했다.',N'웃었다.',N'얼버무렸다.',N'유창했다.',N'3',N'02',N'Y',N'S'),
	 (154,N'01',N'09',N'어린이의 몸안에 미세먼지의 비중이 큰 이유는 무엇인가요?',N'',N'어른보다 어린이의 폐가 작기 때문에',N'어른보다 숨을 크게 쉬기 때문에',N'어른보다 호흡을 적게하기 때문에',N'어른보다 순수한 마음을 가졌기 때문에',N'1',N'04',N'N',N'S'),
	 (154,N'01',N'10',N'미세먼지를 줄이기 위한 실천이 아닌 것은 무엇인가요?',N'',N'석탄 연료의 사용을 줄이고 화력발전소를 추가로 건설한다.',N'에너지 공학에 관심을 가진다.',N'수소 전기차를 적극 이용한다.',N'재생 에너지에 관심을 가진다.',N'1',N'04',N'N',N'S'),
	 (154,N'01',N'11',N'다음 예시의 "수치"와 바꾸어 쓸 수 있는 것은 무엇인가요?',N'미세먼지 수치(數値)가 높다.',N'연기(煙氣)',N'농도(濃度)',N'심해(深海)',N'자연(自然)',N'2',N'06',N'Y',N'S'),
	 (154,N'01',N'12',N'"힘으로 으르고 협박하는 것"을 뜻하는 것은 무엇인가요?',N'',N'위협(威脅)',N'위기(危機)',N'경기(驚氣)',N'활약(活躍)',N'1',N'02',N'N',N'S'),
	 (154,N'01',N'13',N'"아는 것이 없음"을 뜻하는 것은 무엇인가요?',N'',N'경지(境地)',N'개간(開墾)',N'무지(無知)',N'무료(無料)',N'3',N'06',N'N',N'S'),
	 (154,N'01',N'14',N'주변은 아랑곳하지 않고 미세먼지를 만들어내는 중국과 어울리는 사자성어는 무엇인가요?',N'',N'고육지책(苦肉之策)',N'일석이조(一石二鳥)',N'안하무인(眼下無人)',N'학수고대(鶴首苦待)',N'3',N'06',N'N',N'S'),
	 (154,N'01',N'15',N'다음 예시의 빈칸에 어울리는 단어는 무엇인가요?',N'석탄의 (  )한 사용은 미세먼지를 유발한다.',N'과도(過度)',N'과정(過程)',N'과학(科學)',N'수려(秀麗)',N'1',N'06',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (155,N'01',N'01',N'엄마 오리가 품고 있던 가장 큰 알에서 나온 것은 무엇이었나요?',NULL,N'못생긴 아기 오리',N'노란 깃털의 아기 오리',N'부리가 긴 아기 오리',N'아주 작은 아기 오리',N'1',N'01',N'',N'S'),
	 (155,N'01',N'02',N'얼음 위에 꽁꽁 얼어붙은 아기 오리를 구해준 사람은 누구인가요? ',NULL,N'사냥꾼',N'농부',N'할머니',N'어부',N'2',N'01',N'',N'S'),
	 (155,N'01',N'03',N'미운 아기 오리가 겪은 일을 순서대로 바르게 나열한 것은 무엇인가요?',N'(1) 형제들과 동물들에게 미움을 받았어요.
(2) 추운 겨울을 혼자 힘들게 보냈어요.
(3) 물에 비친 자신의 모습을 보고 놀랐어요.',N'(2)-(1)-(3)',N'(1)-(2)-(3)',N'(3)-(1)-(2)',N'(3)-(2)-(1)',N'2',N'03',N'Y',N'S'),
	 (155,N'01',N'04',N'미운 아기 오리가 날개를 푸드덕거리자 어떤 일이 일어났나요? ',NULL,N'깃털이 모두 빠지고 말았어요.',N'두 발을 움직일 수 없게 되었어요.',N'몸이 훨훨 날아올랐어요.',N'깃털이 노랗게 변했어요.',N'3',N'03',N'',N'S'),
	 (155,N'01',N'05',N'미운 아기 오리가 물에 비친 자기 모습을 보고 놀란 까닭은 무엇인가요?',NULL,N'자신이 바로 아름다운 백조였기 때문에',N'물속이 너무 깨끗했기 때문에',N'자신의 모습이 여전히 못생겼기 때문에 ',N'다른 오리가 보였기 때문에',N'1',N'04',N'',N'S'),
	 (155,N'01',N'06',N'아기 오리를 괴롭힌 동물들에게 어떤 말을 해줄 수 있을까요? ',NULL,N'"먼저 양보를 할 줄 알아야 돼."',N'"친구를 겉모습으로 놀리면 안 돼."',N'"거짓말을 하는 것은 잘못이야."',N'"다른 친구보다 잘나야 해."',N'2',N'04',N'',N'S'),
	 (155,N'01',N'07',N'형제들이 미워했을 때 아기 오리는 어떤 마음일까요?',N'“어쩜 저렇게 크고 못생겼을까?” 형제 오리들도 함께 놀아주지 않았어요.',N'기뻤어요.',N'슬펐어요.',N'반가웠어요.',N'신났어요.',N'2',N'05',N'Y',N'S'),
	 (155,N'01',N'08',N'자신이 백조라는 것을 알게 된 아기 오리의 마음으로 알맞은 것은 무엇인가요?',NULL,N'여전히 슬펐어요.',N'부끄럽고 숨고 싶었어요.',N'화가 났어요.',N'기쁘고 놀라웠어요.',N'4',N'05',N'',N'S'),
	 (155,N'01',N'09',N'빈칸에 어울리는 흉내 내는 말을 찾아 보세요.',N'아기오리는 겁이 나서 (       ) 달아났어요.',N'폴짝폴짝  ',N'허둥지둥',N'멀뚱멀뚱 ',N'반짝반짝',N'2',N'02',N'Y',N'S'),
	 (155,N'01',N'10',N'빈칸에 어울리는 흉내 내는 말을 찾아 보세요.',N'형제 오리들이 놀아주지 않자, 아기 오리는 슬퍼서 눈물을 (      ) 흘렸어요.',N'딱딱',N'짝짝',N'뚝뚝',N'쑥쑥',N'3',N'02',N'Y',N'S');
