	 (170,N'01',N'05',N'애벌레에게 어떤 말을 해줄 수 있을까요?',N'케이크, 아이스크림, 소시지 같은 것을 먹자 배가 아팠습니다. 하지만 초록색 이파리를 먹으니 배가 아픈 것이 다 나았습니다. ',N'규칙적인 생활을 해야 건강해 질 수 있어!',N'적당한 운동을 해야 건강해 질 수 있어!',N'자신에게 맞는 먹이를 먹어야 건강해 질 수 있어!',N'아플 때는 아무 것도 먹으면 안 돼!',N'3',N'04',N'Y',N'S'),
	 (170,N'01',N'06',N'애벌레가 나비가 되기 위해 꼭 필요했던 과정은 무엇인가요?',NULL,N'먹이를 많이 먹고 번데기가 되어 기다리는 것이에요.',N'친구들과 함께 노는 것이에요.',N'멀리 여행을 떠나는 것이에요.',N'누워서 잠을 자는 것이에요.',N'1',N'04',N'',N'S'),
	 (170,N'01',N'07',N'애벌레는 어떤 마음이었을까요?',N'"아, 나비다!" 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (171,N'01',N'03',N'조선 땅이 낮에는 곡식이 말라죽도록 뜨겁고, 밤에는 땅이 꽁꽁 얼어붙도록 추웠던 이유는 무엇인가요?',N'',N'신의 저주를 받아서',N'해와 달이 둘씩이나 있어서',N'농사를 잘못 지어서',N'백두거인이 사라졌기 때문에',N'2',N'03',N'',N'S'),
	 (171,N'01',N'04',N'천지왕의 “ 조선 백성들을 도울 자가 없느냐? ”라는 질문에 가장 먼저 나선 이는 누구인가요?',N'',N'백두거인',N'용',N'흑두거인',N'천황닭',N'3',N'01',N'',N'S'),
	 (171,N'01',N'05',N'백두거인이 해와 달을 하나씩 없앤 방법으로 적절한 것은 무엇인가요?',N'',N'해와 달을 맨손으로 꽉 움켜쥐어 바다로 던졌다.',N'천 근 활에 천 근 화살로 해 하나와 달 하나를 쏘아 바다로 떨어뜨렸다.',N'하늘에 닿을 만큼 긴 검으로 해와 달을 베어냈다.',N'용에게 삼키게 했다.',N'2',N'04',N'',N'S'),
	 (171,N'01',N'06',N'천지왕이 조선 땅에 내려보낸 이는 누구인가요?',N'',N'아들인 환웅 왕자',N'조카인 영웅 대군',N'딸인 선화 공주',N'백두거인',N'1',N'07',N'',N'S'),
	 (171,N'01',N'07',N'흑두거인이 천지왕 몰래 이웃 나라를 부추겨 조선 땅에 쳐들어간 이유는 무엇인가요?',N'',N'조선은 원래 흑두거인의 땅이기 때문에',N'자신이 조선을 더 잘 다스릴 수 있을 것 같아서',N'백두거인을 시기하다가 화를 이기지 못해서',N'백성들이 스스로 도움을 청했기 때문에',N'3',N'03',N'',N'S'),
	 (171,N'01',N'08',N'다음이 설명하는 단어는 무엇인가요?',N'사람들은 공포에 질려 사방으로 흩어져 숨었고, 조선을 갈수록 (       )해졌습니다. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (172,N'01',N'01',N'새 왕비에게 가장 예쁜 사람이 백설공주라고 말해준 것은 무엇인가요?',NULL,N'요술 빗자루',N'요술 거울',N'요술 램프',N'요술 반지',N'2',N'01',N'',N'S'),
	 (172,N'01',N'02',N'숲으로 오게 된 백설공주는 누구와 함께 지냈나요?',NULL,N'사과장수 할머니',N'난쟁이들',N'사냥꾼',N'숲속 요정',N'2',N'01',N'',N'S'),
	 (172,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 난쟁이들은 슬퍼하며 유리관 안에 공주를 눕혔어요.
(2) 왕자와 공주는 행복한 결혼식을 올렸어요.
(3) 이웃나라 왕자가 숲을 지나가다가 유리관 안에 누운 공주를 보았어요.',N'(3)-(1)-(2)',N'(2)-(1)-(3)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (172,N'01',N'04',N'다음 중 백설공주가 쓰러지게 된 이유로 가장 알맞은 것은 무엇인가요?',NULL,N'숲에서 길을 잃었기 때문이에요.',N'너무 피곤했기 때문이에요.',N'낯선 사람을 경계하지 않았기 때문이에요.',N'난쟁이들이 곁에 없었기 때문이에요.',N'3',N'03',N'',N'S'),
	 (172,N'01',N'05',N'등장인물의 성격을 잘못 이야기한 것을 찾으세요.',N'',N'왕비 - 욕심이 지나치고 질투심이 많아요.',N'왕자 - 겁이 많고 소극적이에요. ',N'난쟁이들 - 부지런하고 착해요.',N'백설공주 - 거짓말을 즐기고 욕심이 많아요.',N'4',N'04',N'N',N'S'),
	 (172,N'01',N'06',N'이야기를 읽고 배울 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'남보다 예뻐야 해요.',N'혼자 숲에 가도 괜찮아요.',N'거울 말을 꼭 믿어야 해요.',N'질투하는 마음은 좋지 않아요.',N'4',N'04',N'',N'S'),
	 (172,N'01',N'07',N'왕비는 어떤 마음이었을까요?',N'"숲속에 사는 백설공주님이 가장 예쁘답니다."
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (172,N'01',N'11',N'본래의 모습을 알아볼 수 없게 하여 다르게 바꾸다''라는 뜻을 가진 어휘는 무엇인가요?',NULL,N'변장하다',N'명령하다',N'부탁하다',N'약속하다',N'1',N'06',N'',N'S'),
	 (172,N'01',N'12',N'질투하다''와 가장 가까운 뜻을 가진 말은 무엇인가요?',NULL,N'용감하다',N'샘이 나다',N'좋아하다',N'친절하다',N'2',N'06',N'',N'S'),
	 (173,N'01',N'01',N'임금님은 무엇을 하기 좋아하는 사람이었나요?',NULL,N'옷 타령을 하며 멋진 옷을 좋아함',N'나랏일을 열심히 함',N'가난한 사람들을 잘 돌봐줌',N'군사를 훈련시키는 일을 좋아함',N'1',N'01',N'',N'S'),
	 (173,N'01',N'02',N'임금님은 형제를 불러들여 어떤 명령을 내렸나요?',NULL,N'번쩍거리는 구두를 만들어라.',N'가장 특별한 왕관을 만들어라.',N'세상에서 하나뿐인 옷을 만들어라.',N'커다란 성문을 만들어라.',N'3',N'01',N'',N'S'),
	 (173,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 아이의 말을 들은 임금님은 창피해서 급히 성으로 돌아갔어요.
(2) 마침내 거리 행진이 시작되고 백성들이 구경을 하러 나왔어요.
(3) 형제는 옷을 다 만들었다며 성으로 찾아왔어요.',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'(3)-(2)-(1)  ',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (173,N'01',N'04',N'직접 옷을 본 임금님이 거짓말을 한 까닭은 무엇인가요?',NULL,N'옷을 만든 형제가 실망할까 봐',N'사실대로 말하면 바보로 놀림받을까 봐',N'거리행진을 할 수 없게 될까 봐',N'신하들에게 혼날까 봐',N'2',N'03',N'',N'S'),
	 (173,N'01',N'05',N'<벌거벗은 임금님>이야기의 등장인물 중 다음 낱말과 어울리는 사람을 찾아보세요.',N'사치        허영심       어리석음',N'임금님 ',N' 아이 ',N'백성들',N'형제',N'1',N'04',N'Y',N'S'),
	 (173,N'01',N'06',N'이 이야기에서 임금님의 가장 큰 잘못은 무엇인가요?',NULL,N'백성 말을 잘 들은 것',N'멋진 옷을 좋아한 것',N'남의 말에 휩쓸려 거짓말한 것',N'형제를 믿어준 것',N'3',N'04',N'',N'S'),
	 (173,N'01',N'07',N'임금님은 어떤 마음이었을까요?',N'“우하하! 임금님 좀 봐요. 벌거벗고 다닌대요.”
