INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (175,N'01',N'05',N'일본이 조선을 침략하지 않았다면 윤동주의 삶은 어떻게 달려졌을까요?',NULL,N'아버지의 뜻대로 의사가 되었을 거예요.',N'일본에서 계속 살았을 거예요.',N'평화롭게 시를 쓰며 활동했을 거예요.',N'시인을 그만두었을 거예요.',N'3',N'04',N'',N'S'),
	 (175,N'01',N'06',N'동주가 끝까지 시를 쓰고자 했던 마음에서 알 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'시는 재미로만 쓰는 거예요.',N'공부보다 시 쓰기가 쉬워요.',N'친구들이 좋아하는 행동만 하려고 해요.',N'자신이 하고 싶은 일을 포기하지 않아요.',N'4',N'04',N'',N'S'),
