	 (181,N'01',N'10',N'다음 사건들을 시간 순서대로 나열한 것은 무엇인가요?',N'(1) 장인과 ''나''가 주먹다짐을 했다.
(2) ''나''는 점순이 집의 데릴사위로 들어왔다.
(3) 점순이가 ''나''와 혼례를 하고 싶어 한다.',N'(1)-(2)-(3)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (181,N'01',N'11',N'다음 예시에서 알 수 있는 ''내외''의 뜻은 무엇인가요?',N'마는 우리는 장인님이 ''내외''를 해야 한다고 해서 마주서 이야기도 한 마디 하는 법 없다.',N'안과 밖',N'동기나 친척이 아닌 남녀간에 서로 얼굴을 마주 대하지 않고 피하는 일',N'부부',N'우리 동네와 다른 동네',N'2',N'07',N'Y',N'S'),
	 (181,N'01',N'12',N'새경''을 대체할 수 있는 말은 무엇인가요?',N'',N'빚',N'복권(福券)',N'급여(給與)',N'부유(富裕)',N'3',N'02',N'N',N'S'),
	 (181,N'01',N'13',N'다음 중 장인(丈人)과 뜻이 다른 것은 무엇인가요?',N'',N'빙모(聘母)',N'빙장(聘丈)',N'빙부(聘父)',N'처부(妻父)',N'1',N'03',N'N',N'S'),
	 (181,N'01',N'14',N'다음 중 장인에게 올바른 충고의 말을 하지 않는 사람은 누구인가요?',N'지성: 장인님 계속 데릴사위를 데려다 일만 시키시면 믿는 도끼에 발등 찍힐지도 몰라요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (182,N'01',N'05',N'재동이의 마음이 나중에 바뀌게 된 까닭으로 가장 알맞은 것은 무엇인가요?',NULL,N'보퉁이가 너무 무거웠기 때문에',N'할머니가 가져온 물건들로 즐거운 시간을 보내서',N'할머니가 곶감을 먹지 말라고 해서',N'할머니가 집에 혼자 있으라고 해서',N'2',N'04',N'',N'S'),
	 (182,N'01',N'06',N'할머니를 향한 재동이의 마음이 어떻게 바뀌었을까요?',N'할머니의 불똥이 따끔거리지도 뜨겁지도 않았어요. 오히려 마음이 따뜻해졌어요.',N'여전히 할머니가 무서웠어요.',N'할머니를 사랑하게 되었어요.',N'할머니를 미워하게 되었어요.',N'할머니에게 서운하게 되었어요.',N'2',N'04',N'Y',N'S'),
	 (182,N'01',N'07',N'엄마는 어떤 마음이었을까요?',N'"할머니가 예전에는 힘이 넘치셨는데, 이제는 몸이 많이 약해지신 것 같아."',N'안쓰러운 마음',N'기쁘고 들뜬 마음',N'부끄러운 마음',N'즐거운 마음',N'1',N'05',N'Y',N'S'),
	 (182,N'01',N'08',N'할머니와 함께 시간을 보내며 재동이의 마음은 어떻게 변했을까요?',NULL,N'점점 더 무서워졌어요.',N'화가 났어요.',N'편안하고 따뜻해졌어요.',N'아무 느낌이 없었어요.',N'3',N'05',N'',N'S'),
	 (182,N'01',N'09',N'흉내 내는 말이 <u>잘못</u> 사용된 것을 찾아보세요.',NULL,N'엄마는 깜짝 놀라서 <u>허둥지둥</u>  움직였어요.',N'곶감이 맛있어서 <u>날름날름</u> 집어 먹었어요.',N'할머니가 누워있는 방으로 <u>펄럭펄럭</u> 걸어 갔어요.',N'할머니가 코를 <u>다르랑다르랑</u> 골며 잠들었어요.',N'3',N'02',N'',N'S'),
	 (182,N'01',N'10',N'다음 문장에서 ‘감쪽같이’는 어떤 뜻으로 쓰였나요?',N'"와, 두부 한 접시가 감쪽같이 사라졌네!"',N'접시가 꽉 찰 만큼 많이 남은 모습',N'힘들게 조금씩 먹은 모습',N'일부러 숨겨 놓은 모습',N'어느새 하나도 남지 않은 모습',N'4',N'02',N'Y',N'S'),
	 (182,N'01',N'11',N'물건을 싸놓은 보자기''를 뜻하는 어휘를 찾아 문장을 완성해 보세요.',N'불똥 할머니는 커다란 (        )를 양손에 들고 오셨어요.',N'방망이',N'보퉁이',N'양동이',N'바구니',N'2',N'06',N'Y',N'S'),
	 (182,N'01',N'12',N'다음 중 음식에서 나온 말이 <u>아닌</u> 것을 찾으세요.',NULL,N'골탕',N'마음',N'비지땀',N'숙맥',N'2',N'06',N'',N'S'),
	 (183,N'01',N'01',N'주인공이 ''붉은 여우 아저씨''라고 불린 까닭은 무엇 때문이었나요?',NULL,N'털이 붉은 색이라서',N'눈이 붉은 색이라서',N'모자, 신발, 가방, 옷이 모두 붉은 색이라서',N'얼굴이 늘 붉게 달아올라서',N'3',N'01',N'',N'S'),
	 (183,N'01',N'02',N'아저씨와 처음 만난 대머리 독수리는 무엇을 가져갔나요?',NULL,N'모자',N'가방',N'신발',N'겉옷',N'1',N'01',N'',N'S');
