	 (183,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 아저씨는 함께 길을 떠나준 이들과 친구가 되었어요. 
(2) 붉은 여우 아저씨는 친구를 만나러 가기 위해 길을 나섰어요.
(3) 자신의 것을 모두 나누어 준 아저씨는 흰털만 남게 되었어요.',N'(2)-(1)-(3)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'(1)-(2)-(3)',N'3',N'03',N'Y',N'S'),
	 (183,N'01',N'04',N'붉은 여우 아저씨가 길에서 만난 이들이 점점 늘어난 이유는 무엇인가요?',NULL,N'아저씨가 가진 것이 많아서',N'모두 여행을 좋아해서',N'함께 있으면 재미있어서',N'아저씨가 자신의 것을 나누어 주었기 때문에',N'4',N'03',N'',N'S'),
	 (183,N'01',N'05',N'독수리, 버드나무, 물고기, 아이가 아저씨와 함께 길을 떠나게 된 이유는 무엇인가요?',NULL,N'아저씨가 베푼 고마움에 보답 하려고',N'아저씨의 친구가 궁금해서',N'여행을 떠나고 싶어서',N'혼자 가기 무서워서',N'1',N'04',N'',N'S'),
	 (183,N'01',N'06',N'붉은 여우 아저씨를 칭찬해 줄 말을 찾아보세요.',NULL,N'"용기있는 자세를 배우고 싶어요."',N'"약속을 지키는 모습이 정말 멋졌어요."',N'"자신의 것을 나누는 따뜻한 마음을 본받고 싶어요."',N'"붉은 옷만 입는 모습이 멋져요."',N'3',N'04',N'',N'S'),
	 (183,N'01',N'07',N'숭어는 어떤 마음이었을까요?',N'숭어가 말했어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (184,N'01',N'01',N'충성을 다해 일했지만 주인이 당나귀를 쫓아낸 이유는 무엇인가요?',NULL,N'수레를 망가뜨렸기 때문에',N'나이를 먹자 힘든 일을 할 수 없어져서',N'음악대를 만들고 싶다고 해서',N'말을 듣지 않았기 때문에',N'2',N'01',N'',N'S'),
	 (184,N'01',N'02',N'주인이 자신을 잡아 음식으로 만들겠다고 해서 울고 있던 동물은 누구인가요?',NULL,N'수탉 ',N'사냥개 ',N'고양이',N'당나귀',N'1',N'01',N'',N'S'),
	 (184,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 동물들은 서로 힘을 모아 도둑을 몰아냈어요.
(2) 동물들은 매일 멋진 음악을 연주하며 행복하게 살았어요.
(3) 주인에게 버림받은 동물들은 브레멘으로 가서 음악대를 만들기로 했어요.',N'(1)-(3)-(2) ',N'(3)-(1)-(2)',N'(3)-(2)-(1)  ',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (184,N'01',N'04',N'동물들이 도둑을 쫓아낼 수 있었던 가장 큰 이유는 무엇인가요?',NULL,N'도둑들이 너무 약했기 때문이에요.',N'밤이라 아무도 없었기 때문이에요.',N'우연히 소리를 질렀기 때문이에요.',N'동물들이 힘을 합쳤기 때문이에요.',N'4',N'03',N'',N'S'),
	 (184,N'01',N'05',N'이야기 속 등장인물에게 해줄 수 있는 말로 올바르지 않는 것을 찾으세요.',NULL,N'주인-함께 살던 동물을 쓸모가 없어졌다고 쫓아내는 건 정말 나쁜 행동이에요.  ',N'동물들-힘을 모아 어려움을 이겨내고 행복하게 지내게 되어 정말 다행이에요.',N'도둑들-동물들에게서 훔친 음식은 그냥 가져도 돼요.',N'동물들-서로 도와서 문제를 해결한 점이 멋져요.',N'3',N'04',N'',N'S'),
	 (184,N'01',N'06',N'이 책을 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'혼자서만 잘하면 돼요.',N'나이가 들면 쓸모가 없어요.',N'힘을 모으면 어려움을 이길 수 있어요.',N'도둑은 언제나 이겨요.',N'3',N'04',N'',N'S'),
	 (184,N'01',N'07',N'늙은 고양이가 쥐를 잡지 못한 다고 구박을 받을 때 어떤 마음일까요? ',NULL,N'기뻐서 훨훨 날아갈 것 같은 마음 ',N'슬퍼서 엉엉 울고 싶은 마음 ',N'화가 나서 견딜 수 없는 마음 ',N'신나서 자랑하고 싶은 마음',N'2',N'05',N'',N'S'),
