	 (200,N'01',N'06',N'다음 괄호 안에 어울리는 말로 적절한 것은 무엇인가요?',N'인기척도 없이 (       )들어온 선생님이 토론 시작을 알렸다.',N'우당탕',N'스리슬쩍',N'쏜살같이',N'뉘엿뉘엿',N'2',N'02',N'Y',N'S'),
	 (200,N'01',N'07',N'그리스 신화에 나오는 짐승으로, 한 개체 내에 서로 다른 유전적 성질을 가지는 동종의 조직이 함께 존재하는 현상을 뜻하기도 한 이것의 이름은 무엇인가요?',N'',N'고블린',N'타이탄',N'키메라',N'제우스',N'3',N'07',N'N',N'S'),
	 (200,N'01',N'08',N'생명과 과학의 연관에 대하여 윤리적, 도덕적으로 분석하려는 학문을 무엇이라고 하나요?',N'',N'생명 윤리',N'과학 윤리',N'생명 과학',N'윤리 도덕',N'1',N'07',N'N',N'S'),
	 (200,N'01',N'09',N'인공장기를 사용하는 것이 심각한 문제를 일으킬 수 있는 이유는 무엇인가요?',N'',N'인공 장기는 쉽게 녹스는 경우가 많기 때문에',N'인공 장기를 누구나 쉽게 만들 수 있기 때문에',N'인공 장기를 돈 많은 사람들만 구하게 되어 사람들 간의 차별이 더욱 심해질 수 있기 때문에',N'인공 장기는 다른 생명을 해치지 않는 윤리적인 방법이기 때문에',N'3',N'03',N'N',N'S'),
	 (200,N'01',N'10',N'동물실험의 윤리적 기준인 3R 원칙이 아닌 것은 무엇인가요?',N'',N'대체하기(Replacement)',N'줄이기(Reduction)',N'반응하기(Reaction)',N'개선하기(Refinement)',N'3',N'03',N'N',N'S'),
	 (200,N'01',N'11',N' 본디의 것과 똑같은 것을 만듦. 또는 그렇게 만든 것을 뜻하는 단어는 무엇인가요?',N'',N'복제(複製)',N'위조(僞造)',N'복원(復元)',N'복구(復舊)',N'1',N'06',N'N',N'S'),
	 (200,N'01',N'12',N'수정란이 배낭(胚囊) 속에서 분열 증식하여 홀씨체의 바탕이 되는 것, 또는 난할을 시작한 이후의 개체를 뜻하는 단어는 무엇인가요?',N'',N'태아(胎兒)',N'배아(胚芽)',N'줄기세포',N'모세포(母細胞)',N'2',N'06',N'N',N'S'),
	 (200,N'01',N'13',N'옮겨서 붙이거나 심는 것을 무엇이라고 하나요?',N'',N'이사(移徙)',N'이식(移植)',N'이민(移民)',N'이주(移住)',N'2',N'06',N'N',N'S'),
	 (200,N'01',N'14',N'극심한 고통을 받고 있는 불치의 환자에 대하여, 본인 또는 가족의 요구에 따라 고통이 적은 방법으로 생명을 단축하는 행위를 무엇이라고 하나요?',N'',N'즉사(卽死)',N'뇌사(腦死)',N'안락사(安樂死)',N'고사(枯死)',N'3',N'06',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (200,N'01',N'15',N'이론이나 현상을 관찰하고 측정하는 것을 무엇이라고 하나요?',N'',N'실험(實驗)',N'생체(生體)',N'경험(經驗)',N'관망(觀望)',N'1',N'06',N'N',N'S'),
	 (201,N'01',N'01',N'아모스가 자신이 만든 배에 붙여준 이름은 무엇인가요?',NULL,N'코끼리호  ',N' 고래호 ',N'생쥐호',N'바다호',N'3',N'01',N'',N'S'),
	 (201,N'01',N'02',N'아모스 곁에 나타난 보리스는 어떤 동물인가요?',NULL,N'상어',N'고래',N'코끼리',N'돌고래',N'2',N'01',N'',N'S'),
	 (201,N'01',N'03',N' 일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 보리스의 몸이 드디어 바다 속으로 밀려들어 갔습니다.  
(2) 두 친구는 눈물을 흘리며 작별인사를 나누었습니다.
(3) 아모스는 도움이 필요할 때 꼭 도와주겠다      고 말하며 보리스 등에서 뛰어 내렸습니다.',N'(1)-(3)-(2) ',N'(2)-(1)-(3)',N'(3)-(1)-(2)',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (201,N'01',N'04',N'아모스가 바다에서 위험에 빠지게 된 이유는 무엇인가요?',NULL,N'바다 여행이 재미없어서 돌아가고 싶었기 때문에',N'고래를 만나서 겁에 질렸기 때문에',N'집으로 돌아가기 싫어서 방향을 틀었기 때문에',N'풍랑을 만나 배를 잃었기 때문에',N'4',N'03',N'',N'S'),
	 (201,N'01',N'05',N'작은 생쥐 아모스와 덩치 큰 고래 보리스는 어떻게 친구가 될 수 있었을까요?',NULL,N'서로의 좋은 점을 부러워하다가 결국 친구가 되었어요.',N'어려움에 처했을 때 서로의 생명을 구해주고 소중한 친구가 되었어요.',N'젖을 먹고 사는 동물이라는 공통점이 있었기 때문에 친구가 되었어요.',N'함께 놀 시간이 많아서 친구가 되었어요.',N'2',N'04',N'',N'S'),
	 (201,N'01',N'06',N'이 이야기에서 ‘진짜 친구’의 모습으로 알맞은 것은 무엇인가요?',NULL,N'항상 같이 놀아 주는 친구',N'재미있는 이야기만 하는 친구',N'서로 필요할 때 도와주는 친구',N'선물을 많이 주는 친구',N'3',N'04',N'',N'S'),
	 (201,N'01',N'07',N'보리스는 어떤 마음이었을까요?',N'‘아모스가 정말 나를 도울 수 있을까? 저렇게 작은 친구가 어떻게 해 줄 수 있을까?’',N'불안하고 걱정스러운 마음',N'다행스럽고 고마운 마음',N'기쁘고 뿌듯한 마음',N'화가 나고 속상한 마음',N'1',N'05',N'Y',N'S'),
	 (201,N'01',N'08',N'보리스가 다시 바다로 돌아가게 되었을 때 아모스의 마음은 어땠을까요?',NULL,N'무섭고 떨렸어요.',N'화가 났어요.',N'부끄럽고 창피했어요.',N'기쁘지만 아쉬웠어요.',N'4',N'05',N'',N'S'),
	 (201,N'01',N'09',N'다음 문장에 어울리는 흉내 내는 말을 찾아보세요.',N'코끼리들은 온 힘을 다해 보리스의 커다란 몸을 밀기 시작했습니다.',N'영차영차',N'느릿느릿',N'훌쩍훌쩍',N'살금살금',N'1',N'02',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (201,N'01',N'10',N'빈칸에 어울리는 표현을 찾아 보세요.',N'아모스는 생쥐호의 갑판에 누워 (     )거리는 별이 가득 담긴 드넓은 하늘을 바라보았습니다.',N'아장',N'사뿐',N'쿵쾅',N'초롱',N'4',N'02',N'Y',N'S'),
	 (201,N'01',N'11',N'일에 나서서 참견하거나 관심을 두는 일''을 뜻하는 말은 무엇인가요?',NULL,N'아랑곳 ',N'무시',N'대꾸',N'걱정',N'1',N'06',N'',N'S'),
	 (201,N'01',N'12',N'‘항해’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'집에서 쉬는 것',N'배를 타고 바다를 건너가는 것',N'바닷가에서 노는 것',N'물고기를 잡는 것',N'2',N'06',N'',N'S'),
	 (202,N'01',N'01',N'하늘다람쥐에게 ''공중 길'' 역할을 하는 것는 무엇인가요? ',NULL,N'넙적한 바위',N'평평한 들판',N'높은 나무',N'깊은 강물',N'3',N'01',N'',N'S'),
	 (202,N'01',N'02',N'동물들이 가족을 만나지 못하고, 먹이를 찾으러 갈 수 없게 된 이유는 무엇인가요?',NULL,N'도로의 자동차가 무서워 길을 건너지 못하기 때문이에요.',N'힘이 센 동물들의 괴롭힘 때문이에요.',N'살던 곳의 환경이 오염되었기 때문이에요. ',N'가는 길을 잊어버렸기 때문이에요.',N'1',N'01',N'',N'S'),
	 (202,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 짝을 만나러 나선 하늘 다람쥐는 길을 잃고 멈춰섰어요.
(2) 하늘다람쥐 수컷이 도로 가에 세워진 막대기에 올라갔어요.
(3) 사람들은 길을 잃은 물고기들을 위해 ''어도''를 만들었어요. ',N'(1)-(2)-(3)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'(3)-(2)-(1)',N'2',N'03',N'Y',N'S'),
	 (202,N'01',N'04',N'사람들이 동물들을 위해 새로운 ''길''을 만든 이유는 무엇인가요?',NULL,N'동물들이 길을 좋아해서',N'사람들이 걷기 편하게 하려고',N'동물들이 안전하게 이동하도록 도와주려고',N'동물들에게 새로운 먹이를 주려고',N'3',N'03',N'',N'S'),
	 (202,N'01',N'05',N'생태통로를 만들지 않았다면 동물들은 어떻게 되었을까요?',NULL,N'많은 동물들이 길을 잃고 죽거나 다쳤을 거예요.',N'사랑하는 가족과 만나 행복하게 지냈을 거예요.',N'길을 건너 마음대로 먹이를 구하러 다녔을 거예요.',N'더 많은 먹이를 구할 수 있었을 거예요.',N'1',N'04',N'',N'S'),
	 (202,N'01',N'06',N'우리가 자연을 대할 때 가져야 할 생각으로 알맞은 것은 무엇인가요?',NULL,N'자연은 사람 마음대로 바꿔도 돼요.',N'동물은 사람을 피해 살아야 해요.',N'동물은 혼자 살아도 괜찮아요.',N'사람과 동물이 함께 살 방법을 생각해야 해요.',N'4',N'04',N'',N'S'),
	 (202,N'01',N'07',N'하늘 다람쥐의 마음은 어땠을까요?',N'수컷은 먼 나무 끝에서 발만 동동 굴렀어요. 건너편 숲을 바라보며 ''찍찍'' 울었어요. ',N'후회스러워요.',N'안타까워요.',N'부끄러워요.',N'신나고 즐거워요.',N'2',N'05',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (202,N'01',N'08',N'생태통로가 생긴 뒤 동물들의 마음은 어땠을까요?',NULL,N'무섭고 떨렸어요.',N'화가 나고 속상했어요.',N'안심되고 기뻤어요.',N'슬프고 억울했어요.',N'3',N'05',N'',N'S'),
	 (202,N'01',N'09',N'다음 문장에 어울리는 흉내 내는 말을 찾아보세요.',N'낮 기온이 올라가자 만들어 두었던 눈사람이 녹았어요.',N'사르르',N'주르르',N'부르르',N'포르르',N'1',N'02',N'Y',N'S'),
	 (202,N'01',N'10',N'다음 문장에 어울리는 흉내 내는 말을 찾아보세요.',N'널찍한 도로 위를 엄청난 소리를 내며 바퀴 괴물이 달려요.',N'어슬렁',N'부아앙',N'푸드득',N'흐느적',N'2',N'02',N'Y',N'S'),
	 (202,N'01',N'11',N'‘어도’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'사람이 다니는 길',N'다람쥐가 숲을 다닐 수 있게 만든 길',N'물고기가 강을 오르내릴 수 있게 만든 길',N'새가 자유롭게 하늘을 날도록 만든 길',N'3',N'06',N'',N'S'),
	 (202,N'01',N'12',N'땅의 생긴 모양을 가리키는 낱말을 찾아보세요.',NULL,N'지형',N'수형',N'원형',N'큰형',N'1',N'06',N'',N'S'),
	 (203,N'01',N'01',N'윌버가 태어나자마자 죽을 뻔한 이유는 무엇인가요?',N'',N'윌버가 다른 새끼 돼지들을 잡아먹으려고 해서',N'윌버가 먹이를 너무 많이 먹어서',N'윌버가 너무 작고 약했기 때문에',N'윌버가 엄마의 다리에 깔려서',N'3',N'01',N'N',N'S'),
	 (203,N'01',N'02',N'주커만 부인이 품평회에 나가기 전 무엇으로 윌버를 목욕시켰나요?',N'',N'약초 달인 물',N'우유',N'비눗물',N'비누거품',N'2',N'01',N'N',N'S'),
	 (203,N'01',N'03',N'윌버가 샬롯을 처음 만났을 때 가졌던 감정은 무엇인가요?',N'',N'벌레를 잡는 모습을 보고 용감하다고 생각했다.',N'벌레를 잡는 모습을 보고 잔인하고 교활하다고 생각했다.',N'벌레를 잡는 모습을 보고 가엾다고 생각했다.',N'벌레를 잡는 모습을 보고 몹시 굶주렸다고 생각했다.',N'2',N'04',N'N',N'S'),
	 (203,N'01',N'04',N'윌버가 헛간에서 탈출했다가 다시 돌아왔을 때 느꼈던 심정은 무엇인가요?',N'',N'아직 어려서 혼자서는 바깥 세상에 나갈 수 없다고 생각했다.',N'다음번에 다시 탈출을 시도해야겠다고 생각했다.',N'자신을 도와주지 않은 다른 동물들을 원망했다.',N'탈출에 성공하지 못하고 다시 돌아 온 것이 분하고 참을 수가 없었다.',N'1',N'04',N'N',N'S'),
	 (203,N'01',N'05',N'귀뚜라미들이 노래를 한다''는 것이 의미하는 것은 무엇인가요?',N'',N'여름이 끝나가고 가을이 오고있다.',N'위험한 일이 일어날 것을 암시한다.',N'윌버가 기분이 좋다는 것을 말해준다.',N'무더위가 찾아올 것임을 암시한다.',N'2',N'02',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (203,N'01',N'06',N'샬롯이 자신의 알주머니를 윌버에게 무엇이라고 소개했나요?',N'',N'장난감',N'필생의 역작',N'새롭고 눈부신 효과',N'생명의 보금자리',N'2',N'02',N'N',N'S'),
	 (203,N'01',N'07',N'전체 줄거리를 살펴 보았을 때, 사람들이 돼지를 키우는 주된 이유는 무엇인가요?',N'',N'품평회에 데리고 나가 상금을 타기 위해',N'살을 찌워 팔거나 햄, 베이컨등을 만들기 위해',N'돼지가 가장 근사한 동물이기 때문에',N'포동 포동한 모습이 귀여워서 애완용으로 적합하기 때문에',N'2',N'07',N'N',N'S'),
	 (203,N'01',N'08',N'윌버가 샬롯을 점점 좋아하게된 이유가 아닌 것은 무엇인가요?',N'',N'벌레 퇴치 운동이 분별 있고 유익해서',N'윌버에게 먹이를 가져다 줘서',N'벌레들을 먹기 전에 그것들을 잠들게 해서',N'윌버의 말을 끝까지 들어줘서',N'3',N'07',N'N',N'S'),
	 (203,N'01',N'09',N'샬롯이 거미줄에 ''근사한 돼지''라고 글을 쓰게 된 진짜 목적은 무엇인가요? ',N'',N'윌버를 살리기 위해서',N'윌버가 얼마나 근사한 돼지인지 사람들에게 알리고 싶어서',N'윌버가 품평회에 나갈 수 있도록 하려고',N'윌버와 사람들을 속이기 위해',N'1',N'03',N'N',N'S'),
	 (203,N'01',N'10',N'애러블 부인이 도리언 박사를 찾아간 이유는 무엇인가요?',N'',N'거미줄 이야기를 들려주고 조언을 구하기 위해',N'펀의 남자 친구 문제에 대해 조언을 구하기 위해',N'펀이 가축들과 너무 많은 시간을 보내는 것에 대해 조언을 구하기 위해',N'평소 도리언 박사의 유명세를 신망했기 때문에',N'3',N'03',N'N',N'S'),
	 (203,N'01',N'11',N'물건이나 작품의 좋고 나쁨을 평하는 모임''을 뜻하는 단어는 무엇인가요?',N'',N'품평회',N'시상식',N'경진대회',N'경주대회',N'1',N'06',N'N',N'S'),
	 (203,N'01',N'12',N'샬롯이 죽기 직전 마지막으로 썼던 단어로, ''스스로를 낮추고 비우는 태도가 있다''는  뜻을 나타내는 말은 무엇인가요?',N'',N'근사한',N'겸허한',N'진중한',N'화려한',N'2',N'06',N'N',N'S'),
	 (203,N'01',N'13',N'재주도 많고 능력도 뛰어나다''는 뜻을 나타내는 단어는 무엇인가요?',N'',N'다재다능',N'우수한',N'대단한',N'사방팔방',N'1',N'06',N'N',N'S'),
	 (203,N'01',N'14',N'자기 잇속에 맞게 행동하는 데 재빠르다''는 뜻으로 탬플턴의 성격이기도 한 이 단어는 무엇인가요?',N'',N'명석하다',N'침착하다',N'약삭빠르다',N'연약하다',N'3',N'06',N'N',N'S'),
	 (203,N'01',N'15',N'힘이 쇠하고 약하다''는 뜻을 나타내는 단어는 무엇인가요?',N'',N'공허하다',N'노쇠하다',N'쇠약하다',N'유연하다',N'3',N'06',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (204,N'01',N'01',N'덕만 공주는 당나라에서 보낸 그림을 보고 뭐라고 하였나요?',N'',N'꽃이 아름답다고 하면서 감탄했어요.',N'향기가 없는 꽃이라고 말했어요.',N'좋아하는 꽃이 그려져 있다고 했어요.',N'꽃의 색이 이상하다고 했어요.',N'2',N'01',N'',N'S'),
	 (204,N'01',N'02',N'진평왕이 후계자를 정하지 못한 채 세상을 떠난 후 무슨 일이 일어났나요?',N'',N'화백회의를 열어서 덕만 공주가 왕이 될지를 의논했어요.',N'진지왕의 아들이 왕이 되었어요.',N'귀족들이 화백 회의에 참여하지 않았어요.',N'백제와 전쟁이 바로 시작되었어요.',N'1',N'03',N'',N'S'),
	 (204,N'01',N'03',N'화백회의의 특징을 찾아보세요.',N'',N'한사람만 찬성해도 의견이 통과되어요.',N'나라의 큰일들이 결정되어요.',N'성골 이상의 귀족들만 참여해요.',N'왕만 참석할 수 있어요.',N'2',N'01',N'',N'S'),
	 (204,N'01',N'04',N'‘예의없는 태도''를 가리키는 말을 찾으세요.',N'',N'무식하다.',N'무지하다. ',N'무례하다.',N'무관심하다.',N'3',N'06',N'',N'S'),
	 (204,N'01',N'05',N'선덕여왕의 마음은 어땠을까요?',N'"나라를 지키는 데 앞장서야 할 귀족들이 반란을 일으키다니, 아무래도 내가 덕이 부족한 모양입니다."',N'슬프고 안타까운 마음',N'걱정되고 화나는 마음',N'설레고 기쁜 마음',N'자랑스럽고 뿌듯한 마음',N'1',N'05',N'Y',N'S'),
	 (204,N'01',N'06',N'백제군이 쳐들어왔을때 김춘추가 선덕여왕을 찾아온 이유는 무엇인가요?',N'',N'백제의 왕을 찾아가겠어요.',N'고구려에 가서 군사를 얻어오겠어요.',N'당나라에 가서 군사를 얻어오겠어요.',N'왜군을 피해 도망가겠어요.',N'2',N'04',N'',N'S'),
	 (204,N'01',N'07',N'다음 빈칸에 들어갈 낱말이 순서대로 바르게 적혀진 것을 고르세요.',N'김춘추를 중심으로 (A)을 벌이는 한편 김유신을 시켜 (A)을 키웠어요.',N'전쟁, 군대',N'군대, 외교활동',N'외교활동, 군대',N'외교활동, 백성',N'3',N'06',N'Y',N'S'),
	 (204,N'01',N'08',N'다음 문장에 어울리는 표현을 찾아보세요.',N'부끄러워서 얼굴이 붉어졌어요.',N'사과처럼',N'우유처럼',N'은행잎처럼',N'눈처럼',N'1',N'02',N'Y',N'S'),
	 (204,N'01',N'09',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'1) 당나라에 선물을 주며 군대를 보내달라고 했어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (204,N'01',N'11',N'덕만 공주가 나라의 일을 걱정하며 밤늦게까지 생각할 때 마음은 어떠했을까요?',N'',N'신나고 즐거운 마음',N'장난스러운 마움',N'부끄럽고 수줍은 마음',N'걱정되고 책임감 있는 마음',N'4',N'05',N'',N'S'),
	 (204,N'01',N'12',N'빈칸에 들어갈 가장 알맞은 흉내내는 말을 고르세요.',N'백성들이 선덕여왕의 이야기를 듣고 ( ) 박수를 쳤어요.',N'짝짝',N'반짝반짝',N'와글와글',N'살금살금',N'1',N'02',N'Y',N'S'),
	 (205,N'01',N'01',N'심심해서 병원 안을 돌아다니던 기오는 무엇을 보게 되었나요?',NULL,N'장기려 선생님이 쉬지않고 환자를 보러 다니는 모습',N'장기려 선생님이 퇴원 못하는 환자를 위해 몰래 뒷문을 열어놓는 모습 ',N'장기려 선생님이 가난한 사람에게 자신의 월급을 통째로 주는 모습',N'장기려 선생님이 병원에서 혼자 쉬는 모습',N'1',N'01',N'',N'S'),
	 (205,N'01',N'02',N'사람들이 선생님을 ''바보 의사''라고 부른 까닭은 무엇인가요?',NULL,N'항상 손해를 보고도 아무말 않고 자기탓을 하셨기 때문에 ',N'자신을 생각하기보다 남한테 베풀기만 하는 삶을 사셨기 때문에',N'어릴 적부터 별명이 바보 의사였기 때문에',N'어릴 적부터 공부를 못했기 때문에',N'2',N'01',N'',N'S'),
	 (205,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 쓰러지기 직전까지 환자를 돌보시던 선생님은 크리스마스날 세상을 떠났어요.
(2) 선생님은 무료병원을 열어 거리의 환자들을 정성껏 치료하기 시작했어요.
(3) 건강할 때 돈을 모아 병이 났을때 치료 받을 수 있는 방법을 고민하셨어요.',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'2',N'03',N'Y',N'S'),
	 (205,N'01',N'04',N'며칠째 선생님이 보이지 않았던 까닭은 무엇인가요?',NULL,N'너무 일을 많이 하셔서 병이 나셨기 때문이에요',N'북쪽에 있는 가족을 만나러 가셨기 때문이에요.',N'의사가 없는 마을로 사람들을 치료하러 가셨기 때문이에요.',N'병원을 그만두셨기 때문이에요',N'3',N'03',N'',N'S'),
	 (205,N'01',N'05',N'이 책을 읽은 후 감상을 <u>잘못</u> 이야기한 것을 찾아보세요.',NULL,N'환자를 사랑으로 대하는 마음을 많은 의사들이 본받았으면 좋겠어.',N'어려운 사람들에게 아낌없이 베푼 자세는 슈바이처와 닮은 것 같아.',N'장기려 선생님 덕분에 오늘날 정보 통신 분야가 크게 발전한 것 같아.  ',N'사람을 살리는 삶은 정말 값진 것 같아.',N'3',N'04',N'',N'S'),
	 (205,N'01',N'06',N'선생님의 삶에서 가장 잘 드러나는 생각으로 알맞은 것은 무엇인가요?',NULL,N'의사는 돈을 많이 벌어야 해요.',N'혼자만 건강하면 돼요.',N'병원은 꼭 큰 도시에만 있어야 해요.',N'어려운 사람을 위해 자신의 것을 내놓을 수 있어요.',N'4',N'04',N'',N'S'),
	 (205,N'01',N'07',N'엄마는 어떤 마음이었을까요?',N'"기오야, 복음병원이라는 데가 있대. 가난한 사람들을 돌보려고 만든 병원인데, 의사 선생님이 우리 기오 무릎을 고쳐주실 거야."',N'한숨 쉬며 걱정하는 마음',N'괴롭고 허탈한 마음',N'희망을 찾아 안도하는 마음',N'화가 나고 속상한 마음',N'3',N'05',N'Y',N'S'),
	 (205,N'01',N'08',N'선생님은 어떤 마음이었을까요?',N'"기오를 보면 우리 아들 생각이 많이나. 내가 환자들을 정성껏 돌보면 북쪽의 우리 가족도 누군가 돌봐 주겠지 하는 생각이 들어."',N'감동적이고 벅찬 마음',N'애잔하고 그리운 마음',N'불안하고 조마조마한 마음',N'무섭고 떨리는 마음',N'2',N'05',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
