	 (213,N'01',N'09',N'다음 대화를 읽고 거짓을 말하는 사람을 찾아보세요.',N'지호: 얘들아 그거 봤니? 화력발전소에도 물이 필요하대.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (214,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요. ',N'(1) 서른여덟 명의 간호 원정대와 스쿠타리 병원에 갔어요.
(2) 콜레라가 돌았을때 빈민지역으로 달려갔어요.
(3) 고향으로 돌아와 병과 굶주림에 고통받는 사람들을 위해 일했어요.',N'(2)-(3)-(1)',N'(1)-(2)-(3)',N'(2)-(1)-(3)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (214,N'01',N'04',N'플로렌스가 ‘등불을 든 천사’라고 불리게 된 이유는 무엇인가요?',NULL,N'등불을 좋아했기 때문이에요.',N'천사처럼 예뻤기 때문이에요.',N'항상 웃는 표정이었기 때문이에요.',N'밤에도 쉬지 않고 병사들을 돌봤기 때문이에요.',N'4',N'03',N'',N'S'),
	 (214,N'01',N'05',N'나이팅게일에게서 본받을 점은 무엇인가요?',NULL,N'귀족으로 태어나 천한 직업을 선택했어요.',N'평생 남을 위해 봉사하는 삶을 살았어요.',N'영국에서 영웅이 되었어요. ',N'돈을 많이 벌었어요.',N'2',N'04',N'',N'S'),
	 (214,N'01',N'06',N'나이팅게일이 간호사의 길을 포기하지 않은 이유로 가장 알맞은 것은 무엇인가요?',NULL,N'가족들이 열심히 응원해 주었기 때문이에요.',N'유명해지고 싶었기 때문이에요.',N'아픈 사람을 돕는 일이 중요하다고 생각했기 때문이에요.',N'간호사로 일하면 돈을 많이 벌 수 있었기 때문이에요.',N'3',N'04',N'',N'S'),
	 (214,N'01',N'07',N'플로렌스와 간호사들의 마음은 어땠을까요?',N'스쿠타리의 병원에 도착했을때, 그들을 반겨준 것은 쓰레기 더미와 오물에서 나는 악취였어요.',N'화가 났어요.',N'다시 돌아가고 싶어요.',N'충격적이고 안타까워요.',N'즐겁고 설레요.',N'3',N'05',N'Y',N'S'),
	 (214,N'01',N'08',N'병사들이 플로렌스를 보며 편안히 잠들 때의 마음은 어땠을까요?',NULL,N'무섭고 떨렸어요.',N'고맙고 든든했어요.',N'부끄럽고 창피했어요.',N'화가 나고 속상했어요.',N'2',N'05',N'',N'S'),
	 (214,N'01',N'09',N'빈칸에 어울리는 흉내내는 말을 찾아보세요',N'플로렌스를 보면 고통도 잊은 채 (         ) 잠이 들곤 했지요.',N'포르르',N'스르르',N'주르르',N'파르르',N'2',N'02',N'Y',N'S'),
	 (214,N'01',N'10',N'빈칸에 어울리는 흉내내는 말을 찾아보세요',N'플로렌스는 밤마다 병실을 (          ) 걸으며 아픈 병사들을 살폈어요.',N'쿵쾅쿵쾅',N'덜컹덜컹',N'팔랑팔랑',N'조심조심',N'4',N'02',N'Y',N'S'),
	 (214,N'01',N'11',N'영웅''을 대신해 쓸 수 있는 말은 무엇인가요?',NULL,N'위인',N'은인',N'연인',N'여인',N'1',N'06',N'',N'S'),
	 (214,N'01',N'12',N'‘봉사하다’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'돈을 모으는 것',N'명령을 내리는 것',N'남을 위해 힘과 마음을 쓰는 것',N'여행을 떠나는 것',N'3',N'06',N'',N'S');
