	 (217,N'01',N'07',N'셰익스피어가 희곡만 쓴 이유는 무엇인가요?',N'',N'셰익스피어 자신이 직접 연기하기 위해서',N'그 당시에는 아직 소설이라는 형식이 생겨나지 않았기 때문에',N'희곡은 작품성을 크게 고려하지 않아도 괜찮기 때문에',N'희곡은 문학갈래 중 유일하게 이야기구성의 전개가 가능하기 때문에',N'2',N'07',N'N',N'S'),
	 (217,N'01',N'08',N'다음 중 실제 있었던 일을 바탕으로 만들어진 작품은 무엇인가요?',N'',N'햄릿',N'오셀로',N'맥베스',N'리어 왕',N'3',N'07',N'N',N'S'),
	 (217,N'01',N'09',N'《리어왕》에서, 에드먼드가 형에게 앙심을 품은 이유는 무엇인가요?',N'',N'첩에게서 태어났다는 이유로 형과 차별대우를 받아왔기 때문에',N'형이 자신이 사랑하는 여자와 결혼했기 때문에',N'어머니가 재산을 형에게만 물려주려고 했기 때문에',N'아버지를 아버지라고 부르지 못하고 형을 형이라고 부르지 못해서',N'1',N'03',N'N',N'S'),
	 (217,N'01',N'10',N'《오셀로》에서, 이아고가 캐시오에게 술을 권한 진짜 이유는 무엇인가요?',N'',N'캐시오의 속마음을 알기 위해서',N'캐시오가 술을 마시고 실수하게끔 유도하려고',N'캐시오를 일찍 잠들게 하려고',N'술에 독을 타서 독살하기 위해서',N'2',N'03',N'N',N'S'),
	 (217,N'01',N'11',N'인간의 불행과 고통을 묘사한 연극이나 영화, 또는 매우 비참한 사건''을 뜻하는 단어는 무엇인가요?',N'',N'비극(悲劇)',N'희극(喜劇)',N'희곡(戲曲)',N'비장(備藏)',N'1',N'06',N'N',N'S'),
	 (217,N'01',N'12',N'서로 다른 일이나 사물을 구별하여 가름''을 뜻하는 단어는 무엇인가요?',N'',N'분별(分別)',N'분리(分離)',N'차별(差別)',N'차등(差等)',N'1',N'06',N'N',N'S'),
	 (217,N'01',N'13',N'일정한 지위나 임무를 남에게 맡김''을 뜻하는 단어는 무엇인가요?',N'',N'부과(賦課)',N'임명(任命)',N'명령(命令)',N'임무(任務)',N'2',N'06',N'N',N'S'),
	 (217,N'01',N'14',N'자기가 저지른 일의 과보가 자기 자신에게 돌아감''을 뜻하는 사자성어는 무엇인가요?',N'',N'고진감래(苦盡甘來)',N'자업자득(自業自得)',N'사필귀정(事必歸正)',N'다다익선(多多益善)',N'2',N'06',N'N',N'S'),
	 (217,N'01',N'15',N'일반적으로는 어떤 일에 직접 관련된 사람을 뜻하는 단어는 무엇인가요?',N'',N'용의자(容疑者)',N'배신자(背信者) ',N'당사자(當事者)',N'피의자(被疑者)',N'3',N'06',N'N',N'S'),
	 (218,N'01',N'01',N'게으름뱅이는 바쁜 농사철에 어떻게 지냈나요?',N'  ',N'밭에 나가 열심히 일했어요.',N'방에서 놀기만 했어요. ',N'친구를 만나러 나갔어요.',N'시장에 나갔어요.',N'2',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (218,N'01',N'02',N'아내의 잔소리를 들은 게으름뱅이는 무엇을 하기로 마음먹었나요?',NULL,N'열심히 일하기로 했어요.',N'잠을 자기로 했어요.',N'집을 나가기로 했어요.',N'아내에게 사과하기로 했어요.',N'3',N'01',N'',N'S'),
	 (218,N'01',N'03',N'게으름뱅이가 겪은 일을 순서대로 나열한 것을 찾으세요. ',N'(1) 농부에게 팔려가 힘들게 일을 했어요.
(2) 쇠머리 탈을 쓰고 소가 되었어요.
(3) 무를 먹자 사람으로 돌아오게 되었어요.',N'(3)-(1)-(2)',N'(2)-(1)-(3) ',N'(1)-(2)-(3)',N'(2)-(3)-(1)',N'2',N'03',N'Y',N'S'),
	 (218,N'01',N'04',N'게으름뱅이가 다시 사람으로 돌아올 수 있었던 까닭은 무엇인가요?',NULL,N'농부가 도와주었기 때문이에요.',N'아내가 찾아왔기 때문이에요.',N'일을 열심히 했기 때문이에요.',N'무밭에서 무를 먹었기 때문이에요.',N'4',N'03',N'',N'S'),
	 (218,N'01',N'05',N'다시 사람으로 돌아오게 된 게으름뱅이는 무엇을 깨달았을까요?',NULL,N'약속을 꼭 지켜야겠다.',N'욕심을 부리지 않아야겠다.',N'부지런한 사람이 되어야겠다.',N'집을 나가면 안 되겠다.',N'3',N'04',N'',N'S'),
	 (218,N'01',N'06',N'이 이야기에서는 게으름을 계속 부리면 어떤 일이 생길 수 있다는 것을 알려 주나요?',NULL,N'재미있는 일이 더 많아질 수 있어요.',N'다른 사람에게 도움을 받을 수 있어요.',N'아무 일도 일어나지 않아요.',N'힘들고 괴로운 일을 겪을 수 있어요.',N'4',N'04',N'',N'S'),
	 (218,N'01',N'07',N'게으름뱅이는 어떤 마음이었을까요? ',N'쇠머리 탈은 얼굴에서 떨어지지 않았어요.
