INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (230,N'01',N'03',N'어기면 무서운 일이 생긴다는 달빛초원의 전설이 아닌 것은 무엇인가요?',N'',N'수탉이 낳은 알을 발견한 코끼리는 물을 마시면 안 된다.',N'칠 년 된 수탉은 알을 낳아서는 안 된다.',N'두꺼비는 수탉이 낳은 알을 품어서는 안 된다.',N'수탉이 낳은 알은 깨뜨리거나 숨겨야 한다.',N'1',N'01',N'N',N'S'),
	 (230,N'01',N'04',N'바실리스크가 저주 받은 동물이라고 말하는 이유가 아닌 것은 무엇인가요? ',N'',N'두꺼비가 품은 알에서 나왔기 때문에',N'숨만 닿아도 풀이 말라 죽기 때문에',N'부리가 물에 닿기만 해도 시냇물에 독이 퍼지기 때문에',N'수탉이 제대로 보살펴주지 않았기 때문에',N'4',N'03',N'N',N'S'),
	 (230,N'01',N'05',N'나무늘보 주술사가 바실리스크를 없애려는 동물들한테 한 말로 옳은 것은 무엇인가요?',N'',N'바실리스크를 없애면 달빛초원이 사라질 거야.',N'바실리스크는 절대 죽지 않는 불멸의 동물이야.',N'생명은 귀한 것인데, 독을 없애는 방법을 찾는 건 어떨까?',N'바실리스크를 미리 없애서 혹시 모를 우리 마을의 우환을 제거해야해',N'3',N'04',N'N',N'S'),
	 (230,N'01',N'06',N'바실리스크 꿈에 나와 붉은 헨드라 약초를 먹으라고 한 동물은 누구인가요? ',N'',N'기린',N'수탉',N'치타',N'악어',N'2',N'01',N'N',N'S'),
	 (230,N'01',N'07',N'붉은 헨드라 약초를 먹은 바실리스크에게 나타나는 변화는 무엇인가요?',N'',N'독을 마음대로 조절할 수 있게 된다.',N'독이 다 사라진다.',N'독이 더욱 강력해진다.',N'스스로 몸에 독이 퍼진다.',N'1',N'03',N'N',N'S'),
	 (230,N'01',N'08',N'바실리스크가 자신을 희생해 메뚜기 재앙을 막으려 한 이유는 무엇인가요?',N'',N'마을을 지켜달라는 나무늘보의 부탁을 들어주기 위해',N'동물들 앞에서 자신이 강하다는 것을 증명하려고',N'동물들과 어울려 살고 싶어서',N'자신을 괴롭혔던 메뚜기와의 원한이 깊었기 때문에',N'3',N'01',N'N',N'S'),
	 (230,N'01',N'09',N'다음 괄호 안에 들어갈 표현으로 적절한 것은 무엇인가요?',N'먹이를 가져다 주어도 (   )거리던 녀석이 먹보가 되었다.',N'샤방샤방',N'깨작깨작',N'주륵주륵',N'살랑살랑',N'2',N'02',N'Y',N'S'),
	 (230,N'01',N'10',N'쓴 것이 다하면 단 것이 온다라는 뜻으로, 고생(苦生) 끝에 낙이 온다라는 말을 뜻하는 사자성어는 무엇인가요?',N'',N'고진감래(苦盡甘來)',N'흥진비래(興盡悲來)',N'구곡간장(九曲肝腸)',N'천우신조(天佑神助)',N'1',N'07',N'N',N'S'),
	 (230,N'01',N'11',N'원한이 맺힐 정도로 자기에게 해를 끼친 사람이나 집단을 뜻하는 단어로 옳은 것은 무엇인가요?',N'',N'준수(遵守)',N'관수(灌水)',N'원수(怨讐)',N'적수(敵手)',N'3',N'06',N'N',N'S'),
