	 (233,N'01',N'07',N'다음 빈칸에 어울리는 낱말을 찾아보세요.',N'갈색 옷을 입으면 (A) 가 된 기분이 들어.',N'욕심쟁이',N'개구쟁이',N'멋쟁이',N'심술쟁이',N'3',N'06',N'Y',NULL),
	 (233,N'01',N'08',N'숲 속 재봉사에게 아이들은 어떤 마음을 가졌을까요?',N'',N'억울해요.',N'고마워요.',N'궁금해요.',N'화나요.',N'2',N'05',N'N',NULL),
	 (233,N'01',N'09',N'일이 일어난 차례대로 바르게 나열한 것을 찾으세요.',N'1) 깊은 숲속에 옷 만들기를 좋아하는 재봉사가 살았어요.                                                                        2) 아이들은 매일매일 입고 싶은 옷이 달랐어요.                         3) 아이들은 무슨 색깔 옷을 입을지 생각했어요. ',N'1,3,2',N'1,2,3',N'3,1,2',N'3,2.1',N'1',N'03',N'Y',NULL),
	 (233,N'01',N'10',N'숲 속 재봉사가 지어준 여러 색깔의 옷을 입은 아이들의 모습을 보면서 어떤 생각이 들었나요?',N'',N'아이들끼리 서로 도와주는 모습이 감동적이에요.',N'숲 속 재봉사에게 고마워하는 모습이 기특해요.',N'매일 다른 꽃이 피는 것처럼 아이들의 모습도 다양한 것 같아요.',N'자기만 예쁜 옷을 입으려고 하는 욕심꾸러기 같아요.',N'3',N'04',N'N',NULL);
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (233,N'01',N'11',N'어떤 목소리로 말했을까요?',N'"파란색 옷을 입은 날에는 혼자 있고 싶어."',N'깜짝 놀란 목소리',N'화난 목소리',N'신난 목소리',N'조용한 목소리',N'4',N'05',N'Y',NULL),
	 (233,N'01',N'12',N'책을 읽고난 느낌을 올바르게 말한 것을 찾으세요.',N'',N'좋아하는 옷을 입은 아이들이 예뻐.',N'재봉사가 힘들어하니 마음이 아파.',N'모든 옷이 다 똑같다니 신기해.',N'재봉사는 자기만 생각하는 것 같아.',N'1',N'04',N'N',NULL),
	 (234,N'01',N'01',N'숲속에 살고 있는 재봉사는 무엇을 가장 좋아했나요?',NULL,N'동물을 보살피는 일',N'옷 만드는 일',N'꽃과 나무를 키우는 일',N'숲을 돌아다니는 일',N'2',N'01',N'',N'S'),
	 (234,N'01',N'02',N'재봉사가 만들어준 옷을 입은 동물들은 무엇을 열었나요? ',NULL,N'한바탕 잔치',N' 신나는 운동회',N'뽐내기 대회',N'조용한 모임',N'1',N'01',N'',N'S'),
	 (234,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 동물들은 모두들 꿈꿔왔던 옷을 입어 보았어요.  
(2) 재봉사는 만들던 옷을 내려놓고 한숨 자고 일어나기로 했어요. 
(3) 숲 속 재봉사는 밤낮 쉬지 않고 옷을 만들었어요.',N'(2)-(1)-(3)',N'(1)-(3)-(2)',N'(3)-(1)-(2)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (234,N'01',N'04',N'재봉사가 한숨 자고 일어나기로 한 까닭으로 알맞은 것은 무엇인가요?',NULL,N'더 많은 옷을 만들기 위해서',N'동물들이 시켜서',N'옷이 마음에 들지 않아서',N'몸이 아프고 힘들어서',N'4',N'03',N'',N'S'),
	 (234,N'01',N'05',N'이 책을 읽고 느낀 점을 <u>잘못</u> 말한 것을 찾아보세요.',NULL,N'숲속 재봉사를 만난다면 내가 입고 싶은 옷을 부탁하고 싶어.',N'잠에서 깨어나지 않은 재봉사는 게으른 성격인 것 같아.',N'원하는 옷을 입게 된 동물들은 정말 행복했을 거야.',N'재봉사는 동물들을 위해 열심히 일했어.',N'2',N'04',N'',N'S'),
	 (234,N'01',N'06',N'재봉사가 쉬지 않고 옷을 만들다가, 한숨 자고 일어나기로 한 행동을 보며 알 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'동물들의 부탁을 더 빨리 끝내고 싶었어요.',N'옷 만드는 일이 재미없다고 생각했어요.',N'몸이 힘들어도 쉬지 말아야 한다고 생각했어요.',N'몸이 아플 때는 잠시 쉬는 것도 필요하다고 생각했어요.',N'4',N'04',N'',N'S'),
	 (234,N'01',N'07',N'사자는 어떤 목소리로 말했을까요?',N'"바람이 불면 털이 눈을 가려서 모자가 필요해요."',N'화나서 호통치는 목소리',N'차분히 부탁하는 목소리',N'긴장해서 떨리는 목소리',N'즐거워서 장난치는 목소리',N'2',N'05',N'Y',N'S'),
	 (234,N'01',N'08',N'동물들이 자신에게 꼭 맞는 옷을 입었을 때의 마음으로 알맞은 것은 무엇인가요?',NULL,N'속상한 마음',N'부끄러운 마음',N'기쁜 마음',N'무서운 마음',N'3',N'05',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (234,N'01',N'09',N'빈칸에 어울리는 흉내 내는 말을 찾아 보세요.',N'숲속 재봉사는 어깨가 (        )  쑤셔 오는 걸 느꼈어요.',N'욱신욱신',N'스륵스륵',N'조물조물',N'반짝반짝',N'1',N'02',N'Y',N'S'),
	 (234,N'01',N'10',N'재봉사가 옷을 만드는 소리가 <u>아닌</u> 것은 무엇인가요?',NULL,N'사각사각',N'조물조물',N'스륵스륵',N'쿵쾅쿵쾅',N'4',N'02',N'',N'S'),
	 (234,N'01',N'11',N'옷을 만드는 사람''이라는 뜻을 가진 어휘를 찾아 문장을 완성해 보세요.',N'(          )는 밤이나 낮이나 쉬지 않고 옷을 만들었어요.',N'미용사',N'제빵사',N'재봉사',N'요리사',N'3',N'06',N'Y',N'S'),
	 (234,N'01',N'12',N'‘부탁하다’와 뜻이 가장 비슷한 말은 무엇인가요?',NULL,N'거절하다',N'명령하다',N'혼내다',N'요청하다',N'4',N'06',N'',N'S'),
	 (235,N'01',N'01',N'길을 가던 선비는 무엇을 주었나요?',NULL,N'부채',N'가방',N'돈주머니',N'짚신',N'3',N'01',N'',N'S'),
	 (235,N'01',N'02',N'선비는 물건의 주인을 찾기 위해 누구를 찾아 갔나요?',NULL,N'농부',N'사또',N'임금님',N'이웃 사람',N'2',N'01',N'',N'S'),
	 (235,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 사또는 나그네가 거짓말을 하고 있다는 것을 알고 큰 소리로 말했어요.
(2) 하지만 사또는 들은 척도 하지 않았어요.
(3) 사또의 말을 들은 나그네는 쩔쩔매며 사정을 했어요.',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (235,N'01',N'04',N'나그네가 처음에는 ‘스무 냥’이라고 했다가 ‘서른 냥’이라고 말을 바꾼 이유는 무엇인가요?',NULL,N'실제로 돈을 잘못 세어서',N'사또에게 혼이 날까 봐',N'선비를 도와주고 싶어서',N'거짓말을 해서 돈을 더 얻으려고',N'4',N'03',N'',N'S'),
	 (235,N'01',N'05',N'나그네에게 해줄 충고의 말로 가장 알맞은 것은 무엇인가요?',NULL,N'다른 사람에게 양보하는 마음을 가지세요!',N'남보다도 자신을 먼저 생각하세요!',N'앞으로 과한 욕심을 부리지 마세요!',N'작은 생명도 소중히 여기세요!',N'3',N'04',N'',N'S'),
	 (235,N'01',N'06',N'사또의 판결에서 알 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'돈이 많으면 이긴다.',N'말솜씨가 중요하다.',N'힘센 사람이 옳다.',N'거짓말은 결국 드러난다.',N'4',N'04',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (235,N'01',N'07',N'선비는 어떤 마음이었을까요?',N'"아닙니다, 사또. 저는 주머니를 줍자마자 그대로 가지고 와 여기에서 열어보았습니다."',N'억울한 마음',N'기쁜 마음',N'반가운 마음',N'자랑스러운 마음',N'1',N'05',N'Y',N'S'),
	 (235,N'01',N'08',N'나그네는 어떤 마음이었을까요?',N'"정직하게 말할 걸 괜히 스무 냥만 잃었네."
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (236,N'01',N'05',N'그 무엇도 스스로 하지 않으려고 했던 아이에게 어떤 말을 해줄 수 있을까요?',NULL,N'무엇이든지 도와달라고 하는 점은 괜찮아요.',N'혼자서 하기 힘든 일은 무조건 도움을 구해야 해요.',N'처음에는 어렵더라도  차근차근 혼자서 해보는 습관을 가져야 해요.',N'아무것도 하지 않아도 괜찮아요.',N'3',N'04',N'',N'S'),
	 (236,N'01',N'06',N'아이가 스스로 걷고, 먹고, 움직이게 된 뒤의 모습으로 알맞은 것은 무엇인가요?',NULL,N'엄마만 더 찾게 되었어요.',N'아무 일도 하지 않게 되었어요.',N'다시 예전처럼 굴러다녔어요.',N'스스로 하며 즐거워했어요.',N'4',N'04',N'',N'S'),
	 (236,N'01',N'07',N'아이가 엄마에게 달려가 껴안고 입 맞출때 엄마의 표정은 어땠을까요?',NULL,N'화가 난 표정',N'기쁘고 행복한 표정',N'부끄럽고 실망한 표정',N'무서운 표정',N'2',N'05',N'',N'S'),
	 (236,N'01',N'08',N'스스로 움직일 수 있게 된 아이의 마음으로 알맞은 것은 무엇인가요?',NULL,N'뿌듯한 마음',N'답답한 마음',N'무서운 마음',N'서운한 마음',N'1',N'05',N'',N'S'),
	 (236,N'01',N'09',N'다음 문장에 어울리는 표현을 찾으세요.',N'이곳 저곳에 여러 바위가 솟아나 있었어요.',N'펄럭펄럭',N'벌렁벌렁',N'울퉁불퉁',N'번쩍번쩍',N'3',N'02',N'Y',N'S'),
	 (236,N'01',N'10',N'다음 빈칸에 어울리는 흉내 내는 말을 찾으세요.',N'아이는 (      ) 덤불숲을 지나가야 했어요.',N'말랑말랑',N'반질반질',N'뾰족뾰족',N'출렁출렁',N'3',N'02',N'Y',N'S'),
	 (236,N'01',N'11',N'배가 고파서 기운이 빠지는 것을 가리키는 말을 찾아보세요.',NULL,N'어수선하다.',N'허기지다.',N'허무하다.',N'흐릿하다.',N'2',N'06',N'',N'S'),
	 (236,N'01',N'12',N'스스로''와 가장 뜻이 비슷한 말은 무엇인가요?',NULL,N'억지로',N'다함께',N'갑자기',N'혼자서',N'4',N'06',N'',N'S'),
	 (237,N'01',N'01',N'내가 학교에서 책을 읽을때 친구들이 왜 웃곤했나요?',NULL,N'더듬거리며 천천히 읽기 때문이에요.',N'작은 소리로 빨리 읽기 때문이에요.',N'큰소리로 천천히 읽기 때문이에요.',N'엉뚱한 책을 읽기 때문이에요.',N'3',N'01',N'',N'S'),
	 (237,N'01',N'02',N'고양이 맥스는 집에 와서 무엇만 바라봤나요?',NULL,N'벽',N'고양이 침대',N'쥐돌이 장난감',N'창문',N'1',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (237,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 맥스가 다가와 머리를 내 팔 밑으로 디밀었어요. 
(2) 우리반 친구들은 보호소로 와서 책을 읽곤해요.
(3) 맥스는 뭘 해도 시큰둥해 했어요.   ',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'1',N'03',N'Y',N'S'),
	 (237,N'01',N'04',N'보호소 선생님이 나에게 보호소에 와서 책을 읽어달라고 한 이유는 무엇인가요?',NULL,N'나의 부모님이 선생님에게 부탁해서',N'선생님이 나를 보고 싶어해서',N'고양이들이 기운 낼 수 있도록 하기 위해서',N'읽을 책이 부족해서',N'3',N'03',N'',N'S'),
	 (237,N'01',N'05',N'여러 고양이가 보호소에 맡겨진 것을 보고 어떤 생각이 들었나요?',NULL,N'고양이를 키우다가 사정이 생기면 버릴 수도 있어요.',N'고양이들이 보호소에서 사랑을 받고 자라는 모습이 보기 좋아요.',N'고양이도 소중한 생명이므로 함부로 버려서는 안돼요.',N'고양이는 혼자서도 잘 지내요.',N'3',N'04',N'',N'S'),
	 (237,N'01',N'06',N'이 이야기를 통해 우리가 동물을 대할 때 가져야 할 생각으로 알맞은 것은 무엇인가요?',NULL,N'동물은 조용히 두는 게 좋아요.',N'동물은 사람 말을 꼭 들어야 해요.',N'동물은 혼자 살아도 괜찮아요.',N'동물도 마음이 있으니 정성껏 대해 줘야 해요.',N'4',N'04',N'',N'S'),
	 (237,N'01',N'07',N'나의 마음은 어땠을까요?',N'맥스는 머리를 내 팔 밑으로 디밀었다. 나는 가만히 앉아 읽고 또 읽고......',N'지루하고 귀찮아요.',N'놀랍고 행복해요.',N'부담스럽고 싫어요.',N'화가 나고 분해요.',N'2',N'05',N'Y',N'S'),
	 (237,N'01',N'08',N'처음 보호소에 갔을 때 ‘나’의 마음으로 알맞은 것은 무엇인가요?',NULL,N'화가 나 있었어요.',N'슬프고 속상했어요.',N'조금 떨리고 긴장됐어요.',N'심심하고 지루했어요.',N'3',N'05',N'',N'S'),
	 (237,N'01',N'09',N'다음 문장에 어울리는 표현을 찾아보세요.',N'나는 번개처럼 방을 치웠다.',N'후다닥',N'드르륵',N'달그락',N'푸드덕',N'1',N'02',N'Y',N'S'),
	 (237,N'01',N'10',N'‘시큰둥하다’라는 표현을 알맞게 설명한 것은 무엇인가요?',NULL,N'기분이 아주 좋아서 들뜬 모습',N'무서워서 몸을 떠는 모습',N'별로 관심이 없고 무심한 모습',N'깜짝 놀라 눈이 커진 모습',N'3',N'02',N'',N'S'),
	 (237,N'01',N'11',N'주인이 돌보지 않고 내다 버린 고양이를 가리키는 낱말을 찾아보세요.',NULL,N'반려묘',N'유기묘',N'유기견',N'반려견',N'2',N'06',N'',N'S'),
	 (237,N'01',N'12',N'‘보호소’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'책을 읽을 수 있는 곳',N'건강한 동물을 사고파는 곳',N'동물들의 먹이를 파는 곳',N'버려지거나 아픈 동물을 돌보는 곳',N'4',N'06',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (238,N'01',N'01',N'<시튼 동물기>는 어떤 이야기들로 구성되어 있나요?',NULL,N'동물과 사람의 전설',N'마법 동물들의 모험 이야기',N'여러 동물들의 실제 이야기',N'동물에 관한 과학 실험 보고서',N'3',N'01',NULL,N'S'),
	 (238,N'01',N'02',N'로보는 어떤 동물이었나요?',NULL,N'재빠른 여우',N'용감한 사슴',N'말하는 곰',N'영리한 회색 이리',N'4',N'01',NULL,N'S'),
	 (238,N'01',N'03',N'사람들은 왜 로보를 잡으려 했나요?',NULL,N'로보가 사람 말을 해서',N'로보가 가축을 해쳐서',N'로보가 말을 타고 도망쳐서',N'로보가 숲을 불태워서',N'2',N'03',NULL,N'S'),
	 (238,N'01',N'04',N'''거품쟁이 멧돼지''는 왜 거품쟁이라고 불렸나요?',NULL,N'입에 항상 거품을 물고 있어서',N'거품 목욕을 좋아해서',N'물고기를 거품으로 유인해서',N'거품 모양의 무늬가 있어서',N'1',N'03',NULL,N'S'),
	 (238,N'01',N'05',N' ‘교활하다’는 말의 뜻으로 알맞은 것은?',NULL,N'정직하고 착하다',N'머리가 좋고 속이 깊다',N'꾀를 내어 남을 속인다',N'겁이 많아 숨어 지낸다',N'3',N'06',NULL,N'S'),
	 (238,N'01',N'06',N'작가는 회색 곰 워브가 점점 강해지는 모습을 어떻게 표현했나요?',NULL,N'다른 동물들과 싸우는 장면',N'워브가 무리에서 떠나는 장면',N'워브가 사람을 공격하는 장면',N'먹이를 사냥하는 장면',N'1',N'02',NULL,N'S'),
	 (238,N'01',N'07',N'<시튼 동물기>에서 작가는 동물들을 단순한 동물이 아닌 어떤 존재로 표현했나요?',NULL,N'인간의 장난감',N'훈련이 필요한 존재',N'감정과 생각이 있는 생명체',N'인간보다 열등한 존재',N'3',N'02',NULL,N'S'),
	 (238,N'01',N'08',N'‘야생’이라는 말의 뜻으로 알맞은 것은?',NULL,N'집에서 기르는 것',N'자연에서 스스로 사는 것',N'동물원에 있는 것',N'길들여진 상태',N'2',N'06',NULL,N'S'),
	 (238,N'01',N'09',N'<시튼 동물기>의 이야기는 실제 동물 관찰을 바탕으로 쓰였어요. 이 책의 원작자는 누구인가요?',NULL,N'어니스트 시튼',N'찰스 다윈',N'닐 암스트롱',N'알렉산더 플레밍',N'1',N'07',NULL,N'S'),
	 (238,N'01',N'10',N'<시튼 동물기>는 어떤 장르의 책인가요?',NULL,N'전래동화',N'전기문학',N'동물 이야기 중심의 논픽션',N'판타지 소설',N'3',N'07',NULL,N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (238,N'01',N'11',N'''꾀 많은 여우''에서 위기 상황에도 여우가 침착하게 행동한 것을 보면 어떤 태도가 필요한가요?',NULL,N'겁이 나면 울기만 한다',N'상황을 잘 살펴서 지혜롭게 대처한다',N'문제를 피하려고 도망간다',N'무조건 남을 의지한다',N'2',N'04',NULL,N'S'),
	 (238,N'01',N'12',N' <로보 이야기>를 읽고 우리가 느낄 수 있는 교훈은 무엇인가요?',NULL,N'동물은 모두 잡아야 한다는 것',N'동물을 혼내면 말을 잘 듣는다는 것',N'동물도 감정과 삶이 있는 존재라는 것',N'동물을 무조건 길들여야 한다는 것',N'3',N'04',NULL,N'S'),
	 (239,N'01',N'01',N'전우치가 산 아래에 내려가기 전, 한자경이 울고 있었던 이유는 무엇인가요?',N'',N'아버지가 돌아가시고 어머니가 아파서',N'배가 고파서',N'돈이 없어서',N'길을 잃어서',N'1',N'04',N'',N'S'),
	 (239,N'01',N'02',N'전우치가 한자경에게 준 것은 무엇인가요?',N'',N'돈이 나오는 항아리',N'돈이 나오는 그림족자',N'돈이 나오는 망태기',N'금덩이가 가득 든 자루',N'2',N'01',N'',N'S'),
	 (239,N'01',N'03',N'한자경에게 전우치가 고지기를 불러 하루에 한 냥씩 달라고 시킨 이유는 무엇인가요?',N'',N'돈이 조금 밖에 없어서',N'한자경이 부자가 되는 것이 못마땅해서',N'한자경을 시험하려고',N'더한 욕심은 화를 불러서',N'4',N'04',N'',N'S'),
	 (239,N'01',N'04',N'다음 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?',N'어떤 사람들이 (          ) 얘기를 하고 있었어.',N'와르르',N'쑥덕쑥덕',N'도란도란',N'바삭바삭',N'2',N'07',N'Y',N'S'),
	 (239,N'01',N'05',N'한자경은 고지기에게 백냥을 주지 않으면 어떻게 한다고 협박했나요?',N'',N'“곤장을 때릴거야!”',N'“나무에 거꾸로 매달아 놓고 까마귀 밥이 되게 할 것이야!”',N'“나무에 묶어 놓고 호랑이 밥이 되게 할 것이야!”',N'“감옥에 가둘 거야!”',N'3',N'03',N'',N'S'),
	 (239,N'01',N'06',N'한자경은 곳간 안에 있는 돈을 어디에 퍼담았나요?',N'',N'자루',N'주머니',N'파우치',N'망태기',N'4',N'01',N'',N'S'),
	 (239,N'01',N'07',N'한자경이 임금님 앞에 끌려간 이유는 무엇인가요?',N'',N'임금님의 생명의 은인이라서',N'한자경에게 벼슬을 주려고',N'임금님의 곳간을 마음대로 손을 대서',N'전우치를 잡아오라고 명령받아서',N'3',N'03',N'',N'S'),
	 (239,N'01',N'08',N'‘매우 급하게 서두르는 모양새’를 말하며, 다음 빈칸에 들어갈 표현으로 적절한 것은 무엇인가요?',N'도둑이란 신고를 듣고 임금님은 (           ) 궁궐 곳간을 살피러 갔어.',N'부들부들',N'부랴부랴',N'떼굴떼굴',N'허둥지둥',N'2',N'02',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (239,N'01',N'09',N'다음 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?',N'값진 보물들은 괴상하게 변해 있거나 곰팡이 (         ) 피고 있었지.',N'울긋불긋',N'보송보송',N'알록달록',N'시커멓게',N'2',N'02',N'Y',N'S'),
	 (239,N'01',N'10',N'한자경이 임금님의 곳간에 있는 돈을 훔쳤기 때문에 혼이 났습니다. 이때, 볼기짝을 맞았는데 볼기짝은 어디일까요?',N'',N'볼',N'엉덩이',N'손바닥',N'종아리',N'2',N'07',N'',N'S'),
	 (239,N'01',N'11',N'‘간신히’와 다른 뜻의 단어는 무엇인가요?',N'',N'겨우',N'가까스로',N'벌써',N'힘겹게',N'3',N'06',N'',N'S'),
	 (239,N'01',N'12',N'한자경이 다녀간 뒤 보물과 항아리들이 이상하게 변한 것을 보고 임금님은 기함했습니다. 여기서 ‘기함하다’의 뜻은 무엇인가요?',N'',N'몹시 놀라 넋을 잃다',N'어이가 없어 기가 막힌다',N'호들갑스럽게 놀라다',N'깜짝 놀라 웃음을 터뜨리다',N'1',N'06',N'',N'S'),
	 (240,N'01',N'01',N'농사꾼이 발견한 독은 어떤 신기한 재주를 가지고 있었나요?',NULL,N'무엇이든 넣으면 커다랗게 변해서 나왔어요.',N'무엇이든 넣었다 꺼내면 똑같은 것이 자꾸 나왔어요.',N'무엇이든 넣으면 조그맣게 변해서 나왔어요. ',N'무엇이든 넣으면 사라졌어요.',N'2',N'01',N'',N'S'),
	 (240,N'01',N'02',N'신기한 독이 있다는 소문을 들은 부자 영감은 어떤 행동을 했나요?',NULL,N'농사꾼을 찾아가 신기한 독을 나누어 갖자고 이야기 했어요.',N'자기도 신기한 독을 찾으려고 온 밭을 뒤졌어요.',N'농사꾼을 찾아가 자신의 독이라고 우기며 뺏어오려고 했어요.',N'원님에게 먼저 알렸어요.',N'3',N'01',N'',N'S'),
	 (240,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 아버지들의 싸움이 차차 심해져서 결국 독이 와장창 깨졌어요. 
(2) 독이 탐이난 원님은 재판은 뒷전이었어요.
(3) 독 안을 들여다 보던 원님 아버지가 독 속에 빠져버렸어요. ',N'(3)-(2)-(1)',N'(1)-(2)-(3)',N'(2)-(3)-(1)',N'(2)-(1)-(3)',N'3',N'03',N'Y',N'S'),
	 (240,N'01',N'04',N'원님이 신기한 독을 나라에 바치라고 한 까닭은 무엇인가요?',NULL,N'다툼을 공정하게 해결하려고',N'임금님의 명령이 있어서',N'독이 위험해 보여서',N'사실은 독을 자기 것으로 삼고 싶어서',N'4',N'03',N'',N'S'),
	 (240,N'01',N'05',N'책 속 등장인물의 성격을 잘못 말한 것을 찾아보세요.',NULL,N'농사꾼 - 부지런하고 순진해요.',N'부자 영감 - 욕심이 지나쳐요.',N'원님 - 현명하고 정의로워요.  ',N'농사꾼 - 욕심 없이 정직해요.',N'3',N'04',N'',N'S'),
	 (240,N'01',N'06',N'이 이야기에서 원님의 행동을 통해 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'힘 있는 사람의 말이 중요해요.',N'재판에서는 이기는 게 중요해요.',N'신기한 물건은 나라 것이에요.',N'욕심을 부리면 올바른 판단을 할 수 없어요.',N'4',N'04',N'',N'S');
