	 (253,N'01',N'05',N'소탈을 쓴 건이는 왜 힘들었나요?',N'',N'소탈이 너무 무거워서',N'네 발로 기어 다니느라',N'사람들이 제게 일을 시키려고 해서',N'소탈이 너무 작아서',N'2',N'04',N'',N'S'),
	 (253,N'01',N'06',N' 다음과 같은 생김새의 탈은 무엇일까요?',N'붉은 얼굴에는 굵은 점이 다다닥, 두툼한 눈썹 아래 왕방울 눈이 떼굴떼굴, 기다란 주먹코에 썩은 이가 듬성듬성',N'선비탈',N'하회탈',N'부네탈',N'말뚝이탈',N'4',N'07',N'Y',N'S'),
	 (253,N'01',N'07',N'건이는 양반탈을 쓰고 어떤 책을 읽었나요?',N'',N'어려운 책',N'쉬운 책',N'재미있는 책',N'그림 많은 책',N'1',N'01',N'',N'S'),
	 (253,N'01',N'08',N'나리님들이 말뚝이를 심술궂다고 한 이유는 무엇일까요?',N'',N'나리님들의 수염을 뽑아서',N'나리님들의 발을 걸어 넘어뜨려서',N'나리님들의 앞에서 방귀를 뀌어서',N'나리님들에게 반말을 해서',N'3',N'02',N'',N'S'),
	 (253,N'01',N'09',N'건이는 가족들이 어떤 행동을 할 때 나가려고 했나요?',N'',N'건이를 억지로 끌어낸다.',N'건이를 한 번 더 부른다.',N'건이 찾는 것을 포기한다.',N'건이를 위해 잔치를 준비한다.',N'2',N'03',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (253,N'01',N'10',N'다음 중 책을 올바르게 이해하지 못한 사람은 누구인가요?',N'',N'혜리: 우리나라의 전통 탈을 알게되어 좋아!',N'나라: 말뚝이 탈을 쓰면 나도 모르게 말썽을 부리고 싶어.',N'경미: 각시탈은 험상궂은 역할인가봐.',N'수영: 탈을 쓰면 다른 사람이 된 것처럼 행동하고 싶어질 수도 있겠어.',N'3',N'03',N'N',N'S'),
	 (253,N'01',N'11',N'다음 중 ‘점잔을 빼다’가 의미하는 바는 무엇일까요?',N'',N'언행이 신중하지 못하고 가볍다.',N'언행이나 태도가 의젓하고 신중하다.',N'어떤 일에 흥미나 열성이 생겨 기분이 매우 좋아지다.',N'남을 무시하고 건방지게 굴다.',N'2',N'06',N'',N'S'),
	 (253,N'01',N'12',N'다음이 설명하는 단어는 무엇인가요?',N'몹시 화가 나서 크게 소리 지르거나 꾸짖음. 또는 그 소리.',N'호통',N'절규',N'좌절',N'분노',N'1',N'06',N'Y',N'S'),
	 (254,N'01',N'01',N'탄탄건설 김과장님은 무엇을 타고 회사에 가나요?',NULL,N'택시',N'버스',N'트럭',N'자전거',N'2',N'01',N'',N'S'),
	 (254,N'01',N'02',N'김 기사님은 택배상자 열다섯 개를 배달한 뒤, 무엇을 샀나요?',NULL,N'케이크',N'도시락',N'꽃다발',N'장난감',N'3',N'01',N'',N'S'),
	 (254,N'01',N'03',N'일이 일어난 차례대로 바르게 나열한 것을 찾으세요.',N'(1) 김 기사님은 토끼 서영이를, 김 과장님은 사자 정혁이를 한눈에 알아봤어요. 
(2) 오케이 택배 김기사님이 튼튼 소아과 앞에 도착했어요.
(3) 김 원장님은 코감기 환자를 진료하고 있어요. ',N'(2)-(1)-(3)',N'(1)-(2)-(3)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (254,N'01',N'04',N'아빠들이 퇴근 시간이 되자 서둘러 이동한 까닭은 무엇인가요?',NULL,N'회사 일이 더 많아져서',N'눈이 많이 내려서',N'택배를 더 배달해야 해서',N'아이들의 유치원 행사에 가기 위해서',N'4',N'03',N'',N'S'),
	 (254,N'01',N'05',N'바쁘고 힘든 하루를 보낸 아빠들에게 어떤 이야기를 해 줄 수 있을까요?',NULL,N'돈을 많이 버는 아빠의 모습이 존경스러워요.',N'가족들은 위해 노력하는 모습이 감동적이에요.',N'힘들어 하는 모습이 안타깝고 실망스러웠어요.',N'항상 집에 늦게 오는 게 속상해요.',N'2',N'04',N'',N'S'),
	 (254,N'01',N'06',N'이야기 속 아빠들의 행동을 보며 우리가 배울 수 있는 점은 무엇인가요?',NULL,N'일이 힘들면 가족은 나중에 생각해요.',N'약속은 지키지 않아도 괜찮아요.',N'바쁘면 아이들을 잊어도 돼요.',N'바빠도 가족과의 약속을 소중히 여겨요.',N'4',N'04',N'',N'S'),
	 (254,N'01',N'07',N'바쁜 하루를 보내고 퇴근을 하는 아빠들의 마음은 어땠을까요?',NULL,N'힘이 나고 상쾌해요.',N'빨리 아이들을 보고 싶어요.',N'집으로 곧장 가고 싶어요.',N'얼른 혼자 쉬고 싶어요.',N'2',N'05',N'',N'S');
