	 (256,N'01',N'05',N'레이 아빠에게 어떤 말을 해 줄 수 있을까요?',NULL,N'하기 싫은 일을 억지로 한 점이 대단해요.',N'딸을 위해 끝까지 노력하는 모습이 정말 멋있어요.',N'해낼 수 없는 일에 도전한 점이 답답해요.',N'처음부터 하지 말았어야 했어요.',N'2',N'04',N'',N'S'),
	 (256,N'01',N'06',N'아빠의 행동을 보고 배울 수 있는 점은 무엇인가요?',NULL,N'힘들면 중간에 포기해도 된다는 점',N'약속은 지키지 않아도 된다는 점',N'다른 사람보다 빨라야 한다는 점',N'약속을 지키기 위해 노력하는 점',N'4',N'04',N'',N'S'),
	 (256,N'01',N'07',N'레이 아빠는 어떤 목소리로 말했을까요?',N'"아, 아버지 이어달리기를 한다고? 약,약속까지 했다고?"                        ',N'부끄러운 목소리',N'당황스러운 목소리',N'설레는 목소리',N'속상한 목소리',N'2',N'05',N'Y',N'S'),
	 (256,N'01',N'08',N'아빠가 넘어졌을 때 레이의 마음으로 알맞은 것은 무엇인가요?',NULL,N'속상하고 걱정되는 마음',N'자랑스러운 마음',N'화가 난 마음',N'무서운 마음',N'1',N'05',N'',N'S'),
	 (256,N'01',N'09',N'다음 문장에 알맞은 표현을 찾아보세요.',N'달리기 시합을 앞두고 가슴이 뛰었어요.',N'얼렁뚱땅',N'콩닥콩닥',N'오물오물',N'데굴데굴',N'2',N'02',N'Y',N'S'),
	 (256,N'01',N'10',N'빈칸에 어울리는 흉내 내는 말을 찾아보세요.',N'아빠의 코끝에 땀이 (       ) 맺혔어요.',N'송글송글',N'보글보글',N'바글바글',N'우글우글',N'1',N'02',N'Y',N'S'),
	 (256,N'01',N'11',N'남이 가지지 못한 나만의 기술''을 가리키는 낱말을 찾아보세요.',NULL,N'취미',N'소질',N'특기',N'기능',N'3',N'06',N'',N'S'),
	 (256,N'01',N'12',N'‘특훈’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'잠깐 쉬는 시간',N'재미로 하는 연습',N'천천히 하는 공부',N'특별히 열심히 하는 훈련',N'4',N'06',N'',N'S'),
	 (257,N'01',N'01',N'빨강 두건 아씨의 일곱 동무가 <u>아닌</u> 것은 무엇인가요? ',NULL,N'가위 ',N'다리미 ',N'망치 ',N'바늘',N'3',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (257,N'01',N'02',N'다음은 누구의 말인가요?',N'"구슬이 서 말이라도 꿰어야 보배! 내가 이 솔 저 솔 꿰매고 나서야 입을 옷이 되지 않나요?"',N'실 ',N'바늘 ',N'인두 ',N'다리미',N'2',N'01',N'Y',N'S'),
	 (257,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 빨간 두건 아씨가 일곱 동무에게 사과했어요. 
(2) 빨강 두건 아씨의 꿈에서 일곱 동무가 보이지 않았어요.
(3) 아씨와 일곱 동무는 신이 나서 일하게 되었어요. ',N'(1)-(2)-(3)',N'(2)-(1)-(3) ',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'2',N'03',N'Y',N'S'),
	 (257,N'01',N'04',N'일곱 동무가 서로 자기가 제일이라고 다투게 된 이유는 무엇인가요?',NULL,N'아씨가 재미있는 장면을 보고 싶어서 시켰기 때문이에요.',N'일이 너무 많아서 지쳤기 때문이에요.',N'각자 자기 역할이 가장 중요하다고 생각했기 때문이에요.',N'아씨가 만든 옷이 마음에 들지 않았기 때문이에요.',N'3',N'03',N'',N'S'),
	 (257,N'01',N'05',N'이야기에서 일곱 동무가 함께 일해야 하는 이유로 알맞은 것은 무엇인가요?',NULL,N'혼자서도 일을 할 수 있기 때문이에요.',N'일을 빨리 끝내기 위해서예요.',N'아씨가 시켰기 때문이에요.',N'각자의 역할이 모두 필요하기 때문이에요.',N'4',N'04',N'',N'S'),
	 (257,N'01',N'06',N'이 책의 주제와 비슷한 생각을 한 친구를 찾아보세요. ',NULL,N'나도 빨강 두건 아씨처럼 바느질을 잘하고 싶어.',N'일곱 동무의 잘난 척을 배우고 싶어. ',N'어떤 일을 하기 위해서는 모두의 힘이 필요해. ',N'혼자 하는 일이 더 쉬워.',N'3',N'04',N'',N'S'),
	 (257,N'01',N'07',N'홍실 각시의 말에 담긴 감정 표현을 찾아보세요. ',N'"그러니 나야말로 주인공이 아니겠어? 호호호."',N'억울하다 ',N'뽐내다 ',N'덤덤하다 ',N'슬프다',N'2',N'05',N'Y',N'S'),
	 (257,N'01',N'08',N'아씨의 말을 가장 실감 나게 읽어줄 친구를 찾아보세요. ',N'"이 몸이 제일이지. 어째서 너희가 제일이야!"',N'부끄러운 듯이 땅만 쳐다보며 말해야겠어.',N'우물쭈물하다가 화를 참으며 말하고 싶어. ',N'화난 목소리로 당당하게 말할 거야. ',N'졸리고 피곤한 목소리로 말할 거야.',N'3',N'05',N'Y',N'S'),
