	 (262,N'01',N'10',N'다음 괄호 안에 들어갈 표현으로 적절한 것은 무엇인가요?',N'먹이를 가져다 주어도 (   )거리던 녀석이 먹보가 되었다.',N'샤방샤방',N'깨작깨작',N'주륵주륵',N'씩씩',N'2',N'02',N'Y',N'S'),
	 (262,N'01',N'11',N'남을 불쌍하게 여기는 타고난 착한 마음을 이르는 말을 의미하는 단어는 무엇인가요?',N'',N'측은지심(惻隱之心)',N'부창부수(夫唱婦隨)',N'원수근화(遠水近火)',N'견물생심(見物生心)',N'1',N'02',N'N',N'S'),
	 (262,N'01',N'12',N'못마땅한 생각이나 반대의 뜻을 주장하는 것을 뜻하는 단어는 무엇인가요?',N'',N'정의(正義)',N'선의(善意)',N'항의(抗議)',N'동의(同意)',N'3',N'07',N'N',N'S'),
	 (262,N'01',N'13',N'진보 이전의 상태로 되돌아가는 것을 뜻하는 단어는 무엇인가요?',N'',N'진화',N'퇴화',N'중화',N'발전',N'2',N'06',N'N',N'S'),
	 (262,N'01',N'14',N'앞일에 대하여 여러 가지로 마음을 써서 걱정하는 것을 뜻하는 단어는 무엇인가요?',N'',N'염려',N'비녀',N'피력',N'사려',N'1',N'06',N'N',N'S'),
	 (262,N'01',N'15',N'어떤 사람이 편안하게 잘 지내고 있는지 그렇지 아니한지에 대한 소식. 또는 인사로 그것을 전하거나 묻는 일을 의미하는 단어는 무엇인가요?',N'',N'진부',N'간부',N'안부',N'졸부',N'3',N'06',N'N',N'S'),
	 (263,N'01',N'01',N'아이들이 알베르트를 싫어했던 이유는 무엇인가요?',NULL,N'부잣집 아이라서',N'싸움을 못해서',N'몸집이 작아서',N'말수가 적어서',N'1',N'01',N'',N'S'),
	 (263,N'01',N'02',N'알베르트는 대학에서 무엇을 공부했나요?',NULL,N'문학과 철학',N'신학과 철학',N'음악과 문학',N'의학과 과학',N'2',N'01',N'',N'S'),
	 (263,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 슈바이처 부부는 포로 수용소에서 생활하게 되었어요.
(2) 슈바이처 부부는 아프리카로 떠나는 배에 올랐어요.
(3) 땅을 다지고 나무를 베어 큰 병원을 지었어요.',N'(2)-(3)-(1)',N'(1)-(2)-(3)',N'(2)-(1)-(3)',N'(3)-(1)-(2)',N'3',N'03',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (263,N'01',N'04',N'슈바이처가 연주회에서 번 돈으로 의약품을 산 까닭은 무엇인가요?',NULL,N'음악을 더 배우고 싶어서',N'아프리카로 여행을 가기 위해서',N'병원을 크게 짓기 위해서',N'아픈 사람들을 치료하기 위해서',N'4',N'03',N'',N'S'),
	 (263,N'01',N'05',N'슈바이처가 아프리카로 떠나 병원을 세운 이유로 가장 알맞은 것은 무엇인가요?',NULL,N'새로운 나라를 구경하고 싶어서',N'의사가 되면 돈을 많이 벌 수 있어서',N'치료받지 못하는 사람들을 돕고 싶어서',N'혼자 조용히 살고 싶어서',N'3',N'04',N'',N'S'),
	 (263,N'01',N'06',N'슈바이처의 삶에서 가장 본받을 점은 무엇일까요?',NULL,N'많은 상을 받았다는 점',N'음악을 잘 연주했다는 점',N'평생 아픈 사람들을 위해 살았던 점',N'부잣집에서 자랐다는 점',N'3',N'04',N'',N'S'),
	 (263,N'01',N'07',N'슈바이처는 어떤 목소리로 말했을까요?',N'"어떤 동물에게도 나쁜 짓을 해서는 안되네."',N'수줍어하는 목소리',N'엄하고 단호한 목소리',N'상냥한 목소리',N'슬프고 억울한 목소리',N'2',N'05',N'Y',N'S'),
	 (263,N'01',N'08',N'아프리카에 도착해 열악한 모습을 본 슈바이처의 마음은 어땠을까요?',NULL,N'즐겁고 신났어요.',N'화가 나고 억울했어요.',N'부끄럽고 창피했어요.',N'안타깝고 마음이 아팠어요.',N'4',N'05',N'',N'S'),
	 (263,N'01',N'09',N'다음 빈칸에 어울리는 흉내내는 말을 찾아보세요.',N'슈바이처는 두 주먹을 (    ) 쥐고 중얼거렸어요.',N'비틀',N'벌렁',N'불끈',N'살랑',N'3',N'02',N'Y',N'S'),
	 (263,N'01',N'10',N'슈바이처에게 치료 받으려는 사람들이 많이 모인 모습을 가장 잘 나타낸 흉내 내는 말을 찾아 보세요.',NULL,N'북적북적',N'조용조용',N'사뿐사뿐',N'반짝반짝',N'1',N'02',N'',N'S'),
	 (263,N'01',N'11',N'교환''과 비슷한 낱말을 찾아보세요.',NULL,N'변화',N'거래',N'환불',N'약속',N'2',N'06',N'',N'S'),
	 (263,N'01',N'12',N'‘상금’이란 무엇을 뜻하는 말인가요?',NULL,N'상을 받아서 받은 돈',N'일을 하고 받은 월급',N'물건을 팔아 얻은 돈',N'빌렸다가 갚는 돈',N'1',N'06',N'',N'S'),
	 (264,N'01',N'01',N'다음 중 그리워 하는 마음이 드는 상황은 무엇인가요?',NULL,N'시골에 사는 할머니가 보고 싶어.',N'숙제를 다 해서 마음이 편해.',N'엄마도 아빠도 없는 집에 나 혼자 있어.',N'친구와 재미있게 놀았어.',N'1',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (264,N'01',N'02',N'다음 중 당황스러운 마음이 드는 상황은 무엇인가요?',NULL,N'학교에서 신발을 벗다가 양말을 짝짝이로 신었다는걸 알았어.',N'우리집 강아지가 하늘나라로 갔어.',N'재미없는 이야기를 듣다가 하품이 나왔어.',N'소풍이 취소되었어.',N'1',N'01',N'',N'S'),
	 (264,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 깜빡 잊고 숙제를 하지 않아 엄청 불안했어요.
(2) 선생님이 숙제검사를 하지 않아서 정말 다행스러웠어요.
(3) 그 때, 교실문을 열고 들어오신 선생님께서 과학실로 모이라고 하셨어요.',N'(1)-(2)-(3)',N'(2)-(1)-(3)',N'(1)-(3)-(2)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (264,N'01',N'04',N'마음이 달라진 이유는 무엇인가요?',N'숙제를 하지 않아 불안했는데, 선생님이 숙제 검사를 하지 않으셨어요.',N'숙제를 다시 하게 되었기 때문이에요.',N'친구들이 도와주었기 때문이에요.',N'걱정하던 일이 더 크게 일어났기 때문이에요.',N'걱정하던 일이 일어나지 않았기 때문이에요.',N'4',N'03',N'Y',N'S'),
	 (264,N'01',N'05',N'이 책을 읽고 알게 된 사실을 <u>잘못</u> 말한 것을 찾아보세요.',NULL,N'마음을 표현하는 말을 사용해서 감정을 솔직하게 표현 해야겠어.',N'되도록이면 부정적인 마음은 숨기는게 좋다는 걸 알았어.',N'이제는 상대방의 마음도 짐작 할 수 있을 것 같아.',N'마음을 말로 표현하면 서로를 이해할 수 있게 되는 것 같아.',N'2',N'04',N'',N'S'),
	 (264,N'01',N'06',N'친구가 속상해 보일 때 가장 알맞은 행동은 무엇일까요?',NULL,N'아무 말도 하지 않아요.',N'웃으라고 놀려요.',N'왜 그런지 물어보고 들어줘요.',N'모른 척 하고 지나가요.',N'3',N'04',N'',N'S'),
	 (264,N'01',N'07',N'다음 상황에 알맞은 마음을 표현하는 말을 찾아보세요.',N'씨앗을 심은 화분에서 싹이 돋았어.',N'야속하다',N'감격스럽다',N'불안하다',N'창피하다',N'2',N'05',N'Y',N'S'),
	 (264,N'01',N'08',N'긍정적인 마음을 표현하는 말이 <u>아닌</u> 것을 찾아보세요.',NULL,N'심술나다',N'상쾌하다',N'훈훈하다',N'편안하다',N'1',N'05',N'',N'S'),
	 (264,N'01',N'09',N'빈칸에 어울리는 흉내 내는 말을 찾아보세요.',N'퇴근하는 아빠가 들고 온 케이크를 보고 너무 기뻐서 (      ) 뛰었어.',N'방긋방긋',N'폴짝폴짝',N'하하호호',N'사뿐사뿐',N'2',N'02',N'Y',N'S'),
	 (264,N'01',N'10',N'다음 중 기쁜 마음을 몸으로 나타낸 표현은 무엇인가요?',NULL,N'고개를 푹 숙였어요.',N'입술을 꽉 깨물었어요.',N'손뼉을 치며 웃었어요.',N'조용히 앉아 있었어요.',N'3',N'02',N'',N'S'),
	 (264,N'01',N'11',N'애가타서 마음이 조마조마하다는 뜻을 가진 말을 찾아보세요.',NULL,N'창피하다',N'초조하다',N'통쾌하다',N'흐뭇하다',N'2',N'06',N'',N'S');
