	 (273,N'01',N'08',N'식물이 씨앗에서 생겨나듯이 동물은 어디에서 자라나요?',N'',N'씨앗',N'뱃속',N'알',N'풀잎',N'3',N'02',N'',N'S'),
	 (273,N'01',N'09',N'다음 중 알에 대한 설명으로 옳지 않은 것은 무엇인가요?',N'',N'알은 숨을 쉴 수가 없다',N'개구리나 물고기의 알은 흐물흐물하다',N'새의 알은 단단하다',N'알 속에는 노른자와 흰자가 있다',N'1',N'03',N'',N'S'),
	 (273,N'01',N'10',N'새들은 스스로 뱀의 먹이가 되기도 하는데, 그 이유는 무엇인가요?',N'',N'배가 고파 이대로 가다간 살 수 없어서',N'자기가 낳은 알을 지키기 위해서',N'어차피 뱀한테 잡아먹힐 운명이라서',N'다른 새를 지키기 위해서',N'2',N'04',N'',N'S'),
	 (273,N'01',N'11',N'열매에서 씨를 둘러싸고 있는 살을 말하며, 이것에는 씨앗이 둘러싸여 있습니다. 이것은 무엇일까요?',N'',N'과육',N'가시',N'갈고리',N'껍질',N'1',N'06',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (273,N'01',N'12',N'사람에게 있어 알의 역할을 하며, 엄마와 아기를 배꼽을 통해 연결해주는 줄을 무엇이라고 하나요?',N'',N'씨앗',N'수정란',N'혈관',N'탯줄',N'4',N'06',N'',N'S'),
	 (274,N'01',N'01',N'알라딘이 반지를 들고 간절히 기도하자 어떤 일이 벌어졌나요?',NULL,N'반지 요정이 나타나 도와주겠다고 했어요.',N'마법사가 나타나 마법을 가르쳐 주었어요.',N'램프 요정이 나타나 집으로 데려다 주겠다고 했어요.',N'공주가 나타나 알라딘을 도와주었어요.',N'1',N'01',N'',N'S'),
	 (274,N'01',N'02',N'알라딘은 마법사의 꼬임에 빠져 어디에 갇혔나요?',NULL,N' 마법사의 성',N'깊은 동굴 ',N'비밀 창고',N'궁전 지하',N'2',N'01',N'',N'S'),
	 (274,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 램프의 요정은 성을 제자리로 돌려놓았고 알라딘은 공주와 행복하게 살았어요. 
(2) 마법사는 수정 구슬로 공주와 함께 살고 있는 알라딘을 보고 화가 났어요.
(3) 동굴에 갇혔던 알라딘은 램프를 가지고 무사히 집으로 왔어요.',N'(1)-(3)-(2)',N' (2)-(1)-(3)',N'(3)-(2)-(1) ',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (274,N'01',N'04',N'마법사가 램프 장수로 꾸미고 궁전에 간 이유는 무엇인가요?',NULL,N'공주를 만나고 싶어서',N'보물을 팔기 위해서',N'사람들을 속이기 위해서',N'알라딘의 램프를 빼앗기 위해서',N'4',N'03',N'',N'S'),
	 (274,N'01',N'05',N'알라딘에게 해 줄 수 있는 말로 가장 올바른 것을 찾아보세요.',NULL,N'동굴에 혼자 남겨졌을 때 포기하지 않고 희망을 가진 자세를 본받아야겠어. ',N'램프를 숨겨두고 공주와 행복하게 지내겠다고 한걸 보니 욕심이 많은 것 같아.',N'마법사에게 약이든 포도주를 먹인 것을 보면 장난이 심한 성격인 것 같아.',N'요정에게만 의지했다는 점이 좀 아쉬워.',N'1',N'04',N'',N'S'),
	 (274,N'01',N'06',N'알라딘의 행동을 보며 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'위험하면 무조건 도망쳐야 해요.',N'어려운 일은 남에게 맡겨야 해요.',N'힘이 세야 문제를 해결할 수 있어요.',N'용기를 내어 지혜롭게 해결하려는 마음이 중요해요.',N'4',N'04',N'',N'S'),
	 (274,N'01',N'07',N'임금님은 어떤 마음이었을까요?',N'뚝딱! 밤사이 지어진 성을 보고 임금님 눈이 휘둥그레졌어요.',N'실망함',N'외로움',N'깜짝 놀람',N'화가 남',N'3',N'05',N'Y',N'S'),
	 (274,N'01',N'08',N'공주와 성이 사라진 것을 본 알라딘의 마음으로 알맞은 것은 무엇인가요?',NULL,N'기쁘고 설레는 마음',N'걱정되고 놀란 마음',N'자랑스러운 마음',N'심심한 마음',N'2',N'05',N'',N'S'),
	 (274,N'01',N'09',N'다음 문장에 어울리는 흉내 내는 말이 아닌 것을 찾으세요.',N'궁전으로 몰래 들어간 알라딘은 공주에게 말했어요.',N'살금살금',N'시끌벅적',N'소곤소곤',N'조용조용',N'2',N'02',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (274,N'01',N'10',N'빈칸에 어울리는 표현을 찾아보세요.',N'알라딘은 요술램프를 (   ) 문질렀어요.',N'쿵쿵',N'슥슥',N'와르르',N'훨훨',N'2',N'02',N'Y',N'S'),
	 (274,N'01',N'11',N'놀라거나 두려워서 눈이 크고 둥그렇게 되다''는 뜻은 무엇인가요?',NULL,N'휘둥그레지다 ',N'찌푸리다',N'흘기다',N'찡그리다',N'1',N'06',N'',N'S'),
	 (274,N'01',N'12',N'‘간절히’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'아무 생각 없이',N'대충 빠르게',N'천천히 느긋하게',N'매우 바라고 애타게',N'4',N'06',N'',N'S'),
	 (275,N'01',N'01',N'볼 수 없으며 냄새도 맡을 수 없고, 손으로 만질 수도 없는 감정을 건드릴 수 있는 것은 무엇인가요?',N'',N'막대기',N'말',N'새총',N'손짓',N'2',N'04',N'',N'S'),
	 (275,N'01',N'02',N'톰이 블록으로 만든 생일 선물은 무엇인가요?',N'',N'우주선',N'자동차',N'로봇',N'비행기',N'1',N'01',N'',N'S'),
	 (275,N'01',N'03',N'다음의 상황에서 소년의 기분은 어땠을까요?',N'소년은 눈을 떴습니다. 소름이 끼쳤고 머리카락은 꼿꼿이 곤두섰습니다. 소년의 몸은 돌처럼 굳어버렸습니다. 식은땀이 등줄기를 타고 흘러내렸습니다.',N'즐거움',N'두려움',N'지루함',N'설렘',N'2',N'03',N'Y',N'S'),
	 (275,N'01',N'04',N'아기새는 엄마가 돌아오기 전까지 어떤 생각을 하고 있었나요?',N'',N'엄마가 빨리 돌아오면 좋겠다.',N'엄마가 먹이를 많이 가지고 오면 좋겠다.',N'엄마가 다시는 돌아오시지 않을거다.',N'엄마가 다른 새들과 함께 올 것이다.',N'3',N'07',N'',N'S'),
	 (275,N'01',N'05',N'다음이 설명하는 말은 무엇일까요?',N'의식을 잃고 제 몸에 벌어지는 일을 모를 만큼 정신이 없는 상태.',N'정지 상태',N'혼수 상태',N'침착한 상태',N'불안 상태',N'2',N'02',N'Y',N'S'),
	 (275,N'01',N'06',N'존에게 친구들이 한 말로 옳은 것은 무엇일까요?',N'',N'“넌 너무 심술궂어.”',N'“존, 너는 참 착한 아이구나.”',N'“너같이 못된 애를 보면, 난 친해지고 싶!”',N'"넌 참 재밌는 친구야"',N'1',N'02',N'',N'S'),
	 (275,N'01',N'07',N'엘리자베스가 케이트를 좋은 친구라고 생각하는 이유는 무엇인가요?',N'',N'선물을 줘서',N'숙제를 대신해줘서',N'자신의 집에 놀러 와서',N'함께 여행을 가서',N'3',N'03',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (275,N'01',N'08',N'다음의 상황에서 ‘나’의 마음은 어땠을까요?',N'넌 항상 나한테 물어보지도 않고 내 물건을 가져갔어. 어떻게 그럴 수 있어? 응?',N'기쁨',N'화가 남',N'걱정됨',N'서운함',N'2',N'04',N'Y',N'S'),
	 (275,N'01',N'09',N'이 병에 걸리면 온몸에는 빨간 열꽃이 피고, 숨쉬기조차 힘들어집니다. 어떤 병일까요?',N'',N'수두',N'관절염',N'눈병',N'독감',N'1',N'07',N'',N'S'),
	 (275,N'01',N'10',N'보브가 알프레드를 위해 준비한 생일 선물은 무엇일까요?',N'',N'물시계',N'동화책',N'해시계',N'손목시계',N'3',N'01',N'',N'S'),
	 (275,N'01',N'11',N'다음이 설명하는 말은 무엇일까요?',N'다른 사람이 잘 되거나 좋은 처지에 있는 것을 이유 없이 미워하고 깎아내리려 함.',N'분노',N'공감',N'질투',N'원망',N'3',N'06',N'Y',N'S'),
	 (275,N'01',N'12',N'‘이기적’ 이라는 말은 어떤 의미일까요?',N'',N'자기의 이익보다는 다른 이의 이익을 더 중요하게 생각함',N'자기 자신의 이익만을 중요하게 여김',N'용기가 있으며 씩씩하고 기운참',N'다른 사람의 감정을 이해하는 태도',N'2',N'06',N'',N'S'),
	 (276,N'01',N'01',N'동동이는 혼자서 무엇을 하며 놀았나요?',NULL,N' 퍼즐놀이',N'구슬치기',N'블럭놀이',N'종이접기',N'2',N'01',N'',N'S'),
	 (276,N'01',N'02',N'새 구슬이 필요해서 문방구에 간 동동이가 산 것은 무엇이었나요?',NULL,N'솜사탕',N'막대사탕',N'알사탕',N'박하사탕',N'3',N'01',N'',N'S'),
	 (276,N'01',N'03',N'동동이가 풍선껌을 식탁 밑에 붙여둔 까닭은 무엇인가요?',NULL,N'휴지통이 보이지 않았기 때문에 ',N'할머니와 언제든 이야기 할 수 있기 때문에 ',N'아빠에게 복수를 할 수 있기 때문에 ',N'장난을 치고 싶어서',N'2',N'03',N'',N'S'),
	 (276,N'01',N'04',N'동동이가 여러 색의 알사탕을 차례로 먹은 이유로 알맞은 것은 무엇인가요?',NULL,N'배가 너무 고파서',N'사탕 맛을 비교하려고',N'일부러 소란을 피우려고',N'사탕마다 어떤 목소리가 들리는지 알고 싶어서',N'4',N'03',N'',N'S'),
	 (276,N'01',N'05',N'마지막 알사탕을 먹고 밖으로 나와 친구를 만난 동동이는 어떤 아이로 변했을까요?',NULL,N'먼저 마음을 표현하는 용기 있는 아이  ',N'혼자서도 잘 노는 씩씩한 아이',N'힘들어도 포기하지 않는 끈기 있는 아이',N'장난을 좋아하는 아이',N'1',N'04',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (276,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 가장 알맞은 것은 무엇인가요?',NULL,N'혼자 노는 것이 가장 좋아요.',N'어른의 말은 들을 필요가 없어요.',N'마음을 말하지 않으면 괜찮아요.',N'용기를 내어 마음을 말하면 친구를 사귈 수 있어요.',N'4',N'04',N'',N'S'),
