	 (277,N'01',N'04',N'아빠가 결국 고양이를 가족으로 받아들이게 된 이유로 알맞은 것은 무엇인가요?',NULL,N'고양이가 말을 해서',N'아이들이 졸라서',N'병원에서 키우라고 해서',N'아이들이 책임지고 돌보려는 모습을 보여서',N'4',N'03',N'',N'S'),
	 (277,N'01',N'05',N'야옹이가 가족이 되어서 좋은 점은 무엇일까요? ',NULL,N'동물을 아끼고 사랑하는 법을 알게 되었어요.',N'아빠가 모든 동물들을 좋아하게 되었어요.',N'더 많은 길고양이들을 입양하게 되었어요.',N'병원에 자주 가게 되었어요.',N'1',N'04',N'',N'S'),
	 (277,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 가장 알맞은 것은 무엇인가요?',NULL,N'동물은 귀찮아서 키우지 않는 게 좋아요.',N'아픈 동물은 피해야 해요.',N'마음에 들면 바로 데려와도 돼요.',N'생명을 책임지는 마음이 중요해요.',N'4',N'04',N'',N'S'),
	 (277,N'01',N'07',N'쫑이와 완두콩은 어떤 마음이었을까요?',N'"이 돈으로는 턱도 없지만, 너희들이 기특해서......  잘 돌봐야 한다, 알았지?"',N'슬퍼요.',N'고마워요.',N'괴로워요.',N'미안해요.',N'2',N'05',N'Y',N'S'),
	 (277,N'01',N'08',N'놀이터에서 고양이를 괴롭히는 모습을 보았을 때 쫑이의 마음으로 알맞은 것은 무엇인가요?',NULL,N'재미있는 마음',N'걱정되고 안타까운 마음',N'신나고 즐거운 마음',N'아무렇지 않은 마음',N'2',N'05',N'',N'S'),
	 (277,N'01',N'09',N'빈칸에 어울리는 표현을 찾아보세요.',N'놀이터에 (     )한 목소리가 울려퍼지자 아이들이 깜짝 놀랐어요.',N'쩌렁쩌렁',N'슬금슬금',N'살랑살랑',N'조용조용',N'1',N'02',N'Y',N'S'),
	 (277,N'01',N'10',N'고양이가 놀라서 갑자기 도망가는 모습을 가장 잘 나타낸 말은 무엇인가요?',NULL,N'느릿느릿',N'깡충깡충',N'후다닥',N'휘리릭',N'3',N'02',N'',N'S'),
	 (277,N'01',N'11',N'어떤 일이 일어날때를 미리 알아서 계획하는 것''을 가리키는 낱말을 찾으세요.',NULL,N'대상',N'경우',N'대책',N'이유',N'3',N'06',N'',N'S'),
	 (277,N'01',N'12',N'‘보호자’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'함께 노는 사람',N'치료해 주는 사람',N'구경하는 사람',N'돌보고 책임지는 사람',N'4',N'06',N'',N'S'),
	 (278,N'01',N'01',N'우리 몸속의 피를 붉게 보이게 하는 세포는 무엇인가요?',NULL,N'백혈구',N'적혈구 ',N'혈소판',N'세균',N'2',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (278,N'01',N'02',N'감기와 수두를 일으키는 병균을 무엇이라고 부르나요?',NULL,N'딱지 ',N'세균',N'바이러스',N'곰팡이',N'3',N'01',N'',N'S'),
	 (278,N'01',N'03',N'음식을 먹기 전 손을 꼭 씻어야 하는 까닭은 무엇인가요?',NULL,N'음식을 더 맛있게 먹기 위해서 ',N'세균이 몸속으로 들어가는 것을 막기 위해서',N'세균이 음식을 먹어치울 수 있게 하려고',N'손이 하얗게 보이게 하려고',N'2',N'03',N'',N'S'),
	 (278,N'01',N'04',N'딱지가 생긴 뒤에 하면 <u>안 되는</u> 행동은 무엇인가요?',NULL,N'깨끗이 씻어요.',N'딱지가 저절로 떨어지도록 기다려요.',N'상처에 닿지 않게 조심해요.',N'딱지를 손으로 억지로 떼어내요.',N'4',N'03',N'',N'S'),
	 (278,N'01',N'05',N'병균으로부터 우리 몸을 지키는 건강한 생활 습관을 찾아보세요.',NULL,N'딱지가 생기면 저절로 떨어지기 전에 먼저 떼어 내요.',N'좋은 흙에서 자란 몸에 좋은 야채를 골고루 먹어요.',N'재채기를 할 때 휴지로 가리지 않고 시원하게 해요.',N'손을 씻지 않고 바로 먹어요.',N'2',N'04',N'',N'S'),
	 (278,N'01',N'06',N'이 책을 읽고 우리가 실천하면 좋은 일로 알맞은 것은 무엇인가요?',NULL,N'병균이 무서우니 밖에 나가지 않아요.',N'아프면 아무것도 먹지 않아요.',N'손 씻기와 같은 작은 습관을 지켜요.',N'약만 먹으면 괜찮다고 생각해요.',N'3',N'04',N'',N'S'),
	 (278,N'01',N'07',N'아래 상황에서 주인공 샘의 마음으로 알맞은 것은 무엇일까요?',N'"엄마, 우리 눈으로 병균을 볼 수는 없죠?"',N'화가 난 마음 ',N'궁금한 마음 ',N'기쁜 마음 ',N'무서운 마음',N'2',N'05',N'Y',N'S'),
	 (278,N'01',N'08',N'감기와 병균에 대해 알게 된 뒤 샘의 마음으로 알맞은 것은 무엇인가요?',NULL,N'더 알고 싶고 신기한 마음',N'아무 관심 없는 마음',N'짜증 나는 마음',N'슬프고 속상한 마음',N'1',N'05',N'',N'S'),
	 (278,N'01',N'09',N'다음 빈칸에 어울리는 흉내 내는 말을 찾아보세요.',N'“딱지는 피가 (         ) 굳어서
