	 (278,N'01',N'12',N'‘병균’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'우리 몸을 튼튼하게 하는 것',N'눈에 잘 보이는 벌레',N'몸에 좋은 세균',N'병을 일으키는 아주 작은 생물',N'4',N'06',N'',N'S'),
	 (279,N'01',N'01',N'양순이는 어떤 성격을 가진 아이였나요?',NULL,N'활발하고 친구가 많은 아이',N'말수가 적고 조용한 아이',N'장난을 좋아하는 아이',N'운동을 좋아하는 아이',N'2',N'01',NULL,N'S'),
	 (279,N'01',N'02',N'양순이는 무엇을 친구들에게 전하지 못했나요?',NULL,N'생일 초대장',N'사과 편지',N'수학 문제집',N'편지 봉투',N'1',N'01',NULL,N'S'),
	 (279,N'01',N'03',N'양순이는 떡집에서 어떤 떡을 처음 먹었나요?',NULL,N'들깨떡',N'꿀떡',N'조롱이떡',N'말술떡',N'4',N'03',NULL,N'S'),
	 (279,N'01',N'04',N'양순이는 결국 생일 파티를 어떻게 했나요?',NULL,N'파티를 취소함',N'엄마 아빠와만 조용히 지냄',N'친구들과 즐겁게 함께 보냄',N'친척들과만 모임을 가짐',N'3',N'03',NULL,N'S'),
	 (279,N'01',N'05',N'<양순이네 떡집>의 작가는 누구인가요?',NULL,N'전이수',N'김리리',N'유은실',N'김중미',N'2',N'07',NULL,N'S'),
	 (279,N'01',N'06',N'떡의 이름에 숨어 있는 뜻은 무엇을 표현하나요?',NULL,N'떡의 재료',N'양순이의 감정과 변화',N'마을 이름',N'가게 주인의 성격',N'2',N'02',NULL,N'S'),
	 (279,N'01',N'07',N'작가는 양순이의 마음 변화를 어떻게 잘 표현했나요?',NULL,N'떡을 먹을 때마다 달라지는 행동을 통해',N'친구들이 양순이를 혼내는 장면을 통해',N'양순이가 떡을 팔기 시작하는 장면을 통해',N'양순이가 집에서 혼자 생각하는 장면을 통해',N'1',N'02',NULL,N'S'),
	 (279,N'01',N'08',N'‘말술떡’에서 ‘술’은 무슨 뜻으로 쓰였나요?',NULL,N'술 마시는 술',N'말을 술술 잘하게 해 주는 뜻',N'술떡 재료의 이름',N'술래잡기의 ‘술’',N'2',N'06',NULL,N'S'),
	 (279,N'01',N'09',N'조롱이떡을 먹으면 마음의 소리가 어떻게 들리나요?',NULL,N'조심조심',N'조곤조곤',N'조각조각',N'조급조급',N'2',N'06',NULL,N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (279,N'01',N'10',N'이 책을 읽고 느낄 수 있는 교훈으로 가장 알맞은 것은?',NULL,N'친구보다 혼자가 편하다',N'자신감을 가지면 행동이 달라진다',N'말은 많이 할수록 좋다',N'남을 무조건 도와야 한다',N'2',N'04',NULL,N'S'),
	 (279,N'01',N'11',N'<양순이네 떡집>은 어떤 시리즈의 책인가요?',NULL,N'마법의 시간 시리즈',N'학교괴담 시리즈',N'만복이네 떡집 시리즈',N'행복마을 시리즈',N'3',N'07',NULL,N'S'),
	 (279,N'01',N'12',N'양순이처럼 말하기가 어려운 친구가 있다면, 어떻게 하는 것이 좋을까요?',NULL,N'먼저 다가가 말을 걸어본다',N'무시하고 지나간다',N'말 못 한다고 놀린다',N'그냥 모른 척한다',N'1',N'04',NULL,N'S'),
	 (280,N'01',N'01',N'학교에 가기 싫어하는 내가 학교에 가는 이유는 무엇인가요?',NULL,N'잘생긴 선생님이 있어서',N'또래 친구가 많아서',N'급식이 맛있어서',N'친구를 놀리고 싶어서',N'2',N'04',N'',N'S'),
	 (280,N'01',N'02',N'다음 빈칸에 들어갈 말로 알맞게 짝지어 진 것은 무엇인가요?',N'미희는 (      )처럼 사람을 끄는 묘한 매력이 있다. 난 미희 주위를 (         )처럼 오락가락만 하는데 말이다.',N'자석-시계추',N'자석-구름',N'시계추-구름',N'시계추-자석',N'1',N'02',N'Y',N'S'),
	 (280,N'01',N'03',N'양파 아이들의 아지트는 어디인가요?',NULL,N'운동장 스탠드',N'화장실',N'학교 후문',N'쓰레기 분리수거장',N'2',N'01',N'',N'S'),
	 (280,N'01',N'04',N'체육시간이 끝난 후, 양파 애들이 수돗가까지 뛰어서 가지 않아도 되는 이유는 무엇인가요?',NULL,N'미희가 수돗가로 가면 알아서 자리를 비켜주기 때문에',N'양파 애들의 땀냄새 때문에',N'양파 애들 중 한 명이 다리가 다쳐서',N'수돗가에 자리가 많이 남기 때문이다.',N'1',N'03',N'',N'S'),
	 (280,N'01',N'05',N'따돌림에 대한 설명으로 옳지 않은 것은 무엇인가요?',NULL,N'따돌림은 장난처럼 보여도 누군가에게는 큰 상처가 된다.',N'아무 말도 하지 않고 가만히 있는 것은 따돌림을 막는 데 도움이 되지 않는다.',N'따돌림을 당한 친구를 도와주는 것은 용기 있는 행동이다.',N'한 명만 괴롭히면 따돌림이 아니고, 여럿이 해야 따돌림이다.',N'4',N'07',N'',N'S'),
	 (280,N'01',N'06',N'나는 미희 앞에서 무엇 때문에 아빠를 부끄러워했나요?',NULL,N'아빠의 나이 때문에',N'아빠의 직업 때문에',N'아빠가 새 아빠라서',N'아빠가 키가 작아서',N'2',N'04',N'',N'S'),
	 (280,N'01',N'07',N'양파 아이들 중에서 내가 시간이 갈수록 좋아진 아이는 누구인가요?',NULL,N'미희',N'정선',N'수빈',N'철수',N'2',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (280,N'01',N'08',N'정화는 다른 친구를 따돌리는 것은 잘못된 것임을 알고있다. 이 마음과 반대되는 정화의 생각은 무엇인가요?',NULL,N'상처받는 정선을 보며 "내가 왜 이러고 있지?"라고 생각해',N'정선이 말없이 참는 얼굴을 보면 마음이 아파',N'작게 웃어보이는 정선이를 보며 "왜 이런 착한 아이가 따돌림을 당해야하지?"라고 생각해',N'양파에 들어서 다른 친구들에게 주목받고 혼자라는 느낌이 줄어들어',N'4',N'03',N'',N'S'),
	 (280,N'01',N'09',N'나는 글짓기 대회에 나가 어떤 이야기를 글로 썼나요?',NULL,N'아빠를 의사라고 속인 이야기',N'내가 경험한 왕따 이야기',N'양파 아이들의 서열 이야기',N'학교에서 친구들과 어울렸던 이야기',N'2',N'02',N'',N'S'),
	 (280,N'01',N'10',N'몸이 아프거나 출혈이 있을 때에, 피부 밑이나 정맥에 놓는 주사를 무엇이라고 하나요? ',NULL,N'링거',N'예방접종',N'불주사',N'독감주사',N'1',N'06',N'',N'S'),
	 (280,N'01',N'11',N'나중으로 미룬 차례라는 뜻의 단어는 무엇인가요?',NULL,N'목차',N'우선순위',N'뒷전',N'앞전',N'3',N'06',N'',N'S'),
	 (280,N'01',N'12',N'나라에서 지어서 직접 관리ㆍ운영하는 도서관을 무엇이라고 하나요?',NULL,N'독립서점',N'국립도서관',N'시립도서관',N'국가도서관',N'2',N'07',N'',N'S'),
	 (281,N'01',N'01',N'계곡에 간 산이와 친구들이 자리 걱정을 하지 않은 이유는 무엇인가요?',NULL,N'산이네 아빠와 영진이네 아빠가 자리를 잡아 놓아서',N'계곡에 빈 자리가 많아서',N'사람들이 서로 자리를 양보해줘서',N'날씨가 흐려서 사람이 적어서',N'1',N'01',N'',N'S'),
	 (281,N'01',N'02',N'물고기를 잡으러 간 산이에게 어떤 일이 생겼나요?',NULL,N'물에 빠져 허우적 거렸어요.',N'깨진 유리병에 발이 베었어요.',N'커다란 물고기를 잡았어요.',N'친구와 다투었어요.',N'2',N'01',N'',N'S'),
	 (281,N'01',N'03',N'일이 일어난 순서대로나열한 것을 찾으세요.',N'(1) 산이는 물고기를 놓아주고 오면서 쓰레기를 버리리 않겠다고 다짐했어요. 
(2) 계곡을 다시 찾은 아이들은 힘을 모아 계곡의 쓰레기를 청소했어요. 
(3) 계곡으로 물놀이를 가기위해 친구들이 산이네 집으로 모였어요.',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(3)-(1)-(2)',N'(1)-(2)-(3)',N'1',N'03',N'Y',N'S'),
	 (281,N'01',N'04',N'산이와 친구들이 계곡의 쓰레기를 다시 치우게 된 까닭은 무엇인가요?',NULL,N'계곡이 너무 더러워서 놀 수 없었기 때문이에요.',N'어른들이 시켜서 억지로 했어요.',N'집에 빨리 가고 싶었기 때문이에요.',N'쓰레기가 위험하다는 것을 깨달았기 때문이에요.',N'4',N'03',N'',N'S'),
	 (281,N'01',N'05',N'아빠가 말씀하신 쓰레기의 무서움에 대한 내용을 읽고 다짐을 <u>잘못</u> 말한 것을 찾으세요.',N'"반짝거리는 쓰레기를 먹은 물고기의 몸 안에 독성물질이 남아서 그걸 사람이 다시 먹으면 정말 끔찍한 일이 발생 한단다."',N'쓰레기를 함부로 버리지 않도록 해야겠어.',N'플라스틱이나 캔류는 꼭 분리해서 버려야 해.',N'가능하면 일회용품을 많이 사용해야겠어.',N'쓰레기를 줄이고 자연을 아껴야겠어.',N'3',N'04',N'Y',N'S');
