INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (300,N'01',N'02',N'에벌린이 수의과 대학에 갈 수 없었던 이유는 무엇이었나요?',NULL,N'가난해서 대학교 등록금을 내지 못했기 때문이에요.',N'여자들은 절대 수의사가 될 수 없던 시대였기 때문이에요.',N'부모님이 강하게 반대했기 때문이에요.',N'공부를 좋아하지 않았기 때문이에요.',N'2',N'01',N'',N'S'),
	 (300,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 에벌린은 자신의 이야기를 책으로 엮었어요. 
(2) 에벌린은 해 뜰때부터 해 질때까지 태평양의 섬들을 탐험했어요.                                                               (3) 에벌린은 곤충의 집을 맡아보기로 했어요.',N'(3)-(1)-(2)',N'(3)-(2)-(1)',N'(1)-(2)-(3)',N'(2)-(3)-(1)',N'2',N'03',N'Y',N'S'),
	 (300,N'01',N'04',N'그레이스의 편지를 읽고 에벌린은 왜 런던 동물원으로 향했나요?',NULL,N'곤충을 더 찾으려고',N'일자리를 얻을 수 있을 것 같아서',N'여행을 떠나고 싶어서',N'가족을 만나기 위해서',N'2',N'03',N'',N'S'),
	 (300,N'01',N'05',N'이 이야기의 내용과 어울리지 <u>않는</u> 생각은 무엇인가요?',NULL,N'여자도 곤충을 좋아할 수 있어요.',N'좋아하는 일을 하려면 용기가 필요해요.',N'시대의 차별은 노력으로 바꿀 수 있어요.',N'여자는 정해진 일만 해야 해요.',N'4',N'04',N'',N'S'),
	 (300,N'01',N'06',N'에벌린의 모습에서 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'하고 싶은 일이 있어도 남의 눈치를 봐야 해요.',N'위험한 일은 무조건 피해야 해요.',N'어려움이 있어도 좋아하는 일을 계속할 수 있어요.',N'혼자서만 일해야 성공할 수 있어요.',N'3',N'04',N'',N'S'),
	 (300,N'01',N'07',N'에벌린의 마음은 어땠을까요?',N'에벌린은 거미줄에 걸려 비틀거렸어요. 거미줄 가닥을 잡아당기고 발로 찼지만 탈출할 수가 없었어요.',N'무섭고 당황스러워요.',N'우습고 실망스러워요.',N'우스꽝스럽고 시시해요.',N'신나고 즐거워요.',N'1',N'05',N'Y',N'S'),
	 (300,N'01',N'08',N'1955년 영국 여왕에게 훈장을 받았을 때 에벌린의 마음은 어떠했을까요?',NULL,N'부끄럽고 숨고 싶은 마음',N'기쁘고 뿌듯한 마음',N'화가 나고 억울한 마음',N'무섭고 떨리는 마음',N'2',N'05',N'',N'S'),
	 (300,N'01',N'09',N'다음 문장에 어울리는 표현을 찾으세요.',N'딱정벌레 한 마리만 거대한 수조에서 헤엄치고 있었지요.',N'참방참방',N'엉거주춤',N'홀짝홀짝',N'살금살금',N'1',N'02',N'Y',N'S'),
	 (300,N'01',N'10',N'다음 문장에 어울리는 표현을 찾으세요.',N'에벌린은 꽃꿀을 (        )거리는 나비들을 보여 주었지요.',N'반짝',N'비틀',N'데굴',N'홀짝',N'4',N'02',N'Y',N'S'),
	 (300,N'01',N'11',N'여러 곳을 다니며 찾은 것을 모으는 것''을 뜻하는 말은 무엇인가요?',NULL,N'선택',N'채집',N'모집',N'선물',N'2',N'06',N'',N'S');
