	 (305,N'01',N'04',N'염소 두 마리가 강물에 빠지게 된 가장 큰 이유는 무엇인가요?',NULL,N'다리가 미끄러워서',N'물살이 너무 세서',N'바람이 세게 불어서',N'서로 양보하지 않았기 때문에',N'4',N'03',N'',N'S'),
	 (305,N'01',N'05',N'염소들에게 어떤 말을 해줄 수 있을까요?',NULL,N'거짓말을 하지 말고정직한 마음을 가져!',N'자기만 생각하지 말고 양보하는 마음을 가져!',N'게으름 피우지 말고  부지런하게 행동해! ',N'힘이 세야 이길 수 있어!',N'2',N'04',N'',N'S'),
	 (305,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 가장 알맞은 것은 무엇인가요?',NULL,N'먼저 온 사람이 항상 옳아요.',N'싸우면 반드시 이길 수 있어요.',N'끝까지 고집을 부려야 해요.',N'서로 양보하면 다치지 않을 수 있어요.',N'4',N'04',N'',N'S'),
	 (305,N'01',N'07',N'염소 두 마리는 어떤 목소리로 말했을까요?',N'"야, 내가 먼저 왔으니 비켜!"
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (306,N'01',N'01',N'선생님은 월요일마다 무엇을 하시나요?',NULL,N'일기장 검사를 하세요.',N'친구들에게 기분을 물어 보세요.',N'출석을 부르세요.',N'그림을 그리게 하세요.',N'2',N'01',N'',N'S'),
	 (306,N'01',N'02',N'선생님의 질문에 테오는 어떤 반응을 보였나요?',NULL,N'잘 모르겠다며 기분을 설명하지 못했어요.',N'자신있게 자신의 기분을 이야기 했어요.',N'자신의 기분을 행동으로 표현해 보겠다고 했어요.',N'친구에게 대신 말해 달라고 했어요.',N'1',N'01',N'',N'S'),
	 (306,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 곰곰이 생각한 테오는 오빠가 된 기분을 씩씩하게 말하기 시작했어요.
(2) 선생님은 여동생이 생긴 테오에게 기분을 물어보셨어요.
(3) 테오는 자신의 기분을 설명하지 못해 망설였어요.',N'(2)-(3)-(1)',N'(2)-(1)-(3)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'1',N'03',N'Y',N'S'),
	 (306,N'01',N'04',N'생각이 정리된 테오가 기분을 말하자 친구들이 놀란 까닭은 무엇인가요?',NULL,N'테오 목소리가 너무 커서 교실이 울렸기 때문에',N'한꺼번에 많은 기분을 느낀게 신기했기 때문에',N'테오가 말하면서 갑자기 눈물을 흘렸기 때문에 ',N'테오가 말을 너무 길게 했기 때문에',N'2',N'03',N'',N'S'),
	 (306,N'01',N'05',N'테오의 모습을 보고 알 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'기분은 하나만 느끼는 것이다.',N'기분은 숨기고 말하지 않는 것이 좋다.',N'한 사람도 여러 가지 기분을 느낄 수 있다.',N'기분은 어른만 느낄 수 있다.',N'3',N'04',N'',N'S'),
	 (306,N'01',N'06',N'이 이야기에서 가장 중요하게 전하고 싶은 것은 무엇인가요?',NULL,N'기분을 말하면 친구들이 놀란다.',N'기분을 솔직하게 말하는 것은 도움이 된다.',N'동생이 생기면 힘들기만 하다.',N'학교에서는 말을 적게 해야 한다.',N'2',N'04',N'',N'S'),
	 (306,N'01',N'07',N'테오는 어떤 마음이었을까요?',N'테오가 말했어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (306,N'01',N'11',N'빈칸에 알맞은 이어주는 말을 찾아보세요. ',N'"할머니가 우리 집에 계셔서 행복해. 
(       ) 엄마가 나랑 놀아줄 시간이 없으니 질투도 나."',N'하지만',N'그래서',N'그러므로',N'왜냐하면',N'1',N'06',N'Y',N'S'),
	 (306,N'01',N'12',N'밑줄친 말과 비슷한 뜻을 가진 어휘를 찾아보세요.',N'어떻게 그렇게 많은 <u>기분</u>을 느낄 수 있어?',N'대답',N'질문',N'감정',N'질투',N'3',N'06',N'Y',N'S'),
	 (307,N'01',N'01',N'산이는 무엇때문에 스트레스를 받았나요?',NULL,N'받아쓰기',N'태권도',N'줄넘기',N'술래잡기',N'1',N'01',N'',N'S'),
	 (307,N'01',N'02',N'산이가 지호를 부러워한 이유를 찾으세요.',NULL,N'격파를 잘하기 때문이에요.',N'리코더를 잘 부르기 때문이에요.',N'종이접기를 잘하기 떄문이에요.',N'줄넘기를 잘하기 때문이에요.',N'3',N'01',N'',N'S'),
	 (307,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 산이는 태권도 꼬마 선생님이 되었어요
(2) 민지가 산이에게 줄넘기를 가르쳐 달라고 했어요.
(3) 산이는 받아쓰기 빵점을 맞았어요.',N'(3)-(2)-(1)',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'1',N'03',N'Y',N'S'),
	 (307,N'01',N'04',N'선생님이 ‘꼬마 선생님의 날’을 만든 까닭은 무엇인가요?',NULL,N'공부를 안 해도 되게 하려고',N'선생님이 쉬려고',N'시험을 보지 않게 하려고',N'아이들이 서로 잘하는 것을 나누게 하려고',N'4',N'03',N'',N'S'),
	 (307,N'01',N'05',N'이야기 속 아이들의 모습을 보고 알 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'잘하는 것이 없으면 필요 없는 사람이다.',N'사람마다 잘하는 것은 모두 다르다.',N'공부를 잘해야만 친구를 도울 수 있다.',N'선생님만 가르칠 수 있다.',N'2',N'04',N'',N'S'),
	 (307,N'01',N'06',N'산이가 꼬마 선생님이 된 뒤 달라진 모습으로 알맞은 것은 무엇인가요?',NULL,N'더 스트레스를 받게 되었어요.',N'친구들을 무시하게 되었어요.',N'공부를 포기했어요.',N'자신감이 생겼어요.',N'4',N'04',N'',N'S'),
	 (307,N'01',N'07',N'선생님의 말씀을 듣고 지호는 어떤 마음이었을까요?',N'"지호야, 미술 시간에 친구들에게 연필꽂이 접는 방법을 가르쳐 줄래?"',N'쑥스럽지만 기분이 좋아요.',N'부끄럽고 불안해요.',N'얄밉고 짜증스러워요.',N'화가 나고 속상해요.',N'1',N'05',N'Y',N'S'),
	 (307,N'01',N'08',N'줄넘기를 가르쳐 달라는 부탁을 받았을 때 산이의 마음은 어떠했을까요?',NULL,N'창피한 마음',N'무서운 마음',N'뿌듯한 마음',N'화가 난 마음',N'3',N'05',N'',N'S');
