INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (310,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 온이는 나이를 더 먹으려고 떡국을 먹고 또 먹었어요.
(2) 할아버지와 할머니도 시골에서 도착하셨어요.
(3) 할머니는 온이에게 손이보다 나이를 더 먹을 수 있는 방법을 알려주셨어요.',N'(2)-(1)-(3)',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(1)-(3)-(2)',N'3',N'03',N'Y',N'S'),
	 (310,N'01',N'04',N'온이가 떡국을 먹고 또 먹은 까닭은 무엇인가요?',NULL,N'떡국이 너무 맛있어서',N'손이보다 나이를 더 먹고 싶어서',N'엄마가 많이 먹으라고 해서',N'배가 고파서',N'2',N'03',N'',N'S'),
	 (310,N'01',N'05',N'온이가 자신이 누나라고 우겨도 손이는 점잖게 참았어요. 손이에게 어떤 말을 해줄 수 있을까요?',NULL,N'화가 날 수도 있을텐데, 어린 동생을 위해서 참는 모습이 기특해요.',N'버릇이 없는 온이를 혼내주는 게 좋을 것 같아요.',N'온이에게 무관심한 모습이 안타까워요.',N'온이를 이기려고만 하는 모습이 좋지 않아 보여요.',N'1',N'04',N'',N'S'),
	 (310,N'01',N'06',N'이 이야기에서 알 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'형제자매는 함께 놀면 안 돼요.',N'나이가 많으면 무조건 이겨요.',N'이기고 싶어 하는 마음이 들 수도 있어요.',N'떡국을 너무 많이 먹으면 안 돼요.',N'3',N'04',N'',N'S'),
	 (310,N'01',N'07',N'다음 말을 들었을 때 손이의 마음은 어떠했을까요?',N'"안 돼. 따라 하지 마. 그리고 동생은 누나를 못 이겨!"',N'즐거운 마음',N'당황스러운 마음',N'자랑스러운 마음',N'억울한 마음',N'2',N'05',N'Y',N'S'),
	 (310,N'01',N'08',N'설날에 떡국을 먹으며 온이의 마음은 어떠했을까요?',NULL,N'재미없고 심심한 마음',N'더 이기고 싶은 마음',N'무섭고 불안한 마음',N'미안한 마음',N'2',N'05',N'',N'S'),
	 (310,N'01',N'09',N'다음 빈칸에 들어갈 표현을 찾으세요.',N'손이가 눈뭉치를 맞고 (       ) 엎어졌어요.',N'흐느적',N'어슬렁',N'포르르',N'철퍼덕',N'4',N'02',N'Y',N'S'),
	 (310,N'01',N'10',N'다음 빈칸에 들어갈 표현을 찾으세요.',N'남이 들을까봐 귀에 대고 (         ) 말했어요.',N'소곤소곤',N'재잘재잘',N'왁지지껄',N'쿵쾅쿵쾅',N'1',N'02',N'Y',N'S'),
	 (310,N'01',N'11',N'때때옷''의 뜻을 찾아 보세요.',NULL,N'어린아이의 가족이 입는 옷',N'어린아이가 명절에 입는 알록달록한 옷',N'어린아이가 생일에 입는 옷',N'어린아이가 매일 입는 옷',N'2',N'06',N'',N'S'),
	 (310,N'01',N'12',N'‘점잖게’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'화를 내며 말하는 모습',N'크게 웃으며 떠드는 모습',N'떼를 쓰는 모습',N'조용하고 차분한 모습',N'4',N'06',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (311,N'01',N'01',N'스님이 거지 남매와 만난 곳은 어디인가요?',NULL,N'포구',N'절',N'공터',N'숲속',N'1',N'01',N'',N'S'),
	 (311,N'01',N'02',N'스님이 짚더미를 헤쳐 보았더니 장님 소녀와 그 아이가 무엇처럼 웅크리고 있었나요?',NULL,N'민들레',N'노랑지빠귀',N'잔디',N'낙엽',N'2',N'01',N'',N'S'),
	 (311,N'01',N'03',N'빈칸에 들어갈 수 있는 말은 무엇인가요?',N'바다로부터 물새 우는소리가 쫓아와서 스님을 한참 동안 (              )하고 따라다녔다.',N'살랑살랑',N'반질반질',N'꺼억꺼억',N'빙글빙글',N'3',N'02',N'Y',N'S'),
	 (311,N'01',N'04',N'스님이 징검다리를 건너다 말고 발길을 돌린 이유는 무엇인가요?',NULL,N'징검다리가 끊어져 있어서',N'거지 남매가 얼어 죽을지도 모른다는 생각이 들어서',N'포구에 두고 온 것이 생각나서',N'돌아가서 할 일이 생겨서',N'2',N'03',N'',N'S'),
	 (311,N'01',N'05',N'스님은 거지 남매를 무엇으로 삼기로 했나요?',NULL,N'조카',N'자식',N'동생',N'머슴',N'1',N'07',N'',N'S'),
	 (311,N'01',N'06',N'빈칸에 들어갈 수 있는 말이 아닌 것은 무엇인가요?',N'(           ) 얘기하며 걸어가는 세 사람의 등에서 눈발은 서서히 성글어졌다.',N'도란도란',N'조잘조잘',N'토닥토닥',N'재잘재잘',N'3',N'02',N'Y',N'S'),
	 (311,N'01',N'07',N'스님이 길손이를 데리고 암자로 가기로 마음먹은 이유가 아닌 것은 무엇인가요?',N'',N'부엌일도 거들고 해서 제 밥값을 하는 편이기 때문에',N'날마다 말썽을 피워서',N'불개미를 잡아와서 스님들의 바짓가랑이 속으로 들여보내서',N'밤에 이불에 오줌을 싸서',N'1',N'04',N'N',N'S'),
	 (311,N'01',N'08',N'부처님 눈에 바람이 보이는 이유는 무엇인가요?',NULL,N'부처님은 시력이 매우 좋으시기 때문에',N'부처님은 바람을 잘 다룰 수 있어서',N'부처님은 마음의 눈을 뜨고 계셔서',N'바람은 원래 눈에 잘 보이는 것이기 때문에',N'3',N'03',N'',N'S'),
	 (311,N'01',N'09',N'보살님께 이야기한 길손이의 소원은 무엇인가요?',NULL,N'엄마를 가지는 것',N'절을 벗어나는 것',N'배부르게 밥을 먹는 것',N'동생과 헤어지는 것',N'1',N'04',N'',N'S'),
	 (311,N'01',N'10',N'다음이 설명하는 단어는 무엇인가요?',N'눈에 독기를 띠며 쏘아보는 시선.',N'말총',N'눈총',N'총기',N'국총',N'2',N'07',N'Y',N'S');
