INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (312,N'01',N'09',N'친구들은 처음에 자신에게 부족한 것이 있다고 생각했지만, 결국 스스로 해냈어요. 이 장면에서 배울 수 있는 교훈은 무엇인가요?',NULL,N'우리가 원하는 것은 이미 우리 안에 있다',N'마법이 없으면 아무것도 할 수 없다',N'다른 사람만 믿는 게 가장 좋다',N'노력해도 바뀌지 않는다',N'1',N'04',NULL,N'S'),
	 (312,N'01',N'10',N'<오즈의 마법사>에 등장하는 ‘에메랄드 시’는 어떤 곳으로 표현되나요?',NULL,N'공장과 기계로 가득한 도시',N'어둡고 위험한 숲 속 마을',N'마법사가 사는 반짝이는 도시',N'요정들이 사는 숲속 도시',N'3',N'07',NULL,N'S'),
	 (312,N'01',N'11',N'<오즈의 마법사>는 어느 나라를 배경으로 하는 작품인가요?',NULL,N'독일',N'미국',N'일본',N'프랑스',N'2',N'07',NULL,N'S'),
	 (312,N'01',N'12',N'도로시는 집으로 돌아가고 싶다는 마음을 끝까지 잃지 않았어요. 이 모습에서 알 수 있는 것은 무엇인가요?',NULL,N'꿈보다 집이 더 재미있다',N'소중한 것을 잊지 않는 마음이 중요하다',N'여행은 항상 위험하다',N'모험보다 안전이 더 좋다',N'2',N'04',NULL,N'S'),
	 (314,N'01',N'01',N'캔사스 주에서 부는 회오리 바람을 무엇이라 하나요?',N'',N'토네이도',N'튼튼한 다리',N'블랙홀',N'천둥',N'3',N'07',N'N',N'S'),
	 (314,N'01',N'02',N'따뜻한 마음을 얻기 위해 함께 모험을 떠난 친구는 누구인가요?',N'',N'아내',N'양철 나무꾼 ',N'토토',N'허수아비',N'2',N'07',N'N',N'S'),
	 (314,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 도로시와 토토는 아저씨와 아줌마가 있는 캔자스의 농장으로 돌아왔어요.
(2) 도로시는 친구들과 무사히 모험을 마치고 오즈의 마법사를 만났어요. 
(3) 통나무 집 밑에는 빨간 구두를 신은 동쪽나라 마녀가 깔려 있었어요.',N'가까운 치킨 나라',N'가까운 피자 나라',N'먼 치킨 나라',N'먼 피자 나라',N'3',N'03',N'Y',N'S'),
	 (314,N'01',N'04',N'양귀비 꽃향기를 맡고 정신을 잃은 도로시와 사자를 구할 수 있었던 이유는 무엇인가요?',N'',N'허수아비와 양철나무꾼은 냄새를 견딜 수 있기 때문',N'혼자서만 행동하게 되었어요.',N'친구를 구해야 한다는 생각으로 냄새를 견뎠기 때문',N'친구들과 힘을 모아 문제를 해결하게 되었어요.',N'4',N'03',N'N',N'S'),
	 (314,N'01',N'05',N'허수아비가 가장 무서워 하는 것은 무엇인가요?',N'“너희는 모험을 하는 동안 훌쩍 자랐구나.”',N'지혜로운 생각, 용기, 따뜻한 마음으로 어려움을 이겨내고 모험을 잘 마쳤다는 뜻',N'성냥',N'불',N'바람',N'2',N'04',N'Y',N'S'),
	 (314,N'01',N'06',N'이 이야기에서 도로시와 친구들이 함께 모험을 한 가장 큰 이유는 무엇일까요?',N'',N'혼자보다 여럿이 더 재미있어서',N'양철 나무꾼-폐',N'사자-용기',N'여행을 오래 하고 싶어서',N'2',N'04',N'N',N'S');
