	 (314,N'01',N'07',N'양철나무꾼이 ''길을 잘 보고 걸어야 한다''는 교훈을 얻게 된 계기는 무엇인가요?',N'물을 끼얹자 마녀가 녹아 없어지며 소리쳤어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (315,N'01',N'02',N'배를 타지 않고 한강을 건널 방법은 무엇이었나요?',NULL,N'큰 배 80여척을 빌려 배다리로 만들었어요. ',N'한강에 징검다리를 놓았어요.',N'널빤지로만 다리를 만들었어요.',N'얼음 위를 걸어서 건넜어요.',N'1',N'01',N'',N'S'),
	 (315,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열된 것을 찾으세요.',N'(1) 정약용은 틈틈이 서양의 새로운 학문을 공부했어요.
(2) 나라와 백성을 위한 책을 48권이나 썼어요.
(3) 백성들은 신기한 거중기를 고마워했어요.',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'3',N'03',N'Y',N'S'),
	 (315,N'01',N'04',N'정약용의 생각과 행동이 잘 이어진 것을 고르세요.',NULL,N'서양 학문을 좋아했어요 → 혼자 똑똑해지려고 했어요',N'백성들이 힘들어하는 것 같았어요 → 그대로 두고 지켜봤어요',N'자기 이름을 알리고 싶었어요 → 책을 많이 썼어요',N'백성을 걱정했어요 → 백성을 돕는 기구와 방법을 만들었어요',N'4',N'03',N'',N'S'),
	 (315,N'01',N'05',N'항상 백성을 걱정한 정약용에게 어떤 말을 해줄 수 있을까요?',NULL,N'귀양살이때 책을 많이 쓴 점이 훌륭해요.',N'오직 나라와 백성을 생각하는 모습이 감동적이에요.',N'거중기를 만들어서 편리해졌어요.',N'학문을 잘해서 유명해졌어요.',N'2',N'04',N'',N'S'),
	 (315,N'01',N'06',N'정약용이 오늘날에도 필요한 인물인 이유로 알맞은 것은 무엇인가요?',NULL,N'글씨를 예쁘게 썼기 때문이에요.',N'관리가 되는 법을 알려 주었기 때문이에요.',N'백성의 어려움을 먼저 생각했기 때문이에요.',N'서양 문화를 좋아했기 때문이에요.',N'3',N'04',N'',N'S'),
	 (315,N'01',N'07',N'정약용은 어떤 마음이었을까요?',N'"백성들은 이렇게 비참하게 사는데, 관리들은 떵떵거리며 제 배만 불리다니, 어떻게 이럴수가 있는가?"',N'민망함',N'안타까움',N'미안함',N'즐거움',N'2',N'05',N'Y',N'S'),
	 (315,N'01',N'08',N'거중기를 보고 기뻐하는 백성들을 본 정약용의 마음은 어땠을까요?',NULL,N'뿌듯하고 흐뭇했어요.',N'화가 나고 안타까웠어요.',N'부끄럽고 창피했어요.',N'무섭고 불안했어요.',N'1',N'05',N'',N'S'),
	 (315,N'01',N'09',N'빈칸에 어울리는 흉내내는 말을 찾아보세요.',N'나뭇가지로 (     ) 배를 만들었어요.',N'똑딱똑딱',N'뚝딱뚝딱',N'뒤뚱뒤뚱',N'뒤적뒤적',N'2',N'02',N'Y',N'S'),
	 (315,N'01',N'10',N'거중기가 무거운 돌을 단번에 들어 올리는 모습을 가장 잘 나타낸 말은 무엇인가요?',NULL,N'살랑',N'데굴',N'절레',N'번쩍',N'4',N'02',N'',N'S'),
	 (315,N'01',N'11',N'농작물이 잘 자라지 않아 결과가 좋지 않은 때를 무엇이라고 하나요?',NULL,N'매년',N'풍년',N'흉년',N'수확',N'3',N'06',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (315,N'01',N'12',N'‘비참하다’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'즐겁고 신나는',N'편안하고 넉넉한',N'조용하고 평화로운',N'매우 어렵고 불쌍한',N'4',N'06',N'',N'S'),
	 (316,N'01',N'01',N'전 세계에서 가장 많이 생산되는 작물 3가지를 세계 3대 작물이라고 하는데, 이것에 해당하지 않는 것은 무엇인가요?',NULL,N'쌀',N'감자',N'옥수수',N'밀',N'2',N'03',N'',N'S'),
	 (316,N'01',N'02',N'허준이 쓴 책으로, 옥수수에 대한 이야기가 언급된 책의 제목은 무엇인가요?',NULL,N'동의보감',N'명심보감',N'경국대전',N'조의제문',N'1',N'07',N'',N'S'),
	 (316,N'01',N'03',N'유전학의 아버지라고 불리우며, 이 사람이 밝혀낸 유전법칙으로 인해 후대의 과학자들이 열매를 더 많이 맺는 옥수수 씨앗을 발견해냈습니다. 독일의 과학자인 이 사람은 누구인가요?',NULL,N'우장춘',N'헨델',N'멘델',N'그레텔',N'3',N'01',N'',N'S'),
	 (316,N'01',N'04',N'다음 중 식물이 자라는 데에 필요한 조건으로 올바르지 않은 것은 무엇인가요?',NULL,N'질소',N'아연',N'칼륨',N'이산화탄소',N'2',N'04',N'',N'S'),
	 (316,N'01',N'05',N'제2차 세계대전 이후 옥수수를 비롯한 식물들이 더 자랄 수 있게끔 한 수단으로, 벌레를 잡는 데에 유용한 것은 무엇인가요?',NULL,N'살충제',N'항생제',N'미사일',N'제초제',N'1',N'01',N'',N'S'),
	 (316,N'01',N'06',N'항생제의 한 종류로, 제2차 세계대전 때 대량 생산된 물질은 무엇인가요?',N'',N'아미노글리코사이드',N'페니실린',N'폴리믹신',N'아드레날린',N'2',N'07',N'N',N'S'),
	 (316,N'01',N'07',N'18세기 무렵 옥수수를 즐겨 먹던 유럽 사람들이 펠레그라라는 병에 걸렸던 이유는 무엇인가요?',NULL,N'옥수수에 있는 니아신이라는 성분을 섭취하지 못해서',N'정말로 옥수수를 많이 먹으면 병에 걸려서',N'옥수수와 초록채소를 곁들어 먹지 못해서',N'옥수수에 치명적인 병원균이 있어서',N'1',N'04',N'',N'S'),
	 (316,N'01',N'08',N'다음 중 책을 올바르게 이해하지 못한 사람은 누구인가요?',NULL,N'재민: 옥수수가 정말 다양하게 활용되고 있구나.',N'지민: 옥수수가 유럽에서 인정받지 못 할 때도 있었구나.',N'태민: DDT만 사용한다면 옥수수재배는 문제가 없겠네!',N'수지: 옥수수는 빵이 되기 위해 여러과정을 거치는 구나',N'3',N'03',N'',N'S'),
	 (316,N'01',N'09',N'‘돈이나 물 따위를 헤프게 마구 쓰는 모양’을 나타내는 말로 적절한 것은 무엇인가요?',NULL,N'펑펑',N'폴폴',N'출렁',N'풍덩',N'1',N'02',N'',N'S');
