INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (320,N'01',N'12',N'다음 예시의 모이 정부와 어울리는 사자성어는 무엇인가요?',N'모이 정부는 독재정치를 강화하려다 오히려 선진국들에게 많은 비판을 받았다.',N'경국지색(傾國之色): 나라를 기울게 할 만큼 아름다운 미인',N'오합지졸(烏合之卒): 규율이나 통일성 없는 군중',N'자승자박(自繩自縛): 자기가 한 말과 행동에 자신이 구속되어 어려움을 겪음',N'허심탄회(虛心坦懷): 마음을 비우고 솔직하게 말함',N'3',N'02',N'Y',N'S'),
	 (320,N'01',N'13',N'"정치가가 국민에게 어떠한 정책을 실해할 것을 약속함"을 뜻하는 단어는 무엇인가요?',N'',N'노역(勞役)',N'공조(共助)',N'공약(公約)',N'공물(貢物)',N'3',N'06',N'N',N'S'),
	 (320,N'01',N'14',N'끝없는 노력에 결국 독재정권을 물리친 왕가리 마타이와 어울리는 사자성어는 무엇인가요?',N'',N'타산지석(他山之石): 다른 사람의 실수라도 나에게는 커다란 교훈이 됨',N'사필귀정(事必歸正): 무슨 일이든 결국 옳은 이치대로 돌아감',N'경거망동(輕擧妄動): 일의 앞뒤를 생각하지 않고 경솔하게 행동함',N'진퇴양난(進退兩難): 앞으로도 뒤로도 나아가기 어려움',N'2',N'06',N'N',N'S'),
	 (320,N'01',N'15',N'다음 예시의 빈칸에 어울리는 것은 무엇인가요?',N'국회의원 선거에 (  )하였다.',N'출마(出馬)',N'출가(出家)',N'승마(乘馬)',N'출석(出席)',N'1',N'06',N'Y',N'S'),
	 (321,N'01',N'01',N'욕심쟁이 영감은 배고픈 할아버지를 어떻게 대했나요?',NULL,N'집에서 쫓아냈어요.',N'음식을 먹여주었어요.',N'솜이불을 꺼내 덮어 주었어요.',N'잠자리를 마련해 주었어요.',N'1',N'01',N'',N'S'),
	 (321,N'01',N'02',N'농사꾼이 빈 맷돌을 돌리자 어떤 일이 일어났나요?',NULL,N'맷돌에서 요정이 나왔어요.',N'맷돌이 말을하기 시작했어요.',N'말하는 대로 맷돌에서 물건이 나왔어요.',N'맷돌이 굴러다녔어요.',N'3',N'01',N'',N'S'),
	 (321,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열된 것을 찾으세요.',N'(1) 할아버지는 맷돌만 남기고 떠났어요.
(2) 욕심쟁이 영감은 맷돌을 훔쳤어요.
(3) 농사꾼은 이웃 사람들에게 옷과 돈을 나누어 주었어요.',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'2',N'03',N'Y',N'S'),
	 (321,N'01',N'04',N'욕심쟁이 영감에게 맷돌이 위험해진 이유로 알맞은 것은 무엇인가요?',NULL,N'맷돌이 너무 오래되어서',N'맷돌이 말을 듣지 않아서',N'배가 너무 작아서',N'맷돌을 멈추는 법을 몰랐기 때문에',N'4',N'03',N'',N'S'),
	 (321,N'01',N'05',N'맷돌 덕분에 부자가 된 농사꾼에게 어떤 말을 해 줄 수 있을까요?',NULL,N'“착한 일을 하고 복을 받은 모습이 감동적이에요.”',N'“힘들어도 포기 하지 않는 자세를 배우고 싶어요.”',N'“약속을 잘 지키는 모습이 멋져요.”',N'"혼자만 잘 살아야 해요."',N'1',N'04',N'',N'S'),
