	 (325,N'01',N'12',N'목적을 이루기 위하여 몸과 마음을 다하여 힘을 쓴다는 것은 무엇인가요?',N'',N'노동',N'노력',N'노각',N'노선',N'2',N'06',N'',N'S'),
	 (326,N'01',N'01',N'이렇게 말하는 어른이 있다면 어떤 생각을 가지고 있는 거라고 했나요?',N'"해적 놀이는 남자만 하는 거야!"',N'여자는 모든 일을 할 수 있어요.',N'여자가 못 할 일은 많아요.',N'남자는 노력하지 않아도 원하는 일을 할 수 있어요.',N'여자는 남자를 도와야 해요.',N'2',N'01',N'Y',N'S'),
	 (326,N'01',N'02',N'힘차게 공을 차는 직업''을 찾아보세요.',NULL,N'무용수',N'축구선수',N'경찰관',N'화가',N'2',N'01',N'',N'S'),
	 (326,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) ''누구나 무엇이든 할 수 있다''고 했어요.
(2) ''무엇이 될지 모르지만 시간이 충분하기 때문에 괜찮다''고 했어요.
(3) ''여자는 축구를 할 수 없다''고 생각하는 어른들이 있어요.',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'3',N'03',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (326,N'01',N'04',N'이 책의 내용으로 보아 가장 알맞은 생각은 무엇인가요?',NULL,N'여자와 남자는 해야 할 일이 다 달라요',N'여자는 조용한 일만 해야 해요',N'남자는 힘든 일을 맡아야 해요',N'여자와 남자 모두 원하는 일을 선택할 수 있어요',N'4',N'03',N'',N'S'),
	 (326,N'01',N'05',N'남녀의 일이 정해져 있다고 생각하는 어른들에게 어떤 말을 해줄 수 있을까요?',NULL,N'남자가 여자보다 더씩씩하고 용감해요.',N'누구든지 노력하면 원하는 일을 할 수 있어요.',N'여자는 힘이 약해서 할 수 있는 일이 정해져 있어요.',N'남자는 항상 앞에 서야 해요.',N'2',N'04',N'',N'S'),
	 (326,N'01',N'06',N'이 책을 읽고 우리가 가져야 할 태도로 알맞은 것은 무엇인가요?',NULL,N'남의 생각을 그대로 따라야 해요',N'하고 싶은 일을 포기해야 해요',N'나의 선택을 믿고 도전해야 해요',N'어려운 일은 피해야 해요',N'3',N'04',N'',N'S'),
	 (326,N'01',N'07',N'"여자는 겁쟁이야."라는 말을 듣는다면 마음이 어떨까요?',NULL,N'속상하고 화가나요.',N'기쁘고 반가워요.',N'자랑스럽고 행복해요.',N'아무렇지 않아요.',N'1',N'05',N'',N'S'),
	 (326,N'01',N'08',N'“우리 여자도 할 수 있어요!”라고 말할 때의 마음은 어떨까요?',NULL,N'기죽은 마음',N'자신 있고 당당한 마음',N'무섭고 긴장한 마음',N'부끄럽고 창피한 마음',N'2',N'05',N'',N'S'),
	 (326,N'01',N'09',N'다음 문장에 어울리는 흉내내는 말을 찾아보세요.',N'어떤 친구는 여름 햇살처럼 눈부신 옷을 입어요.',N'반짝반짝',N'아장아장',N'술렁술렁',N'쿵쾅쿵쾅',N'1',N'02',N'Y',N'S'),
	 (326,N'01',N'10',N'물웅덩이를 밟으며 신나게 노는 모습을 가장 잘 나타낸 말은 무엇인가요?',NULL,N'살금살금',N'조심조심',N'찔끔찔끔',N'첨벙첨벙',N'4',N'02',N'',N'S'),
	 (326,N'01',N'11',N'배를 타고 다니면서 다른 배에 탄 사람들의 물건을 빼앗는 사람''을 가리키는 낱말을 찾아보세요.',NULL,N'선장',N'해적',N'선원',N'어부',N'2',N'06',N'',N'S'),
	 (326,N'01',N'12',N'‘거추장스럽다’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'가볍고 편하다',N'반짝거린다',N'조용하다',N'불편하고 성가시다',N'4',N'06',N'',N'S'),
	 (327,N'01',N'01',N'민이네 가족이 아침 일찍 향한 곳은 어디인가요?',NULL,N'할아버지 댁',N'고모 댁',N'큰아버지 댁',N'이모 댁',N'1',N'01',N'',N'S');
