	 (327,N'01',N'02',N'윷놀이에서 지는 편이 무엇을 하기로 했나요?',NULL,N'방청소',N'설거지',N'먼지털기',N'장보기',N'2',N'01',N'',N'S'),
	 (327,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 집으로 돌아갈 시간이 되자 할머니 할아버지와 헤어지기 싫었어요. 
(2) 정성스럽게 준비한 음식으로 차례를 올렸어요. 
(3) 할머니와 함께 시장에서 차례 준비를 했어요.',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'1',N'03',N'Y',N'S'),
	 (327,N'01',N'04',N'설날 하루의 흐름으로 가장 알맞은 것은 무엇인가요?',NULL,N'놀이 → 인사 → 차례',N'인사 → 귀가 → 음식 준비',N'차례 → 음식 준비 → 놀이',N'음식 준비 → 차례 → 놀이',N'4',N'03',N'',N'S'),
	 (327,N'01',N'05',N'우리의 명절 설날을 보내는 올바른 자세가 아닌 것을 찾아보세요. ',NULL,N'윷놀이, 연날리기 등 설날의 놀이를 직접 체험 할거야.',N'처음보는 친척들에게는 부끄러우니 인사하지 않을거야.',N'한복을 입고 할머니 할아버지께 예쁘게 세배를 할거야.',N'가족들과 함께 시간을 보낼 거야.',N'2',N'04',N'',N'S'),
	 (327,N'01',N'06',N'이 책을 통해 알 수 있는 설날의 의미로 알맞은 것은 무엇인가요?',NULL,N'쉬기만 하는 날',N'혼자 노는 날',N'가족과 정을 나누는 날',N'물건을 많이 받는 날',N'3',N'04',N'',N'S'),
	 (327,N'01',N'07',N'민후는 어떤 마음이었을까요?',N'민후 눈썹이 하얗게 변해 버렸어요. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (327,N'01',N'12',N'다음 중 ''곡식을 빻아 떡이나 가루를 만드는 곳''을 가리키는 어휘는 무엇인가요?',NULL,N'방청소',N'방앗간',N'곳간',N'외양간',N'2',N'06',N'',N'S'),
	 (328,N'01',N'01',N'세종이 어린 시절 책에 푹 빠지게 된 이유는 무엇인가요?',NULL,N'형제들과 부딪치지 않는 가장 좋은 방법은 궁 안에서 숨죽여 책만 읽는 것이라서',N'아버지가 어린 시절부터 책을 읽으라고 강요해서',N'형들이 놀이에 끼워주지 않았기 때문에',N'똑똑한 왕이 되고싶어서',N'1',N'03',N'',N'S'),
	 (328,N'01',N'02',N'세종대왕이 훈민정음을 만든 이유는 무엇일까요?',NULL,N'백성들이 쉽게 배울 수 있는 글자가 필요해서',N'세종은 한문이 너무 어렵게 느껴지고 배우기 싫었기 때문에',N'새 글자를 만드는 일은 재미있기 때문에',N'우수한 문자를 만들어서 우리 민족의 우월함을 확인하려고',N'1',N'04',N'',N'S'),
	 (328,N'01',N'03',N'정조가 할아버지 영조에게 받은 독서 수업의 내용이 아닌 것은 무엇인가요?',NULL,N'매일 책을 얼마나 읽을지 계획을 세운다.',N'한 번 읽은 책은 다시 읽지 않는다.',N'독서가 끝나면 꼭 자신의 의견을 메모하여 독서 기록을 남긴다.',N'이해가 부족한 부분은 영조가 직접 가르친다.',N'2',N'01',N'',N'S'),
	 (328,N'01',N'04',N'인선이는 다른 자매들과 달리 어떤 성격이었나요?',NULL,N'씩씩하다',N'조신하다',N'어른스럽다',N'느긋하다',N'1',N'01',N'',N'S'),
	 (328,N'01',N'05',N'다음의 상황에서 이이의 마음은 어땠을까요?',N'이이의 볼이 점점 붉어졌습니다. 그제야 이이는 어머니의 말씀을 이해할 수 있었습니다. 그 쉬운 『명심보감』조차 제 것으로 만들지 못한 채 거들먹거렸음을 깨달았기 때문입니다.',N'기쁨',N'안도감',N'부끄러움',N'자부심',N'3',N'02',N'Y',N'S'),
	 (328,N'01',N'06',N' 『홍길동전』의 작가 허균의 누이이자 비운의 천재 시인으로 불리는 사람은 누구인가요?',NULL,N'허난설헌',N'허준',N'허임',N'허각',N'1',N'07',N'',N'S'),
	 (328,N'01',N'07',N'유배를 갔다 돌아온 유희춘은 선조에게 어떤 일을 하고 싶다고 말했나요?',NULL,N'높은 벼슬을 하고 싶다.',N'오류가 있는 책들을 바로잡아 새로 편찬하고 싶다.',N'자신을 유배 보낸 관리들을 벌하고 싶다.',N'유배를 가서 몸이 상했으니 편하게 쉬고싶다.',N'2',N'04',N'',N'S'),
	 (328,N'01',N'08',N' ’낙숫물이 바위를 뚫는다’는 말의 뜻은 무엇일까요?',NULL,N'작은 힘이라도 꾸준히 계속하면 큰일을 이룰 수 있음을 비유적으로 이르는 말',N'자기는 더 큰 흉이 있으면서 도리어 남의 작은 흉을 본다는 말',N'어떠한 행동이 습관이 되면 그 행동을 마음먹지 않은 때에도 하게 된다는 뜻',N'아무 관련 없는 두 일이 우연히 일어났을때, 두 일이 서로 관련 있다고 오해한다는 뜻',N'1',N'02',N'',N'S'),
	 (328,N'01',N'09',N'어머니는 왜 덕무에게 책을 읽지 말라고 꾸지람했나요?',NULL,N'책을 읽으면 눈이 나빠지기 때문에',N'덕무가 책만 읽고 집안일을 돌보지 않아서',N'열심히 책을 읽어도 출신이 미천해서 벼슬길에 나갈 수 없기 때문에',N'책이 너무 비싸 사줄 돈이 없었기 때문에',N'3',N'03',N'',N'S');
