INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (364,N'01',N'05',N'막내가 고양이에게 해 줄 수 있는 말로 가장 알맞은 것을 찾아보세요.',NULL,N'“재치 있는 행동으로 가난한 나를 도와 주어서 너무 고마워.”',N'“장화와 자루를 돌려주지 않다니 약속을 지키지 않는구나.” ',N'“형들을 물리치고 재산을 빼앗는걸 보니 욕심이 지나친 것 같아.”',N'"쉽게 도망치는 걸 보니 넌 겁이 많고 소심하구나."',N'1',N'04',N'',N'S'),
	 (364,N'01',N'06',N'이 이야기에서 가장 중요한 교훈은 무엇일까요?',NULL,N'가진 것이 많아야 행복해요.',N'꾀와 지혜로 어려움을 이길 수 있어요.',N'형제와 싸워야 성공해요.',N'왕을 만나야 부자가 돼요.',N'2',N'04',N'',N'S'),
	 (364,N'01',N'07',N'막내는 어떤 마음이었을까요?',N'“후유, 이제부터 어떻게 살아가지?”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (365,N'01',N'03',N'오 형제가 의형제를 맺게 된 순서로 바르게 나열한 것은 무엇인가요?',N'(1) 길에서 서로의 재주를 알게 되었어요.
(2) 재주 많은 다섯 친구는 의형제를 맺었어요.
(3) 단지손이가 세상 구경을 하러 집을 나섰어요.',N'(3)-(1)-(2)',N'(2)-(1)-(3)',N'(3)-(2)-(1)  ',N'(2)-(3)-(1)',N'1',N'03',N'Y',N'S'),
	 (365,N'01',N'04',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 호랑이를 물리친 오 형제는 다시 세상 구경을 하려고 길을 나섰어요.
(2) 호랑이가 오줌 강에 휩쓸려 떠내려갔어요.
(3) 재주 많은 다섯 친구는 의형제를 맺었어요.',N'(1)-(3)-(2) ',N'(2)-(1)-(3)',N'(3)-(2)-(1)  ',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (365,N'01',N'05',N'오 형제에게 해줄 수 있는 말로 가장 올바른 것을 찾아보세요.',NULL,N'“재주가 뛰어나다고 뽐내는 것은 잘못이라고 생각해.”',N'“친구끼리 힘을 모아 어려움을 이겨낸  모습이 대단해.”',N'“낯선 친구한테 먼저 다가가는 용기를  가지도록 해봐.”',N'"호랑이를 물리친 것은 운이 좋았기 때문이야."',N'2',N'04',N'',N'S'),
	 (365,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 가장 알맞은 것은 무엇인가요?',NULL,N'재주가 많으면 혼자 행동해야 해요.',N'낯선 친구는 믿으면 안 돼요.',N'호랑이는 항상 무서워요.',N'친구와 힘을 합치면 어려움을 이길 수 있어요.',N'4',N'04',N'',N'S'),
	 (365,N'01',N'07',N'두 친구는 어떤 목소리로 자기소개를 했을까요?',N'“난 가장 힘센 단지손이다. 넌 누구냐?”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (366,N'01',N'01',N'오성과 한음의 이름을 바르게 짝지은 것을 고르세요.',N'',N'오성:이항복-한음:이한음',N'오성:이항복-한음:이덕형',N'오성:이덕형-한음:이항복',N'오성: 이덕형 - 한음: 이한음',N'2',N'01',N'',N'S'),
	 (366,N'01',N'02',N'오성과 한음이 처음 만난 장소는 어디인가요?',N'',N'서당',N'사당',N'궁궐',N'장터',N'1',N'01',N'',N'S'),
	 (366,N'01',N'03',N'오성이 권철대감 댁에 찾아간 까닭은 무엇인가요?',N'',N'권대감님의 집이 얼마나 큰지 보려고',N'하인들을 혼내 주려고',N'감나무의 주인이 누구인지 물으려고',N'권대감에게 장난을 치려고',N'3',N'03',N'',N'S'),
	 (366,N'01',N'04',N'괄호 안의 자리에 쓸 수 있는 것은 무엇인가요?',N'"(무례한) 행동을 너그럽게 용서하여 주십시오."',N'버릇없는',N'정중한',N'정확한',N'친절한',N'1',N'02',N'Y',N'S'),
	 (366,N'01',N'05',N'임진왜란때 행주산성에서 왜군을 크게 무찌른 권대감의 아들은 누구인가요?',N'',N'이순신 장군',N'강감찬 장군',N'김유신 장군',N'권율 장군',N'4',N'07',N'',N'S'),
	 (366,N'01',N'06',N'신하가 죄를 지었을 때 내리는 벌로 관직을 빼앗기고 본래의  집을 떠나 사는 것을 무엇이라 하나요?',N'',N'귀향',N'귀농 ',N'추방',N'귀양',N'4',N'06',N'',N'S'),
	 (366,N'01',N'07',N'한음이 임금님 앞에서 닭소리를 낸 까닭은 무엇인가요?',N'마음을 가다듬은 한음이 갑지기 큰 소리로 외쳤습니다."꼬꼬댁, 꼬꼬꼬!"',N'달걀을 들고 오지 못하였으나 달걀보다 그 어미가 낫다는 재치를 보이려고',N'닭 우는  소리를 잘 내는 것을 보여주려고',N'임금님이 닭 소리를 내보라고 하여서',N'궁중 놀이의 벌칙으로 소리를 내게 되어',N'1',N'04',N'Y',N'S'),
	 (366,N'01',N'08',N'1592년에 일어난 전쟁의 이름은 무엇인가요?',N'',N'병자호란',N'임진왜란',N'6.25전쟁',N'청일전쟁',N'2',N'07',N'',N'S'),
	 (366,N'01',N'09',N'궁 안에서 신하들의 다툼이 일어나고 수 많은 사람들이 처형 당한 것은 무엇 때문인가요?',N'',N'좋은 자리를 차지하고 자신의 힘을 과시하려는 잘못된 신하들 때문에',N'서로 왕을 하려고 신하들이 다투었기 때문에',N'전쟁에서 죽지 않으려고 도망다녔기 때문에 ',N'임금님의 명령을 거부했기 때문에',N'1',N'04',N'',N'S'),
	 (366,N'01',N'10',N'다음 대화를 읽고 책을 잘 이해한 사람을 찾아보세요.',N'정윤: 얘들아, 오늘의 인물은 오성과 한음이야. 고려시대 귀족계층이지
