	 (368,N'01',N'09',N'박서방의 저승 곳간에는 찬바람만 휭휭 돌았다. ''휭휭''과 바꾸어 쓸 수 있는 표현은 무엇인가요?',N'',N'쉬쉬',N'쌩쌩',N'살랑살랑',N'솔솔',N'2',N'02',N'N',N'S'),
	 (368,N'01',N'10',N'박서방이 빌린 돈은 얼마인가요?',N'',N'백냥',N'이백냥',N'삼백냥',N'사백냥',N'3',N'04',N'N',N'S'),
	 (368,N'01',N'11',N'박서방이 노자를 구한 방법은 무엇인가요?',N'',N'저승사자에게 빌린다',N'이서방네 곳간에서 빌린다',N'일을 해서 번다',N'지나다니는 사람에게 구걸한다',N'2',N'01',N'N',N'S'),
	 (368,N'01',N'12',N'저승에서 자신의 곳간을 본 박서방은 후회를 하며 다음과 같은 말을 한다. 알맞은 것은 무엇인가요?',N'이럴 줄 알았으면 OO 좀 하고 살걸.',N'적선(積善)',N'적금(積金)',N'적수(敵手)',N'예금(預金)',N'1',N'06',N'Y',N'S'),
	 (368,N'01',N'13',N'박서방의 곳간을 본 저승사자가 한 말로 다음의 OO에 들어갈 단어는 무엇인가요?',N'쳇, 자네는 이승에서 어지간히 OO했던 모양이로군.',N'인간적(人間的)',N'인기(嫉妬)',N'인색(吝嗇)',N'궁색(窮塞)',N'3',N'03',N'Y',N'S'),
	 (368,N'01',N'14',N'이승에 온 박서방의 행동으로 옳지 않은 것은 무엇인가요?',N'',N'남을 잘 도와준다',N'이서방에게 돈을 갚는다',N'동네방네 저승의 일을 소문낸다',N'부지런히 일하며 생활한다',N'3',N'01',N'N',N'S'),
	 (368,N'01',N'15',N'박서방이 자신의 행동을 후회하고 이승으로 가서 착하게 잘 지내는 것을 잘 나타낸 사자성어는 무엇인가요?',N'',N'후회막급(後悔莫及)',N'후회막심(後悔莫甚)',N'개과천선(改過遷善)',N'절치부심(切齒腐心)',N'3',N'06',N'N',N'S'),
	 (369,N'01',N'01',N'오늘날 전세계 인구의 절반이 사는 곳은 어디인가요?',NULL,N'농촌',N'어촌',N'도시',N'산촌',N'3',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (369,N'01',N'02',N'수돗물은 어디를 거치면서 오염물이 제거되나요?',NULL,N'양수장',N'정수센터',N'하수도',N'저수지',N'2',N'01',N'',N'S'),
	 (369,N'01',N'03',N'도시 인구가 늘어날 때 일어나는 일을 순서대로 고르세요.',N'(1) 도시에 사람이 많아져요.
(2) 도시 근교에 새 지역이 생겨요.
(3) 주택(집)이 부족해져요.',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'3',N'03',N'Y',N'S'),
	 (369,N'01',N'04',N'전기가 우리 집에 오기까지의 과정을 순서대로 나열한 것을 찾으세요.',N'(1) 전기가 발전소에서 만들어져요.
(2) 고압선과 중압선을 거쳐 전압이 조절돼요.
(3) 케이블을 통해 전기가 우리 집까지 오게 돼요.',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'1',N'03',N'Y',N'S'),
	 (369,N'01',N'05',N'가스나 석탄 같은 화석연료를 많이 사용하면 어떤 문제가 생길까요?',NULL,N'공기가 더 깨끗해져요.',N'대기 오염이 생겨요.',N'물이 더 많아져요.',N'숲이 늘어나요.',N'2',N'04',N'',N'S'),
	 (369,N'01',N'06',N'지구 환경을 위해 우리가 할 수 있는 일은 무엇이 있을까요?',NULL,N'모두 도시를 떠나 농촌으로 가요.',N'평소에 물과 전기를 아껴서 사용해요.',N'모든 쓰레기를 태워 버려요.',N'쓰레기를 아무 데나 버려요.',N'2',N'04',N'',N'S'),
	 (369,N'01',N'07',N'만약 지구에게 마음이 있다면, 계속되는 환경 오염에 대해서 어떤 감정을 느낄까요?',NULL,N'기쁘고 반가워요.',N'슬프고 힘들어요.',N'외롭고 부끄러워요.',N'신나고 설레요.',N'2',N'05',N'',N'S'),
	 (369,N'01',N'08',N'맑은 공기와 깨끗한 물을 지키면 우리의 마음은 어떨까요?',NULL,N'불안해요.',N'화가 나요.',N'부끄러워요.',N'편안하고 기뻐요.',N'4',N'05',N'',N'S'),
	 (369,N'01',N'09',N'다음 문장에 어울리는 표현을 찾아보세요.',N'자전거 전용 도로에 자전거가 지나다녀요. ',N'으르렁',N'부르릉',N'따르릉',N'와르르',N'3',N'02',N'Y',N'S'),
	 (369,N'01',N'10',N'전기가 켜질 때의 모습을 잘 나타낸 말은 무엇인가요?',NULL,N'깜깜',N'반짝',N'철벅',N'덜컹',N'2',N'02',N'',N'S'),
	 (369,N'01',N'11',N'사람이 살기 위해 꼭 필요한 물, 전기, 공기 같은 것을 무엇이라고 하나요?',NULL,N'장난감',N'쓰레기',N'자원',N'상품',N'3',N'06',N'',N'S');
