INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (372,N'01',N'06',N'훗날 약용이에게 큰 영향을 준 것은 누구의 책이었을까요?',N'',N'유형원',N'장영실',N'정조',N'이익',N'4',N'01',N'',N'S'),
	 (372,N'01',N'07',N'정약용이 ‘거중기’를 만든 이유는 무엇인가요?',N'',N'많은 사람들이 다리를 쉽게 건너게 하기 위해서',N'힘을 덜 들이고 크고 무거운 돌을 옮기기 위해서',N'많은 사람들이 쉽게 농사를 짓게 하기 위해서',N'군사 훈련을 돕기 위해서',N'2',N'03',N'',N'S'),
	 (372,N'01',N'08',N'정약용은 무엇으로 일하는 동안 지방 관리가 어떤 마음가짐을 가져야 하는지에 대해 깊이 생각했나요?',N'',N'암행어사',N'병조판서',N'춘추관',N'사헌부 감찰',N'1',N'07',N'',N'S'),
	 (372,N'01',N'09',N'정약용이 스스로 벼슬에서 물러나 고향 마재로 돌아간 이유는 무엇인가요?',N'',N'건강이 나빠져서',N'고향에 있는 가족들이 보고 싶어서',N'자신이 벼슬을 계속하는 것이 오히려 정조를 힘들게 하는 일이라고 생각해서',N'새로운 학문을 연구하기 위해서',N'3',N'04',N'',N'S'),
	 (372,N'01',N'10',N'다음에 나오는 ‘부패’의 뜻은 무엇일까요?',N'너 같은 사람이 많아야 한다. 억울한 일을 당한 백성은 관가에 그 잘못을 따지는 것이 옳다. 그렇지 않아서 관리들이 ‘부패’하는 것이다. 너는 무죄다.',N'다양한 음식을 두고 먹을 만큼 덜어 먹는 식사 방법',N'단백질이나 지방 따위가 아주 작은 생물에 의해 분해되는 과정',N'정치, 사상, 의식 따위가 올바른 길에서 벗어나 잘못된 길로 빠지는 일',N'사회적 질서가 무너지는 일',N'3',N'06',N'Y',N'S'),
	 (372,N'01',N'11',N'다음이 설명하는 단어는 무엇인가요?',N'결국 정약용은 경상도 장기로 (      )을 떠나게 되었어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (373,N'01',N'04',N'다음 ( ) 안에 들어갈 말을 바르게 짝지은 것은 무엇인가요?',N'아무리 복 많은 사람이나 인품이 높은 선비라도 ( )과 ( )을 갖추지 않으면 집안을 다스릴 수 없다.',N'효(孝), 행(行)',N'예(禮), 의(義)',N'충(忠), 효(孝)',N'근(勤), 검(儉)',N'4',N'06',N'Y',N'S'),
	 (373,N'01',N'05',N'다음은 정약용이 한 말입니다. 그 말에 나타난 가르침은 무엇인가요?',N'시골에 살면서 과수원이나 채소밭을 가꾸지 않는다면 천하에 쓸모없는 사람이 되고 만다.',N'자신이 먹을 것은 자신이 농사지어야 한다',N'부지런해야 한다',N'남을 돕고 살아야 한다',N'농사의 중요성을 알고 깨달아야한다.',N'2',N'04',N'Y',N'S'),
	 (373,N'01',N'06',N'공부하는 데 있어 가장 중요한 자세가 아닌 것은 무엇인가요?',N'',N'몸에 힘을 푸는 것',N'얼굴 표정을 바로 하는 것',N'고운 말을 쓰는 것',N'지식을 쌓기 전에 마음가짐을 바르게 하는 것',N'1',N'01',N'N',N'S'),
	 (373,N'01',N'07',N'수원 화성을 지을 때 도르래의 원리를 이용해 만든 재래식 기계의 이름은 무엇인가요?',N'',N'자격루',N'측우기',N'거중기',N'도르래',N'3',N'01',N'N',N'S'),
	 (373,N'01',N'08',N'다음 ( ) 안에 들어갈 수 있는 의태어가 아닌 것은 무엇인가요?',N'눈물까지 흘리며 괴로워하다가도 다음날 일이 풀리면 금세 좋아서 ( )거린다.',N'배시시',N'헐레벌떡',N'싱글벙글',N'방긋방긋',N'2',N'02',N'Y',N'S'),
	 (373,N'01',N'09',N'정약용의 편지에서 신중하게 생각해 말을 해야 한다는 뜻의 속담은 무엇인가요?',N'',N'가는 말이 고와야 오는 말이 곱다',N'발 없는 말이 천리간다',N'말 한마디가 천냥 빚을 갚는다',N'아는 길도 물어 가라',N'3',N'06',N'N',N'S'),
	 (373,N'01',N'10',N'다음 ( ) 안에 들어갈 것 말은 무엇인가요?',N'공부에는 반드시 기초가 되는 힘이 기둥처럼 세워져 있어야 한다.
( )와 ( ), 즉 부모에게 효도하고 형제 간에 서로 사랑하는 마음이다',N'모(母), 조(祖)',N'효(孝), 제(弟)',N'제(弟), 우(友)',N'형(兄), 우(友)',N'2',N'06',N'Y',N'S'),
	 (373,N'01',N'11',N'유배 생활의 경험들이 학문과 사상에 큰 영향을 미쳤다. 이것을 밑거름으로 편찬한 책 제목은 무엇인가?',N'',N'목민심서',N'훈민정음',N'사서삼경',N'삼국사기',N'1',N'01',N'N',N'S'),
	 (373,N'01',N'12',N'선비들은 사군자를 귀하게 여겼는데 사군자에 해당하지 않는 것은 무엇인가요?',N'',N'매화',N'무궁화',N'국화',N'대나무',N'2',N'07',N'N',N'S'),
	 (373,N'01',N'13',N'사람의 인상은 ( )과 ( )으로 변하고 만들어진다''에서 괄호 안에 들어갈 단어로 적절한 것은 무엇인가요?',N'',N'양보, 미덕',N'배움, 버릇',N'배움, 질서',N'양보, 질서',N'2',N'03',N'N',N'S');
