	 (381,N'01',N'04',N'다음 중 이야기의 내용과 맞는 것을 고르세요.',NULL,N'아이는 아무 생각 없이 호랑이를 만났어요.',N'아이는 호랑이를 잡기 위해 미리 준비를 했어요.',N'아이는 호랑이를 도와줬어요.',N'아이는 호랑이에게 도움을 받았어요.',N'2',N'03',N'',N'S'),
	 (381,N'01',N'05',N'그 후 아이는 어떻게 지냈을지 가장 잘 추측한 친구는  누구인가요?',NULL,N'서영: 호랑이 가죽을 팔아서 부자가 되었어요.',N'시후: 수백 마리의 호랑이들한테 혼이 났어요.',N'가윤: 게으름을 피우며 가난하게 살았어요.',N'정우: 엄마에게 혼이 나고 집을 나왔어요.',N'1',N'04',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (381,N'01',N'06',N'아이가 호랑이를 잡을 수 있었던 이유는 무엇일까요?',NULL,N'힘이 아주 세서',N'호랑이가 착해서',N'지혜롭게 생각하고 준비했기 때문에',N'운이 좋아서',N'3',N'04',N'',N'S'),
	 (381,N'01',N'07',N'아이에게 어떤 말을 해 줄 수 있을까요?',NULL,N'“아픈 어머니를 위해 호랑이를 잡아오다 니 정말 효심이 가득하구나.”',N'“게으른 줄만 알았는데 지혜로운 생각을  가지고 있었다니 놀라워.”',N'“어려운 사람을 보면 지나치지 않고 도와 주는 자세를 본받아야겠어.”',N'"호랑이를 때리는 것은 나쁜 행동이야."',N'2',N'05',N'',N'S'),
	 (381,N'01',N'08',N'호랑이들이 줄줄이 꿰였을 때 아이의 마음은 어땠을까요?',NULL,N'무섭고 슬펐어요.',N'신기하고 뿌듯했어요.',N'화가 나 있었어요.',N'부끄러웠어요.',N'2',N'05',N'',N'S'),
	 (381,N'01',N'09',N'빈칸에 어울리는 흉내 내는 말을 찾아 보세요.',N'가을이 되자 굵은 참깨가 (       ) 열렸어. ',N' 주룩주룩 ',N'다닥다닥   ',N'새근새근',N'살금살금',N'2',N'02',N'Y',N'S'),
	 (381,N'01',N'10',N'성질 급한 호랑이가 강아지를 한 입에 삼키는 모습을 나타낸 말로 알맞은 것은 무엇인가요?',NULL,N'꿀꺽',N'데굴',N'삐죽',N'찌릿',N'1',N'02',N'',N'S'),
	 (381,N'01',N'11',N'‘해야 할 일을 하지 않고 미루거나 놀기만 하는 모습’을 뜻하는 말은 무엇인가요?',NULL,N'부지런하다',N'똑똑하다',N'용감하다',N'게으르다',N'4',N'06',N'',N'S'),
	 (381,N'01',N'12',N'여러 개가 한 줄로 이어진 모습을 뜻하는 말은 무엇인가요?',NULL,N'듬성듬성',N'줄줄이',N'따로따로',N'천천히',N'2',N'06',N'',N'S'),
	 (382,N'01',N'01',N'학교 가는 길에 만난 사자는 존에게 어떤 짓을 했나요?',NULL,N'장갑을 물었어요.',N'바지를 물어뜯었어요.',N'책가방을 물었어요.',N'모자를 빼앗았어요.',N'2',N'01',N'',N'S'),
	 (382,N'01',N'02',N'다음 날 학교를 가던 존은 다리 위에서 어떤 일을 겪었나요?',NULL,N'털북숭이 고릴라가 존을 덮쳤어요.',N'파도가 밀려와 존을 덮쳤어요.',N'양떼가 몰려와 존을 덮쳤어요.',N'강아지가 존을 따라왔어요.',N'2',N'01',N'',N'S'),
	 (382,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 천장에 매달린 선생님이 도와달라고 했어요.
(2) 하수구에서 나온 악어가 책가방을 물었어요.
(3) 교실 안에 갇혀서 반성문을 500번 썼어요.',N'(2)-(3)-(1)',N'(3)-(1)-(2)   ',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'1',N'03',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (382,N'01',N'04',N'존이 지각을 하게 된 까닭으로 알맞은 것은 무엇인가요?',NULL,N'아침에 늦잠을 자서',N'학교가 너무 멀어서',N'길에서 무서운 일을 계속 겪어서',N'준비물을 못 챙겨서',N'3',N'03',N'',N'S'),
	 (382,N'01',N'05',N'존은 왜 다음과 같이 말했을까요?',N'“이 동네 천장에 커다란 털북숭이 고릴라 따위는 살지 않아요, 선생님.”',N'고릴라가 무서워 모른 척하고 싶어서',N'평소에 자신의 말을 믿어주지 않았던 선생님께 복수하려고',N'선생님을 도와주기에 키가 작아서',N'자기 말을 아무도 믿지 않는다는 것을 알았기 때문에',N'2',N'04',N'Y',N'S'),
	 (382,N'01',N'06',N'존의 이야기를 통해 우리가 배울 수 있는 점은 무엇인가요?',NULL,N'어른의 말은 항상 옳아요.',N'믿기 어려운 말은 무조건 거짓말이에요.',N'무조건 의심하지 말고 대화를 하며 이해해야 해요.',N'무서운 일은 말하지 않는 게 좋아요.',N'3',N'04',N'',N'S'),
	 (382,N'01',N'07',N'선생님은 어떤 목소리로 말했을까요?',N'“내가 별소리를 다 듣겠다. 말도 안 되는 소리! 갇혀 봐야 정신을 차리겠군!”',N'부드럽게 속삭이는 목소리 ',N'힘없이 슬퍼하는 목소리',N'의심하며 화난 목소리',N'기쁘고 즐거운 목소리',N'3',N'05',N'Y',N'S'),
	 (382,N'01',N'08',N'선생님이 존의 말을 믿지 않았을 때 존의 마음은 어땠을까요?',NULL,N'기쁜 마음',N'편안한 마음',N'자랑스러운 마음',N'억울한 마음',N'4',N'05',N'',N'S'),
	 (382,N'01',N'09',N'다음 문장에 어울리는 흉내 내는 말을 찾아보세요.',N'존 패트릭 노먼 맥헤너시는 서둘러 학교로 달려갔습니다.',N'엉금엉금',N'옹기종기',N'허겁지겁',N'사뿐사뿐',N'3',N'02',N'Y',N'S'),
	 (382,N'01',N'10',N'빈칸에 어울리는 표현을 찾아 보세요.',N'학교 가는 길에 파도를 만난 존은 (    ) 젖었어요.',N'흠뻑',N'슬쩍',N'보글',N'살랑',N'1',N'02',N'Y',N'S'),
	 (382,N'01',N'11',N'사람이 떨어지는 것을 막기 위해 세워 놓은 것''을 무엇이라고 하나요?',NULL,N'계단 ',N'난간',N'비석',N'의자',N'2',N'06',N'',N'S'),
	 (382,N'01',N'12',N'‘정해진 시간보다 늦게 도착하는 것’을 무엇이라고 하나요?',NULL,N'준비',N'약속',N'지각',N'대기',N'3',N'06',N'',N'S'),
	 (383,N'01',N'01',N'전 세계에서 인구가 가장 많은 나라는 어디인가요?',NULL,N'미국',N'인도',N'중국',N'한국',N'3',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (383,N'01',N'02',N'지구에는 대략 6,000개의 언어가 있는데, 이 중 사람들의 반 이상은 몇 개의 언어로 이야기할까요?',NULL,N'21개',N'8개',N'5개',N'3개',N'2',N'07',N'',N'S'),
	 (383,N'01',N'03',N'다음 중 전 세계의 인구에 대한 설명으로 옳은 것은 무엇인가요?',NULL,N'인구의 절반은 인구가 많은 여덟 개의 나라에서 왔다',N'전 세계의 인구는 70억이 되지 않는다',N'많은 나라의 인구가 점점 줄어들고 있다',N'많은 나라의 인구가 점점 늘고있다.',N'3',N'04',N'',N'S'),
	 (383,N'01',N'04',N'가장 많은 사람들이 믿는 종교는 무엇인가요?',NULL,N'기독교',N'이슬람교',N'불교',N'천주교',N'1',N'07',N'',N'S'),
	 (383,N'01',N'05',N'바람이 보드랍게 부는 모양으로 다음 빈칸에 들어갈 알맞은 말은 무엇인가요?',N'맛있는 음식 냄새가 (       ) 풍깁니다.',N'꽥꽥',N'흐물흐물',N'솔솔',N'살랑살랑',N'3',N'02',N'Y',N'S'),
	 (383,N'01',N'06',N'다음 중 지구의 환경에 대한 설명으로 옳지 않은 것은 무엇인가요?',NULL,N'깨끗한 물을 얻기 위해 애쓰는 건 대부분 여자가 한다',N'누구나 상수도와 하수도 처리가 되어 있는 곳에서 산다',N'공해로 더러워진 공기를 마시며 살아가는 사람들도 있다',N'많은 사람들이 충분한 음식을 먹지 못한다',N'2',N'01',N'',N'S'),
	 (383,N'01',N'07',N'지구에 있는 사람들이 모두 돈을 똑같이 나누어 가지면 한 사람이 1년에 얼마씩 가질 수 있나요?',NULL,N'13,000,000원',N'14,000,000원',N'15,000,000원',N'16,000,000원',N'2',N'03',N'',N'S'),
	 (383,N'01',N'08',N'지구에서 1년 동안 생활하는 데 필요한 돈을 얼마인가요?',NULL,N'5,500,000원',N'6,600,000원',N'7,700,000원',N'8,800,000원',N'1',N'03',N'',N'S'),
	 (383,N'01',N'09',N'인구는 1년에 평균 몇 명이 늘고 있나요?',NULL,N'5.1명',N'1.15명',N'2.35명',N'3명',N'2',N'02',N'',N'S'),
	 (383,N'01',N'10',N'물체가 나아가거나 일이 진행되는 빠르기를 무엇이라고 하나요?',NULL,N'박자',N'지구력',N'속도',N'진척',N'3',N'06',N'',N'S'),
	 (383,N'01',N'11',N'은혜와 덕택을 아울러 이르는 말을 혜택이라고 합니다. 혜택과 비슷한 말이 아닌 것은 무엇인가요?',NULL,N'주택',N'덕분',N'은의',N'덕혜',N'1',N'06',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (383,N'01',N'12',N'이 책을 많은 사람들이 읽어야 하는 이유로 알맞지 않은 것은 무엇인가요?',NULL,N'나보다 어려운 상황의 사람들을 생각하는 마음을 가지게 하려고',N'내가 얼마나 잘 사는지 확인하기 위해서',N'절약과 나눔을 실천하기 위해서',N'지구를 지키는 마음을 키우기 위해서',N'2',N'04',N'',N'S'),
	 (384,N'01',N'01',N'한창 뛰놀며 공부해야 하는 어린이가 공장에서 바느질하고 있는 이유는 무엇일까요?',N'',N'기업의 이윤때문에',N'나라에서 일을 시키기 때문에',N'부모님의 욕심 때문에',N'놀기만 하면 안되기 때문에',N'1',N'04',N'N',N'S'),
	 (384,N'01',N'02',N'다음 중 올바른 말을 하는 사람은 누구인가요?',N'다예: 다른 나라의 어린이들이 불쌍해. 우리 힘을 합쳐서 초콜릿을 사먹지 말자.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (384,N'01',N'10',N'공정무역은 왜 ''얼굴 있는 거래''라고 불릴까요?',N'',N'중개상인을 보고 거래하기 때문에',N'아는 사람에게 물건을 구입하면 그 사람의 처지를 알고 배려할 수 있기 때문에',N'로고에 웃는 얼굴이 그려져 있어서',N'얼굴이 없으면 거래를 할 수 없어서',N'2',N'02',N'N',N'S'),
	 (384,N'01',N'11',N'물체 따위가 속까지 환히 비치는 성질은 무엇인가요?',N'',N'투자성(投資性)',N'투명성(透明性)',N'여과성(濾過性)',N'공정성(公正性)',N'2',N'06',N'N',N'S'),
	 (384,N'01',N'12',N'높이어 귀중하게 대하는 것은 무엇인가요?',N'',N'미천(微賤)',N'고산(高山)',N'존중(尊重)',N'자비(慈悲)',N'3',N'06',N'N',N'S'),
	 (384,N'01',N'13',N'땅을 갈아서 농사를 짓는 것은 무엇인가요?',N'',N'농민(農民)',N'경지(耕地)',N'경작(耕作)',N'어업(漁業)',N'3',N'06',N'N',N'S'),
	 (384,N'01',N'14',N'어떤 일을 행하거나 타인에 대하여 당연히 요구할 수 있는 힘이나 자격은 무엇인가요?',N'',N'권세(權勢) ',N'권리(權利)',N'권한(權限)',N'권려(勸勵_',N'2',N'06',N'N',N'S'),
	 (384,N'01',N'15',N'기업이 벌어들인 전체 수입에서 그 돈을 벌기 위해 쓴 모든 비용을 제하고 남은 돈은 무엇인가요?',N'',N'임금(賃金)',N'이윤(利潤)',N'세금(稅金)',N'비용(費用)',N'2',N'07',N'N',N'S'),
	 (385,N'01',N'01',N'바람에 단단하게 뭉쳐진 눈덩이를 길쭉하고 네모나게 자른 뒤, 한 층 한 층 둥글게 쌓아서 돔 모양으로 지은 집을 무엇이라고 부르나요?',N'',N'수상 가옥',N'움집',N'이글루',N'기와집',N'3',N'01',N'N',N'S'),
	 (385,N'01',N'02',N'통나무를 ’우물 정(井)‘ 자 모양으로 쌓아 올려 벽을 만든 뒤, 그 위에 지붕을 얹은 집을 무엇이라고 하냐요?',N'',N'초가집',N'기와집',N'투막집',N'움집',N'1',N'01',N'N',N'S'),
	 (385,N'01',N'03',N'’캇쇼즈쿠리‘의 지붕 경사가 가파른 이유는 무엇일까요?',N'',N'많은 양의 눈이 지붕 위에 쌓이지 않고 잘 흘러내릴 수 있게 하기 위해서',N'경사가 가파른 지붕이 아름답기 때문에',N'바람이 많이 불어서',N'지붕을 경사로 만들어서 미끄럼틀을 타면 재미있기때문에',N'1',N'04',N'N',N'S'),
	 (385,N'01',N'04',N'열대 기후의 고상 가옥은 무엇을 막기 위해 지은 집인가요?',N'',N'열기와 습기가 땅에서 올라오는 것을 막기 위해',N'심한 바람을 막기 위해서',N'건조한 날씨를 피하기 위해서',N'비가 많이 오면 집이 물에 잠기는 것을 막기 위해서',N'1',N'02',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (385,N'01',N'05',N'다음 중 잘못된 이야기를 하는 사람은 누구인가요?',N'',N'민규: 석굴암의 원래 이름은 석불사구나.',N'재현: 일제 강점기가 아니었으면 유리 보호막이 없는 석굴암을 볼 수 있었겠다.',N'현지: 우와. 석굴암은 자연적으로 만들어졌구나. 어쩐지 자동으로 습기 조절도 된다니 신기했어.',N'수지:천장석이 떨어지지 않도록 정교하게 얹혀있어. 삼국시대에 이런 돌건축 기술이 있었다니 신기해',N'3',N'03',N'N',N'S'),
	 (385,N'01',N'06',N'몽골인들의 이동식 천막집을 무엇이라고 부르나요?',N'',N'게르',N'카파도키아',N'갈대집',N'이글루',N'1',N'07',N'N',N'S'),
	 (385,N'01',N'07',N'중세 유럽에서 성당을 지을 때, 하늘을 찌를 듯 높고 길게 세우려고 했던 이유는 무엇인가요?',N'',N'조금이라도 더 신에게 가까이 다가갈 수 있다고 믿었기 때문에',N'높고 길게 세우는 방식이 짓기 편해서',N'놉고 긴 첨탑은 아름답기 때문에',N'새처럼 높은 하늘에 닿고싶다는 소망이 있었기 때문에',N'1',N'03',N'N',N'S'),
	 (385,N'01',N'08',N'수리야바르만이 앙코르와트를 지은 이유는 무엇인가요?',N'',N'아들에게 물려주기 위해서',N'죽은 왕비의 묘로 사용하기 위해서',N'훌륭한 건축물을 지어 백성들 마음을 사로잡으려고',N'왕국의 위엄을 다른 나라에게 보여주려고',N'3',N'04',N'N',N'S'),
