INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (387,N'01',N'01',N'동식물들이 위기에 처한 가장 큰 원인은 무엇인가요?',N'',N'동식물들에 대한 관심도가 떨어져서',N'사람들의 무분별한 자연 개발과 사냥때문에 ',N'먹이가 점점 줄어들어서',N'지구 온난화 때문에 기후변화가 심해져서',N'2',N'01',N'N',N'S'),
	 (387,N'01',N'02',N'지구온난화의 영향으로 남극과 북극의 어떤 변화가 일어났나요?',N'',N'빙하가 녹으면서 그 곳에 사는 생물들이 피해를 입고있다.',N'따뜻한 기후로 환경이 변했다.',N'외래종들이 많이 들어오게 됐다.',N'기온의 상승으로 이전에는 볼 수 없었던 다양한 생명체를 볼 수 있다.',N'1',N'01',N'N',N'S'),
	 (387,N'01',N'03',N'외래종들이 문제가 되는 이유는 무엇인가요?',N'',N'오염물질을 배출하기 때문에',N'생태계를 교란시키기 때문에',N'사람들을 잡아먹기 때문에',N'토종생물의 먹잇감이 되기 때문에',N'2',N'04',N'N',N'S'),
	 (387,N'01',N'04',N'탄광에서 일하는 광부들이 카나리아를 이용했던 이유는 무엇인가요?',N'',N'카나리아를 이용해 편지를 주고 받으려고',N'카나리아가 박쥐를 잡아먹어서',N'카나리아가 노래를 부르는 것을 듣고 유독가스의 정도를 확인하려고',N'카나리아는 광부와 유대관계가 깊기 때문에',N'3',N'04',N'N',N'S'),
	 (387,N'01',N'05',N'아마존 열대 우림은 지구의 ''이것''이라고 불립니다. ''이것''은 무엇인가요?',N'',N'뇌',N'근육',N'허파',N'심장',N'3',N'02',N'N',N'S'),
	 (387,N'01',N'06',N'우리나라의 비무장지대(DMZ)를 부르는 명칭은 무엇인가요?',N'',N'한반도의 철새 서식지',N'한반도의 지뢰밭',N'한반도의 사냥터',N'한반도의 생태 천국',N'4',N'02',N'N',N'S'),
	 (387,N'01',N'07',N'멸종 위기에 처한 동식물이 불법으로 거래되거나 과도하게 수출입 되는 것을 막기 위해 세계 각국이 함께 만든 협약의 이름은 무엇인가요?',N'',N'사이테스(CITES)',N'유네스코(UNESCO)',N'레드 리스트(Red Rist)',N'세계자연보전연맹(IUCN)',N'1',N'07',N'N',N'S'),
	 (387,N'01',N'08',N'특정한 환경 조건을 나타내는 생물을 무엇이라고 하나요?',N'',N'핵심종',N'서식종',N'외래종',N'지표종',N'4',N'07',N'N',N'S'),
	 (387,N'01',N'09',N'모든 생물들이 생태계의 주인공인 이유는 무엇인가요?',N'',N'생물은 혼자서 살아갈 수 없고 다른 생물이나 자연환경에 의존하여 살아가기 때문에',N'모든 생물들은 서로가 서로를 잡아먹기 때문에',N'인간보다 더 중요한 생물들도 많기 때문에',N'주인공이 많으면 많을수록 생태계가 건강해지기 때문에',N'1',N'03',N'N',N'S'),
	 (387,N'01',N'10',N'멸종 위기에 처한 동식물들을 보호하는 가장 좋은 방법은 무엇인가요?',N'',N'번식 포획 프로젝트를 적극적으로 활용한다.',N'동식물들이 잘 살 수 있도록 인간이 무조건 도움을 줘야한다.',N'그들이 사는 생태계를 온전히 보존한다',N'동식물이 잘 자랄 수 있는 인공환경을 조성하여 번식을 돕는다',N'3',N'03',N'N',N'S');
