INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (394,N'01',N'08',N'다음 예시를 읽고 책에 나오는 노래 가사에 대해 적절하지 않은 것을 고르세요.',N'선생님: 노래 가사는 소설의 주제를 부각시켜주고, 독자로 하여금 흥미를 유발시켜줍니다. 또 영화화 되었을 때 유용하게 쓰입니다.',N'채영: 내가 영화 감독이라면 노래 가사를 삭제하고 사용하지 않았을거야.',N'나연: 노래를 통해서 작가가 전하고자 하는 바가 더 명확해지는 것 같아!',N'다현: 노래가 나오니 소설이 재밌었어.',N'라미: 노래가 나오니 긴장되던 마음이 이완되고 흥이 돋았어',N'1',N'07',N'Y',N'S'),
	 (394,N'01',N'09',N'다음 예시의 ''장미처럼''에서 사용된 비유법은 무엇인가요?',N'웡카: 누가 장미처럼 아리따운 분을 피합니까.',N'은유: 원관념과 보조관념을 간접적으로 연결하여 표현',N'직유: 원관념과 보조관념을 직접 연결하여 표현',N'의인: 사물이나 관념에 인격을 부여하는 표현',N'상징: 추상적인 개념이나 사물을 구체적인 사물로 나타냄',N'2',N'02',N'Y',N'S'),
	 (394,N'01',N'10',N'마이너스랜드에 가기 위해 웡카와 찰리가 한 것은 무엇인가요?',N'',N'웡카 바이트를 많이 먹었다.',N'강철 엘리베이터를 탔다.',N'바이타 웡크를 먹는다.',N'유리 엘리베이터를 탔다.',N'4',N'03',N'N',N'S'),
	 (394,N'01',N'11',N'윙카 바이트를 욕심 내서 먹다가 아기가 되는 상황에 어울리는 사자성어는 무엇인가요?',N'',N'과유불급(過猶不及)',N'일장춘몽(一場春夢)',N'조삼모사(朝三暮四)',N'진퇴양난(進退兩難)',N'1',N'06',N'N',N'S'),
	 (394,N'01',N'12',N'다음 예시의 ''침입''과 바꿔쓸 수 없는 것은 무엇인가요?',N'" 멈춰라! 너희는 지금 우리 영토에 침입했다."',N'침범(侵犯)',N'난입(亂入)',N'침전(沈澱)',N'침략(侵略)',N'3',N'04',N'Y',N'S'),
	 (394,N'01',N'13',N'"아기를 대신 길러주는 사람"을 뜻하는 단어는 무엇인가요?',N'',N'주모',N'장모',N'유모',N'수모',N'3',N'06',N'N',N'S'),
	 (394,N'01',N'14',N'왕꿈틀이로부터 가까스로 벗어나는 상황에 어울리는 사자성어는 무엇인가요?',N'',N'십시일반(十匙一飯)',N'구사일생(九死一生)',N'토사구팽(兎死狗烹)',N'전전긍긍(戰戰兢兢)',N'2',N'06',N'N',N'S'),
	 (394,N'01',N'15',N'우물쭈물과 바꾸어 쓸 수 있는 것은 무엇인가요?',N'"그렇게 우물쭈물 했다가는 다 죽을거야!"',N'엉금엉금',N'뭉그적',N'어물쩍',N'빠릿빠릿',N'2',N'06',N'Y',N'S'),
	 (395,N'01',N'01',N'여우 아저씨는 책을 다 읽고 나면 어떻게 하는 버릇이 있었나요?',NULL,N'책장에 정리했어요.',N'독서일기를 썼어요. ',N'소금과 후추를 뿌려 먹었어요. ',N'친구에게 빌려주었어요.',N'3',N'01',N'',N'S'),
	 (395,N'01',N'02',N'책을 좋아하는 여우 아저씨가 눈여겨 봐둔 새로운 장소는 어디인가요?',NULL,N'도서관  ',N'서점',N'출판사',N'학교',N'1',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (395,N'01',N'03',N'여우 아저씨가 겪은 일을 차례대로 나열한 것을 찾아보세요.',N'(1) 감옥에 간 여우 아저씨는 ‘독서절대금지’라는 벌을 받았어요.
(2) 여우 아저씨는 ‘도서관 출입금지’라는 말을 듣고 집으로 돌아갔어요.
(3) 털모자를 눌러 쓰고 길모퉁이 서점으로 가서 책을 훔쳤어요.',N'(1)-(3)-(2)',N'(3)-(1)-(2)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (395,N'01',N'04',N'여우 아저씨가 소화불량에 걸리게 된 까닭은 무엇인가요?',NULL,N'신문지나 헌 종이를 먹었기 때문에',N'책을 너무 많이 먹었기 때문에',N'소금과 후추를 너무 많이 뿌렸기 때문에',N'딱딱한 책들을 먹었기 때문에',N'1',N'03',N'',N'S'),
	 (395,N'01',N'05',N'서점에서 책을 훔친 여우 아저씨에게 해 줄 수 있는 말로 가장 바른 것은 무엇인가요?',NULL,N'"아무리 책이 맛있어도 남의 물건에 손을 대면 안 돼요."',N'"서점에서는 다른 사람들을 위해 조용히 해야 해요."',N'"아저씨의 용감한 행동에 박수를 보내고 싶어요."',N'"다음에는 더 많이 가져가세요."',N'1',N'04',N'',N'S'),
	 (395,N'01',N'06',N'여우 아저씨가 결국 작가가 될 수 있었던 이유로 알맞은 것은 무엇인가요?',NULL,N'책을 훔쳐서 유명해졌기 때문에',N'벌은 받은 뒤에 책을 훔치지 않고 직접 글을 쓰기 시작했기 때문에',N'경찰이 대신 글을 써 주었기 때문에',N'소금과 후추를 덜 뿌리게 되었기 때문에',N'2',N'04',N'',N'S'),
	 (395,N'01',N'07',N'경찰관의 말을 들은 여우 아저씨는 어떤 마음이었을까요?',N'“당신을 체포하겠소. 책을 훔치는 아주 못된 짓을 했기 때문이오.”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (396,N'01',N'01',N'횽 교리의 집 현판에 쓰여 있는 ''서유당(書遊堂)''의 의미는 무엇인가요?',N'',N'책과 노니는 집',N'책을 만드는 집',N'책을 빌려주는 집',N'책을 많이 쓰는 집',N'1',N'01',N'N',N'S'),
	 (396,N'01',N'02',N'장이가 남몰래 곤죽을 만드는 일을 하게 된 이유는 무엇인가요?',N'',N'허궁제비에게 닷 전을 주고 상아찌를 되찾아 오기 위해서',N'홍교리에게 빌린 돈을 갚기 위해서',N'최 서쾌 몰래 책을 사기 위해서',N'최 서쾌에게 약점을 잡혔기 때문에',N'1',N'01',N'N',N'S'),
	 (396,N'01',N'03',N'낙심이가 《심청전》 이야기를 듣기 싫어 했던 이유는 무엇인가요?',N'',N'자신이 이미 알고 있는 이야기여서',N'자신이 좋아하는 전쟁 이야기가 아니었기 때문에',N'심청이가 팔려간 것이 자신의 처지와 닮았다고 느껴서',N'심청이의 이야기를 너무 많이 들었기 때문에',N'3',N'04',N'N',N'S'),
	 (396,N'01',N'04',N'장이가 낙심이를 ''쓸모 많은 고자질쟁이''라고 생각한 이유는 무엇인가요?                  ',N'',N'낙심이가 고자질을 해서 허궁제비를 잡아 혼쭐을 냈기 때문에',N'낙심이 덕분에 필사를 배울 수 있게 돼서',N'낙심이의 고자질을 통해 더 이상 책 심부를 안가게 되어서',N'낙심이 덕분에 많은 사람들을 속이고 돈을 많이 벌 수 있어서',N'1',N'04',N'N',N'S'),
	 (396,N'01',N'05',N'다음 보기에 나오는 ''어둡다''의 의미는 무엇인가요?',N'"책을 보실 땐 바깥 기척에 어두우시다."',N'분위기나 표정, 성격 따위가 침울하고 무겁다.',N'희망이 없이 참담하고 막막하다.',N'눈이 잘 보이지 아니하거나 귀가 잘 들리지 아니하다.',N'빛깔의 느낌이 무겁고 침침하다.',N'3',N'02',N'Y',N'S'),
	 (396,N'01',N'06',N'최 서쾌가 어린 장이에게 "필사쟁이 피는 못 속이는구나" 라는 말을 했습니다. 이 말의 의미는 무엇인가요?',N'',N'장이가 아버지와 생김새가 닮았다.',N'장이가 아버지의 어린 시절에 대해 구구절절하게 늘어놓았다.',N'장이는 아버지와는 다른 길을 가려고 한다.',N'장이가 글을 잘 쓰는 것은 아버지의 영향이다.',N'4',N'04',N'N',N'S'),
	 (396,N'01',N'07',N'당시 조선시대에는 돈을 받고 책을 빌려주는 책방이 인기가 많았습니다. 이 책방의 이름은 무엇인가요?',N'',N'대여점',N'새책집',N'헌책방',N'책창고',N'2',N'07',N'N',N'S'),
	 (396,N'01',N'08',N'사건을 시간 순서대로 나열한 것을 찾아보세요.',N'(1) 상아찌를 허궁제비에게 빼앗김
(2) 최 서쾌가 동국통감과 비단 주머니를 장이에게 줌
(3) 홍 교리가 뒤에 따라오던 사람이 없었냐고 물어봄',N'(1)-(2)-(3)',N'(2)-(1)-(3)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'2',N'03',N'Y',N'S'),
	 (396,N'01',N'09',N'이야기 연회가 끝난 후 홍 교리가 장이에게 했던 말들의 진짜 의미는 무엇인가요?',N'',N'지금보다 더 평등한 세상이 되는 것',N'백성들이 지금보다 책을 더 많이 읽는 것',N'필사라는 일의 얼마나 중요성과 위험성',N'책의 중요성을 알리고 많은 사람들이 지혜를 쌓아가는 것',N'1',N'04',N'N',N'S'),
	 (396,N'01',N'10',N'장이가 홍 교리의 서고에서 책 제목에 동녘 동(東)이 적힌 책들을 찾으려는 이유는 무엇인가요?',N'',N'동녘 동(東)이 적힌 책들은 잘못 필사된 책이어서',N'동녘 동(東)이 적힌 책들은 천주학 책이기 때문에 찾아 없애려고',N'동녘 동(東)이 적힌 책들을 찾아오라는 홍 교리의 부탁이 떠올라서 ',N'동녘 동(東)이 불온한 일을 발생시킨다는 허무맹랑한 믿음 때문에',N'2',N'03',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (396,N'01',N'11',N'베끼어 쓰는 것''을 뜻하는 단어는 무엇인가요?',N'',N'필사(筆寫)',N'속사(速寫)',N'필담(筆談)',N'사수(師授)',N'1',N'02',N'N',N'S'),
	 (396,N'01',N'12',N'병이 깨끗이 나음''을 뜻하는 단어는 무엇인가요',N'',N'호전(好轉)',N'양호(良好)',N'쾌차(快差)',N'양질(良質)',N'3',N'07',N'N',N'S'),
	 (396,N'01',N'13',N'''남을 해치고자 하는 짓''을 뜻하는 단어는 무엇인가요? ',N'',N'난동(亂動)',N'해코지',N'패악(悖惡)',N'격분(激忿)',N'2',N'06',N'N',N'S'),
	 (396,N'01',N'14',N'  ''겉모양이 깨끗하지 못하고 생기가 없다''는 뜻의 단어는 무엇인가요?',N'',N'난잡하다',N'추레하다',N'조잡하다',N'분주하다',N'2',N'06',N'N',N'S'),
	 (396,N'01',N'15',N'권력과 세력을 아울러 이르는 말은 무엇인가요?',N'',N'역관(役官)',N'권한(權限)',N'권세(權勢)',N'영역(領域)',N'3',N'06',N'N',N'S'),
	 (397,N'01',N'01',N'남자의 표정은 어떤가요?',N'',N'즐거워 보인다.',N'지쳐 보인다.',N'슬퍼 보인다.',N'기뻐 보인다.',N'2',N'01',N'N',N'S'),
	 (397,N'01',N'02',N'어느 날 남자가 엄청난 분노에 사로잡힌 이유는 무엇인가요?',N'',N'친구가 약속을 어겨서',N'새 소리가 너무 시끄러워서',N'아무것도 달리진 게 없어서',N'친구가 거짓말을 해서',N'3',N'03',N'N',N'S'),
	 (397,N'01',N'03',N'남자가 가진 의문은 무엇인가요?',N'',N'사람은 왜 사는지',N'시계의 초침이 어떻게 움직이는지',N'사물에 붙은 이름을 왜 그대로 불러야 하는지',N'언어는 왜 사람의 의식에 영향을 주는지',N'3',N'04',N'N',N'S'),
	 (397,N'01',N'04',N'남자는 책상을 무엇이라 부르나요?',N'',N'양탄자',N'책상',N'포크',N'지우개',N'1',N'01',N'N',N'S'),
	 (397,N'01',N'05',N'소리와 의미의 관계가 사회적으로 약속된 후에는 개인이 마음대로 바꿀 수 없는 특성은 무엇인가요?',N'',N'언어의 사회성',N'언어의 특별성',N'언어의 존재감',N'언어의 역사성',N'1',N'07',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (397,N'01',N'06',N'남자는 이 일에 재미가 들어 어떤 행동을 하나요?',N'',N'길거리에서 춤을 춘다.',N'온종일 단어를 암기한다.',N'사람들에게 자신의 단어를 알려준다.',N'자신의 단어를 수첩에 기록한다.',N'2',N'04',N'N',N'S'),
	 (397,N'01',N'07',N'괄호 안에 들어갈 말을 찾아보세요.',N'그는 노래들을 작은 소리로 혼자 불러보기도 했다. (      ) 얼마 지나지 않아 이처럼 자기 언어로 바꾸는 것이 힘들어졌다.',N'그럼에도',N'왜냐하면',N'그러나',N'그래서',N'3',N'02',N'Y',N'S'),
	 (397,N'01',N'08',N'남자는 왜 다른 사람들의 얘기를 듣고 있으면 웃음이 나왔나요?',N'',N'나만의 언어가 있는 것이 즐거워서',N'웃어야 사람들이 자신을 좋아하니까',N'말의 뜻을 이해할 수 없어서',N'다른 사람과 소통하는 것이 재미있어서',N'3',N'04',N'N',N'S'),
	 (397,N'01',N'09',N'결국 남자는 어떻게 되었나요?',N'',N'자기 자신하고만 이야기 했다.',N'말도 안 된다고 생각하고 자신의 언어를 버렸다.',N'애완 동물을 입양했다.',N'벽을 보고 이야기하며 깨달음을 정리했다.',N'1',N'01',N'N',N'S'),
	 (397,N'01',N'10',N'책을 읽은 느낌으로 어색한 사람은 누구인가요?',N'윤지: 언어의 기본은 다른 사람과의 소통인데 남자는 그것을 놓쳤네.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
