	 (406,N'01',N'07',N'‘넓은 범위를 한 번에 훑어보는 모양’을 말하며, 다음 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?',N'선생님은 애들을 (    ) 둘러 보셨다.',N'찬찬히',N'주욱',N'꼼꼼히',N'슬그머니',N'2',N'07',N'Y',N'S'),
	 (406,N'01',N'08',N'선생님께서 누굴 시킬까 둘러볼 때 ‘나’의 어디가 빨간 신호등처럼 변했나요?',N'',N'이마',N'코',N'볼',N'귀',N'4',N'02',N'',N'S'),
	 (406,N'01',N'09',N'새로 온 선생님은 무엇을 못 찾아서 자신의 가방을 뒤지고 있었나요?',N'',N'만년필',N'손수건',N'분필',N'안경',N'1',N'03',N'',N'S'),
	 (406,N'01',N'10',N'‘나’는 왜 손을 번쩍 들고선 칠판 앞으로 나갔나요?',N'',N'선생님께 구구단을 자랑하고 싶어서',N'허둥대는 선생님을 도와 드리고 싶어서',N'겁쟁이가 아니라는 것을 친구들에게 보여주기 위해서',N'친구를 놀래키려고',N'2',N'02',N'',N'S'),
	 (406,N'01',N'11',N'내키지 않는 사태를 피하거나 사실을 감추려고 다른 일을 내세우는 것''을 무엇이라고 하나요?',N'',N'짐작',N'설명',N'핑계',N'변명',N'3',N'06',N'',N'S'),
	 (406,N'01',N'12',N'배운 것을 다시 익혀 공부하는 것과 반대말이 알맞게 짝지어진 것은 무엇인가요?',N'',N'복습-예습',N'예습-학습',N'학습-복습',N'숙제-예습',N'1',N'07',N'',N'S'),
	 (407,N'01',N'01',N'닥터 몽 선생님이 상담사가 된 건 무엇 덕분이었나요?',NULL,N'커다란 귀',N'커다란 손',N'커다란 눈',N'커다란 발',N'1',N'01',N'',N'S'),
	 (407,N'01',N'02',N'친구들이 같이 놀아주지 않자 몽이는 무엇을 했나요?',NULL,N'잠만 잤어요.',N'텔레비전만 봤어요.',N'책만 읽었어요.',N'밖으로 나갔어요.',N'3',N'01',N'',N'S'),
	 (407,N'01',N'03',N'일이 일어난 차례대로 바르게 나열한 것을 찾으세요.',N'(1) 친구들이 몽이의 귀를 좋아하기 시작했어요.
(2) 몽이는 원숭이 상담가 ''닥터 몽''이 되었어요. 
(3) 몽이는 자신의 커다란 귀를 싫어했어요.',N'(1)-(3)-(2)',N'(3)-(1)-(2)',N'(2)-(1)-(3)',N'(1)-(2)-(3)',N'2',N'03',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (407,N'01',N'04',N'나나와 탱구의 소문이 퍼진 뒤, 몽이에게 생긴 변화로 알맞은 것은 무엇인가요?',NULL,N'몽이를 괴롭히는 친구들이 늘었어요.',N'몽이가 더 혼자 있게 되었어요.',N'몽이에게 고민을 털어놓는 친구들이 늘었어요.',N'몽이가 학교에 가지 않았어요.',N'3',N'03',N'',N'S'),
	 (407,N'01',N'05',N'이야기를 통해 알 수 있는 몽이의 장점은 무엇인가요?',NULL,N'노래를 잘하는 점',N'친구 말을 잘 들어주는 점',N'달리기를 잘하는 점',N'그림을 잘 그리는 점',N'2',N'04',N'',N'S'),
	 (407,N'01',N'06',N'닥터몽 선생님의 이야기를 듣고 어떤 점을 느꼈나요?',NULL,N'다른 이의 이야기를 잘 들어주는 모습이 멋져요.',N'닥터몽 선생님처럼 커다란 귀를 가지고 싶어요.',N'듣는 것보다 말하는 것이 중요한 것 같아요.',N'놀림받지 않기 위해서는 숨어야 해요.',N'1',N'04',N'',N'S'),
	 (407,N'01',N'07',N'처음에 자신의 귀가 싫었던 몽이는 어떤 마음이었을까요?',NULL,N'신나고 즐거웠어요.',N'화가 나고 슬펐어요.',N'속상하고 위축되었어요.',N'아무렇지 않았어요.',N'3',N'05',N'',N'S'),
	 (407,N'01',N'08',N'몽이의 마음은 어땠을까요?',N'"네게 털어놓기를 정말 잘했어.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (408,N'01',N'02',N'가을이 되자, 할아버지와 작은 아이는 무엇을 했나요?',NULL,N'여기 저기 솟아난 잡초를 뽑았어요.',N'들판에 씨앗을 뿌렸어요.',N'옥수수와, 콩, 들깨와 기장을 거두었어요.',N'나무를 베어 장작을 만들었어요.',N'3',N'01',N'',N'S'),
	 (408,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 어린 새들이 씨앗을 파먹어서 거둘 게 얼마 없었어요.
(2) 한겨울이 되자 산 속 오두막집 식구들은 모두 배가 고팠아요.
(3) 할아버지와 작은 아이들은 낟알들을 밭에 듬뿍 남겨 두었어요. ',N'(1)-(3)-(2)',N'(1)-(2)-(3)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'2',N'03',N'Y',N'S'),
	 (408,N'01',N'04',N'돌아온 가을에 농사가 잘된 이유는 무엇인가요?',NULL,N'모두 배가 고팠지만 씩씩하게 잘 참았기 때문이에요.',N'새들이 모두 떠나서 씨앗이 멀쩡했기 때문이에요.',N'비가 자주 와서 농사가 잘되었기 때문이에요.',N'씨앗을 새들에게 전혀 주지 않았기 때문이에요.',N'1',N'03',N'',N'S'),
	 (408,N'01',N'05',N'한겨울에 산 속 식구들은 모두 배가 고팠어요. 만약 할아버지와 작은 아이가 콩과 옥수수를 거의 다 먹어버렸다면, 봄에는 어떤 일이 일어났을까요?',NULL,N'더 많은 식구들이 산 속 오두막집으로 모여들었을 거예요. ',N'새들이 곡식 낟알을 배불리 먹을 수 있었을 거예요.',N'봄에 씨앗을 많이 뿌릴 수 없어서 농사가 잘되지 않았을 거예요.',N'돌아온 가을에 더 많은 곡식을 거둘 수 있었을 거예요.',N'3',N'04',N'',N'S'),
	 (408,N'01',N'06',N'이 이야기를 통해 알 수 있는 가장 중요한 생각은 무엇인가요?',NULL,N'배가 고프면 씨앗도 모두 먹어야 해요.',N'자연은 사람이 마음대로 써도 돼요.',N'농사는 많이 심을수록 좋아요.',N'다른 생명과 나누며 살아가는 것이 중요해요.',N'4',N'04',N'',N'S'),
	 (408,N'01',N'07',N'작은 아이는 어떤 목소리로 말했을까요?',N'"아무리 배가 고파도 씨 할 것 없이 먹어 버리면 안 돼. 먹고 싶어도 참아야 해."',N'씩씩한 목소리',N'부끄러운 목소리',N'단호한 목소리',N'불안한 목소리',N'3',N'05',N'Y',N'S'),
	 (408,N'01',N'08',N'씨앗을 심으며 새와 두더지 몫까지 남겨 둔 할아버지와 작은 아이의 마음은 어떠했을까요?',NULL,N'자기 것만 챙기고 싶은 마음',N'자연과 다른 생명을 아끼는 따뜻한 마음',N'빨리 먹고 싶은 조급한 마음',N'먹을 것이 적어서 속상한 마음',N'2',N'05',N'',N'S'),
	 (408,N'01',N'09',N'다음 빈칸에 어울리는 표현을 찾아 보세요.',N'새들은 밭에 (         ) 모여 떨어진 낟알을 배불리 먹었어요.',N'옹기종기',N'들쑥날쑥',N'엉거주춤',N'울퉁불퉁',N'1',N'02',N'Y',N'S'),
	 (408,N'01',N'10',N'다음 빈칸에 어울리는 표현을 찾아 보세요.',N'아침마다 새들이 (          ) 소리를 내며 오두막집 주위를 날아다녔어요.',N'쿵쾅쿵쾅',N'재잘재잘',N'수군수군',N'왁자지껄',N'2',N'02',N'Y',N'S'),
	 (408,N'01',N'11',N'밑줄 친 부분을 대신할 수 있는 낱말을 찾으세요.',N'할아버지와 작은 아이는 고구마를 캐서 알뜰하게 <u>갈무리</u> 했어요.',N'요리 ',N'판매 ',N'정리',N'나눔',N'3',N'06',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (408,N'01',N'12',N'‘몫’의 뜻으로 알맞은 것은 무엇인가요?',N'"한 알은 두더지 몫이고, 한 알은 우리 몫이야."',N'함께 쓰는 물건',N'차례대로 하는 일',N'우연히 얻게 된 것',N'나누어 가지는 부분',N'4',N'06',N'Y',N'S'),
	 (409,N'01',N'01',N'아버지는 세 딸을 불러 할아버지 생신 준비를 하라고 무엇을 나누어 주었나요?',NULL,N'콩 한 알',N'닭 한 마리',N'꿩 한 마리 ',N'송아지 한 마리',N'1',N'01',N'',N'S'),
	 (409,N'01',N'02',N'막내딸이 준비한 할아버지 선물은 무엇이었나요?',NULL,N'병아리 두 마리',N'어미닭이 낳은 알',N'송아지 한 마리',N'꿩 한 마리',N'3',N'01',N'',N'S'),
	 (409,N'01',N'03',N'막내딸이 콩 한 알로 송아지를 산 과정을 순서대로 나열한 것을 찾아보세요.',N'(1) 닭이 낳은 병아리들을 모두 내다팔아서 송아지 한 마리를 샀어요.
(2) 산으로 올라가 콩 한 알로 꿩을 잡았어요.
(3) 시장에 가서 꿩을 병아리 한 쌍과 바꿨어요.',N'(2)-(3)-(1) ',N'(2)-(1)-(3)',N'(1)-(3)-(2)  ',N'(3)-(1)-(2)',N'1',N'03',N'Y',N'S'),
	 (409,N'01',N'04',N'다음 중 이야기의 흐름에 맞는 설명은 무엇인가요?',NULL,N'작은 것을 버리고 큰 것을 바로 얻었어요.',N'작은 것을 잘 바꾸어 점점 큰 것으로 만들었어요.',N'언니들의 도움으로 선물을 준비했어요.',N'시장에서 우연히 송아지를 얻었어요.',N'2',N'03',N'',N'S'),
	 (409,N'01',N'05',N'막내딸을 칭찬하는 말로 가장 올바른 것을 찾아보세요.',NULL,N'“언니들과 사이좋게 지내는 모습이 정말 정다워 보였어.”',N'"동물을 보호하는 따뜻한 마음을 배워야겠어.”',N'“작은 것도 소중히 여기는 자세와 지혜로움을 본받아야겠어."',N'"운이 좋아서 큰 선물을 받았구나."',N'3',N'04',N'',N'S'),
	 (409,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 가장 알맞은 것은 무엇인가요?',NULL,N'처음부터 큰 것을 받아야 해요.',N'남의 도움만 기다려야 해요.',N'운이 좋아야 성공할 수 있어요.',N'작은 것도 잘 생각하고 지혜롭게 사용하면 큰 도움이 돼요.',N'4',N'04',N'',N'S'),
	 (409,N'01',N'07',N'막내딸의 말을 들은 아버지는 어떤 마음이었을까요?',N'“저는 아버지가 주신 콩 한 알로 이 송아지를 샀어요.”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (409,N'01',N'10',N'다음 중 콩 한 알을 창밖으로 던져버린 큰딸의 태도를 가장 잘 나타내는 말은 무엇인가요?',NULL,N'고개를 끄덕이다',N'눈물을 흘리다',N'콧방귀를 뀌다',N'박수를 치다',N'3',N'02',N'',N'S'),
	 (409,N'01',N'11',N'이야기에서 막내딸이 꿩을 잡기 위해 사용한 도구로, ''짐승을 잡기 위해 줄로 만든 장치''를 의미하는 것은 무엇인가요?',NULL,N'그물',N'올가미',N'바구니',N'주머니',N'2',N'06',N'',N'S'),
	 (409,N'01',N'12',N'‘지혜’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'힘이 세고 튼튼한 것',N'다른 사람보다 앞서 나가는 것',N'다른 사람보다 잘하지 못하는 것',N'상황을 잘 생각해 바르게 판단하는 것',N'4',N'06',N'',N'S'),
	 (410,N'01',N'01',N'예나에게 책과 볼펜을 주워준 사람은 누구인가요?',NULL,N'용수',N'민수',N'용화',N'철수',N'1',N'01',N'',N'S'),
	 (410,N'01',N'02',N'예나는 어떤 일로 사람들을 도왔나요?',NULL,N'공부를 가르쳐 주는 일',N'편지를 쓰는 일',N'편지를 배달해 주는 일',N'편지를 대신 읽어주는 일',N'2',N'02',N'',N'S'),
	 (410,N'01',N'03',N'예나가 편지 쓰는 일을 계속하고 싶은 이유는 무엇일까요?',NULL,N'답장을 받는 일이 재미있기 때문에',N'용수와 함께 하는 것이 즐거워서',N'누군가에게 조금이라도 도움이 될 수 있다고 생각하면 힘이 나서',N'자신의 글솜씨를 뽐내고 싶어서',N'3',N'03',N'',N'S'),
	 (410,N'01',N'04',N'예나 엄마는 예나와 용수에게 어떤 감정을 느꼈나요?',NULL,N'부끄럽다',N'자랑스럽다',N'걱정된다',N'염려된다',N'2',N'04',N'',N'S'),
	 (410,N'01',N'05',N'과일 가게 아주머니는 키 작은 생도에게 어떤 친절을 베풀었나요?',NULL,N'과일을 공짜로 먹게 해 주었다.',N'과일을 가져다 팔 수 있게 해주었다.',N'과일을 외상으로 먹게 해 주었다.',N'과일을 집으로 배달해 주었다.',N'3',N'01',N'',N'S'),
	 (410,N'01',N'06',N'사과를 준 아주머니 덕분에 자존심을 지켰던 생도는 훗날 어떤 사람이 되었나요?',NULL,N'프랑스의 영웅 나폴레옹',N'만세 운동을 벌인 유관순',N'미국의 대통령 링컨',N'평화로운 독립운동을 이끈 간디',N'1',N'07',N'',N'S'),
	 (410,N'01',N'07',N'동우는 백혈병에 걸려 빡빡 머리가 된 윤수를 무엇이라고 놀렸나요?',NULL,N'사과 머리',N'햇밤 머리',N'문어 머리',N'민둥머리',N'3',N'04',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (410,N'01',N'08',N'동우가 은지와 친해질 수 있었던 이유는 무엇일까요?',NULL,N'이식 수술을 받는다는 공통점 때문에',N'은지와 동우는 좋아하는 음식이 같아서',N'같은 만화 영화를 좋아한다는 공통점 때문에',N'함께 보낸 시간이 많았기 때문에',N'1',N'03',N'',N'S'),
	 (410,N'01',N'09',N'빈칸에 들어갈 수 있는 말은 무엇인가요?',N'심장이 빠르게 (     )거려 동우는 얼른 가슴팍을 붙잡았다. 금방이라도 심장이 멈처 버릴 것 같아서 의사가 가르쳐 준 대로 심호흡을 했다.',N'반짝',N'쿵쾅',N'산들',N'번쩍',N'2',N'02',N'Y',N'S'),
	 (410,N'01',N'10',N'라오즈가 의족을 택한 이유는 무엇일까요?',NULL,N'의족을 택해야 혼자 일어서서 걸을 수 있기 때문',N'의족의 가격이 더 저렴하기 때문',N'의사가 의족을 선택하라고 말했기 때문',N'의족은 누구나 사용하는 흔한 치료법이기 때문에',N'1',N'07',N'',N'S'),
	 (410,N'01',N'11',N'다음이 설명하는 단어는 무엇인가요?',N'(      )어머니인 기생 월중선은 만덕이 가게를 차릴 수 있도록 도와주었다. 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (411,N'01',N'06',N'승연이는 왜 우진이가 가방을 주섬주섬 싸는 동안 멍하게 있었나요?',NULL,N'우진이와 짝이 된 것이 설레서',N'우진이가 뒷자리로 가는 것이 믿기지 않아서',N'집에 두고 온 준비물이 생각 나서',N'우진이를 보고싶지 않아서',N'2',N'03',N'',N'S'),
	 (411,N'01',N'07',N'빈칸에 들어갈 수 없는 말은 무엇인가요?',N'연필은 (               ) 굴러 선생님 발끝에서 멈췄어요.',N'데구르르',N'데굴데굴',N'개굴개굴',N'떼굴떼굴',N'3',N'02',N'Y',N'S'),
	 (411,N'01',N'08',N'승연이는 창훈이가 어떨 때 귀엽게 느껴졌나요?',NULL,N'바람 가득 찬 공처럼 통통 뛰어다니며 놀 때',N'사물함 밑에 들어간 공기를 주워 줄 때',N'등을 밀치고 지나갈 때',N'창훈이가 공기놀이를 매우 잘 할때',N'1',N'04',N'',N'S'),
	 (411,N'01',N'09',N'승연이는 어디에 자신의 속마음을 썼나요?',NULL,N'교환 일기',N'마음 나누기 공책',N'선생님께 보내는 편지',N'혼자 쓰는 일기',N'2',N'01',N'',N'S'),
	 (411,N'01',N'10',N'다음의 ''복수''가 나타내는 뜻으로 알맞은 것은 무엇인가요?',N'모르긴 몰라도 수업 시간 일을 두고 나하테 분명히 복수할 거에요.',N'배에 차오르는 물',N'원수를 갚음',N'둘 이상의 수',N'원래의 상태를 되찾음',N'2',N'06',N'Y',N'S'),
	 (411,N'01',N'11',N'남에게 굽히지 않고 자신의 품위를 스스로 지키는 마음을 무엇이라 하나요?',NULL,N'자존심',N'자율성',N'욕심',N'교만함',N'1',N'07',N'',N'S'),
	 (411,N'01',N'12',N'퉁명스럽다''의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'따분하고 싫증이 남',N' 마음씨가 부드럽고 상냥함',N'못마땅하거나 시답지 아니하여 불쑥 하는 말이나 태도에 무뚝뚝한 기색이 있음',N'성질이 싹싹하고 부드럽다',N'3',N'06',N'',N'S'),
	 (412,N'01',N'01',N'생쥐 콩이는 풀숲 아래서 무엇을 발견했나요? ',NULL,N'나뭇가지',N'구멍',N'돌',N'꽃씨',N'2',N'01',N'',N'S'),
	 (412,N'01',N'02',N'콩이는 왜 씨니가 가장 좋은 친구라고 생각했나요?',NULL,N'씨니가 가장 말을 예쁘게 해 주어서',N'아팠을 때 씨니가 병문안을 와 주어서',N'길을 잃었을 때 씨니가 도와주어서',N'씨니와 항상 같이 놀아서',N'3',N'01',N'',N'S'),
	 (412,N'01',N'03',N'콩이가 옆집을 방문해서 겪은 일을 순서대로 나열한 것을 찾으세요.',N'(1) 애벌레 방을 구경했어요.
(2) 여왕개미와 이야기를 나누었어요. 
(3) 고치방으로 가서 고치들을 보았어요.',N'(1)-(3)-(2)',N'(2)-(1)-(3)     ',N'(3)-(1)-(2)    ',N'(3)-(2)-(1)',N'1',N'03',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (412,N'01',N'04',N'며칠 동안 콩이가 밖에 나오지 않고 집에서만 지낸 까닭은 무엇인가요?',NULL,N'옆집에 이사 온 이웃과 마주칠까 봐 무서웠기 때문에',N'깡군이 앞으로는 절대로 집 밖에 나오지 말라고 했기 때문에',N'떡두가 씨니랑 친하게 지내서 화가 났기때문에',N'몸이 아파서 쉬고 있었기 때문에',N'1',N'03',N'',N'S'),
	 (412,N'01',N'05',N'이웃을 잘 알지 못할 때 콩이의 모습에서 배울 수 있는 점은 무엇인가요?',NULL,N'모르는 이웃은 피하는 것이 좋아요.',N'겉모습만 보고 판단하면 안 돼요.',N'친구 말만 믿고 행동해야 해요.',N'무조건 집에만 있어야 해요.',N'2',N'04',N'',N'S'),
	 (412,N'01',N'06',N'이야기에서 ‘좋은 이웃’은 어떤 사람이라고 할 수 있을까요?',NULL,N'자기 일만 하는 사람',N'남의 흉을 잘 보는 사람',N'서로 도우며 지내는 사람',N'혼자 조용히 지내는 사람',N'3',N'04',N'',N'S'),
	 (412,N'01',N'07',N'씨니는 어떤 마음이었을까요?',N'“나는 네 친구니까”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (413,N'01',N'02',N'콩쥐가 자갈밭을 매는데 도움을 준 동물은 누구인가요?',NULL,N'검은 소',N'두꺼비',N'참새',N'강아지',N'1',N'01',N'',N'S'),
	 (413,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요. ',N'(1) 선녀는 콩쥐에게 비단옷과 꽃신을 주었어요.
(2) 콩쥐와 원님은 서로 아껴주며 행복하게 살았어요.
(3) 급하게 징검다리를 건너던 콩쥐는 꽃신을 냇물에 빠뜨리고 말았어요.',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (413,N'01',N'04',N'다음 중 원님이 콩쥐를 찾게 된 까닭으로 알맞은 것은 무엇인가요?',NULL,N'콩쥐가 새엄마를 혼냈기 때문이에요.',N'팥쥐가 원님에게 꽃신을 주었기 때문이에요.',N'선녀가 원님에게 편지를 보냈기 때문이에요.',N'콩쥐가 잃어버린 꽃신을 원님이 주웠기 때문이에요.',N'4',N'03',N'',N'S'),
	 (413,N'01',N'05',N'등장인물의 성격을 <u>잘못</u> 말한 것을 찾으세요.',NULL,N'새엄마-질투가 심하고 마음씨가 고약해요.',N'팥쥐-엄마와 달리 정이 많아요.',N'콩쥐-이해심이 깊고 착한 마음을 가졌어요.',N'선녀-콩쥐를 도와주는 따뜻한 마음이 있어요.',N'2',N'04',N'',N'S'),
	 (413,N'01',N'06',N'콩쥐 이야기에서 배울 수 있는 태도로 가장 알맞은 것은 무엇인가요?',NULL,N'힘든 일은 남에게 떠넘겨야 해요.',N'남을 괴롭히면 결국 행복해져요.',N'착하게 살면 도움을 받을 수 있어요.',N'모르는 사람은 무조건 믿으면 안 돼요.',N'3',N'04',N'',N'S'),
	 (413,N'01',N'07',N'콩쥐는 어떤 마음이었을까요?',N'콩쥐는 한숨을 쉬며 말했어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (413,N'01',N'12',N'‘힘든 일을 참고 견디는 마음’을 뜻하는 낱말은 무엇인가요?',NULL,N'자랑',N'욕심',N'투정',N'인내',N'4',N'06',N'',N'S'),
	 (414,N'01',N'01',N'다음 중 음파에 대한 설명으로 옳지 않은 것은 무엇인가요?',NULL,N'음파는 공기 외에 다른 물체가 진동해서 생겨나기도 한다',N'음파는 공기가 진동하면서 생기는 파동이기 때문에 공기 없이는 생겨나지 않는다',N'음파는 벽이 진동했을 때에도 생겨난다',N'물체만 진동하고 매질이 없다면 음파는 전달되지 않는다',N'2',N'01',N'',N'S'),
	 (414,N'01',N'02',N'귀가 두 개인 이유는 무엇인가요?',NULL,N'소리가 어느 방향에서 오는지 알게 하기 위해서',N'하나만 있으면 외계인처럼 보이니까',N'위험에서 벗어나게 하기 위해서',N'귀는 일정한 방향의 소리만 들을 수 있어서',N'1',N'04',N'',N'S'),
	 (414,N'01',N'03',N'물고기 중 항문으로 공기 방울을 만들어 소리를 내는 물고기의 이름은 무엇인가요?',NULL,N'청어',N'오징어',N'복어',N'문어',N'1',N'04',N'',N'S'),
	 (414,N'01',N'04',N'박쥐는 어둠 속에서 어떤 방법으로 곤충을 사냥하나요?',NULL,N'큰 소리를 질러 정신을 잃게 함으로써',N'곤충이 날개를 퍼덕이는 소리를 듣고서',N'초음파를 발사한 뒤, 그 반사음을 듣고서',N'먹이를 발견하면 째빨리 낙하하면서 낚아채서',N'3',N'03',N'',N'S'),
	 (414,N'01',N'05',N'새가 노래 부르는 이유는 무엇인가요?',NULL,N'암수 모두 행복한 기분을 표현하기 위해',N'수컷이 암컷을 유혹하거나 다른 수컷을 쫓아내기 위해',N'암컷이 다른 새로부터 새끼를 감시하기 위해',N'다른 새들의 주목을 받고싶어서',N'2',N'03',N'',N'S'),
	 (414,N'01',N'06',N'소리가 방 안의 모든 벽에 반사되어 다시 들리는 현상을 무엇이라고 하나요?',NULL,N'반향',N'방음',N'소음',N'굉음',N'1',N'01',N'',N'S'),
	 (414,N'01',N'07',N'스피커를 넣는 나무로 만든 상자를 무엇이라고 하나요?',NULL,N'트위터',N'우퍼',N'스피커 박스',N'앰프',N'3',N'02',N'',N'S'),
	 (414,N'01',N'08',N'다음 중 가장 빠른 것은 무엇인가요?',NULL,N'빛',N'눈',N'소리',N'공기',N'1',N'07',N'',N'S'),
	 (414,N'01',N'09',N'소리와 관련된 표현이 아닌 것은 무엇인가요?',NULL,N'지지배배 지지배배',N'찰칵 찰칵',N'둥실 둥실',N'드르렁 드르렁',N'3',N'02',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (414,N'01',N'10',N'소리에 관한 모든 것을 연구하는 학문을 무엇이라고 하나요?',NULL,N'음성학',N'음향학',N'예술',N'음운학',N'2',N'07',N'',N'S'),
	 (414,N'01',N'11',N'소리의 세기를 나타내는 단위를 무엇이라고 하나요?',NULL,N'데시벨',N'헤르츠',N'초음파',N'메트로놈',N'1',N'06',N'',N'S'),
	 (414,N'01',N'12',N'진동수가 20헤르츠 미만인 소리를 무엇이라고 하나요?',NULL,N'초고주파',N'초음파',N'초저주파',N'저주파',N'3',N'06',N'',N'S'),
	 (415,N'01',N'01',N'텔레비전이 소리를 지른 까닭은 무엇인가요?',NULL,N'크록텔레 가족들이 방송이 끝날 때까지 하루 종일 자기만 쳐다봐서',N'크록텔레 가족들이 더이상 자신을 찾지 않아서',N'크록텔레 가족들이 자신만 빼놓고 별장에 가 버려서',N'크록텔레 가족들이 텔레비전을 거칠게 다루어서',N'1',N'01',N'',N'S'),
	 (415,N'01',N'02',N'텔레비전이 없는 동안 크록텔레 가족들은 어떤 생활을 했나요?',NULL,N'가족 모두 집을 나와 밖에서 즐길 수 있는 일을 찾았어요. ',N'가족들은 열흘간 여행을 떠나 즐거운 시간을 보냈어요.',N'지루함의 연속이라 한 사람도 즐겁지 않았어요.',N'텔레비전 생각은 전혀 하지 않고 친구들과 놀았어요.',N'3',N'01',N'',N'S'),
	 (415,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 금요일이 되자 크록텔레 가족은 텔레비전을 데려오기로 결정했어요.
(2) 텔레비전은 웅웅거리더니 그만 기절해 버리고 말았어요.
(3) 텔레비전은 야자나무 아래에서 즐거운 시간을 보내고 있었어요. ',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'(3)-(2)-(1)',N'(2)-(1)-(3)',N'2',N'03',N'Y',N'S'),
	 (415,N'01',N'04',N'텔레비전이 기절하게 된 가장 큰 이유는 무엇인가요?',NULL,N'바닷바람을 너무 많이 쐬어서',N'가족들이 텔레비전을 싫어해서',N'텔레비전 소리가 너무 커서',N'오랫동안 쉬지 못하고 계속 켜져 있어서',N'4',N'03',N'',N'S'),
	 (415,N'01',N'05',N'행복을 찾은 크록텔레 가족을 칭찬하는 말로 올바른 것을 찾아보세요.',NULL,N'가족들 모두 규칙적인 생활을 하는걸 보니 건강해질 것 같아요! ',N'서로 이해하고 용서하는 모습에서 가족의 사랑이 느껴졌어요!',N'능동적으로 각자 취미를 즐기는 모습이 훨씬 더 의미있어 보여요!',N'거짓말을 하지 않고 솔직하게 털어놓는 모습이 멋져요!',N'3',N'04',N'',N'S'),
