	 (426,N'01',N'11',N'남을 존중하고 자기를 내세우지 않는 태도가 있는 것은 무엇인가요?',N'',N'거만',N'겸손',N'교만',N'자존심',N'2',N'06',N'',N'S'),
	 (426,N'01',N'12',N'내용이 알차고 좋으면 겉모양도 보기가 좋다는 말과 겉모양새를 잘 꾸미는 것도 중요하다는 말은 무엇인가요?',N'',N'소 잃고 외양간 고친다',N'보기 좋은 떡이 먹기도 좋다',N'빛 좋은 개살구',N'등잔 밑이 어둡다',N'2',N'06',N'',N'S'),
	 (427,N'01',N'01',N'선생님과 친구들이 모여 생각을 말하는 장소는 어디인가요?',N'  ',N'교실 ',N'영화관',N'시장',N'놀이터',N'1',N'01',N'',N'S'),
	 (427,N'01',N'02',N'틀린 생각이라도 자꾸 이야기하다 보면 어떤 변화가 생기나요?',NULL,N'할 말을 자꾸 잊어버리게 돼요.',N'입을 꾹 다문 채 시간이 흘러가요. ',N'두근거림이 줄어들어 말을 잘할 수 있어요.',N'더 틀릴까 봐 발표를 안 하게 돼요.',N'3',N'01',N'',N'S'),
	 (427,N'01',N'03',N'교실에서 틀린 답, 틀린 의견을 말해도 되는 까닭은 무엇인가요?',NULL,N'친구들에게 웃음을 줄 수 있기 때문에',N'선생님이 혼자서 설명하시기 때문에',N'함께 생각하고 정답을 찾으면 되기 때문에',N'빨리 수업을 끝낼 수 있기 때문에',N'3',N'03',N'',N'S'),
	 (427,N'01',N'04',N'다음 중 글의 내용에 맞게 생각한 것은 무엇인가요?',NULL,N'정답만 말해야 교실이 조용해져요.',N'틀리면 발표하지 않는 게 좋아요.',N'친구 생각은 들을 필요가 없어요.',N'틀린 생각도 말해야 더 좋은 생각이 나요.',N'4',N'03',N'',N'S'),
	 (427,N'01',N'05',N'가장 멋진 교실은 어떤 모습일까요? ',NULL,N'선생님이 혼자 설명하고 아이들이 딴청을 피워요.  ',N'너도 나도 자신 있게 손을 들고 생각을 말해요.',N'자기와 다른 생각을 가진 친구의 발표는 듣지 않아요. ',N'발표하는 친구를 놀려요.',N'2',N'04',N'',N'S'),
	 (427,N'01',N'06',N'친구가 틀린 답을 발표했을 때 어떻게 하는 것이 가장 올바른 자세일까요?',NULL,N'고쳐주고 가르쳐 주어요.',N'바보라고 놀려요.',N'틀렸다고 큰 소리로 웃어요.',N'모른 척 해요.',N'1',N'04',N'',N'S'),
	 (427,N'01',N'07',N'선생님은 어떤 목소리로 말했을까요?',N'“그래 잘했어! 처음부터 멋진 말이 나올 수 있는 건 아니야. 두려워 하지마.”',N'다정한 목소리',N'화난 목소리',N'떨리는 목소리',N'슬픈 목소리',N'1',N'05',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (427,N'01',N'08',N'“항상 정답만 말해야 한다”고 생각하면 발표할 때 어떤 마음이 들까요?',NULL,N'신나고 즐거워요.',N'틀릴까 봐 두렵고 떨려요.',N'더 크게 말하고 싶어요.',N'웃음이 나요.',N'2',N'05',N'',N'S'),
	 (427,N'01',N'09',N'다음 빈칸에 어울리는 흉내 내는 말을 찾아보세요.',N'온몸에 힘이 빠지고 다리가 (         ) 떨렸어.',N'후들후들   ',N'쿵쾅쿵쾅',N'두근두근',N'소곤소곤',N'1',N'02',N'Y',N'S'),
	 (427,N'01',N'10',N'다음 빈칸에 어울리는 흉내 내는 말을 알맞게 나열한 것을 찾아 보세요.',N'발표를 하려고 일어서니, 가슴이 (        ), 얼굴이 (        ) 해서 다시 앉아버렸어.',N'후들후들-두근두근',N'데굴데굴-속닥속닥',N'반짝반짝-비틀비틀',N'쿵쾅쿵쾅-화끈화끈',N'4',N'02',N'Y',N'S'),
	 (427,N'01',N'11',N'몸이나 몸의 한 부분이 매우 오그라져 들어가거나 작아지다''는 뜻의 어휘는 무엇인가요?',NULL,N'납작하다',N'초조하다',N'움츠러들다',N'늘어나다',N'3',N'06',N'',N'S'),
	 (427,N'01',N'12',N'‘다른 사람들 앞에서 자신의 생각이나 의견을 말하는 것’을 뜻하는 말은 무엇인가요?',NULL,N'약속',N'발표',N'놀이',N'연습',N'2',N'06',N'',N'S'),
	 (428,N'01',N'01',N'주머니처럼 속이 빈 창자를 가진 동물을 뜻하는 말은 무엇인가요?',N'',N'봉생동물',N'동물농장',N'강장동물',N'포유동물',N'3',N'01',N'N',N'S'),
	 (428,N'01',N'02',N'히드라를 동물이라고 하는 이유는 무엇인가요?',N'',N'소리를 지른다.',N'아픔을 느낀다.',N'슬픔을 느낀다.',N'앞을 본다.',N'2',N'04',N'N',N'S'),
	 (428,N'01',N'03',N'눈비늘의 뜻은 무엇인가요?',N'',N'눈을 보호하는 비늘 조각',N'눈에 난 비늘',N'눈 안의 염증',N'비늘에 달린 눈',N'1',N'07',N'N',N'S'),
	 (428,N'01',N'04',N'겨울에 살아남기 위해 비늘 조각을 만들어 영양분을 저장하며, 독립하는 눈을 가진 식물은 무엇인가요?',N'',N'마늘',N'양파',N'대파',N'고구마',N'2',N'03',N'N',N'S'),
	 (428,N'01',N'05',N'파브르가 가장 많이 관찰한 식물은 무엇인가요?',N'',N'감자',N'고구마',N'무',N'당근',N'1',N'01',N'N',N'S');
