	 (428,N'01',N'06',N'물관과 체관이 만들어지면서 생기는 것은 무엇인가요?',N'',N'뿌리',N'색소침착',N'나이테',N'줄기',N'3',N'04',N'N',N'S'),
	 (428,N'01',N'07',N'파브르가 모든 식물은 그 자체로 완전하다고 말한 이유가 아닌 것은 무엇인가요?',N'',N'식물은 많은 것을 배울 수 있는 존재이기 때문에',N'식물들은 더 이상 발전하지 않고 옛날 모습 그대로이기 때문에',N'식물로 인해서 지구가 얻는 것이 많기 때문에',N'식물은 자연 속에서 제 역할을 다하고 있기 때문에',N'2',N'03',N'N',N'S'),
	 (428,N'01',N'08',N'덩굴식물의 특징이 아닌 것은 무엇인가요?',N'',N'덩굴식물은 줄기의 모양을 절대 바꿀 수 없다.',N'덩굴식물은 이웃 식물의 도움 없이는 줄기를 뻗지 못한다.',N'덩굴식물은 기어오르거나 휘감아 오르는 식물이다.',N'덩굴식물은 햇빛을 받기 위해 주변의 나무나 구조물을 이용해 위로 자란다.',N'1',N'01',N'N',N'S'),
	 (428,N'01',N'09',N'다음 괄호 안에 들어갈 표현으로 적절한 것은 무엇인가요?',N'몸은 젤리처럼 (  )한데, 몹시 연약하다.',N'찰랑찰랑',N'부릉부릉',N'말랑말랑',N'부스스',N'3',N'02',N'Y',N'S'),
	 (428,N'01',N'10',N'다음 보기를 참고하여 파브르의 성격으로 알맞은 것을 고르세요',N'- 벌레의 생김새를 관찰한다
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (429,N'01',N'01',N'파블로 아버지의 직업은 무엇이었나요?',NULL,N'화가이자 미술 선생님',N'음악가이자 음악 선생님',N'운동선수이자 체육 선생님',N'작가이자 국어 선생님',N'1',N'01',N'',N'S'),
	 (429,N'01',N'02',N'아버지는 파블로가 자신의 그림을 너무 잘 그리게 되자 어떻게 행동했나요?',NULL,N'새로운 그림을 창작했어요.',N'미술학교에 데려갔어요.',N'그림도구를 전부 물려주었어요.',N'파블로에게 그림을 그만두게 했어요.',N'3',N'01',N'',N'S'),
	 (429,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 파블로는 흙으로 도자기 만드는 법을 배웠어요.
(2) 파블로는 조국에서 일어난 전쟁에 충격을 받고 한달만에 작품을 완성했어요.
(3) 프랑스 파리로 떠나서 ''인상파'' 화가들의 작품을 보았어요. ',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(3)-(1)-(2)',N'(1)-(2)-(3)',N'1',N'03',N'Y',N'S'),
	 (429,N'01',N'04',N'친구 카를로스가 죽은 뒤, 파블로가 파란색 그림을 많이 그리게 된 이유는 무엇인가요?',NULL,N'파란색을 가장 좋아했기 때문에',N'물감이 파란색만 있었기 때문에',N'사람들이 파란색 그림을 원했기 때문에',N'슬픈 마음을 그림에 담았기 때문에',N'4',N'03',N'',N'S'),
	 (429,N'01',N'05',N'파블로에게서 배울 점은 무엇인가요?',NULL,N'예술을 사랑하고 열정적으로 작품활동을 했어요.',N'전쟁중에도 그림만 그렸어요.',N'공부를 정말 좋아했어요. ',N'다른 사람들의 말을 듣지 않았어요.',N'1',N'04',N'',N'S'),
	 (429,N'01',N'06',N'다음 중 파블로의 생각과 가장 잘 어울리는 것은 무엇인가요?',NULL,N'그림은 정답대로 그려야 해요.',N'새로운 방법으로 그려 보는 것도 중요해요.',N'남들과 항상 똑같이 그려야 해요.',N'한 가지 방법만 써야 해요.',N'2',N'04',N'',N'S'),
	 (429,N'01',N'07',N'친구 카를로스가 죽은 뒤, 파블로의 마음은 어땠을까요?',NULL,N'황당하고 화나요.',N'슬프고 괴로워요.',N'언짢고 실망스러워요.',N'자랑스럽고 뿌듯해요.',N'2',N'05',N'',N'S'),
	 (429,N'01',N'08',N'사람들이 파블로의 새로운 그림을 처음 보았을 때의 마음은 무엇이었을까요?',NULL,N'지루함',N'화남',N'걱정됨',N'놀람',N'4',N'05',N'',N'S'),
	 (429,N'01',N'09',N'다음 문장에 어울리는 표현을 찾아보세요.',N'파블로가 작업한 작품을 보여주자 다들 놀라서 입을 다물지 못했어요.',N'우지끈',N'화들짝',N'우수수',N'어슬렁',N'2',N'02',N'Y',N'S'),
	 (429,N'01',N'10',N'다음 빈칸에 어울리는 표현을 찾아보세요.',N'막냇동생이 큰 병에 걸려 (        ) 앓았어요.',N'시름시름',N'사뿐사뿐',N'성큼성큼',N'살랑살랑',N'1',N'02',N'Y',N'S');
