	 (434,N'01',N'04',N'네로의 소원은 무엇이었나요?',NULL,N'우유배달을 그만하는 것',N'학교에 다니는 것',N'대성당 안에 있는 그림을 보는 것',N'부자가 되는 것',N'3',N'03',NULL,N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (434,N'01',N'05',N'이야기의 마지막에서 네로와 파트라슈는 어디에서 함께 있었나요?',NULL,N'시장 광장',N'아로아의 집',N'성당 ',N'숲속 오두막',N'3',N'03',NULL,N'S'),
	 (434,N'01',N'06',N'작가는 네로의 따뜻한 마음을 어떻게 표현했나요?',NULL,N'네로가 파트라슈를 돌보는 모습',N'네로가 혼자 그림을 그리는 모습',N'네로 시장에 가는 장면',N'네로가 친구를 위로하는 장면',N'1',N'02',NULL,N'S'),
	 (434,N'01',N'07',N'이야기에서 코제츠 영감 어떤 인물로 표현되었나요?',NULL,N'따뜻하고 인정이 많다',N'욕심이 많은 심술쟁이',N'겉으로는 따뜻하나 속은 냉정하다',N'재치 있는 농부',N'2',N'02',NULL,N'S'),
	 (434,N'01',N'08',N'''어림없다''는 무슨 뜻인가요?',N'하지만 우리 형편에는 어림도 없단다.',N'확실하다',N'가능하다',N'불가능하다',N'괜찮다',N'3',N'06',N'Y',N'S'),
	 (434,N'01',N'09',N'''끼니''와 유사한 단어는 무엇인가요?',N'우유배달을 해서 번 돈으로 끼니를 잇는 어려운 형편이었기 때문에 그럴 만한 돈이 없었습니다.',N'밥',N'군것질',N'간식',N'점심',N'1',N'06',N'Y',N'S'),
	 (434,N'01',N'10',N'<플랜더스의 개>의 배경이 되는 나라는 어디인가요?',NULL,N'벨기에',N'인도',N'러시아',N'프랑스',N'1',N'07',NULL,N'S'),
	 (434,N'01',N'11',N'네로가 보고싶어 하는 그림은 누가 그린 것인가요?',NULL,N'모네',N'루벤스',N'다빈치',N'반 고흐',N'2',N'07',NULL,N'S'),
	 (434,N'01',N'12',N'네로는 힘든 상황에서도 그림을 그리는 꿈을 포기하지 않았어요. 이 모습에서 배울 점은 무엇인가요?',NULL,N'힘들면 꿈을 바꾸는 것이 좋다',N'노력과 끈기가 중요하다는 것',N'꿈은 아무 소용이 없다는 것',N'포기하는 것이 더 현명하다',N'2',N'04',NULL,N'S'),
	 (435,N'01',N'01',N'제페토 할아버지는 나무인형을 만들어 어떤 이름을 지어주었나요?',NULL,N'피터팬',N'피노키오',N'알라딘',N'신밧드',N'2',N'01',N'',N'S'),
	 (435,N'01',N'02',N'피노키오는 돈 대신 무엇을 맡기고 극장에 갔나요?',NULL,N'가방',N'신발',N'책',N'모자',N'3',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (435,N'01',N'03',N'피노키오가 겪은 일을 순서대로 연결한 것을 찾아보세요. ',N'(1) 강도들은 피노키오를 나무에 매달았어요.
(2) 상어 뱃속에서 할아버지를 만났어요.
(3) 장난감 나라에서 시간 가는 줄 모르고 놀았어요',N'(1)-(2)-(3)',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (435,N'01',N'04',N'피노키오의 코가 길어지는 까닭은 무엇인가요?',NULL,N'손으로 코를 만졌기 때문에',N'인사를 많이 했기 때문에',N'달리기를 많이 했기 때문에',N'거짓말을 했기 때문에',N'4',N'03',N'',N'S'),
	 (435,N'01',N'05',N'파란머리 요정이 다음과 같이 말한 까닭은 무엇일까요? ',N'“피노키오! 넌 정말 마음씨가 착하구나”',N'할아버지를 돕고 공부를 열심히 했기 때문에 ',N'극장 주인에게 인사를 잘했기 때문에',N'강도에게 금화를 주었기 때문에',N'친구와 놀기만 했기 때문에',N'1',N'04',N'Y',N'S'),
	 (435,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점은 무엇인가요?',NULL,N'거짓말을 잘하면 도움이 돼요.',N'정직하고 착하게 살아야 해요.',N'재미있는 곳만 찾아다녀야 해요.',N'돈이 가장 중요해요.',N'2',N'04',N'',N'S'),
	 (435,N'01',N'07',N'피노키오는 어떤 마음일까요?',N'“제발 살려 주세요. 아빠한테 가야 해요. 흑흑”',N'슬프고 두려움',N'기쁘고 반가움',N'놀랍고 궁금함',N'신나고 즐거움',N'1',N'05',N'Y',N'S'),
	 (435,N'01',N'08',N'강도를 만나 쓰러진 피노키오 앞에 파란 머리 요정이 나타났을 때, 피노키오의 마음은 어땠을까요?',NULL,N'화가 나고 짜증 났어요.',N'신나고 즐거웠어요.',N'안심되고 고마웠어요.',N'속상하고 억울했어요.',N'3',N'05',N'',N'S'),
	 (435,N'01',N'09',N'빈칸에 어울리는 알맞은 흉내 내는 말을 찾아 보세요',N'인형의 눈이 (        ) 쳐다보고 입은 (     ) 웃었어요.',N'말똥말똥 - 깔깔',N'뒤뚱뒤뚱 - 쑥쑥',N'폴짝폴짝 - 쭉쭉',N'성큼성큼 - 슥슥',N'1',N'02',N'Y',N'S'),
	 (435,N'01',N'10',N'빈칸에 어울리는 알맞은 흉내 내는 말을 찾아 보세요',N'다리와 발까지 다 만들자 (        ) 뛰어다녔지요.',N'살랑살랑',N'뚝딱뚝딱',N'흐물흐물',N'폴짝폴짝',N'4',N'02',N'Y',N'S'),
	 (435,N'01',N'11',N'납작한 물건이나 돈을 셀 때 쓰던 단위는 무엇인가요?',NULL,N'닢',N'입',N'말',N'개',N'1',N'06',N'',N'S'),
	 (435,N'01',N'12',N'‘거짓말을 하지 않고 바르게 행동하는 마음’을 뜻하는 말은 무엇인가요?',NULL,N'욕심',N'정직',N'장난',N'걱정',N'2',N'06',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (436,N'01',N'01',N'피터 팬은 무엇을 찾기 위해 웬디의 집으로 왔나요?',NULL,N'그림자',N'강아지 ',N'단추 ',N'모자',N'1',N'01',N'',N'S'),
	 (436,N'01',N'02',N'무사히 네버랜드에 도착한 웬디는 아이들에게 무엇이 되어 주었나요?',NULL,N'의사',N'선생님 ',N'엄마',N'누나',N'3',N'01',N'',N'S'),
	 (436,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 웬디와 이이들이 해적들에게 잡혀갔어요. 
(2) 피터 팬과 아이들은 하늘을 날아 네버랜드에 도착했어요.
(3) 웬디와 동생들은 다시 집으로 돌아와 엄마 아빠를 만났어요.',N' (1)-(3)-(2) ',N'(3)-(1)-(2)',N'(2)-(1)-(3) ',N'(2)-(3)-(1)',N'3',N'03',N'Y',N'S'),
	 (436,N'01',N'04',N'다음 중 이야기에서 가장 먼저 일어난 일은 무엇인가요?',NULL,N'웬디가 엄마가 되었어요.',N'피터 팬이 그림자를 찾으러 왔어요.',N'후크 선장이 악어에게 쫓겼어요.',N'웬디가 집으로 돌아왔어요.',N'2',N'03',N'',N'S'),
	 (436,N'01',N'05',N'피터 팬이 아이들을 네버랜드로 데려간 이유로 알맞은 것은 무엇인가요?',NULL,N'공부를 시키려고',N'어른이 되게 하려고',N'해적을 잡게 하려고',N'자유롭고 즐겁게 놀게 하려고',N'4',N'04',N'',N'S'),
	 (436,N'01',N'06',N'<피터 팬> 이야기를 읽고 느낀 점을 잘못 말한 것을 찾아보세요.',NULL,N'후크 선장이 결국 악어의 밥이 된 걸 보니 고악한 마음 때문에 벌을 받은 것 같아.',N'피터 팬이 아이들을 데리고 간 네버랜드는 정말 환상적인 나라일 것 같아. ',N'피터 팬이 영원히 자라지 않는 아이로 있고 싶다고 한걸 보니 정말 어른스러워. ',N'모험과 상상은 즐거운 경험이 될 수 있다는 생각이 들어.',N'3',N'04',N'',N'S'),
	 (436,N'01',N'07',N'웬디와 아이들은 어떤 마음이었을까요?',N'“너희들은 이제 죽은 목숨이나 마찬가지야.”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (436,N'01',N'11',N'‘현실에는 없지만 상상 속에서만 있는 세계’를 가리키는 말은 무엇인가요?',NULL,N'일기',N'학교',N'환상',N'약속',N'3',N'06',N'',N'S'),
	 (436,N'01',N'12',N'‘새로운 곳으로 가서 신기한 일을 겪는 것’을 뜻하는 말은 무엇인가요?',NULL,N'모험',N'약속',N'걱정',N'습관',N'1',N'06',N'',N'S'),
	 (437,N'01',N'01',N'피터팬의 이야기를 지은 작가 제임스 매튜 배리는 어느 나라 사람인가요?',NULL,N'스코틀랜드',N'잉글랜드',N'네버랜드',N'에버랜드',N'1',N'07',N'',N'S'),
	 (437,N'01',N'02',N'웬디의 집에서 세 아이를 돌봐 주는 유모는 누구였나요?',NULL,N'나이가 많은 아주머니',N'웬디 또래의 소녀',N'’나나‘라는 이름의 영리한 개',N'가족이 고용한 집사',N'3',N'01',N'',N'S'),
	 (437,N'01',N'03',N'팅커 벨은 피터 팬에게 그림자가 어디에 있다고 말했나요?',NULL,N'옷장 서랍 속',N'창고 구석',N'방 한가운데',N'거실의 화분',N'1',N'01',N'',N'S'),
	 (437,N'01',N'04',N'후크는 잘린 오른손 대신 무엇을 달았나요?',NULL,N'나무 손잡이',N'쇠갈고리',N'돌 방망이',N'의족',N'2',N'02',N'',N'S'),
	 (437,N'01',N'05',N'추장의 딸 ’릴리‘에 대한 설명으로 알맞지 않은 것은 무엇인가요?',NULL,N'아주 용감함',N'몸이 약하고 조용함',N'모든 인디언들이 그녀를 아내로 맞고 싶어함',N'튼튼하고 건강함',N'2',N'04',N'',N'S'),
	 (437,N'01',N'06',N'투틀즈는 왜 웬디에게 화살을 쏘았나요?',NULL,N'팅커 벨이 피터 팬의 명령이라고 거짓말을 해서',N'웬디가 전부터 마음에 들지 않아서',N'피터 팬이 직접 웬디를 쏘라고 말했기 때문에',N'웬디가 해적이라고 착각했기 때문에',N'1',N'03',N'',N'S'),
	 (437,N'01',N'07',N' 바위를 오르던 피터 팬이 후크 선장에게 손을 내밀어 끌어올려준 이유는 무엇인가요?',NULL,N'자신이 더 높은 곳에 있는 상태에서 공격하는 것은 정당하지 않아서',N'후크 선장이 자신을 구해줬던 적이 있어서',N'후크 선장이 도와달라고 울어서',N'후크 선장이 보물을 주겠다고 약속했기 때문에',N'1',N'04',N'',N'S'),
	 (437,N'01',N'08',N'다음과 같은 상황에서 피터의 마음은 어땠을까요?',N'이제 바위 위에는 피터만 남았습니다. 바위는 금방 물에 잠길 듯이, 피터가 겨우 발을 디딜 정도밖에 남지 않았습니다.',N'겁이 남',N'설렘',N'기대됨',N'기쁨',N'1',N'07',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (437,N'01',N'09',N'인디언들이 아이들 편이 된 이유는 무엇일까요?',NULL,N'웬디가 인디언들에게 맛있는 음식을 해줘서',N'피터 팬이 추장의 딸 타이거 릴리와 결혼해서',N'피터 팬이 추장의 딸 타이거 릴리를 해적의 손에서 구해줘서',N'아이들이 인디언 마을을 지켜주는 신호 불을 밝혀 주었기 때문에',N'3',N'03',N'',N'S'),
	 (437,N'01',N'10',N'다음 중 ’섬뜩하다‘의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'갑자기 소름이 끼치도록 무섭고 끔찍하다.',N'눈을 크게 뜨고 흰자위를 한 번 번득 움직이는 모양',N'조금도 모자람이 없을 정도로 넉넉하여 만족하다.',N'필요한 양이나 기준에 미치지 못해 충분하지 아니하다',N'1',N'02',N'',N'S'),
	 (437,N'01',N'11',N'다음이 설명하는 단어는 무엇일까요?',N'“좋아, 스타키! 네가 (      )해서 반란을 일으킬 생각인가?” 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (438,N'01',N'07',N'하루는 저수지에 가서 누구를 만났을까요?',N'',N'달맞이꽃',N'대추나무',N'엄마',N'동네 친구',N'3',N'07',N'',N'S'),
	 (438,N'01',N'08',N'미야는 자신을 구해주지 않은 미요에게 어떻게 말했을까요?',N'',N'너도 많이 무서웠지. 나는 이해해.',N'하여간 넌 겁쟁이야. 이제 난 너랑 안 놀 거야!',N'네가 물에 빠졌다면 나는 너를 구하러 뛰어들었을 거야.',N'널 용서할 수 없어.',N'2',N'02',N'',N'S'),
	 (438,N'01',N'09',N'하루가 큰 개에게 용기를 긁어모아 어렵사리 한 말은 무엇인가요?',N'',N'“너를 내가 무찌르고 말거야!”',N'“저, 저수지로 가고 싶어요.”',N'“너만 없으면 좋을텐데!”',N'“나랑 친구하자!”',N'2',N'01',N'',N'S'),
	 (438,N'01',N'10',N'결과에 맞는 원인을 찾아보세요.',N'고양이라면 당연히 하지 않던 일들을 아기 고양이들이 하나둘 시작했다.',N'미요가 헤엄 기술을 배워 아기 고양이 동글이를 구했기 때문에',N'한 고양이가 손톱을 짧게 잘랐기 때문에',N'들쥐와 사귀는 고양이가 나타났기 때문에',N'먹이를 많이 먹었기 때문에',N'1',N'03',N'Y',N'S'),
	 (438,N'01',N'11',N'다음이 설명하는 단어는 무엇일까요?',N'남에게 굽히지 아니하고 자신의 품위를 스스로 지키는 마음.',N'자만심',N'질투심',N'자존심',N'교만심',N'3',N'06',N'Y',N'S'),
	 (438,N'01',N'12',N'다음 중 ‘줄행랑’이 의미하는 바는 무엇일까요?',N'',N'술에 거나하게 취함',N'도망을 속되게 이르는 말',N'성공적으로 끝남',N'친구를 속이는 말',N'2',N'06',N'',N'S'),
	 (439,N'01',N'01',N'연필은 무엇을 하고 싶다고 했나요?',NULL,N'낙서',N'그리기',N'공부',N'색칠',N'1',N'01',N'',N'S'),
	 (439,N'01',N'02',N'연필심은 ''흑연''이라는 까만 가루와 무엇을 섞어서 만드나요?',NULL,N'고무',N'소금',N'점토',N'설탕',N'3',N'01',N'',N'S'),
	 (439,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 마루는 숙제를 마치고 밖으로 놀러 나갔습니다.
(2) 학용품들은 낙서를 멈추지 않았습니다.
(3) 학용품들은 눈을 꼭 감고 모르는 척 했습니다.',N'(2)-(3)-(1)',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'(1)-(3)-(2)',N'2',N'03',N'Y',N'S'),
	 (439,N'01',N'04',N'볼펜이 쓴 것을 수정액과 수정테이프로 지울 수 있는 이유는 무엇인가요?',NULL,N'종이를 문질러서 지우기 때문이에요.',N'종이를 벗겨 내서 지우기 때문이에요.',N'종이 위를 덮어서 지우기 때문이에요.',N'종이를 새것으로 바꿔 주기 때문이에요.',N'3',N'03',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (439,N'01',N'05',N'평소에 학용품을 어떻게 사용하면 좋을까요?',NULL,N'함부로 사용하지 않고 아껴 써요.',N'조금 더러워지면 버리고 새 것으로 사요.',N'망가진 학용품을 계속 사용해요.',N'친구 것과 바꿔 써요.',N'1',N'04',N'',N'S'),
	 (439,N'01',N'06',N'이 책이 우리에게 알려 주고 싶은 중요한 점은 무엇인가요?',NULL,N'학용품은 새것이 가장 좋아요.',N'학용품의 원리를 알면 더 잘 사용할 수 있어요.',N'학용품은 모두 같은 역할을 해요.',N'학용품은 많이 가질수록 좋아요.',N'2',N'04',N'',N'S'),
	 (439,N'01',N'07',N'종이는 어떤 마음일까요?',N'"못 지운다고! 볼펜 네 잉크는 종이 속까지 스며든단 말이야. 그러니까 내가 지우기 힘들어. 이렇게 낙서해 버리면 어떡해......"',N'화가 나고 걱정돼요.',N'외롭고 속상해요.',N'기쁘고 아쉬워요.',N'신나고 들떠요.',N'1',N'05',N'Y',N'S'),
	 (439,N'01',N'08',N'학용품들이 자신의 장점과 특징을 이야기할 때의 마음은 어떨까요?',NULL,N'슬프고 외로워요.',N'화가 나고 짜증 나요.',N'겁이 나고 무서워요.',N'뿌듯하고 자신 있어요.',N'4',N'05',N'',N'S'),
	 (439,N'01',N'09',N'빈칸에 들어갈 알맞은 표현을 찾아보세요.',N'잠시 뒤, 어디선가 (         ) 목소리가 들려왔습니다.',N'철썩철썩',N'끈적끈적',N'울퉁불퉁',N'소곤소곤',N'4',N'02',N'Y',N'S'),
	 (439,N'01',N'10',N'빈칸에 들어갈 알맞은 표현을 찾아보세요.',N'공책에 쓴 일기를 지우개로 (      ) 지웠어요.',N'쓱쓱',N'툭툭',N'휙휙',N'쾅쾅',N'1',N'02',N'Y',N'S'),
	 (439,N'01',N'11',N'요철''의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'매끄러운 것',N'오목하고 볼록한 것',N'구멍이 난 것',N'딱딱한 것',N'2',N'06',N'',N'S'),
	 (439,N'01',N'12',N'다음 빈칸에 들어갈 알맞은 단어를 찾아 보세요.',N'비슷한 색을 나란히 동그랗게 배열하면 빨간색과 청록색이 서로 반대쪽에 있게 돼. 이런 관계를 (    )이라고 해.',N'색칠',N'회색',N'갈색',N'보색',N'4',N'06',N'Y',N'S'),
	 (440,N'01',N'01',N'태종이 충녕군에게 임금 자리를 물려준 이유는 무엇이었나요?',NULL,N'백성을 아끼는 마음을 귀하게 여겨서',N'낮이나 밤이나 책을 읽어서',N'큰 아들이 마음에 들지 않아서',N'전쟁을 잘했기 때문에',N'1',N'01',N'',N'S'),
	 (440,N'01',N'02',N'세종대왕이 백성들을 위해 한 일로 알맞은 것은 무엇인가요?',NULL,N'중국의 문자를 그대로 사용하도록 했어요.',N'농사를 짓지 못하게 했어요.',N'훈민정음을 만들었어요.',N'글자를 아는 사람만 글을 쓰게 했어요.',N'3',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (440,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열된 것을 찾으세요',N'(1) 장영실이 열심히 연구할 수 있도록 도왔어요.
(2) 인재들을 집현전으로 불러모았어요.
(3) 백성들을 위해 훈민정음을 발명했어요.',N'(1)-(2)-(3)',N'(2)-(1)-(3)',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'2',N'03',N'Y',N'S'),
	 (440,N'01',N'04',N'다음 중 세종대왕의 생각과 행동이 잘 이어진 것은 무엇인가요?',NULL,N'글은 어려워야 한다 → 한자만 사용했어요.',N'백성이 힘들다 → 백성을 돌보는 제도를 만들었어요.',N'학자가 필요 없다 → 집현전을 없앴어요.',N'발명은 위험하다 → 연구를 금지했어요.',N'2',N'03',N'',N'S'),
	 (440,N'01',N'05',N'우리 글자를 만든 세종대왕에게 백성들은 어떤 말을 해주고 싶을까요?',NULL,N'쉽고 편한 글자를 만들어줘서 고마워요.',N'한자와 같이 사용해서 번거로워요.',N'사용하기까지 오래걸려서 아쉬워요.',N'글을 못 쓰게 해서 속상해요.',N'1',N'04',N'',N'S'),
	 (440,N'01',N'06',N'세종대왕이 글자를 만든 가장 큰 이유는 무엇이라고 생각하나요?',NULL,N'학자들을 칭찬받게 하려고',N'다른 나라보다 잘 보이려고',N'왕의 힘을 보여주려고',N'백성들이 글을 쉽게 쓰게 하려고',N'4',N'04',N'',N'S'),
	 (440,N'01',N'07',N'세종대왕은 어떤 마음이었을까요?',N'우리문자가 백성들에게 알려지기까지는 시간이 꽤 걸렸어요. 학자들의 반대가 심했기 때문이에요.',N'안타까움',N'외로움',N'두려움',N'부끄러움',N'1',N'05',N'Y',N'S'),
	 (440,N'01',N'08',N'백성들이 글을 읽고 쓸 수 있게 되었을 때 세종대왕은 어떤 마음이었을까요?',NULL,N'후회하는 마음',N'서운하고 속상한 마음',N'기쁘고 뿌듯한 마음',N'무섭고 두려운 마음',N'3',N'05',N'',N'S'),
	 (440,N'01',N'09',N'빈칸에 어울리는 흉내내는 말을 찾아보세요.',N'부끄러워서 가슴이 (     ) 뛰었어요.',N'덩실덩실',N'으실으실',N'콩닥콩닥',N'느릿느릿',N'3',N'02',N'Y',N'S'),
	 (440,N'01',N'10',N'다음 중 기쁜 마음에 춤을 추는 모습을 가장 잘 표현한 말은 무엇인가요?',NULL,N'주룩주룩',N'덩실덩실',N'느릿느릿',N'콩닥콩닥',N'2',N'02',N'',N'S'),
	 (440,N'01',N'11',N'까막눈''의 의미를 찾아보세요.',NULL,N'글자를 깨우친 사람',N'글자를 읽고 쓰지 못하는 사람',N'눈동자가 유난히 까만 사람',N'밤에만 보는 사람',N'2',N'06',N'',N'S'),
	 (440,N'01',N'12',N'‘인재’의 뜻으로 알맞은 것은 무엇인가요?',NULL,N'힘이 센 사람',N'나이가 많은 사람',N'책을 많이 가진 사람',N'나라에 도움이 되는 재주 있는 사람',N'4',N'06',N'',N'S');
