INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (444,N'01',N'02',N'용왕의 코에는 무엇이 박혀 있었나요?',NULL,N'플라스틱 빨대',N'비닐봉지',N'종이 빨대',N'나뭇가지',N'1',N'01',N'',N'S'),
	 (444,N'01',N'03',N'일이 일어난 차례대로 올바르게 나열한 것을 찾으세요.',N'(1) 할머니는 미역 밭에서 많은 전복을 발견했어요.
