INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (448,N'01',N'04',N'오누이가 엄마가 호랑이인 것을 알고는 뒷간에 간다고 했습니다. 뒷간은 오늘날 무엇을 가리키는 것인가요?',N'',N'부엌',N'화장실',N'거실',N'다락방',N'2',N'07',N'',N'S'),
	 (448,N'01',N'05',N'나무 위로 도망친 오누이가 호랑이에게 들킨 이유는 무엇인가요?',N'',N'허리가 아파 기지개를 펴다 오누이를 우연히 보게 되어서',N'호랑이가 궁둥이 춤을 추는 모습이 우스워 오누이가 웃어 버렸기 때문에',N'누이동생이 숨바꼭질을 하는 줄 알고 “나 여기 있다. 호랑아.”라고 말해버렸기 때문에',N'나뭇가지가 부러져서',N'2',N'04',N'',N'S'),
	 (448,N'01',N'06',N'호랑이가 오누이에게 나무 꼭대기에 어떻게 올라갔냐고 물었을 때, 처음 한 대답은 무엇인가요?',N'',N'참기름을 바르고 올라왔다고 함',N'들기름을 바르고 올라왔다고 함',N'도끼를 얻어다가 찍어서 올라왔다고 함.',N'밧줄을 타고 올라왔다고 함',N'1',N'01',N'',N'S'),
	 (448,N'01',N'07',N'이 책에서 말하는, 사람들이 해를 쳐다볼 때 바늘로 찌르는 것처럼 눈이 시린 이유는 무엇인가요?',N'',N'햇빛이 너무 강해서',N'사람들이 해를 쳐다보면 누이동생이 바늘로 찌르기 때문에',N'해를 똑바로 쳐다보는 사람들이 건방지다고 생각해서',N'해가 된 누이동생은 사람들이 자기를 쳐다보는 게 부끄러워서',N'4',N'04',N'',N'S'),
	 (448,N'01',N'08',N'오누이가 호랑이의 손이 꺼끌꺼끌하다고 했을 때, 호랑이가 댄 핑계는 무엇인가요?',N'',N'핸드크림을 살 돈이 없어서 손이 거칠다',N'부잣집에서 베를 매느라 풀이 묻어 말라붙었다',N'가시덤불에 찔려 피가 나서 손이 꺼끌하다',N'나무를 깎아서',N'2',N'03',N'',N'S'),
	 (448,N'01',N'09',N'호랑이가 아기를 잡아먹는 소리를 듣고 오누이가 자기도 달라고 했을 때, 호랑이가 던져준 것은 무엇인가요?',N'',N'아기의 다리',N'볶은 콩',N'아기의 손가락',N'떡 조각',N'3',N'01',N'',N'S'),
	 (448,N'01',N'10',N'호랑이가 이것을 심는 밭에 떨어져 이것의 색깔이 빨개졌다고 합니다. 이것은 무엇인가요?',N'',N'팥밭',N'옥수수밭',N'고구마밭',N'수수밭',N'4',N'07',N'',N'S'),
	 (448,N'01',N'11',N'어머니가 주인집에 베를 매 주고는 받은 수수팥떡을 품삯이라고 합니다. 품삯의 뜻으로 알맞은 것은 무엇인가요?',N'',N'품을 사고판 대가로 주거나 받는 돈이나 물건',N'힘든 일을 서로 도와주고 품을 지고 받는 일',N'개인이 자지구레하게 쓰는 돈',N'물건을 빌린 대가',N'1',N'06',N'',N'S'),
	 (448,N'01',N'12',N'‘발을 가까이 자주 떼며 급히 걷는 걸음.’을 말하며, 다음 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?',N'어머니는 배곯고 있을 어린것들 생각에 수수팥떡을 이고 (       )을 쳤어.',N'가재걸음',N'단걸음',N'종종걸음',N'게걸음',N'3',N'06',N'Y',N'S'),
	 (449,N'01',N'01',N'해와 바람은 누구를 내려다보고 있었나요? ',NULL,N'걸어가는 남자 ',N'기어가는 아기',N'뛰어가는 여자',N'말을 탄 부부',N'1',N'01',N'',N'S');
