	 (450,N'01',N'11',N'슬기아빠의 직장을 잃은 일 따윈 왜 아무것도 아닌 것처럼 여겨졌나요?',N'',N'하늘이 아빠 이야기를 듣고',N'슬기 엄마가 힘들게 일하는 것을 보고',N'슬기가 열심히 공부하는 것을 보고',N'슬기가 큰 병에 걸렸기 때문에',N'1',N'04',N'N',N'S'),
	 (450,N'01',N'12',N'가지런하지 않고 앞쪽으로 툭 튀어나온 앞니를 무엇이라 하나요?',N'',N'송곳니',N'덧니',N'뻐드렁니 ',N'어금니',N'3',N'06',N'N',N'S'),
	 (450,N'01',N'13',N'엄마의 뻐드렁니 때문에 피해만 보는 게 아닌 것 같다고 느낀 이유는 무엇인가요?',N'',N'엄마와 아빠를 이어주었기 때문에',N'뻐드렁니로 사람들을 웃길 수 있기 때문에',N'뻐드렁니가 없었으면 엄마가 더 큰 소리로 야단칠 수도 있었기 때문에',N'뻐드렁니는 딱딱한 채소를 씹을 때 도움이 되기 때문에',N'2',N'07',N'N',N'S'),
	 (450,N'01',N'14',N'다음 중 ''어느 한 지방에서만 쓰는, 표준어가 아닌 말''의 의미를 지닌 단어로만 묶인 것은?',N'',N'사투리, 서울말',N'도시말, 향토어',N'지역어, 표준어',N'방언, 시골말',N'4',N'07',N'N',N'S'),
	 (450,N'01',N'15',N'할머니가 도섭이에게 비루먹은 당나귀 같다고 한 이유가 아닌 것은 무엇인가요?',N'',N'친구를 괴롭혀서',N'얼굴에 마른버짐이 피고 비적 말라서',N'키가 작아서',N'부당한 일을 당해도 항의하지 못해서',N'1',N'03',N'N',N'S'),
	 (451,N'01',N'01',N'영민이가 승호에게 화가 난 이유는 무엇인가요?',N'',N'승호가 영민이를 계속 놀려서',N'승호가 실수로 테니스 경기에서 점수를 내주는 바람에',N'승호가 영민이와 한 약속을 지키지 않아서',N'승호가 아기 참새를 몰래 풀어줘서',N'2',N'01',N'',N'S'),
	 (451,N'01',N'02',N'어떤 현상이나 실체가 없어졌거나 지나간 뒤에 남은 자국이나 자취를 뜻하는 단어는 무엇인가요?',N'',N'산적',N'기적',N'흔적',N'표적',N'3',N'07',N'',N'S'),
	 (451,N'01',N'03',N'빈칸에 들어갈 수 있는 말이 아닌 것은 무엇인가요?',N'승호는 아기 참새를 쥔 두 손을 높이 들고 (       ) 뛰며 놓아주었습니다.',N'폴짝',N'반짝',N'깡충',N'껑충',N'2',N'02',N'Y',N'S'),
	 (451,N'01',N'04',N'빈칸에 들어갈 수 있는 말은 무엇인가요?',N'차들이 아기 참새 옆으로 (           )하게 달려갑니다.',N'물렁물렁',N'쫄깃쫄깃',N'아슬아슬',N'반짝반짝',N'3',N'02',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (451,N'01',N'05',N'승호가 찻길로 뛰어든 이유는 무엇인가요?',N'',N'참새를 구하기 위해서',N'친구와 장난을 하기 위해서',N'모르는 아저씨가 쫓아와서',N'참새를 잡기 위해서',N'1',N'03',N'',N'S'),
	 (451,N'01',N'06',N'선생님께서 참새를 교실에 놓고 키우자고 한 이유는 무엇인가요?',N'',N'참새가 날지 못할 만큼 다쳐서',N'자연 속에서 자유롭게 살던 새는 새장에 넣어 키우면 죽기 쉬워서',N'참새를 가까이 두고 자주 보고 싶어서',N'아이들이 좋아할 것 같아서',N'2',N'03',N'',N'S'),
	 (451,N'01',N'07',N'다음 중 ‘유괴범’의 뜻으로 알맞은 것은 무엇인가요?',N'',N'남을 속여 불법으로 이익을 얻음으로써 성립하는 범죄. 또는 그런 죄를 지은 사람',N'남의 물건을 몰래 훔침으로써 성립하는 죄. 또는 그런 죄를 지은 사람',N'사람을 속여서 꾀어냄으로써 성립하는 범죄. 또는 그 범인',N'습관적으로 남을 속여 이득을 꾀하는 사람.',N'3',N'06',N'',N'S'),
	 (451,N'01',N'08',N'선생님과 승호, 여러 아이들이 저녁시간에 왜 교실에 돌아왔나요? ',N'',N'혼자 있을 아기 참새가 걱정이 되어서',N'저녁에 모이자고 약속해서',N'저녁에 학교에서 놀면 재미있을 것 같아서',N'참새에게 모이를 주기 위해서',N'1',N'04',N'',N'S'),
	 (451,N'01',N'09',N'아기 참새를 돌보는 첫 당번은 누구인가요?',N'',N'철수',N'영민이',N'선생님',N'승호',N'4',N'01',N'',N'S'),
	 (451,N'01',N'10',N'찻길로 뛰어든 승호를 사람들이 더는 나무라지 않은 이유는 무엇인가요?',N'',N'승호가 다쳤기 때문에',N'참새를 놓쳤기 때문에',N'참새를 구하려던 승호의 따뜻한 마음을 알아서',N'선생님이 대신 사과했기 때문에',N'3',N'04',N'',N'S'),
	 (451,N'01',N'11',N'다음이 설명하는 단어는 무엇인가요?',N'“잘 키워서 진짜 엄마한테 보내 줘야 하니까 이것이지.” 
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (452,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 제비는 왕자에게 입맞춤을 하고 발밑으로 떨어져버렸습니다.
(2) 사람들은 왕자의 심장을 죽은 제비가 있는 곳으로 던졌습니다.
(3) 제비는 왕자의 곁에 머물며 심부름을 했습니다.',N'(3)-(1)-(2) ',N'(2)-(1)-(3)',N'(1)-(3)-(2)',N'(3)-(2)-(1)',N'1',N'03',N'Y',N'S'),
	 (452,N'01',N'04',N'천사가 왕자의 납 심장과 죽은 제비를 가져간 이유는 무엇인가요?',NULL,N'가장 크고 눈에 잘 띄었기 때문에',N'사람들이 버리라고 했기 때문에',N'금과 보석처럼 반짝거렸기 때문에',N'그들의 따뜻한 마음이 도시에서 가장 귀한 것이었기 때문에',N'4',N'03',N'',N'S'),
	 (452,N'01',N'05',N'행복한 왕자에게 어떤 말을 해줄 수 있을까요?',NULL,N'“제비에게 은혜를 갚고 진정한 친구가 된 점이 정말 대단해요.”',N'“어려운 사람들에게 모든 것을 나누어 주고도 행복해하는 모습이 감동적이에요.”',N'“온몸이 보석과 금으로 되어 있다고 뽐내는 것은 잘못이에요.” ',N'"자기 자신만 생각하고 이기적으로 굴면 안 돼요."',N'2',N'04',N'',N'S'),
	 (452,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 알맞은 것은 무엇인가요?',NULL,N'아름다운 모습이 가장 중요해요.',N'어려운 사람을 보면 외면해야 해요.',N'겉모습보다도 다른 사람을 돕는 마음이 소중해요.',N'가진 것을 꼭 숨겨야 해요.',N'3',N'04',N'',N'S'),
	 (452,N'01',N'07',N'제비는 어떤 목소리로 말했을까요?',N'“그렇지만 눈을 뽑을 수는 없어요. 왕자님은 아무것도 못 보실 텐데요.”
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (453,N'01',N'01',N'표지판 청소부들이 자전거를 타고 떠나는 모습은 어땠나요?',N'',N'노란 병아리들이 어미 닭을 졸졸 따라가는 것 같다.',N'커다란 파란 새들이 떼 지어 둥지를 떠나는 것 같다.',N'초원의 사슴 무리가 사자에게 쫓기는 것 같다.',N'회색 늑대 무리가 산속으로 흩어지는 것 같다.',N'2',N'02',N'',N'S'),
	 (453,N'01',N'02',N'표지판 청소부 아저씨가 행복한 원인은 무엇일까요?',N'',N'표지판을 청소하는 일은 돈을 많이 벌 수 있어서',N'표지판은 닦지 않아도 깨끗하기 때문에',N'자기 직업을 사랑하고, 자기가 맡은 거리와 표지판들을 사랑해서',N'청소가 끝나면 여행을 갈 수 있어서',N'3',N'03',N'',N'S'),
	 (453,N'01',N'03',N'청소부 아저씨가 당황해서 ‘글루크’ 표지판을 다시 한 번 쳐다본 이유는 무엇인가요?',N'',N'표지판의 글자가 잘못 쓰여 있어서',N'표지판이 바람에 쓰러져 있어서',N'표지판이 너무 더러워서 ',N'문득 글루크라는 사람에 대해 아무것도 모른다는 생각이 들어서',N'4',N'04',N'',N'S'),
	 (453,N'01',N'04',N'청소부 아저씨가 공부하기 위해 종이에 쓴 이름들입니다. 이들의 직업은 무엇인가요?',N'글루크-모차르트-바그너-바흐-베토벤-쇼팽-하이든-헨델',N'음악가',N'미술가',N'건축가',N'시인',N'1',N'07',N'Y',N'S'),
	 (453,N'01',N'05',N'청소부 아저씨가 공부하기 위해 종이에 쓴 이름들입니다. 이들의 직업은 무엇인가요?',N'괴테-그릴파르처-만-바흐만-부슈-브레히트-실러-슈토름-케스트너',N'정치가',N'미술가',N'조각가',N'작가',N'4',N'07',N'Y',N'S'),
	 (453,N'01',N'06',N'지나가던 사람들이 청소부 아저씨의 파란 사다리를 올려보고 깜짝 놀란 이유는 무엇일까요?',N'',N'청소부가 시와 음악을 알아서',N'표지판이 매우 깨끗해서',N'청소부 아저씨가 사다리에서 떨어질 것만 같아서',N'사다리가 매우 높아서',N'1',N'04',N'',N'S'),
	 (453,N'01',N'07',N'청소부 아저씨가 책 속에서 발견했던 비밀들은 어땠나요?',N'',N'음악에서 발견했던 비밀들과 무척이나 달랐다.',N'전혀 흥미롭지 않았다.',N'음악에서 발견했던 비밀들과 무척이나 비슷했다.',N'음악과는 상관없는 이야기였다.',N'3',N'01',N'',N'S'),
	 (453,N'01',N'08',N'빈칸에 들어갈 말은 무엇일까요?',N'표지판이 (        ) 빛나면 비로소 일을 멈추고 쉬었어.',N'흔들흔들',N'반짝반짝',N'쿵쾅쿵쾅',N'살금살금',N'2',N'02',N'Y',N'S'),
	 (453,N'01',N'09',N'다음이 설명하는 단어는 무엇일까요?',N'포장을 풀어 플레이어를 꺼내 크리스마스트리 밑에 갖다 놓고, (     )하게 첫 번째 레코드판을 올려놓았어. 
