	 (453,N'01',N'11',N'다음이 설명하는 단어는 무엇일까요?',N'어떤 집단의 사람들에 대한 단순하고 지나치게 일반화된 생각들.',N'의식',N'존중',N'고정 관념',N'연민',N'3',N'06',N'Y',N'S'),
	 (453,N'01',N'12',N'청소부 아저씨가 다른 사람들을 생각해야 한다는 걸 깨달은 후 한 일은 무엇인가요?
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (454,N'01',N'09',N'허생의 아내가 허생에게 화를 낸 근본적인 까닭은 무엇인가요?',N'',N'글공부를 그만두겠다고 해서',N'먹고살 궁리를 하지 않아서',N'삯바느질이 하기 싫어서',N'공부에 재능이 없어서',N'2',N'03',N'N',N'S'),
	 (454,N'01',N'10',N'변대감이 처음보는 허생에게 돈을 빌려준 이유는 무엇인가요?',N'',N'허생에 말재주에 속아 넘어가서',N'허생의 당당한 태도에 기가 죽어서',N'허생이 남을 속이거나 배신할 사람이 아니고 믿음직스러워 보였기 때문에',N'허생이 유명한 사람이라는 것을 알아서',N'3',N'03',N'N',N'S'),
	 (454,N'01',N'11',N'소설 《도화원기》에 나오는 말로, 신선들이 살았다는 중국의 전설적인 곳을 뜻하는 말은 무엇인가요?',N'',N'유토피아',N'무릉도원',N'지상낙원',N'고산지대',N'2',N'06',N'N',N'S'),
	 (454,N'01',N'12',N'이리저리 제 마음대로 휘두르거나 다룬다''는 뜻의 사자성어는 무엇인가요?',N'',N'좌지우지(左之右之)',N'우왕좌왕(右往左往)',N'단도직입(單刀直入)',N'자수성가(自手成家)',N'1',N'06',N'N',N'S'),
	 (454,N'01',N'13',N'허생이 돈을 번 방법으로, ''물건 값이 오르기를 기다려 많은 양을 사둔 다음 오를 때까지 팔지 않고 보관해 두는 행위''를 뜻하는 말은 무엇인가요?',N'',N'매관매직(賣官賣職)',N'중개무역(仲介貿易)',N'매점매석(買占賣惜)',N'호시탐탐(虎視眈眈)',N'3',N'06',N'N',N'S'),
	 (454,N'01',N'14',N'재앙과 화가 바뀌어 오히려 복이 됨''을 뜻하는 사자성어는 무엇인가요?',N'',N'전화위복( 轉禍爲福)',N'추풍낙엽(秋風落葉)',N'노발대발(怒發大發)',N'파란만장(波瀾萬丈)',N'1',N'06',N'N',N'S'),
	 (454,N'01',N'15',N'이완이 허생을 처음 만나러 갈 때 가졌던 심정으로, ''인재를 맞기 위해 참을성 있게 노력한다''는 뜻의 고사성어는 무엇인가요?',N'',N'사면초가(四面楚歌)',N'삼고초려(三顧草廬)',N'과유불급(過猶不及)',N'군계일학(群鷄一鶴)',N'2',N'06',N'N',N'S'),
	 (455,N'01',N'01',N'새엄마는 아빠에게 왜 아이들을 숲에 버리자고 했나요?',NULL,N'새로운 아이가 태어나게 되어서',N'아이들이 장난이 너무 심해서',N'가난해서 먹을 것이 없어서',N'숲이 너무 예뻐서',N'3',N'01',N'',N'S'),
	 (455,N'01',N'02',N'숲속에 남게 된 헨젤과 그레텔은 무엇을 따라 다시 집으로 돌아왔나요?',NULL,N'유리조각  ',N'조약돌  ',N'모래알',N'나뭇잎',N'2',N'01',N'',N'S'),
	 (455,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 과자로 만든 집을 발견하고 허겁지겁 뜯어 먹었어요.
(2) 헨젤은 숲 속으로 가는 길에 조약돌을 떨어 뜨리며 걸었어요. 
(3) 마녀를 물리치고 보석을 한가득 챙겨 다시 집으로 돌아왔어요.',N'(1)-(3)-(2) ',N' (3)-(1)-(2)',N'(2)-(1)-(3) ',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (455,N'01',N'04',N'빵 조각으로 길을 표시했을 때 집으로 돌아오지 못한 이유는 무엇인가요?',NULL,N'비가 와서 사라져서',N'밤이라서 보이지 않아서',N'새들이 빵을 먹어 버려서',N'숲이 너무 넓어서',N'3',N'03',N'',N'S'),
	 (455,N'01',N'05',N'이야기 속 등장인물에게 해줄 수 있는 말로 올바른 것을 찾으세요.',NULL,N'아이들-어려움을 겪었지만 지혜롭게 해결하고 다시 행복을 찾게 되어 다행이야. ',N'새엄마-항상 아이들을 사랑으로 대해 주신걸보니 마음이 따뜻하신 분 같아요.',N'아빠-가난했지만 아이들을 먼저 생각하고 가족을 지켜낸 모습에 감동받았어요.',N'마녀-아이들에게 집을 내어 주고 잘 돌봐 주려 한 점이 고마워요.',N'1',N'04',N'',N'S'),
	 (455,N'01',N'06',N'헨젤과 그레텔의 행동에서 배울 수 있는 점으로 가장 알맞은 것은 무엇인가요?',NULL,N'어려우면 포기해야 해요.',N'어려움이 생겼을 때는 서로 도우며 지혜롭게 해결해야 해요.',N'어른 말은 꼭 따라야 해요.',N'어려운 일이 생기면 혼자서만 해결해야 해요.',N'2',N'04',N'',N'S'),
	 (455,N'01',N'07',N'과자로 만든 집을 처음 보았을 때 헨젤과 그레텔의 마음은 어땠을까요?',NULL,N'무섭고 두려웠어요.',N'슬프고 화가 났어요.',N'지루하고 심심했어요.',N'신기하고 기뻤어요.',N'4',N'05',N'',N'S'),
	 (455,N'01',N'08',N'아이들을 만났을 때 아빠는 어떤 마음이었을까요?',N'아이들은 아빠에게 달려가 와락 안겼어요.
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (456,N'01',N'02',N'기름 장수는 어두운 호랑이 배 속을 밝히기 위해 무엇을 켰나요? ',NULL,N'등잔불',N'성냥불',N'손전등',N'모닥불',N'1',N'01',N'',N'S'),
	 (456,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 놀란 호랑이는 다시는 나타나지 않았어요.
(2) 드디어 소금 장수와 기름 장수가 호랑이 몸 밖으로 나오게 되었어요.
(3) 기름 장수가 등잔불을 켜고, 소금 장수가 소금을 뿌리자 호랑이는 고통 스러웠어요.',N'(3)-(1)-(2)',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(1)-(3)-(2)',N'2',N'03',N'Y',N'S'),
	 (456,N'01',N'04',N'호랑이가 배 속에 든 것을 모두 토해 낸 까닭은 무엇인가요?',NULL,N'너무 많이 먹어 속이 울렁거렸기 때문에',N'운동을 많이 해서 소화가 잘 되었기 때문에',N'소금 장수가 호랑이 배 속에 소금을 뿌렸기 때문에',N'기름 장수가 배 속에서 소리를 질렀기 때문에',N'3',N'03',N'',N'S'),
	 (456,N'01',N'05',N'기름 장수와 소금 장수에게서 어떤 점을 배울 수 있나요?',NULL,N'힘을 모아 어려움을 이겨내는 용기',N'보모님을 정성껏 모시는 효심 ',N'끝까지 약속을 지키는 의리',N'가족을 먼저 생각하는 따뜻한 마음',N'1',N'04',N'',N'S'),
	 (456,N'01',N'06',N'이 이야기를 통해 우리가 할 수 있는 생각으로 알맞은 것은 무엇인가요?',NULL,N'힘이 세면 무엇이든 이길 수 있어요.',N'무서우면 소리만 지르면 돼요.',N'문제는 시간이 지나면 저절로 해결돼요.',N'위기에서는 함께 지혜를 모아야 해요.',N'4',N'04',N'',N'S'),
	 (456,N'01',N'07',N'호랑이는 어떤 마음이었을까요?',N'"앗, 따가워! 아이고, 배야! 호랑이 죽네!"',N'고통스러움',N'감격스러움',N'걱정스러움',N'부끄러움',N'1',N'05',N'Y',N'S'),
	 (456,N'01',N'08',N'호랑이 배 속에서 빠져나오게 되었을 때, 소금 장수와 기름 장수의 마음은 어땠을까요?',NULL,N'무섭고 떨렸어요.',N'안도하고 기뻤어요.',N'화가 나고 속상했어요.',N'지루하고 따분했어요.',N'2',N'05',N'',N'S'),
	 (456,N'01',N'09',N'빈칸에 어울리는 흉내 내는 말을 찾아 보세요.',N'호랑이가 소금 장수를 (     ) 삼켜 버렸어요.',N'똑딱',N'쿵쾅',N'꿀꺽',N'성큼',N'3',N'02',N'Y',N'S'),
	 (456,N'01',N'10',N'다음 문장에 어울리는 흉내 내는 말을 찾아 보세요.',N'호랑이는 뜨거워진 배를 움켜쥐고 뛰었어요.',N'소곤소곤',N'느릿느릿',N'펄쩍펄쩍',N'조용조용',N'3',N'02',N'Y',N'S'),
	 (456,N'01',N'11',N'마음 속으로 이리저리 깊이 생각하다''는 뜻을 가진 단어는 무엇인가요?',NULL,N'부탁하다',N'궁리하다',N'결정하다',N'약속하다',N'2',N'06',N'',N'S');
