	 (459,N'01',N'01',N'혹부리 영감의 턱 밑에는 무엇이 달려 있었나요?',NULL,N'커다란 혹',N'커다란 점',N'기다란 수염',N'커다란 흉터',N'1',N'01',N'',N'S'),
	 (459,N'01',N'02',N'혹부리 영감은 빈집에서 하루를 머무르게 되었을 때 누구를 만났나요? ',NULL,N'저승사자',N'호랑이',N'도깨비',N'나무꾼',N'3',N'01',N'',N'S'),
	 (459,N'01',N'03',N'혹부리 영감에게 일어난 일을 순서대로 바르게 나열한 것은 무엇인가요?',N'(1) 혹부리 영감은 산속 빈집에서 하룻밤을 보내게 되었어요.
(2) 도깨비들이 혹부리 영감의 노래를 듣고 신이 났어요.
(3) 도깨비들이 혹부리 영감의 혹을 떼어 주었어요.',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(3)-(1)-(2)',N'1',N'03',N'Y',N'S'),
	 (459,N'01',N'04',N'심술 혹부리 영감에게 일어난 일을 순서대로 바르게 나열한 것은 무엇인가요?',N'(1) 심술 혹부리 영감은 혹을 두 개나 달고 집으로 왔어요.
(2) 소문을 들은 심술 혹부리 영감은 산으로 올라갔어요.
(3) 심술 혹부리 영감은 도깨비들에게 혹을 사라고 했어요. ',N'(1)-(2)-(3)',N'(3)-(2)-(1)',N'(2)-(3)-(1)',N'(3)-(1)-(2)',N'3',N'03',N'Y',N'S'),
	 (459,N'01',N'05',N'심술 혹부리 영감에게 어떤 말을 해줄 수 있을까요? ',NULL,N'“할아버지 약속을 지키세요.”',N'“할아버지 욕심을 부리지 마세요.”',N'“할아버지 용기를 가지세요.”',N'"할아버지 더 크게 노래해야 해요."',N'2',N'04',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (459,N'01',N'06',N'이 이야기를 통해 우리가 배울 수 있는 점으로 가장 알맞은 것은 무엇인가요?',NULL,N'욕심을 부리면 좋은 일이 생겨요.',N'노래를 잘하면 무엇이든 얻어요.',N'무서운 곳에는 가지 말아야 해요.',N'착한 마음을 가지면 복을 받아요.',N'4',N'04',N'',N'S'),
	 (459,N'01',N'07',N'혹부리 할아버지는 어떤 마음일까요?',N'‘목을 내 놓으라 하면 어떡하지? 에구~ 큰일일세.’',N'두려움',N'반가움',N'놀라움',N'즐거움',N'1',N'05',N'Y',N'S'),
	 (459,N'01',N'08',N'혹이 떨어지고 집으로 돌아가는 혹부리 영감의 마음은 어땠을까요?',NULL,N'속상한 마음',N'기쁘고 후련한 마음',N'무섭고 불안한 마음',N'화나고 억울한 마음',N'2',N'05',N'',N'S'),
	 (459,N'01',N'09',N'빈칸에 어울리는 흉내 내는 말을 찾아 보세요. ',N'혹부리 영감은 (        ) 떨며 도깨비 앞으로 끌려 나왔지.',N'덩실덩실 ',N'부들부들',N'뚜벅뚜벅',N'성큼성큼',N'2',N'02',N'Y',N'S'),
	 (459,N'01',N'10',N'빈칸에 어울리는 흉내 내는 말을 찾아 보세요. ',N'혹부리 영감의 커다란 혹은 (      ) 흔들렸어.',N'찔끔찔끔',N'반짝반짝',N'덜렁덜렁',N'성큼성큼',N'3',N'02',N'Y',N'S'),
	 (459,N'01',N'11',N'마땅치 않게 여기는 나쁜 마음''을 무엇이라고 할까요?',NULL,N'심술',N'기쁨',N'후회',N'배려',N'1',N'06',N'',N'S'),
	 (459,N'01',N'12',N'‘다른 사람보다 더 많이 가지려는 마음’을 뜻하는 말은 무엇인가요?',NULL,N'용기',N'친절',N'욕심',N'노력',N'3',N'06',N'',N'S'),
	 (460,N'01',N'01',N'나무는 두 동네의 어디쯤에 심어져 있었나요?',N'',N'1/2 지점',N'1/3 지점',N'2/5 지점',N'3/7 지점',N'1',N'01',N'N',N'S'),
	 (460,N'01',N'02',N'사람들이 나무에 눈여겨 보는 이유는 무엇인가요?',N'',N'황금 사과가 열려서',N'나무가 아름다워서',N'신기한 과일이 열려서',N'신기한 사람이 있어서',N'1',N'01',N'N',N'S'),
	 (460,N'01',N'03',N'사람들이 땅바닥에 금을 그은 까닭은 무엇인가요?',N'',N'땅따먹기를 하기 위해',N'마을을 구분하기 위해',N'황금 사과를 잘 나누기 위해',N'이웃 나라의 부러움을 사기 위해',N'3',N'03',N'N',N'S');
