	 (460,N'01',N'05',N'다른 방법을 생각해야 했던 이유는?',N'',N'금이 계속 지워져서',N'금이 그려져 있는 것을 잘 보지 못해서',N'사과를 따기 위해 금을 넘어서',N'금은 아무나 그을 수 있는 것이어서',N'3',N'03',N'N',N'S'),
	 (460,N'01',N'06',N'다음 중 사과나무가 자라는 데 꼭 필요한 것이 아닌 것은 무엇인가요?',N'',N'물',N'비옥한 토양',N'햇빛',N'사람들의 욕심',N'4',N'07',N'N',N'S'),
	 (460,N'01',N'07',N'다음 중 모양을 나타내는 것이 아닌 것은?',N'',N'벌떼처럼 우르르',N'무시무시한 괴물',N'공이 떼굴떼굴',N'바위가 들썩들썩',N'2',N'02',N'N',N'S'),
	 (460,N'01',N'08',N'다음 (  ) 안에 가장 잘 어울리는 단어는?',N'다들 황금 사과를 갖겠다고 (  )이었지.',N'아우성',N'구시렁',N'재잘',N'속삭',N'1',N'02',N'Y',N'S'),
	 (460,N'01',N'09',N'다음 (  ) 속의 말과 어울리는 속담은?',N'그러다 나중에는 서로 (잡아먹을 듯)이 미워하게 되었지.',N'가는 말이 고와야 오는 말이 곱듯',N'고양이 쥐 어르듯',N'남의 밥에 든 콩이 굵듯',N'게 눈 감추듯',N'2',N'06',N'Y',N'S'),
	 (460,N'01',N'10',N'여러 장치로 막아보았지만 사람들의 (  )을 막을 수 없었다. 
(  )안에 들어갈 말은?',N'',N'고생(苦生)',N'욕심(慾心)',N'생각(生角)',N'수준(水準)',N'2',N'06',N'N',N'S'),
	 (460,N'01',N'11',N'엄마는 아이에게 담에 넘어가면 안되는 이유로 말한 것이 아닌 것은?',N'',N'아주 나쁜 사람들이 살고 있다.',N'무시무시한 괴물이 살고 있다.',N'빨려 들어가는 블랙홀이 있다',N'위험해서 다치거나 다시 돌아오지 못할 수도 있다.',N'3',N'07',N'N',N'S'),
	 (460,N'01',N'12',N'담을 넘었을 때 아이의 눈에 보인 것은?',N'',N'또래 친구들',N'괴물',N'엄마',N'사과',N'1',N'01',N'N',N'S'),
	 (460,N'01',N'13',N'다음 중 느껴지는 모양을 표현한 것이 아닌 것은?',N'',N'으스스한 그곳',N'몸이 오싹거렸다',N'희미한 빛',N'쌀쌀한 날씨',N'3',N'02',N'N',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (460,N'01',N'14',N'공을 놓친 꼬마가 공을 주으러 담쪽으로 걸어갈 때 느꼈던 심정이 아닌 것은?',N'',N'두려움',N'무서움',N'설레임',N'공포',N'3',N'04',N'N',N'S'),
	 (460,N'01',N'15',N'아이가 문을 열고 윗동네를 처음 봤을 때 느꼈을 기분이 아닌 것은?',N'',N'신기함',N'어색함',N'신남',N'기쁨',N'2',N'04',N'N',N'S'),
	 (461,N'01',N'01',N'장에 갔다 오는 길에 만난 도깨비는 돌쇠에게 어떤 부탁을 했나요?',NULL,N'황소의 뱃속에 들어가 살게 해 달라.',N'꼬리에 난 상처를 치료해 달라.',N'집으로 데려가 먹을 것을 달라.',N'하룻밤만 재워 달라.',N'1',N'01',N'',N'S'),
	 (461,N'01',N'02',N'도깨비는 보답으로 무엇을 약속했나요?',NULL,N'황소를 비싼 값에 팔아 주겠다.',N'산에 있는 나무를 모두 베어 주겠다.',N'황소의 힘을 열 배나 세게 해주겠다.',N'값비싼 금은보화를 주겠다.',N'3',N'01',N'',N'S'),
	 (461,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 벌어진 황소 입으로 살찐 도깨비가 뛰어 나왔어요.
(2) 사냥개에게 꼬리를 물린 도깨비가 도와달라고 부탁했어요.
(3) 황소는 배가 부르기 시작했고 몹시 괴로워했어요.',N'(2)-(3)-(1) ',N'(3)-(1)-(2)',N'(1)-(3)-(2)',N'(2)-(1)-(3)',N'1',N'03',N'Y',N'S'),
	 (461,N'01',N'04',N'정해진 날이 되었지만 도깨비가 약속을 지킬 수 없었던 이유는 무엇인가요?',NULL,N'꼬리의 상처가 아직 낫지 않았기 때문에',N'소의 뱃속이 너무 편했기 때문에',N'살이 쪄서 밖으로 나갈 수 없었기 때문에 ',N'소의 뱃속에서 길을 잃었기 때문에',N'3',N'03',N'',N'S'),
	 (461,N'01',N'05',N'돌쇠를 칭찬하는 말로 가장 올바른 것을 찾아보세요.',NULL,N'“처음부터 게으름을 부리지 않고 노력하는 모습이 멋졌어.”',N'“불쌍한 사람을 보면 도와주는 자세를 본받아야겠어.”',N'“잊지 않고 은혜를 갚을 줄 아는 모습이 정말 대단해.”',N'"힘이 세서 뭐든 할 수 있는 모습이 멋져."',N'2',N'04',N'',N'S'),
	 (461,N'01',N'06',N'이 이야기의 내용과 가장 잘 어울리는 생각은 무엇인가요?',NULL,N'도움을 받으면 고마운 마음을 잊지 말아야 해요.',N'편한 곳에 오래 있는 것이 가장 좋아요.',N'힘이 있으면 약속을 얼마든지 어겨도 돼요.',N'거짓말을 잘하는 것이 이득이에요.',N'1',N'04',N'',N'S'),
	 (461,N'01',N'07',N'도깨비는 어떤 목소리로 말했을까요?',N'“제발 살려 주세요. 은혜는 평생 잊지 않겠습니다.”
