	 (463,N'01',N'06',N'신사임당의 부모님이 생각한 가장 좋은 신랑감은 어떤 사람인가요?',NULL,N'재산이 많은 사람',N'벼슬이 높은 사람',N'키가 크고 힘이 센 사람',N'딸의 재능을 인정해 주는 사람',N'4',N'04',N'',N'S'),
	 (463,N'01',N'07',N'신사임당은 어떤 마음이었을까요?',N'"서방님, 아저씨 댁에는 가지 마십시오."',N'기쁜 마음',N'미워하는 마음',N'걱정되는 마음',N'자랑스러운 마음',N'3',N'05',N'Y',N'S'),
	 (463,N'01',N'08',N'가난한 집의 부인을 도와주기 위해 그림을 그릴 때 신사임당의 마음은 어땠을까요?',NULL,N'귀찮은 마음',N'따뜻한 마음',N'부끄러운 마음',N'화난 마음',N'2',N'05',N'',N'S'),
	 (463,N'01',N'09',N'빈칸에 들어갈 흉내내는 말을 찾아보세요.',N'외할아버지는 (          ) 웃으시며 고개를 끄덕이셨어요.',N'빙그레',N'부시시',N'스르륵',N'어슬렁',N'1',N'02',N'Y',N'S'),
	 (463,N'01',N'10',N'빈칸에 들어갈 흉내내는 말을 찾아보세요.',N'신사임당은 혼자서 (        ) 그림을 그리기 시작했어요.',N'북적북적',N'뒤뚱뒤뚱  ',N'쓰윽쓰윽',N'벌렁벌렁',N'3',N'02',N'Y',N'S'),
	 (463,N'01',N'11',N'혼례''와 비슷한 낱말을 찾으세요.',NULL,N'결혼',N'인사',N'이별',N'만남',N'1',N'06',N'',N'S'),
	 (463,N'01',N'12',N'‘예술가’의 뜻으로 가장 알맞은 것은 무엇인가요?',NULL,N'물건을 사고파는 사람',N'그림이나 음악 같은 것을 만들며 자신의 뜻을 펼치는 사람',N'어린이들에게 글자를 가르치는 사람',N'운동을 잘하고 달리기가 빠른 사람',N'2',N'06',N'',N'S'),
	 (464,N'01',N'01',N'할머니는 밭에서 돌아온 할아버지에게 무엇을 해 달라고 졸랐니요?',NULL,N'맛있는 저녁밥',N'재미있는 이야기',N'외딴집 청소',N'시장 구경',N'2',N'01',N'',N'S'),
	 (464,N'01',N'02',N'할아버지가 시장에서 무명을 팔고 사려고 하는 것은 무엇인가요? ',NULL,N'이야기 한 자리',N'소 한 마리',N'쌀 한 포대',N'닭 한 마리',N'1',N'01',N'',N'S');
INSERT INTO erp_bookstore_itempool (content_id,qlevel,qnum,q,qex,e1,e2,e3,e4,ans,qtype,qexgb,state) VALUES
	 (464,N'01',N'03',N'일이 일어난 순서대로 나열한 것을 찾으세요.',N'(1) 할아버지는 빨간코 아저씨한테 무명 한 필을 건네주고 서둘러 집으로 갔어요.
(2) 도둑은 날살려라 담을 훌쩍 넘어 달아났어요.
(3) 눈이 빠지게 기다리던 할머니는 할아버지를 반갑게 맞았어요.',N'(2)-(3)-(1)',N'(1)-(2)-(3)',N'(1)-(3)-(2)',N'(3)-(2)-(1)',N'3',N'03',N'Y',N'S'),
	 (464,N'01',N'04',N'도둑이 이야기를 듣고 도망가게 된 이유는 무엇인가요?',NULL,N'할아버지의 이야기가 너무 길어서',N'할아버지의 이야기가 자기를 보고 하는 이야기인 줄 알고',N'할머니가 이야기를 듣다가 소리를 질러서',N'할아버지의 이야기를 듣다가 날이 어두워져서',N'2',N'03',N'',N'S'),
	 (464,N'01',N'05',N'이 책을 읽고 느낀점을 올바르게 말한 것을 찾아보세요.',NULL,N'할아버지 할머니가 욕심을 부리지 않았기 때문에 큰 복을 받은 것 같아.',N'이야기 하나로 도둑을 물리친 장면이 재미있고 통괘했어.',N'도둑이 앞 일을 미리 알고 도망친 걸 보면 정말 지혜로운 것 같아. ',N'돈이 있으면 모든 일이 쉽게 해결될 수 있는 것 같아.',N'2',N'04',N'',N'S'),
	 (464,N'01',N'06',N'이야기 속 도둑의 모습으로 가장 알맞은 것은 무엇인가요?',NULL,N'침착하고 생각이 깊어요.',N'용감하고 똑똑해요.',N'겁이 많고 어리석어요.',N'정직하고 친절해요.',N'3',N'04',N'',N'S'),
	 (464,N'01',N'07',N'이야기를 배운 할아버지는 어떤 마음이었을까요?',N'"아이쿠, 재미있는 이야기 잘 배웠소."
